window.POEM_SHARD={"open_11500":["绝句六首 三","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["凿井交椶叶，开渠断竹根。","扁舟轻褭缆，小径曲通村。"],"庄子凿井而饮尔雅交加参错也呉若本杜注交椶作井绠也赵注蜀有盐井雨露之水落其中则壊新凿井时则交㯶叶以覆之",[["古注·《御选唐诗》","庄子凿井而饮尔雅交加参错也呉若本杜注交椶作井绠也赵注蜀有盐井雨露之水落其中则壊新凿井时则交㯶叶以覆之广雅并闾㯶也广志㯶叶似车轮乃在巅下有皮纒之附地起二旬一采转复上生"],["古注·《御选唐诗》","魏志牵招传凿源开渠注水城内江赋触涧开渠范云诗开渠纳秋水陈後主采桑曲柯新攀易断南史明僧绍传赐竹根知意笋箨冠隠者以为荣焉庾信诗山盃奉竹根"],["古注·《御选唐诗》","史记货殖传范蠡乗扁舟浮於江湖朱超道诗扁舟已入浪庾信赋吹落叶之扁舟庾肩吾诗浪涌燕舟轻鲍令晖诗褭褭临窓竹梁简文帝诗卧石藤为缆"],["古注·《御选唐诗》","王勃诗小径偏宜草法言或曰焉得直道而由诸曰涂虽曲而通诸夏则由诸川虽曲而通诸海则由诸王洙杜工部诗史旧集序入蜀卜居成都浣花里又杜甫诗集有江村诗"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《御选唐诗》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/御選唐詩_(四庫全書本)）"]],"open_11501":["绝句六首 四","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["急雨捎溪足，斜晖转树腰。","隔巢黄鸟竝，翻藻白鱼跳。"],"尔雅瀑雨谓之涷注今江东呼夏月暴雨为涷雨南史任昉传风雨急而不辍其音韵㑹捎掠也魏徴诗风捎幽渚荷尔雅水注川",[["古注·《御选唐诗》","尔雅瀑雨谓之涷注今江东呼夏月暴雨为涷雨南史任昉传风雨急而不辍其音韵㑹捎掠也魏徴诗风捎幽渚荷尔雅水注川曰溪又趾足也"],["古注·《御选唐诗》","梁简文帝赋看斜晖之度寮徐陵春日诗岸水带斜晖徐彦伯赋天旋日转庾信诗上林栁腰细新丰酒迳多"],["古注·《杜詩詳註》","三章见井渠而起咏井在㯶下故叶交加渠在竹旁故根断截此属内景下二则外景也杜臆有井有渠革堂所需畧具葢为久居计矣吴若本注交㯶作井绠也赵曰蜀有盐井雨露之水落其中则壊新凿井时即交㯶叶以覆之按二説皆非汲绠用椶毛不用㯶叶此井在村中於盐井无涉庄子凿井而饮"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《御选唐诗》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/御選唐詩_(四庫全書本)）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11502":["绝句六首 五","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["舍下笋穿壁，庭中藤刺檐。","地晴丝冉冉，江白草纤纤。"],"谢灵运游名山志始宁又北转一汀十里直指舍下梁简文帝诗横阶入细笋左传筚门闺窦之人注闺窦小户穿壁为户状如圭",[["古注·《御选唐诗》","谢灵运游名山志始宁又北转一汀十里直指舍下梁简文帝诗横阶入细笋左传筚门闺窦之人注闺窦小户穿壁为户状如圭也西京杂记匡衡勤学而无烛隣舍有烛乃穿壁引其光以书暎其光而读之"],["古注·《御选唐诗》","梁简文帝诗杂蕊暎南庭庭中光累媚梁武帝子夜四时歌庭中花照眼梁元帝诗桂影侵檐进藤枝绕槛长广韵刺穿也尔雅檐谓之樀疏屋檐一名樀一名屋梠一名宇説文檐㮰也櫩同"],["古注·《御选唐诗》","江淹赋芜阶翠地间居赋㣲雨新晴梁武帝诗晻暧曯游丝沈约诗游丝暎空转蔡邕赋修长冉冉曺植诗柔条纷冉冉"],["古注·《杜詩詳註》","四章倐雨倐晴之景捎溪足雨势掠过也转树腰日影横穿也鸟竝承树鱼跳承溪诗交交黄鸟古史白鱼入舟"],["古注·《杜詩詳註》","七亦切一作到"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《御选唐诗》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/御選唐詩_(四庫全書本)）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11503":["绝句六首 六","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["江动月移石，溪虚云傍花。","鸟栖知故道，帆过宿谁家。"],"尚书注江以南凡水皆呼曰江礼记仲冬之月水泉动何逊宿南洲浦诗江月初三五卢照隣诗江月夜临空论衡湍濑之流沙石",[["古注·《御选唐诗》","尚书注江以南凡水皆呼曰江礼记仲冬之月水泉动何逊宿南洲浦诗江月初三五卢照隣诗江月夜临空论衡湍濑之流沙石转而大石不移鲍照诗瑶波逐月开霞石触峯起"],["古注·《御选唐诗》","释慧标诗银溪锦碛明庄子川竭而谷虚江淹诗赤玉隠瑶溪云锦披沙汭元杰文又有古木倒傍絶壁无名氏子夜歌白云停隂冈丹华耀阳林江淹诗云煦江上花"],["古注·《御选唐诗》","王粲槐赋鸟愿栖而投翼繁钦暑赋鸟张翼而近栖梁宣帝赋灵木之所自生瑞鸟之所栖宿陶潜归去来辞鸟倦飞而知还汉书髙帝纪引兵从故道出曺植诗欲归忘故道"],["古注·《御选唐诗》","开河记自大梁至淮口锦帆过处香闻百里説文宿止也左传一宿为舍再宿为信宋子侯董娇娆不知谁家子提笼行采桑传灯録师唱谁家曲宗风嗣阿谁"],["古注·《杜詩詳註》","五章草堂春日之景笋穿壁藤刺檐此近景丝冉冉草纎纎此逺景杜臆此诗具见幽致"],["古注·《杜詩詳註》","六章江溪春夜之景江动月翻恍如移石而去溪虚云度隐然傍花而迷写景俱在空际鸟归溪畔帆迅江流二句分承而意则有感见客帆之不如栖鸟也"],["古注·《杜詩詳註》","王嗣奭曰公奔窜既久初归草堂凡目之所见景之所触情之所感皆掇拾成诗犹之浸兴也"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《御选唐诗》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/御選唐詩_(四庫全書本)）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11504":["绝句四首 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["堂西长笋别开门，堑北行椒却背村。","梅熟许同朱老吃，松高拟对阮生论。"],"",[["古注·《杜詩詳註》","此依朱本与前诗连编旧在永泰元年者非是年四月严武方卒公行出蜀矣"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11505":["绝句四首 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["欲作鱼梁云复湍，因惊四月雨声寒。","青溪先有蛟龙窟，竹石如山不敢安。"],"",[["古注·《杜詩詳註》","次章为鱼梁而赋也赵曰作鱼梁须劈竹沉石横截中流以为聚鱼之区因溪有蛟龙时兴云雨公故不敢冐险以取利汉武帝瓠子歌隤林竹兮楗石菑宣房塞兮万福来"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11506":["绝句四首 三","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["两个黄鹂鸣翠柳，一行白鹭上青天。","窗含西岭千秋雪，门泊东吴万里船。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11507":["绝句四首 四","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["药条药甲润青青，色过棕亭入草亭。","苗满空山慙取誉，根居隙地怯成形。"],"",[["古注·《杜詩詳註》","三章咏溪前诸景此皆指现前所见而近逺兼举范成大呉船録蜀人入呉者皆从合江亭登舟其西则万里桥杜诗门泊东呉万里船此桥正为呉人设"],["古注·《杜詩詳註》","四章为药圃而赋也种药在两亭之间故青色叠映彼苖长荒山者不能遍识其名此隙地所栽者又恐日浅未及成形耳杜臆公常多病所至必种药故有种药扶衰病之句有条有甲见种药多品吴论成形如人参成人形茯苓成禽兽形之类"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11508":["哭严仆射归榇","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["素幔随流水，归舟返旧京。","老亲如宿昔，部曲异平生。","风送蛟龙雨，天长骠骑营。","一哀三峡暮，遗後见君情。"],"刘云谓其化为蛟龙而风雨之情境惨然与天地意称",[["古评·《唐诗品汇》","刘云谓其化为蛟龙而风雨之情境惨然与天地意称"],["古注·《杜詩詳註》","鹤注当在渝忠时作通典唐左右仆射本副尚书令自尚书令废仆射为宰相开元元年改为左右丞相天宝元年复旧严武传永泰元年四月薨年四十赠尚书左仆射"],["古注·《杜詩詳註》","上四叙归榇下四哀仆射武本华阴人故返於旧京老亲犹在而部下人稀此归路之可哀者风送舟行而军营长寂此去後之可哀者至想到平日交情尤足伤心酸鼻所以一哀而日暮也陶潜诗平生去旧京国史补武卒母哭且曰吾今而後吾知免为官婢矣汉书李广传行无部曲行阵褚少孙集风雨以送之流水以行之老子天长地久骠骑营朱注引霍去病为是旧注引晋齐王攸迁"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗品彚（附唐诗拾遗）》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩品彚_(四庫全書本)）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11509":["宴戎州杨使君东楼","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["胜绝惊身老，情忘发兴奇。","座从歌妓密，乐任主人爲。","重碧拈春酒，轻红擘荔枝。","楼高欲愁思，横笛未休吹。"],"",[["古注·《杜詩詳註》","欧阳公作拈旧作酤一作擎一作拓"],["古注·《杜詩詳註》","突説惊竒见喜出望外中四宴中景事承发兴竒末二楼上有感应惊身老胜宴而自惊身老惜非少壮也忘老而发兴特竒忽逢乐事也两句辗转説来意思沈着坐从妓宻写出年少痴心乐任主为曲尽妖姬媚态山谷云拈酒擘枝此主人使歌妓为乐也笛声无解"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11510":["渝州候严六侍御不到先下峡","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["闻道乘骢发，沙边待至今。","不知云雨散，虚费短长吟。","山带乌蛮阔，江连白帝深。","船经一柱观，留眼共登临。"],"",[["古注·《杜詩詳註》","上四𠉀严未到五六渝州之胜七八下峡以待也本言泊船相待耳却云留眼共登临句法婉而多风王粲诗风流云散一别如雨江总别袁昌诗不言云雨散更似东西流古诗有长短吟唐书南蛮传南诏本哀牢夷後乌蛮别种也居永昌姚州之间梁益记嶲州隽山其地接诸蛮部有乌蛮白蛮全蜀总志白帝城在夔州府治东五里下即西陵峡口大江漰腾澍湃楚蜀咽喉一柱观在荆州刘孝绰诗经过一柱观出入三休台顾注杜诗一字一句皆有来厯如尽室畏途边尽室出左传畏途出庄子此诗云雨散长短吟俱本古诗"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11511":["拨闷","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["闻道云安麴米春，才倾一醆即醺人。","乘舟取醉非难事，下峡消愁定几巡。","长年三老遥怜汝，棙柁开头捷有神。","已办青钱防雇直，当令美味入吾唇。"],"",[["古注·《杜詩詳註》","黄鹤云永泰元年在忠州作邵注是年五月离成都下戎渝六月至忠州杜臆题曰拨闷因心有所闷为此谑浪以自寛演义谓欲饮酒拨闷非也别本作赠严二别驾者误"],["古注·《杜詩詳註》","一作鸣铙"],["古注·《杜詩詳註》","上四欲往云安五六顶乗舟下峡七八承取醉销愁顾注一盏即醺故取醉非难但欲销愁定须酌几廵也蔡注峡中以篙师为长年柂工为三老邵注三老捩柂者长年开头者杜臆汝指麴米春言舟子亦怜酒而捷往也旧唐书云安县属夔州本汉巴郡𦚧䏰县地邵注云安即今云阳县东坡志林退之诗百年未满不得死且可勤买抛青春国史补酒有荥阳之土窟春富平之石冻春剑南之烧春子美亦云闻道云安麴米春裴鉶传竒记裴航事亦有松醪春乃知唐人名酒多以春也东方朔传销愁者莫若酒庾信诗五两开船头黄生注赵氏以不准折一色见钱为青钱此倒训矣青铜质美故一色行使其鎈恶者用必准折故价直以青钱为率也杜臆雇谓舟费直谓酒资史记秦纪酒未及濡唇补注白乐天诗青旗沽酒趂棃花自注杭俗棃花开时酒熟号棃花春"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11512":["闻高常侍亡","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["归朝不相见，蜀使忽传亡。","虚历金华省，何殊地下郎。","致君丹槛折，哭友白云长。","独步诗名在，秪令故旧伤。"],"",[["古注·《杜詩詳註》","唐书广徳元年适召还为刑部侍郎转左散骑常侍永泰元年正月卒赠礼部尚书鹤注诗云蜀使忽传亡当是永泰元年成都作原注谓忠州所作非不应正月己卒六月始闻也"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11513":["宴忠州使君侄宅","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["出守吾家侄，殊方此日欢。","自须游阮巷，不是怕湖滩。","乐助长歌逸，杯饶旅思宽。","昔曾如意舞，牵率强爲看。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11514":["禹庙","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["禹庙空山里，秋风落日斜。","荒庭垂橘柚，古屋画龙蛇。","云气生虚壁，江声走白沙。","早知乘四载，疏凿控三巴。"],"永泰元年成都所作",[["古评·《唐诗镜》","三四事切"],["古评·《唐诗品汇》","永泰元年成都所作"],["古评·《唐诗品汇》","孙萃老云橘柚锡贡驱龙蛇皆禹之事公因见此有感也刘云皆本色语暗用"],["古注·《御选唐诗》","江淹诗思起秋风年谢灵运诗落日次朱方梁元帝诗西山晚日斜萧诠诗青山照落晖"],["古注·《御选唐诗》","张协诗荒庭寂以闲禹贡淮海惟扬州厥包橘柚锡贡孔安国曰小曰橘大曰柚淮南子橘柚有乡古诗橘柚垂佳实"],["古注·《御选唐诗》","左传深山大泽实生龙蛇宋玉招魂仰观刻桷画龙蛇些孙莘老云荒庭垂橘柚古屋画龙蛇盖橘柚锡贡驱龙蛇皆禹之事公因见此有感也"],["古注·《御选唐诗》","庄子乗云气御飞龙呉均与顾章书幽岫含云深溪蓄翠陆倕诗纲户图云气庾信登歌封中云气"],["古注·《御选唐诗》","山谦之南徐州记京江禹贡南江也春秋朔望輙有大涛声势骇然极为竒观湘中记白沙若霜雪子虗赋内隐巨石白沙梁武帝诗白沙青涟漪庾信诗白沙如湿粉"],["古注·《杜詩詳註》","鹤注夔州本巴东郡而忠乃析巴东之临江置又渝州有巴县此诗当是永泰元年秋在渝忠间作"],["古注·《杜詩詳註》","従英华一作生虚"],["古注·《杜詩詳註》","首二秋至禹庙三四庙中之景五六庙外之景末乃因禹庙而遡禹功孙莘老曰贡橘柚放龙蛇皆禹事公见此而有感也黄注壁间嘘云气沙上走江声二句倒装能写出山水之险峻故下接以疏凿三巴之语禹乘四载以治水向时早已知之今亲至三巴而见其疏凿遗蹟也疏主江言凿主山言控则引水而往黄注秋风记时三巴记地胡夏客曰只一水涯古庙耳写得如许雄壮陶𢎞景诗空山霜满高烟平古诗秋风萧萧愁杀人张协诗荒庭寂以闲招魂仰观刻桷画龙蛇些庄子乘云气御飞龙陆倕诗网户图云气宋书马岌铭诗於石壁曰丹崖百丈青壁千寻子虚赋钜石白沙庾信诗早知觅不见书传四载水乗舟陆乗车泥乗輴山乗樏庾信诗玉山乗四载江赋巴东之峡夏后疏凿班固两都赋控引淮湖谯周巴记刘璋分巴以永宁为巴东郡垫江为巴郡阆中为巴西郡是为三巴"],["古评·《瀛奎律髓》","凡唐人祠庙诗皆不能出老杜此等局段之外二诗葢絶唱也"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗镜》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩鏡_(四庫全書本)）","古籍注评：《唐诗品彚（附唐诗拾遗）》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩品彚_(四庫全書本)）","古籍注评：《御选唐诗》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/御選唐詩_(四庫全書本)）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）","古籍注评：《瀛奎律髓》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/瀛奎律髓_(四庫全書本)）"]],"open_11515":["题忠州龙兴寺所居院壁","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["忠州三峡内，井邑聚云根。","小市常争米，孤城早闭门。","空看过客泪，莫觅主人恩。","淹泊仍愁虎，深居赖独园。"],"争米闭门愁虎峡内小郡如此老杜诗善言风土他如塞俗人无井山田饭有砂瓦卜传神语畲田费火耕白鱼如切玉朱橘不论",[["古注·《杜詩詳註》","鹤注公永泰元年至忠州寓居於寺故作此诗杜臆忠州使君乃公之侄其薄情至此诗题不着其名而止题院壁犹见忠厚之意"],["古注·《杜詩詳註》","上四忠州之景下四有感而叹峡内云根言其僻隘争米闭门则极荒凉矣使君必失於周旋故有客泪主恩之慨邑近山故愁虎居独园在寺院也蜀都赋经三峡之峥嵘巴东永安县有高山对峙相去可二十丈左右崖甚高人谓之峡江赵曰三峡以明月峡为首巴峡巫峡之类为中东突峡为尽忠州在渝州之上所谓三峡内也黄希曰唐志忠州本临州州有五县而戸止六千七百则井邑萧条可知陆云诗井邑自相循张协诗云根临八极注五岳之云触石出者云之根也庾信诗山城早掩扉鲍照诗既荷人主恩金刚经有祗树给孤独园"],["古评·《瀛奎律髓》","争米闭门愁虎峡内小郡如此老杜诗善言风土他如塞俗人无井山田饭有砂瓦卜传神语畲田费火耕白鱼如切玉朱橘不论钱之类不可胜数可以类触"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）","古籍注评：《瀛奎律髓》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/瀛奎律髓_(四庫全書本)）"]],"open_11516":["旅夜书怀","杜甫","五言律诗","永泰元年（765）","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["细草微风岸，危樯独夜舟。","星垂平野阔，月涌大江流。","名岂文章着，官因老病休。","飘飘何所似，天地一沙鸥。"],"永泰元年（765）四月，严武卒，杜甫失所依，五月携家离成都乘舟东下。此诗即作于舟中。诗题“旅夜书怀”，写夜泊江岸之景与漂泊之感。",[["1. **危樯**","高耸之桅杆。"],["2. **星垂**","星辰低垂。"],["3. **平野阔**","原野辽阔。"],["4. **月涌**","月影随波浪涌动。"],["5. **沙鸥**","一种水鸟，常孤飞。比喻漂泊无依之身。"],["古评·《唐诗品汇》","刘云等闲星月着一涌字夐觉不同"],["古注·《杜詩詳註》","鹤注当是永泰元年去成都舟下渝忠时作"],["古注·《杜詩詳註》","一作飘零"],["古注·《杜詩詳註》","上四旅夜下四书懐微风岸边夜舟独系两句串説岸上星垂舟前月涌两句分承五属自谦六乃自解末则对鸥而自伤飘泊也顾注名实因文章而着官不为老病而休故用岂应二字反言以见意所云书懐也一沙鸥仍应上独字王融诗翻堦没细草宋玉舞赋顺微风阴铿诗度鸟息危樯王粲诗独夜不能寐易天垂象当作星垂吴均诗逺送出平野谢朓诗大江日夜流扬雄传赞雄好古乐道其意欲求文章成名於後世汉书韦贤以老病乞骸骨罢归按天地一沙鸥乾坤一草亭一字上加间字句义自明"]],{"source":"据霍松林《唐诗鉴赏辞典》“旅夜书怀”条（上海辞书出版社，1983 年版）","body":["此诗写旅夜漂泊之感，前半写景，后半抒情。首联“细草微风岸，危樯独夜舟”写近景。微风吹拂江岸细草，孤舟夜泊，高桅独立。“独”字已暗写孤独之意。颔联“星垂平野阔，月涌大江流”为千古名句，写远景。星辰低垂，平野辽阔；月影涌动，大江奔流。此联气象宏阔，与李白“山随平野尽，江入大荒流”同为写景绝唱。","颈联“名岂文章著，官应老病休”转入抒情。名声岂能因文章而显？老病罢官亦是应当。此联看似自宽，实含愤激——杜甫一生抱负在经世济民，岂在以文章传世；然终以文章名，岂其所愿。尾联“飘飘何所似，天地一沙鸥”以景作结。漂泊一身，似天地间一只孤鸥。全诗以小景起，以大景承，以自叹转，以孤鸥合，沉郁顿挫，为杜诗代表。"]},[],["https://github.com/chinese-poetry/chinese-poetry","据霍松林《唐诗鉴赏辞典》“旅夜书怀”条（上海辞书出版社，1983 年版）","《全唐诗》（清·曹寅等编，康熙扬州诗局本）","古籍注评：《唐诗品彚（附唐诗拾遗）》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩品彚_(四庫全書本)）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11517":["别常徵君","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["儿扶犹杖策，卧病一秋强。","白发少新洗，寒衣宽总长。","故人忧见及，此别泪相忘。","各逐萍流转，来书细作行。"],"三四作腰折句法只言衣寛不道人瘦",[["古评·《唐诗镜》","三四作腰折句法只言衣寛不道人瘦"],["古注·《杜詩詳註》","顾注永泰元年自秋徂冬公在云安故云卧病一秋强强多也"],["古注·《杜詩詳註》","平声黄生作望旧作忘"],["古注·《杜詩詳註》","音杭上四自叙病态下四送别常君扶而犹杖病已惫也髪少矣新加梳洗衣寛矣下垂而长此备写老病之状故人忧及已病彼此伤心而相对泪下故曰泪相望张逺谓忧病甚於惜别故泪可相忘稍曲白髪少寒衣寛此上三字下二字句法谢灵运诗此别久无适黄注见及恐大命之见及也"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗镜》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩鏡_(四庫全書本)）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11518":["三绝句 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["前年渝州杀刺史，今年开州杀刺史。","羣盗相随剧虎狼，食人更肯留妻子。"],"",[["古注·《杜詩詳註》","朱注此诗梁权道编在广徳二年鲁訔编在上元二年黄鹤编在大厯三年按首章渝开杀刺史事虽无考而以後二章证之此乃永泰元年事也"],["古注·《杜詩詳註》","此三章杂记蜀中之乱首章伤两州之被寇也食人留妻子就虎狼言以见盗之尤剧唐书开州盛山郡属山南西道本万州郡天宝元年更名"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11519":["三绝句 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["二十一家同入蜀，惟残一人出骆谷。","自说二女啮臂时，回头却向秦云哭。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11520":["三绝句 三","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["殿前兵马虽骁雄，纵暴略与羌浑同。","闻道杀人汉水上，妇女多在官军中。"],"",[["古注·《杜詩詳註》","末章叹禁军之暴横也汉水在巴西禁兵葢曾至蜀而肆虐者羌浑党项羌吐谷浑也唐书党项古析支地东距松州北隣吐谷浑吐谷浑注见前"],["古注·《杜詩詳註》","朱鹤龄曰代宗任用中人依禁军以平乱而不知其纵暴乃如此诗故深刺之也师古注时天子命陆瓘以三千神策军弹压蜀乱徧考史监俱无此事凢师氏所引唐史拾遗皆出伪譔严沧浪尝辩之如公诗自平中官吕太一事载正史师乃云唐史拾遗有吕宁为太一宫使即此推之他可知矣又曰唐本纪永泰元年九月仆固懐恩诱党项羌浑奴刺寇同州及凤翔盩厔末章云纵暴畧与羌浑同则知其时为寇者乃羌浑也次章云惟残一人出骆谷骆谷闗在盩厔西南又知二十一家因避羌浑而入蜀也虽宝应元年党项奴刺尝寇梁洋间然尔时禁军尚未盛兵志谓在广徳元年代宗幸陕以後以诗中殿前兵马句观之是作於宝应之後矣"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11521":["十二月一日三首 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["今朝腊月春意动，云安县前江可怜。","一声何处送书鴈，百丈谁家上水船。","未将梅蘂惊愁眼，要取楸花媚远天。","明光起草人所羡，肺病几时朝日边。"],"",[["古注·《杜詩詳註》","鹤注永泰元年秋公至云安是冬在云安作明年春晚迁居䕫州"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11522":["十二月一日三首 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["寒轻市上山烟碧，日满楼前江雾黄。","负盐出井此谿女，打鼓发船何郡郎。","新亭举目风景切，茂陵着书消渴长。","春花不愁不烂漫，楚客唯听棹相将。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11523":["十二月一日三首 三","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["即看燕子入山扉，岂有黄鹂历翠微。","短短桃花临水岸，轻轻柳絮点人衣。","春来准拟开怀久，老去亲知见面稀。","他日一杯难强进，重嗟筋力故山违。"],"",[["古评·《唐诗镜》","三四凄清欲絶"],["古注·《杜詩詳註》","次章承云安上四云安景事下四云安情绪烟碧雾黄冬暖之色此溪女嫌其俗陋何郡郎怪其冒险中原未平故有新亭风景之伤肺病留蜀故有茂陵消渴之慨春花应春动听棹思出峡也何逊诗山烟函树色鲍照诗蒙昧江上雾马岭谣三牛对马岭不出贵人出盐井逺注云安人家有盐井其俗以女当门戸皆贩盐自给唐书夔州奉节县有永安井盐官又云安大昌皆有盐官又云峡中多曲江有峭石两舟相触急不及避故发船多打鼓听前船鼓声既逺後船方发恐相值触损也何氏语林王敦尝坐武昌钓台闻行船打鼓嗟称其能王导传中州士人避乱江左毎至暇日邀饮新亭周顗中坐叹曰风景不殊举目有江山之异通监注新亭去江宁县十里近临江渚切乃凄切之切茂陵着书用司马相如事注别见顾注䕫为南楚故自称楚客鲍照诗楚客心悠哉仪礼注相将彼此相扶助陶潜诗相将还旧居杜臆发必同行故曰相将犹俗云船幇"],["古注·《杜詩詳註》","末章承春意上四拟春日之景下四冩春日之情朱注诗作於十二月一日而云燕鹂桃栁者葢逆道其事即所谓他日也亲知稀见欲开懐而不得故山终违欲强饮而不能意有两层故曰重嗟朱瀚谓一嗟筋力一嗟故山非是"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗镜》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩鏡_(四庫全書本)）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11524":["又雪","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["南雪不到地，青崖沾未消。","微微向日薄，脉脉去人遥。","冬热鸳鸯病，峡深豺虎骄。","愁边有江水，焉得北之朝。"],"江水东流欲挽之使北爱君恋阙之心切矣",[["古注·《杜詩詳註》","鹤注当是永泰元年冬作题曰又雪前面应有雪诗一章疑脱漏矣"],["古注·《杜詩詳註》","此公厌居云安而托冬雪以写意也上四言景下四感懐雪不到地气煖故也沾崖之雪向日旋消人毎不见故脉脉而遥杜臆文禽偏病猛兽偏骄见地恶不可久居安得乗此江水而北返长安乎风土记南方无雪江淹诗鸡鸣丹壁上猿啸青崖间陶潜诗闲雨纷微微吴均诗脉脉留南浦杜臆峡深有虎负嵎之势"],["古评·《瀛奎律髓》","江水东流欲挽之使北爱君恋阙之心切矣"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）","古籍注评：《瀛奎律髓》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/瀛奎律髓_(四庫全書本)）"]],"open_11525":["奉汉中王手札","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["国有乾坤大，王今叔父尊。","剖符来蜀道，归盖取荆门。","峡险通舟过，江长注海奔。","主人留上客，避暑得名园。","前後缄书报，分明馔玉恩。","天云浮绝壁，风竹在华轩。","已觉良宵永，何看骇浪翻。","入期朱邸雪，朝傍紫微垣。","枚乘文章老，河间礼乐存。","悲秋宋玉宅，失路武陵源。","淹薄俱崖口，东西异石根。","夷音迷咫尺，鬼物傍黄昏。","犬马诚爲恋，狐狸不足论。","从容草奏罢，宿昔奉清罇。"],"",[["古注·《杜詩詳註》","鹤注汉中王贬蓬州刺史今出峡将归京作书报公而公复之以诗旧编在永泰元年今依朱氏入在大厯元年䕫州杜臆题上加奉字以天潢尊之其谨严如是"],["古注·《杜詩詳註》","首段叙王行踪王时罢郡归朝取道夷陵而暂留归州也张逺注主人指归州守上客即汉中王胡夏客曰上四起局庄严通舟注海作去笔留客避暑作留笔溍注首句谓王所封之国甚大也书大传周公曰吾今王之叔父也王让皇帝之子代宗之叔父曹植诗剖符梭玉王爵是加夷陵有荆门山其状如阙然吴越春秋决江导河东注於海梁元帝诗光时留上客"],["古注·《杜詩詳註》","去声一作望"],["古注·《杜詩詳註》","此想归途景事馔玉葢与缄书同赠者絶壁华轩即名园佳景良宵堪适不必触浪前行朱邸指王第紫微指帝宫避暑在夏宵永属秋还京正当冬雪叙次详明戴暠诗馔王待鸣钟苏彦诗洪涛奔逸势骇浪驾丘山谢朓牋朱邸方开又诗黄旗映朱邸玉海汉书注郡国朝宿之舍在京师者率名邸诸侯朱尸故曰朱邸晋志紫微大帝之座天子之所居也"],["古注·《杜詩詳註》","末致临岐缱绻之情犬马自方狐狸指当时窃位者王於草奏之余应念宿昔交欢嘱其去後不忘也此章前三段各八句末段四句收曹植诗不胜犬马恋主之情张纲传豺狼当道安问狐狸前汉京房传为淮阳王作求朝奏草沈佺期诗顾我叨郎署渐无草奏工古诗宿昔梦见之古歌清樽发朱顔"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11526":["赠崔十三评事公辅","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["飘飘西极马，来自渥洼池。","飒飁定山桂，低徊风雨枝。","我闻龙正直，道屈尔何爲。","且有元戎命，悲歌识者谁。","官联辞宂长，行路洗欹危。","脱劒主人赠，去帆春色随。","阴沈铁凤阙，教练羽林儿。","天子朝侵早，云台仗数移。","分军应供给，百姓日支离。","黠吏因封己，公才或守雌。","燕王买骏骨，渭老得熊罴。","活国名公在，拜坛羣寇疑。","冰壶动瑶碧，野水失蛟螭。","入幕诸彦集，渴贤高选宜。","骞腾坐可致，九万起於斯。","复进出矛戟，昭然开鼎彝。","会看之子贵，叹及老夫衰。","岂但江曾决，还思雾一披。","暗尘生古镜，拂匣照西施。","舅氏多人物，无慙困翮垂。"],"",[["古注·《杜詩詳註》","一作飘飘"],["古注·《杜詩詳註》","一作定一作邓"],["古注·《杜詩詳註》","此送崔还朝辞冗长离散职徙欹危将出峡赠在元戎去指评事凤阙谓宫殿羽林乃卫士朱注评事掌出使推按不为冗官此云官聨辞冗长下云教练羽林儿葢崔自外僚徵入朝为羽林幕职评事恐是兼官或先曾以评事贬斥者申屠嘉传冗官居其中师古曰冗散辈也文赋固无取乎冗长郑曰长直亮切吴越春秋伍子胥解剑赠"],["古注·《杜詩詳註》","渔父文心雕龙天髙气清阴沈之气逺汉书建章宫东则凤阙髙二十余丈西都赋注圆阙上作铁凤凰令张两翼举头敷尾陆倕石闗铭铜雀铁凤之工汉宣帝纪羽林孤儿注天有羽林星林喻若林木之盛羽有羽翼鸷击之意故以名武官焉百官表取从军死事者之子养羽林官教以五兵号曰羽林孤儿"],["古注·《杜詩詳註》","此则有慨时事杜臆朝侵早世乱多事仗数移乘舆播迁供给谓军需之急支离谓民力已罢封已有害於民者守雌无益於民者二语説尽官曹之弊公才泛言在位者不指崔君国语叔向曰引党以封已注封厚也晋书孔愉有公才而无公望老子知其雄守其雌"],["古注·《杜詩詳註》","此谓元戎得以靖乱骏骨熊罴言主帅能用崔名公即指元戎羣寇惊疑则国多全活矣冰壶句言将令肃清野水句言余孽销除战国策涓人为君求千里马马已死买其骨五百金返以报君大怒涓人曰死马且买之况生马乎不三年千里马至者三渭老熊罴注见三巻南史王广之子珍国为南谯太守高帝手敇云爱人活国甚副吾意拜坛用汉髙拜韩信事逺注冰壶即冰雪静聪明意鲍照诗清如玉壶冰"],["古注·《杜詩詳註》","末赠别而致称羡之意昔听崔谈论如悬河之注今想其丰采如披云见天其先屈而後伸又如拭尘照面矣舅氏之门多材如此亦何慙困抑乎末葢幸之也此亦三用比喻与起处相应此章首尾各八句中四段各六句庄子决西江之水而活汝世説卫瓘见乐广曰若披云雾覩青天鲍照诗明镜尘匣中杜臆旧注皆以崔为公舅氏今诗中称崔为之子自称为老夫其非甥舅可知後有毒热简崔评事十六弟诗亦自称老夫而称崔为内弟又知二评事皆公中表以生於舅家故云舅氏多人物耳"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11527":["长江二首 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["衆水会涪万，瞿塘争一门。","朝宗人共挹，盗贼尔谁尊。","孤石隐如马，高萝垂饮猨。","归心异波浪，何事即飞飜。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11528":["长江二首 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["浩浩终不息，乃知东极临。","衆流归海意，万国奉君心。","色借潇湘阔，声驱灧澦深。","未辞添雾雨，接上遇衣襟。"],"书浩浩滔天宋之问髙山引攀龙窈窕兮上跻悬峯长路浩浩兮此去何従易冥升利於不息之贞礼记天髙地下万物散殊而礼",[["古评·《唐诗品汇》","刘云接上不可晓"],["古注·《御选唐诗》","书浩浩滔天宋之问髙山引攀龙窈窕兮上跻悬峯长路浩浩兮此去何従易冥升利於不息之贞礼记天髙地下万物散殊而礼制行矣流而不息合同而化而乐兴焉"],["古注·《御选唐诗》","史记秦始皇纪登兹㤗山周览东极淮南子禹使大章步自东极至于西极二亿三万三千五百里使竖亥步自北极至于南极二亿三万三千五百里七千五步左思呉都赋出乎大荒之中行乎东极之外"],["古注·《御选唐诗》","水经注涟水经连道县控行衆流合成一溪谢灵运山居赋衆流所凑万泉所滙泛滥异态首毖终肥史记司马相如传夏后氏堙鸿水决江疏河洒沈澹灾东归之於海而天下永宁左思呉都赋百川派别归海而㑹"],["古注·《御选唐诗》","易首出庶物万国咸宁左传禹㑹诸侯于涂山执玉帛者万国张正见诗轨文通万国旌节靖三边京房易传坤纯隂用事象配地属土柔道光也隂凝盛与乾相纳臣奉君也"],["古注·《御选唐诗》","赵子栎注潇湘在潭州三峡之水下入洞庭与潇湘相逺故云色借也山海经洞庭之山帝之二女居之是常游於江渊澧沅之间交潇湘之渊出入必以飘风暴雨曹植诗朝游江北岸夕宿潇湘沚谢朓诗洞庭张乐地潇湘帝子游"],["古注·《御选唐诗》","寰宇记䕫州灔澦堆在州之西蜀江中心瞿唐峡口冬水浅出二十余丈夏水涨半没王洙注世説灔澦如象瞿唐莫上灔澦如马瞿唐莫下言其险絶舟人常以此候之"],["古注·《御选唐诗》","汉书邹阳传浮云出游雾雨咸集"],["古注·《御选唐诗》","按遇王洙注本作过公羊传沾袍注袍衣前襟也尔雅佩襟谓之褑方言袒饰谓之直襟杜诗博议江流之大不辞雾雨雨接江流而上过人衣襟之间所谓波浪兼天者如此"],["古注·《杜詩詳註》","首章观长江而慨身世也上四惜水以感时事下四触景而动归思衆水㑹集而争赴一门其迅急可知自此东流赴海水有朝宗之义今盗贼据险为乱尔不尊朝廷而将谁尊耶石如马险可畏猿垂饮物可増写景中亦含归意江水飞翻阻人归路而归心终不可阻亦何用飞翻为哉黄注此八句整对格亦虚实相间格旧书涪州涪陵郡武徳元年以渝州之涪陵镇置万州南浦郡武徳二年析信州置俱属山南东道寰宇记瞿塘在夔州东一里古西陵峡也连崖千丈崩流电激方舆胜览瞿塘峡乃三峡之门两崖对峙中贯一江望之如门焉诗沔彼流水朝宗於海诗挹彼注兹黄注共挹犹言共饮其徳以一门应衆水以谁尊应朝宗皆用斜对法杜臆云朝宗者人所共取今盗贼不知此义谁是尊尔者见逆理之必亡也二句解作正对以下章奉君例之则谁尊当主君説李膺益州记灔澦堆夏月涨没数十丈其状如马舟人不敢进又曰犹豫言舟子取途不决水脉故犹豫也水经注江中有孤石为滛豫石冬出水二十余丈夏则没亦有裁出矣乐府滛豫大如马瞿唐不可下寰宇记灔澦堆周围二十丈在州西南二百步蜀江中心瞿唐峡口水经注瞿唐峡多猿猿不生北岸非惟一处或取之放着北山中初不闻声吴均书企水之猿百臂相接谢灵运游名山志观挂猿下饮百丈相连"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗品彚（附唐诗拾遗）》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩品彚_(四庫全書本)）","古籍注评：《御选唐诗》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/御選唐詩_(四庫全書本)）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11529":["承闻故房相公灵榇自阆州啓殡归葬东都有作二首 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["远闻房太守，归葬陆浑山。","一德兴王後，孤魂久客间。","孔明多故事，安石竟崇班。","他日嘉陵涕，仍沾楚水还。"],"",[["古评·《唐诗品汇》","刘云岂𤣥龄後耶"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗品彚（附唐诗拾遗）》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩品彚_(四庫全書本)）"]],"open_11530":["承闻故房相公灵榇自阆州啓殡归葬东都有作二首 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["丹旐飞飞日，初传发阆州。","风尘终不解，江汉忽同流。","劒动新身匣，书归故国楼。","尽哀知有处，爲客恐长休。"],"",[["古注·《杜詩詳註》","首章哀思故相欲𠉀哭於夔江也一德而多故事言生前相业孤魂而竟崇班言殁後赠典嘉陵泪初哭於阆州楚水还再逄於夔州黄生注孔明安石皆身厯两朝者比房相独切公田园在东都常有归志今哭公於此地空有泪逐榇还而已还字仍挽归塟赵曰旧本作太守非善本作太尉葢琯适汉州刺史召拜刑部尚书道病卒赠太尉不应呼之为太守也宋之问诗归塟出三条唐书琯河南人宰相房融之子少好学与东平吕向偕隠陆浑山十年郑曰十道志陆浑山在洛阳洙曰昔辛有适伊川见被髪而祭者言此地当夷後为陆浑之戎所有山因而得名书咸有一德宋之问诗业重兴王际孔融诗孤魂游穷暮後汉书温序为隗嚣所杀䘮到洛阳赐城旁地为塜长子夀梦序曰久客思乡里夀即上书请骸骨归塟蜀志陈寿与荀勖等定故蜀丞相诸葛亮故事二十四篇以进谢安传安塟时年六十六帝三日临於朝堂赐东园秘器朝服赠太傅谥曰文靖及塟加殊礼依大司马桓温故事王献之传谢安薨赠礼有异同之议献之与徐邈共明安之忠勋遂加殊礼鹤曰嘉陵江在果州果与梓阆为隣楚水夔已下之江也江淹赋楚水而吴江"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11531":["云安九日郑十八携酒陪诸公宴","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["寒花开已尽，菊蘂独盈枝。","旧摘人频异，轻香酒蹔随。","地偏初衣裌，山拥更登危。","万国皆戎马，酣歌泪欲垂。"],"",[["古注·《杜詩詳註》","鹤注永泰元年八月仆固懐恩及吐蕃回纥等入寇故诗云万国皆戎马逺注郑十八名贲云安人"],["古注·《杜詩詳註》","上四九日自伤飘荡下四云安慨世乱离人指诸公曰频异忆去年也郑方擕酒曰暂随念将来也初衣夹见地气之煖更登危见山城之髙张正见诗霜雁排空断寒花映短篱沈佺期诗魏文颁菊蘂汉武赐茰囊陶潜诗心逺地自偏説文裌无絮衣秋兴赋籍莞蒻御裌衣风俗通九日登高以禳灾厄记孝子不登危商书酣歌於室"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11532":["荅郑十七郎一绝","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["雨後过畦润，花残步屐迟。","把文惊小陆，好客见当时。"],"",[["古注·《杜詩詳註》","鹤注郑十七郑十八兄弟也"],["古注·《杜詩詳註》","此访郑後郑赠诗而公答之也上二叙景下二言情小陆陆云也比郑十八当时郑庄也比郑十七"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11533":["将晓二首 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["石城除击柝，铁锁欲开关。","鼓角悲荒塞，星河落曙山。","巴人常小梗，蜀使动无还。","垂老孤帆色，飘飘犯百蛮。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11534":["将晓二首 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["军吏回官烛，舟人自楚歌。","寒沙蒙薄雾，落月去清波。","壮惜身名晚，衰慙应接多。","归朝日簪笏，筋力定如何。"],"",[["古注·《杜詩詳註》","此章叙景言情亦四句分截上四乃发船时所闻见者下截仍叹垂老意壮字衰字微读言追思壮年惜身名已晚今当衰老惭应接徒多縦使归朝正恐筋力难堪耳前章写岸上之景此章写舟前之景前章叹留滞南方此章欲还归北阙也官烛官府之烛黄庭坚曰巴只为扬州刺史与坐客暗中不燃官烛史记项羽纪闻军中四面皆楚歌沈庆之诗朽老筋力尽徒步归南国"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11535":["怀锦水居止二首 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["军旅西征僻，风尘战伐多。","犹闻蜀父老，不忘舜讴歌。","天险终难立，柴门岂重过。","朝朝巫峡水，远逗锦江波。"],"",[["古注·《杜詩詳註》","鹤注当是永泰元年在云安作陶潜诗居止次城邑"],["古注·《杜詩詳註》","义从平声读从去声"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11536":["怀锦水居止二首 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["万里桥南宅，百花潭北庄。","层轩皆面水，老树饱经霜。","雪岭界天白，锦城曛日黄。","惜哉形胜地，回首一茫茫。"],"",[["古注·《杜詩詳註》","次章懐思锦水胜境也亦四句分段首二居止所在三四近景五六逺景此即形胜也回首句应前岂重过仍结到懐字杜臆万里桥六句乃草堂记也公之神情锺此故百世而後复为所有宋玉招魂髙堂䆳宇槛层轩史万岁诗界天自岭胜金汤剑阁铭形胜之地匪亲勿居"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11537":["子规","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["峡里云安县，江楼翼瓦齐。","两边山木合，终日子规啼。","眇眇春风见，萧萧夜色凄。","客愁那听此，故作傍人低。"],"",[["古注·《杜詩詳註》","此亦云安春作乃水阁所闻子规也杜臆一説子规非杜鹃乃呌不如归去者"],["古注·《杜詩詳註》","去声一作傍旅"],["古注·《杜詩詳註》","此听子规而动客愁也峡中有县县前有江江上有楼楼边拥以山木而子规终日啼号当此春风之际俨如夜色凄凉客愁何堪听此况故作低声以近人乎八句一气滚下夜色即就日间言此杜臆之説也眇眇指子规萧萧指山木申涵光曰两边山木合终日子规啼爽豁如弹丸脱手此太白隽语也梦弼曰翼瓦谓檐宇飞扬如鸟之张翼庾信诗清梵两边来鲍照诗眇眇负霜鹤夏后湛秋夕赋木萧萧以被风"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11538":["立春","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["春日春盘细生菜，忽忆两京梅发时。","盘出高门行白玉，菜传纤手送青丝。","巫峡寒江那对眼，杜陵远客不胜悲。","此身未知归定处，呼儿觅纸一题诗。"],"",[["古注·《杜詩詳註》","诗云巫峡寒江系夔州所作依朱氏入在大厯二年"],["古注·《杜詩詳註》","一作梅发"],["古注·《杜詩詳註》","上四忆两京春日下四感夔江春日杜臆通章只是一个悲意人但知其悲一身之飘泊而不知其悲两京之萧索也对春盘生菜忆及两京盛时今老客峡江则两京失其□而身亦失其居矣悲曰不胜包身世无穷之感三四分承盘菜而意却贯穿菜经纎手玉盘传送二句倒叙那对眼谓那能对眼归定处谓欲归两京尚无定处也摭言晋李鄂立春日命以芦菔芹芽为菜盘相馈贶四时寳镜唐立春日春饼生菜号春盘黄生注生菜韭也欧公归田録杨六年为文务避俗语门生摘其徳迈九皇之句讽之云未知何时得买生菜以九皇音近韭黄也按诗言青丝指韭良是东坡诗渐觉东风斜峭寒青蒿黄韭试春盘谢灵运诗两京愧佳丽公居杜陵而家在洛阳故两京春盘皆所尝食庄子高门悬薄无不走也此指贵戚之家旧引三辅黄圆未央宫中高门殿误传经也古诗纤纤出素手"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11539":["漫成一绝","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["江月去人只数尺，风灯照夜欲三更。","沙头宿鹭联拳静，船尾跳鱼拨刺鸣。"],"",[["古注·《杜詩詳註》","鹤注此是云安发船下䕫州时作"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11540":["老病","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["老病巫山里，稽留楚客中。","药残他日裹，花发去年丛。","夜足沾沙雨，春多逆水风。","合分双赐笔，犹作一飘蓬。"],"老杜诗一句说病者极多两三句说病者如髙秋苏肺气白发自能梳药饵増加减门庭问扫除第二句最妙昔者之病头亦不自",[["古注·《杜詩詳註》","鹤注诗云老病巫山里当是大厯元年夔州作葢是年春晚方自云安迁夔州"],["古注·《杜詩詳註》","老病稽留意用双提药残句承老病花发句承稽留夜雨逆风难於出峡故有飘蓬之叹往日药裹今用之已残去年丛枝当眷而花发旧注谓公两经花放者非公自去年秋方至云安也合犹当也後汉书太原闵仲叔家居安邑老病家贫焦氏易林行者稽留赐笔见十四巻赤管注沈佺期诗恵移双赐笔恩降五时衣"],["古评·《瀛奎律髓》","老杜诗一句说病者极多两三句说病者如髙秋苏肺气白发自能梳药饵増加减门庭问扫除第二句最妙昔者之病头亦不自能梳今始自能梳头也杖藜还客拜又以见病愈愈已能答拜但仍须倚杖耳所以老杜诗虚实字皆当细细审看今所取一首尤见圆活而峭拔"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）","古籍注评：《瀛奎律髓》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/瀛奎律髓_(四庫全書本)）"]],"open_11541":["南楚","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["南楚青春异，暄寒早早分。","无名江上草，随意岭头云。","正月蜂相见，非时鸟共闻。","杖藜妨跃马，不是故离羣。"],"附宴戎州杨使君东楼胜絶惊身老情忘发兴竒座从歌妓宻乐任主人为重碧拈春酒轻红擘荔枝楼髙欲愁思横笛未休吹",[["古评·《唐诗镜》","附宴戎州杨使君东楼胜絶惊身老情忘发兴竒座从歌妓宻乐任主人为重碧拈春酒轻红擘荔枝楼髙欲愁思横笛未休吹"],["古注·《杜詩詳註》","鹤注当是大厯元年春在云安作顾注云安在楚之西南故曰南楚宋玉笛赋絶郑之遗离南楚兮方言南楚之人"],["古注·《杜詩詳註》","上六写春暄之景下二叙客楚之情杜臆他处初春必有余寒惟南楚交春即暄故云早早分春暄佳胜如此而不及与人游赏正恐杖藜缓行有妨少年跃马者耳非是故意离羣也黄注五六见物皆乐羣与七八反照记子夏离羣而索居"],["古注·《杜詩詳註》","无名江上草随意岭头云此奥水流心不竞云在意俱迟同一间旷心境但此处似出之太易耳"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗镜》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩鏡_(四庫全書本)）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11542":["寄常徵君","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["白水青山空复春，徵君晚节傍风尘。","楚妃堂上色殊衆，海鹤阶前鸣向人。","万事纠纷犹绝粒，一官羇绊实藏身。","开州入夏知凉冷，不似云安毒热新。"],"",[["古注·《杜詩詳註》","此诗伤徵君之晩出上四惜词五六解词七八慰词山水空度春光以其晚节犹逐风尘也楚妃比朝贵之得宠海鹤比处士之依人今事丛犹然乏食知官卑但以藏身耳黄注藏身犹云吏隠七句见地见时世説顾景怡不就徵晩节服食不与世通泽州陈冡宰注楚妃犹言宋子齐姜燕姬越女喻仕途中名位相轧才嫉妬者旧引樊姬以比徵君之徳非也陆机诗楚妃且勿叹齐娥且莫讴马元熙诗掩抑歌张女凄清奏楚妃应瑒鹦鹉赋表衆艶之殊色西京杂记海鹤江鸥湛方生吊鹤文忽闻堦前有孤鹤鸣庄子通其一万事毕贾谊传糺错相纷司马相如传交错纠纷後汉书范丹为莱芜长遁居梁沛之间所止单陋有时絶粒穷居自若庄子知效一官晋载纪马能千里不免羁绊宋书刘瑀曰骐骥罗於羁绊逺注藏身即东方朔避世金马门意庄子夫全其形生之人藏其身也九域志开州东至夔州云安县龙目驿二百九十里卢世㴶曰此诗字字沈痛説者类云讽刺因错㑹晚节傍风尘一语遂致通篇皆错夫傍风尘犹奔走道路耳人少壮蹇踬犹冀前途至老年道路则无复之矣此最是伤心处海鹤鸣向人岂鸡鹜流哉万事纠纷犹然絶粒一官羁绊实以藏身此等艰辛向谁人道全是自苦自诉并以怜及徵君想寄诗时不知泪下㡬行矣"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11543":["寄岑嘉州","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["不见故人十年余，不道故人无素书。","愿逢颜色关塞远，岂意出守江城居。","外江三峡且相接，斗酒新诗终日疎。","谢朓每篇堪讽诵，冯唐已老听吹嘘。","泊船秋夜经春草，伏枕青枫限玉除。","眼前所寄选何物，赠子云安双鲤鱼。"],"自注云州据蜀江外",[["古评·《唐诗镜》","自注云州据蜀江外"],["古注·《杜詩詳註》","原注州据蜀江外诗云泊船秋夜经春草葢公自去年秋至云安大厯元年春尚在其地也杜确岑参集序参自库部正郎出为嘉州杜鸿渐表为职方郎中兼侍御史列於幕府无㡬使罢寓居於蜀汉武帝通西南夷立犍为郡成帝永初六年得古磬改嘉定後周改为嘉州唐初嘉定郡领县八乾元初仍为嘉州嘉州在成都东南去成都为近去夔州为逺"],["古注·《杜詩詳註》","思遇岑於嘉州也张衡诗长跪读素书江城指嘉州"],["古注·《杜詩詳註》","此叙岑之近况也谢比岑冯自方邵注一统志一渠由永康过新安入成都府谓之外江一渠由永康过郫县入成都府谓之内江县西五里自洛口分支经汉州谓之中江三江皆与嘉州岷江相接前汉杨恽传斗酒自劳南史梁昭明太子遍读五经通讽诵"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗镜》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩鏡_(四庫全書本)）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11544":["移居夔州郭","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["伏枕云安县，迁居白帝城。","春知催柳别，江与放船清。","农事闻人说，山光见鸟情。","禹功饶断石，且就土微平。"],"",[["古注·《杜詩詳註》","或为郭黄鹤注此大厯元年春晚作唐书䕫州云安属山南东道寰宇记䕫州云安县上水去䕫州奉节县二百四十三里"],["古注·《杜詩詳註》","首二记行踪二四承云安言临去时景五六承白帝言迁後景事末言移居之故春知别意江与清波此从无情处看出有情农事方兴春已暮矣鸟悦山光春气暖也多断石谓云安以下土微平见夔州可居杜臆农事闻人説便有为农意後果有瀼西督耕之举张溍注因灞桥赠别故事遂用春栁催别但春知江与二语後人用之易涉於纤宋之问诗春迟栁暗催常建诗山光悦鸟性潭影空人心为殷璠首推不知出於少陵也杜臆见鸟情属人悦鸟性属鸟左传见河洛者思禹功水经注广谿峡乃三峡之首葢自夏禹疏凿以通江者王洙注沿峡皆因开凿而成故少平土惟䕫州稍平耳"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11545":["船下夔州郭宿雨湿不得上岸别王十二判官","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["依沙宿舸船，石濑月娟娟。","风起春灯乱，江鸣夜雨悬。","晨钟云外湿，胜地石堂烟。","柔橹轻鸥外，含凄觉汝贤。"],"大歴元年䕫州所作",[["古评·《唐诗镜》","三四精刻"],["古评·《唐诗品汇》","大歴元年䕫州所作"],["古评·《唐诗品汇》","刘云精章不刋"],["古注·《杜詩詳註》","鹤注大厯元年春晚自云安迁居䕫州时作郭宿宿於云安郭外王判官葢在云安也"],["古注·《杜詩詳註》","晋作岸一作外杜臆作径"],["古注·《杜詩詳註》","上四宿郭遇雨夜中之景五六岸湿难上早起之景末因不得面别而留诗致王张逺注宿船见月忽而风起雨悬直至钟响烟生从薄暮至平明景象厯厯清出晨钟胜地畧读风起句下因上江鸣句上因下杜臆柔橹相送轻鸥伴行橹鸥之外但觉汝贤此感判官之厚亦怆人情之薄方言江湖凢大船曰舸尔雅水流沙石上曰濑楚辞石濑兮浅浅鲍照玩月诗娟娟似蛾眉雨落江鸣势如悬瀑写景刻画蔡邕霖雨赋悬长雨之霖霖庾信诗山寺响晨钟云外方𢎞静定为云磴王嗣奭杜臆定为云径今依晋本作云岸与题相合薛道衡诗石湿晓云浓江总诗名山极厯览胜地殊流连赵曰石堂夔州佳处烟是晨景作偏字者少理㑹古诗柔橹鸣深江谢朓诗含凄泛广川或以汝贤指鸥鸟於别王之意不合"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗镜》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩鏡_(四庫全書本)）","古籍注评：《唐诗品彚（附唐诗拾遗）》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩品彚_(四庫全書本)）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11546":["雨不绝","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["鸣雨既过渐细微，映空摇扬如丝飞。","阶前短草泥不乱，院里长条风乍稀。","舞石旋应将乳子，行云莫自湿仙衣。","眼边江舸何怱促，未待安流逆浪归。"],"",[["古注·《杜詩詳註》","梁权道依旧次编在大厯元年䕫州诗内以诗有行云莫自湿仙衣句也演义先之以鸣雨继之以微雨故题云雨不絶"],["古注·《杜詩詳註》","晋作细雨"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11547":["崔评事弟许相迎不到应虑老夫见泥雨怯出必愆佳期走笔戏简","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["江阁要宾许马迎，午时起坐自天明。","浮云不负青春色，细雨何孤白帝城。","身过花间沾湿好，醉於马上往来轻。","虚疑皓首冲泥怯，实少银鞍傍险行。"],"",[["古注·《杜詩詳註》","起结二聨宾主双闗中间四句述坐时望迎之意本是邀宾江阁许马迎天明起坐至午时两句皆用倒装法卲注江阁公所寓白帝城崔所居通首逐句顺下俱帯戏词顾注剡溪漫笔云王右军在郡迎王敬仁敬仁每用车常恶其迟後以马迎敬仁虽复风雨亦不以车也杜诗江阁邀宾许马迎用此事於泥雨甚切秦嘉诗起坐为不宁别赋龙马银鞍"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11548":["宿江边阁","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["暝色延山径，高斋次水门。","薄云岩际宿，孤月浪中飜。","鹳鹤追飞静，豺狼得食喧。","不眠忧战伐，无力正乾坤。"],"",[["古注·《杜詩詳註》","延暝色将宿之时次水门西阁之地上二㸃题中四分承山水云过山头停岩似宿月浮水靣浪动若翻此初夜之景鹳鹤飞静水边所见豺狼喧食山上所闻此夜深之景忧乱萦懐故竟夕不寐薄云岩际出初月波中上何仲言诗尚在实处摹冩此用前人成句只换转一二字间便觉㸃睛欲飞鹤注谓鹳鹤喻军士豺狼喻盗贼起下战伐时蜀有崔旰之乱此诗八句皆对谢灵运诗林壑敛暝色孟子山径之蹊间襄沔记城内有髙斋梁昭明造文选处简文为晋安王时引刘孝威等於此综核诗集因号为髙斋次乃次舍之次易旅即次汉循吏传召信臣开通沟洫起水门梁简文诗寒潮浸水门杜臆名胜志载闗耆孙瞿塘闗行记则髙斋即在闗上耆孙与客饮此诵少陵薄云孤月诗叹此老具眼䕫江山麤恶唯少陵所纪处独异庾信诗云宿鳯凰门梁简文帝诗夕波照孤月左传郑翩愿为鹳其御愿为鵞抱朴子穆王南征一军"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11549":["夜宿西阁晓呈元二十一曹长","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["城暗更筹急，楼高雨雪微。","稍通绡幕霁，远带玉绳稀。","门鹊晨光起，墙乌宿处飞。","寒江流甚细，有意待人归。"],"",[["古注·《杜詩詳註》","子丈切顾宸注大厯元年公自云安县至夔州秋寓於西阁终嵗居之明年春始自西阁迁居赤甲故凢西阁诸诗皆自秋及冬作也黄鹤及千家注分为两时俱失考公昔曽与元同曹故曰曹长"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11550":["西阁口号","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["山木抱云稠，寒江绕上头。","雪崖才变石，风幔不依楼。","社稷堪流涕，安危在运筹。","看君话王室，感动几销忧。"],"",[["古注·《杜詩詳註》","上四冩西阁景下四寄元曹长隂云绕树寒气盘空故雷沾石变而风𦂳幔飘堪流涕世乱未已在运筹谋国待人二句述元君话中之意感动销忧喜留心王室者尚有同志也前首未及呈元意故此章特详之顾注谓杜鸿渐不能征讨请以节制譲旰运筹无䇿系蜀安危公故闻而流涕据诗云社稷王室应指朝政"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11551":["西阁雨望","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["楼雨沾云幔，山寒着水城。","径添沙面出，湍减石棱生。","菊蘂凄疎放，松林驻远情。","滂沱朱槛湿，万虑傍檐楹。"],"",[["古注·《杜詩詳註》","此下五章皆属大厯元年"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11552":["不离西阁二首 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["江柳非时发，江花冷色频。","地偏应有瘴，腊近已含春。","失学从愚子，无家住老身。","不知西阁意，肯别定留人。"],"",[["古注·《杜詩詳註》","此亦大厯元年冬作杜臆题曰不离有厌居西阁意"],["古注·《杜詩詳註》","首章对景感懐向西阁作问词非时先发当冷频开此见地暖含春也失学阁中之事无家居阁之故末乃久客无聊之语赵注言西阁之意肯令我别乎抑亦定留人也顾注公诗用定字有两义定卜瀼西居是决词肯别定留人是疑词杭州定越州亦然陶诗心逺地自偏"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11553":["不离西阁二首 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["西阁从人别，人今亦故亭。","江云飘素练，石壁断空青。","沧海先迎日，银河倒列星。","平生耽胜事，吁骇始初经。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11554":["西阁三度期大昌严明府同宿不到","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["问子能来宿，今疑索故要。","匣琴虚夜夜，手板自朝朝。","金吼霜钟彻，花催腊炬销。","早凫江槛底，双影漫飘颻。"],"",[["古注·《杜詩詳註》","唐书大昌县属䕫州"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11555":["西阁二首 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["巫山小摇落，碧色见松林。","百鸟各相命，孤云无自心。","层轩俯江壁，要路亦高深。","朱绂犹纱帽，新诗近玉琴。","功名不早立，衰病谢知音。","哀世非王粲，终然学越吟。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11556":["西阁二首 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["嬾心似江水，日夜向沧洲。","不道含香贱，其如镊白休。","经过调碧柳，萧索倚朱楼。","毕娶何时竟，消中得自由。","豪华看古往，服食寄冥搜。","诗尽人间兴，兼须入海求。"],"",[["古注·《杜詩詳註》","去声一作意"],["古注·《杜詩詳註》","次章有不欲留阁之意起句托景言情叹衰白休官不如身赴沧洲也今但凴楼对栁亦何为者俟男婚巳毕消病可痊行当长往耳且㸔豪华易过何如服食引年入海求仙乎仍结到欲往沧洲意此各四句分截公尝云到今有余恨不得穷扶桑云云蓬莱如可到衰白问神仙其语谆谆似欲为长生之学者然实不得志於时而托言遯世耳犹孔子乗桴浮海之叹欤吕氏春秋水泉东流日夜不休神异经东海沧浪之洲汉官仪尚书郎握兰含鸡舌香奏事镊白用齐髙祖事注见七巻楚词萧瑟兮草木摇落而变衰冯衍赋伏朱楼而四望後汉书向子平男女嫁娶毕敕断家事弗复相"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11557":["阁夜","杜甫","七言律诗","大历元年（766）冬","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["岁暮阴阳催短景，天涯霜雪霁寒宵。","五更鼓角声悲壮，三峡星河影动摇。","野哭几家闻战伐，夷歌数处起渔樵。","卧龙跃马终黄土，人事依依漫寂寥。"],"大历元年（766）冬，杜甫寓居夔州西阁。时蜀中崔旰之乱未平，吐蕃入侵，战乱频仍。杜甫夜宿西阁，闻鼓角之声，感战乱之苦，遂作此诗。",[["1. **阴阳**","指日月。"],["2. **短景**","冬日昼短，故曰短景。"],["3. **霁**","雪止。"],["4. **鼓角**","军中之鼓与号角。"],["5. **星河**","银河。"],["6. **野哭**","野外之哭声。"],["7. **夷歌**","少数民族之歌谣。"],["8. **卧龙**","诸葛亮。"],["9. **跃马**","公孙述，跃马称帝于蜀。"],["古注·《杜詩詳註》","一作数一作是"],["古评·《诗人玉屑》","自老杜……与等句之後，当恨无复继者"]],{"source":"据霍松林《唐诗鉴赏辞典》“阁夜”条（上海辞书出版社，1983 年版）","body":["首联写出诗人异乡作客的无限感慨，意境开阔雄浑，感情沉郁悲凉。出句中“岁暮”，指冬季；“阴阳”，指日月；“短景”，指冬天日短。此联中“催”字颇为灵动，说明夜长昼短，使人觉得光阴荏苒，岁序逼人。对句又有天涯沦落，独伤老大的意思。诗人对此霜雪已停、雪明如昼的凄凉夜晚，不由感慨万千。","尾联在杜甫手里不但顺利地完成全诗的起承转合，而且颇见老到。这两句作者说：诸葛亮和公孙述，一样最终归于黄土；人事变迁，音书断绝，使人感到寂寞无聊，但又算得了什么？“漫”，任随。“卧龙跃马”和“人事音书”都是并列结构。“卧龙”，指诸葛亮。“跃马”，指公孙述。公孙述在西汉末曾乘乱据蜀，自称白帝。这里用晋左思《蜀都赋》“公孙跃马而称帝”之意，诸葛亮和公孙述都曾在夔州活动。尾联看似自宽自慰，实则有着诗人深入的思虑。诗人不只是一般地描写战乱，而是将眼前的动荡放到更深广的历史背景中去思考。他在告诉读者：古往今来，不论贤愚忠逆，最终都不免归卧黄土；战争无论延续多久，终会结束；生命无论受到多少摧残，总会延续。","中间两联对仗尤佳。“鼓角”对“星河”，“战伐”对“渔樵”，都是并列词组相对。对仗中的数量词，一般只能对数量词。这里“五更”对“三峡”，“千家”对“数处”都是工对。写诗的人，要想做到工对，不是很困难的事，但是想要达到杜甫的意境可就难了。你看颔联：五更时分传来的鼓角声，起伏悲壮；三峡倒映着银河星辰，随着江波动摇。出句重在写“声”，重在写听觉，对句重在写“色”，重在写视觉，真可谓有声有色。愁人不寐，五更犹闻鼓角，是何等悲壮感人；大江流动群星，又与诗人流落的身世何等相似！出现在诗人笔下的景色，是饱含着诗人丰富感情的艺术形象，蕴含着诗人无限的情思。宋人叶梦得说：“七言难于气象雄浑，句中有力而纡余，不失言外之意。自老杜‘锦江春色来天地，玉垒浮云变古今’与‘五更鼓角声悲壮，三峡星河影动摇’等句之后，常恨无复继者。”（《石林诗话》卷下）说“无复继者”，那倒未必，但是这两句诗确实意境雄浑而又含蓄深刻，富有感人的艺术效果。再看颈联：一闻战伐，千家皆哭，可见死者之多；拂晓即传来当地少数民族捕鱼打柴人的歌声，可见劳者之痛。这两句把偏远的夔州的典型环境刻画得很真实。颔联出句和对句都是写听觉，仔细品味可以猜度出句写近处，对句写远处。由此种种声音，衬托出诗人心绪不宁。这些，后人要继承杜甫，委实不易，要超过杜甫，几乎没有可能。"]},[["五更鼓角声悲壮，三峡星河影动摇。","千古名句，气象悲壮。"]],["https://github.com/chinese-poetry/chinese-poetry","据霍松林《唐诗鉴赏辞典》“阁夜”条（上海辞书出版社，1983 年版）","《全唐诗》（清·曹寅等编，康熙扬州诗局本）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）","古籍注评：《诗人玉屑》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/詩人玉屑_(四庫全書本)）"]],"open_11558":["西阁夜","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["恍惚寒山暮，逶迤白雾昏。","山虚风落石，楼静月侵门。","击柝可怜子，无衣何处村。","时危关百虑，盗贼尔犹存。"],"",[["古注·《杜詩詳註》","洪注从江别作山者犯重"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11559":["瀼西寒望","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["水色含羣动，朝光切太虚。","年侵频怅望，兴远一萧疎。","猨挂时相学，鸥行炯自如。","瞿唐春欲至，定卜瀼西居。"],"",[["古注·《杜詩詳註》","鹤注此是大厯元年冬作明年春迁居赤甲三月迁瀼西"],["古注·《杜詩詳註》","此诗扼题在三四为上下关纽年侵频望㸃明寒望兴逺萧疎望时所见杜臆水色朝光此萧疎之逺而大者猿挂鸥行此萧疎之近而小者瀼西卜居又结出望中之意又云水色含羣动即寒水光难定变语也朝光切太虚即早霞随类影变景也皆公㝠搜所得日映水靣其色闪动朝光初起切近太虚此以一俯一仰对言赵汸注时相学冩猿之戏狎炯自如冩鸥之明洁此以在山在水对言年侵照春至是伤嵗暮不是恨年衰杜臆年侵怅望初非乐事乃因频望而发兴遂有此一叚光景无边际无絓碍直神与境㑹意超象外矣陶潜诗日入羣动息鲍照诗朝光散流霞天台赋太虚寥廓陆机诗後望随年侵谢灵运游名山志观挂猿下饮百丈相连呉均诗猿挂似悬𤓰"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11560":["入宅三首 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["奔峭背赤甲，断崖当白盐。","客居愧迁次，春酒渐多添。","花亚欲移竹，鸟窥新卷帘。","衰年不敢恨，胜概欲相兼。"],"",[["古注·《杜詩詳註》","朱注年谱大厯二年春自西阁迁居赤甲鹤注赤甲瀼西皆在奉节县北三十里"],["古注·《杜詩詳註》","一作酒非"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11561":["入宅三首 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["乱後居难定，春归客未还。","水生鱼复浦，云暖麝香山。","半顶梳头白，过眉拄杖斑。","相看多使者，一一问函关。"],"",[["古注·《杜詩詳註》","首章志赤甲之胜此诗八句整对而□实相间首聨宅外景三聨宅内景春色起花鸟胜㮣总六句顾注背赤甲之奔峭当白盐之断崖以二山形势明宅之向背花厌竹枝爱花故须移竹鸟常入室巻帘故复来窥藉此娱之故不恨屡迁谢灵运诗徒旅苦奔峭邵注山峯高峻如奔涌然又云赤甲城是鱼复县旧基故云水生鱼复浦白盐注见十五巻洙曰次舍也迁次移居也诗谈二编杜审言枝亚果新肥孟东野南浦红花亚水红包佶多年亚石松方干候先开亚木枝亚义如压言低披也黄注亚乃相依之意王嗣奭曰避乱奔走无日不思故乡造次移居必择胜地且加修葺㸃缀如此襟懐自不可及郭林宗逆旅经过必洒扫王子猷借居必种竹意正相同"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11562":["入宅三首 三","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["宋玉归州宅，云通白帝城。","吾人淹老病，旅食岂才名。","峡口风常急，江流气不平。","只应与儿子，飘转任浮生。"],"",[["古注·《杜詩詳註》","此故乡未归而叹旅居也杜臆公欲北还必过归州云通白帝见相去不逺淹老病久留白帝岂才名不如宋玉二句分承风急江翻归州且不易到何况故乡亦惟随地漂转而已杜臆三诗各一意而展转相因顾注公居赤甲本非得已故後复有瀼西之迁陆游入蜀记宋王宅在秭归县东今为酒家旧有石刻宋玉宅三字唐书归州属山南东道武徳二年析夔州之秭归巴东置湖广通志宋玉宅有两处一在归州一在荆州与杜诗相合"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11563":["赤甲","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["卜居赤甲迁居新，两见巫山楚水春。","炙背可以献天子，美芹由来知野人。","荆州郑薛寄书近，蜀客郗岑非我邻。","笑接郎中评事饮，病从深酌道吾真。"],"",[["古注·《杜詩詳註》","鹤注此与入宅诗同时作"],["古注·《杜詩詳註》","此居赤甲而念知交也在四句分截公初迁赤甲而云两见春色者自去春至夔已经两春也炙背食芹述春山景物兼有朝野濶絶之感郑薜在荆寄诗颇近郄岑在蜀渐与之逺惟接郎中评事喜得酌酒而道真精列子宋国有田父东作曝於日不知有绵纩狐貉谓其妻曰负日之暄人莫知之以献吾君将有重赏里之富室告之曰昔人有美戎菽甘枲茎芹萍子对乡豪称之乡豪取尝之蜇於口惨於腹衆哂而怨之子此类也嵇康絶交书野人有快炙背而美芹子者欲献之至尊虽有区区之意亦已疎矣鹤注郑是江陵郑少尹审薛是石首薛明府璩岑是岑嘉州参郄是梓州郄使君昻评事必崔十三评事公在夔州多有诗与之顾注郎中应是呉郎司法葢刑曹也朱注文苑英华有苻载志杨鸥墓云永泰二载相公杜公鸿渐奏授鸥犀浦县令僚友杜员外甫岑郎中参郄舍人昻闻公殒落失声咨嗟则郄为郄昻无疑曹植髑髅説是反吾真也"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11564":["卜居","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["归羡辽东鹤，吟同楚执珪。","未成游碧海，着处觅丹梯。","云障宽江左，春耕破瀼西。","桃红客若至，定似昔人迷。"],"",[["古注·《杜詩詳註》","此是大厯二年自赤甲将迁居瀼西而作"],["古注·《杜詩詳註》","上四客居有感下欲托居瀼西也丁公魂归故里庄舄病而吟越皆不忘故乡者故借以自方碧海丹梯叹不能水行而复山栖江北即瀼西其地寛平故可耕种杜臆公以此地为桃源直作避秦计矣辽东华表柱有鹤栖其上曰有鸟有鸟丁令威去家千里今始归城郭如故人民非何不学仙塜累累选注越人庄舄起家寒微为楚执珪有病犹为越吟十洲记扶桑之东有碧海谢灵运诗洒歩临丹梯破是破土希曰瀼溪在白帝城之东昔人迷指刘晨阮肇"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11565":["暮春题瀼西新赁草屋五首 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["久嗟三峡客，再与暮春期。","百舌欲无语，繁花能几时。","谷虚云气薄，波乱日华迟。","战伐何由定，哀伤不在兹。"],"",[["古注·《杜詩詳註》","年谱大厯二年自赤甲将迁居瀼西而作"],["古注·《杜詩詳註》","首章题瀼西暮春中四冩季春时景末二伤心世乱为後两章伏脉杜臆久客而再逢暮春见非初意百舌二句见物候易迁谷虚二句见瀼土堪适谷内云升春晴故薄波中日漾春长故迟不在兹言岂不在此战伐赵曰反舌无声在芒种後十日今欲无语则暮春时矣谢朓诗日华川上动"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11566":["暮春题瀼西新赁草屋五首 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["此邦千树橘，不见比封君。","养拙干戈际，全生麋鹿羣。","畏人江北草，旅食瀼西云。","万里巴渝曲，三年实饱闻。"],"",[["古注·《杜詩詳註》","次章题瀼西赁居地産贫瘠而托居於此不过为养拙全生计耳身际干戈故畏人而依江北之草同群麋鹿故旅食而伴瀼西之云三年闻曲即所谓久嗟三峡客也公自永泰元年秋之云安至此为三年在夔州逢春则再度矣史货殖传封者衣租税千户之君嵗率二十万蜀汉江陵千树橘其人皆与千戸侯等絶交论独立高山之顶懽与麋鹿同群魏文帝诗客子常畏人汉礼乐志巴渝鼓员三十六员注高帝初为汉王得巴渝趫捷人与之定三秦灭楚存其乐为巴渝乐巴州在今夔州府渝州今在重庆府"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11567":["暮春题瀼西新赁草屋五首 三","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["彩云阴复白，锦树晓来青。","身世双蓬鬓，乾坤一草亭。","哀歌时自短，醉舞爲谁醒。","细雨荷锄立，江猨吟翠屏。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11568":["暮春题瀼西新赁草屋五首 四","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["壮年学书劒，他日委泥沙。","事主非无禄，浮生即有涯。","高斋依药饵，绝域改春华。","丧乱丹心破，王臣未一家。"],"",[["古注·《杜詩詳註》","一作无非"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11569":["暮春题瀼西新赁草屋五首 五","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["欲陈济世策，已老尚书郎。","未息豺虎鬬，空慙鸳鹭行。","时危人事急，风逆羽毛伤。","落日悲江汉，中宵泪满床。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11570":["园","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["仲夏流多水，清晨向小园。","碧溪摇艇阔，朱果烂枝繁。","始爲江山静，终防市井喧。","畦蔬绕茅屋，自足媚盘餐。"],"",[["古注·《杜詩詳註》","此是大厯二年夏瀼西所作瀼西草屋公所居也园隔瀼西之溪别有茅舍"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11571":["竖子至","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["樝梨且缀碧，梅杏半传黄。","小子幽园至，轻笼熟柰香。","山风犹满把，野露及新尝。","欲寄江湖客，提携日月长。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11572":["示獠奴阿段","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["山木苍苍落日曛，竹竿褭褭细泉分。","郡人入夜争余沥，竖子寻源独不闻。","病渴三更回白首，传声一注湿青云。","曾惊陶侃胡奴异，怪尔常穿虎豹羣。"],"",[["古注·《杜詩詳註》","此为獠童引泉而作也上四引泉之事下则泉至而喜生注争沥不闻而寻源则往视世之狃小利而忽逺图避独劳而诿公事者其贤逺矣故诗特表之溍注传声一注状其从髙下注也诗籊籊竹竿淳于髠曰持酒於前时赐余沥温子昇诗传声逓响何凄凉张九龄望瀑布诗洒流湿行云此诗湿青云本之西王母吟虎豹为羣乌雀与处"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11573":["秋野五首 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["秋野日疏芜，寒江动碧虚。","系舟蛮井络，卜宅楚村墟。","枣熟从人打，葵荒欲自锄。","盘餐老夫食，分减及溪鱼。"],"易识浮生理难教一物违水深鱼极乐林茂乌知归吾老甘贫病荣华有是非秋风吹几杖不厌北山薇礼乐攻吾短山林引兴长",[["古注·《杜詩詳註》","鹤注当是大厯二年瀼西作"],["古注·《杜詩詳註》","旧作蔬非一作荒"],["古注·《杜詩詳註》","一作路黄生作落"],["古评·《瀛奎律髓》","易识浮生理难教一物违水深鱼极乐林茂乌知归吾老甘贫病荣华有是非秋风吹几杖不厌北山薇礼乐攻吾短山林引兴长掉头纱㡌侧曝背竹书光风落收松子天寒割蜜房稀疎小红翠驻屐近微香逺岸秋沙白连山晚照红潜鳞输骇浪归翼㑹髙风砧响家家发樵声个个同飞霜任青女赐被隔南宫身许麒麟画年衰鸥鹭羣大江秋易盛空峡夜多闻迳隠千重石帆留一片云儿童解蛮语不必作参军读老杜此五诗不见所谓景联亦不见所谓颔联何处是四虚何处是四实虚中有实实中有虚景可为颔颔可为景大手笔混混乎无穷也却有一絶不可及处五首诗五个结句无不吃紧着力未尝有轻易放过也然则真积力久亦在乎熟之而已或问吾老系单字荣华是双字亦可对否曰在老杜则可若我辈且当作衰老甘贫病然不如吾老之语健意足也"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）","古籍注评：《瀛奎律髓》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/瀛奎律髓_(四庫全書本)）"]],"open_11574":["秋野五首 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["易识浮生理，难教一物违。","水深鱼极乐，林茂鸟知归。","吾老甘贫病，荣华有是非。","秋风吹几杖，不厌此山薇。"],"",[["古注·《杜詩詳註》","首章记秋野景事系舟承江卜宅承野枣熟葵荒卜居之事减食饲鱼系舟之兴此下数章多以首二句为主疏芜收获巳毕野色萧疎也碧虚波光相荡水天一色也杜臆系舟卜宅去住尚难自决也枣从人打则人巳一视葵欲自锄则贵贱一视食及溪鱼则物我一视此皆见道语萧子范诗云昇秋野平谢朓诗邑里向疏芜吴均诗飘飘上碧虚扬雄蜀都赋稽乾度则井络储精左思蜀都赋岷山之精上为井络注岷山之地上为东井络维也䕫州属楚即荆蛮地庾信赋揺落小村墟公诗堂前扑枣任西隣又诗自锄新菜甲周靖曰华严经十布施内有分减布施"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11575":["秋野五首 三","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["礼乐攻吾短，山林引兴长。","掉头纱帽仄，曝背竹书光。","风落收松子，天寒割蜜房。","稀疎小红翠，驻屐近微香。"],"",[["古注·《杜詩詳註》","次章言秋野可以避世欲识浮生之理即观物情可见如鱼鸟藏身此物情之近理者今亦惟托迹山林以顺浮生之理而已三四承次句五六承首句脉络固然须知三四仍是借物兴已语气方见融贯赵汸谓以达生处已以遂性待物将两句开说不合语意视此生若浮则贫病可安而荣华不足羡矣杜臆几杖言老山薇言贫庄子其生也若浮江淹诗一物之微有足悲者淮南子水深则鱼聚水茂则鸟乐赵汸注甘贫病者为避是非也下句申上句谢朓诗敢忘恤贫病管子万物荣华庄子此亦一是非月令养衰老授几杖北山北崦也史记夷齐隠於首阳山采薇而食陆玑曰薇山菜也塟叶似小荳蔓生味如荳藿亦可食"],["古注·《杜詩詳註》","三章见秋野可以自娱承上北山薇来首聨总提短长二字另读掉头二句言检身之疎所谓短於礼乐也风落四句言野居之适所谓山林兴长也或将山林领下六句则起句无照应矣纱帽侧指㡌影斜侧竹书光谓书映日光两句例看自明庄子礼乐之士敬容攻治也庄子入山林观天性黄生注三四与吟诗坐回首随意葛巾低正可㕘看庄子在宥篇雀跃掉头纱帽见管宁纱㡌静注隋书独孤信举止风流曾风吹帽檐侧观者塞路秦国䇿暴背而耨晋书荀朂领秘书监汲郡冢中得竹书赵注竹书竹简之书列仙传偓佺好食松实以松子遗尧尧不暇服也时受服者皆至二三百岁洙曰蜜房蜂房也班固终南颂蜜房溜其巅左思蜀都赋蜜房郁毓被其阜"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11576":["秋野五首 四","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["远岸秋沙白，连山晚照红。","潜鳞输骇浪，归翼会高风。","砧响家家发，樵声个个同。","飞霜任青女，赐被隔南宫。"],"",[["古注·《杜詩詳註》","四章见秋野无羡於荣禄承上山林兴来首句秋景次句晚景三四俯仰所见五六逺近所闻毎句各兼秋晚两意末叹寒色凄凉山林与廊庙判隔矣输如输送之输是逐浪而去㑹如际㑹之㑹是顺风而回杜臆南宫之赐被已隔则飞霜聴之青女而巳南都赋川渎则箭驰风疾长输逺逝注输泻也是泻去之义江赋骇浪暴洒惊波飞薄张翰曰如归翼得高风翺翔投林中魏文帝诗适与飘风㑹谢恵连诗櫊高砧响发淮南子秋三月青女出以降霜高诱注青女天神主霜雪汉旧仪郎官给青缣白绫被或锦被後汉书药崧家贫为郎常独直台上无被枕杫帝闻而嘉之诏给帷被皂袍"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11577":["秋野五首 五","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["身许麒膦画，年衰鸳鹭羣。","大江秋易盛，空峡夜多闻。","径隐千重石，帆留一片云。","儿童解蛮语，不必作参军。"],"",[["古注·《杜詩詳註》","末章身在秋野而自伤留滞也承上隔南宫来上二客䕫之故下皆对景述情老别鸳班徒负许身初志唯有卧病江峡而已秋易盛浪高水涨夜多闻风怒兽号径隠石避地已深帆片云归航在望五六分顶峡江而意却注下杜臆末叹客巴日久语帯谑词世说郝隆为蛮府参军上已日作诗曰娵隅跃青池桓温问何物答曰蛮名鱼为娵隅温曰何为作蛮语隆曰千里投公始得蛮府参军那得不蛮语也前三章叙日间景事第四章则自日而晚末一章则自晚而夜矣凡杜诗连叙数首必有层次安顿其细于诗律如此"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11578":["溪上","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["峡内淹留客，溪边四五家。","古苔生迮地，秋竹隐疎花。","塞俗人无井，山田饭有沙。","西江使船至，时复问京华。"],"",[["古注·《杜詩詳註》","鹤注此当是大厯二年秋在瀼西作"],["古注·《杜詩詳註》","音摘一作窄或作湿"],["古注·《杜詩詳註》","逺注中四溪上景末聨溪上情顾注乆客孤村首聨写得荒凉杜臆苔生花隐聊以自适无井有沙差可相安问京华有二意乱定可以北归乱未定不如姑留溪上也董斯张曰苕陵苕也诗疏生下湿水中八九月花图经浙有苕溪以岸多苕花也杜故于溪上诗言之今按苔可云古苕不可云古还作苔为当"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11579":["树间","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["岑寂双甘树，婆娑一院香。","交柯低几杖，垂实碍衣裳。","满岁如松碧，同时待菊黄。","几回沾叶露，乘月坐胡牀。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11580":["课小竖鉏斫舍北果林枝蔓荒秽净讫移牀三首 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["病枕依茅栋，荒鉏净果林。","背堂资僻远，在野兴清深。","山雉防求敌，江猨应独吟。","泄云高不去，隐几亦无心。"],"",[["古注·《杜詩詳註》","一云秋日闲居三首鹤注当是大厯二年瀼西作陶潜诗晨兴理荒秽杜臆牀藜牀也公视园诗衰年动觅藜牀坐可证"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11581":["课小竖鉏斫舍北果林枝蔓荒秽净讫移牀三首 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["衆壑生寒早，长林卷雾齐。","青虫悬就日，朱果落封泥。","薄俗防人面，全身学马蹄。","吟诗坐回首，随意葛巾低。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11582":["课小竖鉏斫舍北果林枝蔓荒秽净讫移牀三首 三","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["篱弱门何向，沙虚岸只摧。","日斜鱼更食，客散鸟还来。","寒水光难定，秋山响易哀。","天涯稍曛黑，倚杖更裴回。"],"",[["古注·《杜詩詳註》","邵经邦曰暗牖悬蛛网空梁落燕泥古今以为佳句余恨其惨澹凄凉类鬼仙语宜乎其罹害也不若青䖝悬就日朱果落封泥穠丽闲雅景象自别黄生曰杨子法言云貌则人心则兽庄子马蹄篇云至徳之世同与禽兽居族与万物并恶乎知君子小人哉此言薄俗人心叵测惟以浑同之道处之庶可全身逺害上句以人面影兽心下句以篇题括篇意如此用事真出神入化矣又曰观此二诗则知此地人情之薄不及浣花邻曲多矣故遣闷诗有云异俗吁可怪斯人难并居"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11583":["寒雨朝行视园树","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["柴门杂树向千株，丹橘黄甘此地无。","江上今朝寒雨歇，篱中秀色画屏纡。","桃蹊李径年虽故，栀子红椒艳复殊。","鏁石藤稍元自落，倚天松骨见来枯。","林香出实垂将尽，叶蔕辞枝不重苏。","爱日恩光蒙借贷，清霜杀气得忧虞。","衰颜更觅藜床坐，缓步仍须竹杖扶。","散骑未知云阁处，啼猨僻在楚山隅。"],"",[["古注·《杜詩詳註》","一作边新"],["古注·《杜詩詳註》","扶又切一作色"],["古注·《杜詩詳註》","义从平声读用去声"],["古注·《杜詩詳註》","次申篱中秀色桃李椒栀藤梢松骨所谓拥树也林香出实叶蒂辞枝所谓甘橘也爱日清霜寒天朝景借贷忧虞代为园树计也汉书李广传賛桃李不言下自成蹊顔师古注蹊为径道重苏犹云复生左传注冬日可爱江淹上建平王书恵以恩光顾以顔色赵次公曰仲秋之月杀气浸盛"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11584":["季秋江村","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["乔木村墟古，疎篱野蔓悬。","清琴将暇日，白首望霜天。","登俎黄甘重，支床锦石圆。","远游虽寂寞，难见此山川。"],"",[["古注·《杜詩詳註》","鹤注当是大厯二年作"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11585":["小园","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["由来巫峡水，本自楚人家。","客病留因药，春深买爲花。","秋庭风落果，瀼岸雨颓沙。","问俗营寒事，将诗待物华。"],"",[["古注·《杜詩詳註》","上四置园之故五六园前景七八园中事巫峡之水本楚人所居今置园於此者总为莳药种花计耳畱买指园黄生注此诗秋时所作春深而买追忆前事寒事物华又豫计冬春也杜臆园中寒事如秋药冬菁皆是"],["古注·《杜詩詳註》","素不习惯故问俗而营又云以诗叙事为难在律诗尤难此章该括四时妙在错综见意陆倕诗江闗寒事早寒事御寒之事"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11586":["自瀼西荆扉且移居东屯茅屋四首 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["白盐危峤北，赤甲古城东。","平地一川稳，高山四面同。","烟霜凄野日，秔稻熟天风。","人事伤蓬转，吾将守桂丛。"],"",[["古注·《杜詩詳註》","鹤注公以大厯二年移居东屯当是其时作于□东屯少陵故居记峡中多高山峻谷地少平旷东屯距白帝五里而近稻田水畦延袤百顷前带清溪後枕高冈树林葱蒨气象深秀称高人逸士之居陆游记东屯李氏居已数世上距少陵才三易主大厯初故劵犹在何宇度谈资工部草堂在城东十余里尚有遗址可寻止有一碑存数字题重修东屯草堂记似是元物"],["古注·《杜詩詳註》","首章叙移居之事上四东屯地势五六东屯秋景末㸃居屯之意後有寄裴施州诗云几度附书白盐北可见东屯在白盐之北赤甲之东矣霜烟凄野日下半句因上秔稻熟天风上半句因下顾注公自冬寓夔之西阁再𨗇赤甲三𨗇瀼西今又𨗇东屯一岁四𨗇不啻如飘蓬之转故欲守此而不移也邵注山峻而高曰峤秔稻粳米也谢灵运诗序石门新营所住四面高山周王褒诗庭昏野日黄刘安招隠士桂树丛生兮山之幽曰桂丛时盖八月矣"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11587":["自瀼西荆扉且移居东屯茅屋四首 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["东屯复瀼西，一种住青溪。","来往皆茅屋，淹留爲稻畦。","市喧宜近利，林僻此无蹊。","若访衰翁语，须令賸客迷。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11588":["自瀼西荆扉且移居东屯茅屋四首 三","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["道北冯都使，高斋见一川。","子能渠细石，吾亦沼清泉。","枕带还相似，柴荆即有焉。","斫畲应费日，解缆不知年。"],"",[["古注·《杜詩詳註》","次章写居屯之故东西两舍总在清溪今特移屯者一为获稻而来一为避喧而至也过客易迷言地僻不减桃源一种一様也市喧指瀼西公诗市暨瀼西头可证易㢲为近利市三倍庾信赋晏婴近市不求朝夕之利曹植诗欲还絶无蹊陆机诗游赏愧賸客賸言其多也"],["古注·《杜詩詳註》","三章叙东屯隣居之胜都使高斋隔川望见故彼渠此沼共在一川朱注林泉枕带两家相似故柴门之外即可兼而有之斫畲种植应费时目则解䌫而去正未有期也北道谓东屯之北陆游少陵髙斋记少陵居夔三徙居皆名高斋其诗曰次水门者白帝城之高斋也曰依药饵者瀼西之高斋也曰见一川者东屯之高斋也故又曰高斋非一处今按高斋见一川紧接道北冯都使则高斋当属冯氏之居大约集中高斋有就他人言者如高斋坐林杪是白水崔少府之斋有就自已言者如高斋常见野是梓州所寓之居此皆可证赵汸云渠之沼之实字作活字用逺注细石通渠清泉作沼两句用倒装法北史韦夐淡於营利所居之宅枕带林泉对玩琴书萧然自逺申𣹢光曰柴荆即有焉不成句法薛梦符曰荆楚多畲田先纵火烧炉𠉀经雨下种盖田厯三岁土脉已竭不可复树艺故须烧榛以肥其土尔雅田三岁曰畲刘梦得竹枝歌长刀短笠去烧畲扬雄太𤣥经徒费日也谢灵运诗解缆候前侣"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11589":["自瀼西荆扉且移居东屯茅屋四首 四","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["牢落西江外，参差北户间。","久游巴子国，卧病楚人山。","幽独移佳境，清深隔远关。","寒空见鸳鹭，回首忆朝班。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11590":["茅堂检校收稻二首 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["香稻三秋末，平田百顷间。","喜无多屋宇，幸不碍云山。","御裌侵寒气，尝新破旅颜。","红鲜终日有，玉粒未吾悭。"],"",[["古注·《杜詩詳註》","此是大厯二年东屯作卢注瀼西有果园而无稻田公以课园责之竪子以稻畦责之行官前诗自明鹤注作瀼西茅屋误矣"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11591":["茅堂检校收稻二首 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["稻米炊能白，秋葵煮复新。","谁云滑易饱，老藉软俱匀。","种幸房州熟，苗同伊阙春。","无劳映渠盌，自有色如银。"],"",[["古注·《杜詩詳註》","此章叙东屯收稻之事上四喜茅堂地旷下四喜检校多获杜臆络绎收回故云终日有写出贫家暴富光景诗如三秋兮百顷通计屯内之田非公有百顷也秋兴赋藉莞蒻御裌衣吕氏春秋孟秋之月农乃升谷天子尝新逺注稻有红白二种红鲜红稻种名李百药诗落日照红鲜沈约诗玉粒晨炊"],["古注·《杜詩詳註》","次章尝稻而嘉其色味上四以秋葵形稻米五六以故乡嘉种比东屯美稻皆借客意相形滑指葵软指饭俱匀言二物配食如银言其白可爱自秦陇赴蜀十载流离今见秋成刈获故庆有年而喜旅食次年适荆南又有朝夕不给之忧矣唐书房州房陵郡属山南东道武徳元年析迁州之竹山上庸置顾注伊阙县属河南府公有庄墅在焉魏文帝车渠盌赋序车渠玉属也多纤理缛文生於西国其俗寳之陆倕蠡杯铭用迈羽盃珍逾渠盌渠盌以渠石为盌晋白紵质如轻云色如银顾云此与莫笑田家老瓦盆倾银注玉惊人眼同意"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11592":["东屯月夜","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["抱疾漂萍老，防边旧谷屯。","春农亲异俗，岁月在衡门。","青女霜枫重，黄牛峡水喧。","泥留虎鬬迹，月挂客愁村。","乔木澄稀影，轻云倚细根。","数惊闻雀噪，暂睡想猨蹲。","日转东方白，风来北斗昏。","天寒不成寝，无梦寄归魂。"],"",[["古注·《杜詩詳註》","从东屯叙起杜臆据困学记闻东屯之田公孙述所开以积谷养兵者故云防边旧榖屯自春至秋故云岁月诗衡门之下"],["古注·《杜詩詳註》","中记月夜之景秋深故霜落重夜静故水声喧虎留迹见地险月挂村见身孤稀影木梢叶脱细根云起石边青女注见本巻杜臆黄牛峡在夷陵而此云黄牛峡水喧又寄弟诗云青春不假报黄牛意䕫州亦有此峡但今不可考耳吴均诗挂月青山下张协诗云根临八极杜臆石为云根拆用自新"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11593":["东屯北崦","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["盗贼浮生困，诛求异俗贫。","空村惟见鸟，落日未逢人。","步壑风吹面，看松露滴身。","远山回白首，战地有黄尘。"],"",[["古注·《杜詩詳註》","鹤注当是大厯二年秋作是年有栁灵州之寇故云战地北崦东屯之北山阿也"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11594":["从驿次草堂复至东屯二首 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["峡内归田客，江边借马骑。","非寻戴安道，似向习家池。","峡险风烟僻，天寒橘柚垂。","筑场看敛积，一学楚人爲。"],"",[["古注·《杜詩詳註》","一本无茅屋二字鹤注当是大厯二年冬作此从驿借马暂次瀼西之草堂而复至东屯也"],["古注·《杜詩詳註》","一作地一作峡"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11595":["从驿次草堂复至东屯二首 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["短景难高卧，衰年强此身。","山家蒸栗暖，野饭射麋新。","世路知交薄，门庭畏客频。","牧童斯在眼，田父实爲邻。"],"",[["古注·《杜詩詳註》","此章从驿次至东屯下四叙其景事公骑马不乘船故非访戴而似向习恨赋罢归田里诗九月筑场圃申𣹢光曰道池假对句法亦竒戴安道见二十一巻习家池见四巻"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11596":["暂往白帝复还东屯","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["复作归田去，犹残获稻功。","筑场怜穴蚁，拾穗许村童。","落杵光辉白，除芒子粒红。","加餐可扶老，仓庾慰飘蓬。"],"",[["古注·《杜詩詳註》","鹤注此大厯二年秋作"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11597":["刈稻了咏怀","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["稻获空云水，川平对石门。","寒风疎落木，旭日散鸡豚。","野哭初闻战，樵歌稍出村。","无家问消息，作客信乾坤。"],"刘云初闻其战後见野哭而已五字悲甚稍字尤萧索可怜结意沉着非托之悠悠者",[["古评·《唐诗镜》","三四老而得雅"],["古评·《唐诗品汇》","刘云初闻其战後见野哭而已五字悲甚稍字尤萧索可怜结意沉着非托之悠悠者"],["古注·《杜詩詳註》","鹤注此大厯二年冬作黄生注此感归期无日终年旅食故因获稻以起兴"],["古注·《杜詩詳註》","上四刈稻後野旷冬寒之景下则伤乱思归所谓咏怀也黄注三四承上五六起下此两截正格散鸡豚田有余粒也初闻战因哭而知稍出村农毕始樵杜臆兵戈定而归家此公之素志今已无家可问消息则彼此均之作客一任乾坤之位置而已意欲藉此地以偷安也黄生注东渚耗稻诗竖苗亦已穊云水涨方塘此苗在水中之景今获稻则云水为之空廓矣石门水中对立如门水落而後石出故曰平川对石门赵曰石门即所谓双崖壮此门也旧引蜀都赋阻以石门注云石门在溪中之西於此无预诗旭日始旦束晳劝农赋鸡豚争下壶榼横至前诗野哭千家闻战伐指崔旴之乱是年无事而云初"],["古评·《瀛奎律髓》","三四乃诗家句法必合如此下字则健峭後四句亦惟老杜能道之也"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗镜》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩鏡_(四庫全書本)）","古籍注评：《唐诗品彚（附唐诗拾遗）》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩品彚_(四庫全書本)）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）","古籍注评：《瀛奎律髓》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/瀛奎律髓_(四庫全書本)）"]],"open_11598":["上白帝城","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["城峻随天壁，楼高更女墙。","江流思夏后，风至忆襄王。","老去闻悲角，人扶报夕阳。","公孙初恃险，跃马意何长。"],"",[["古注·《杜詩詳註》","上四登城懐古下四登城感时随天壁依山建城也临墙遥望起下二句杨徳周曰提出夏禹楚襄便足压倒公孙子阳引出公孙跃马又足折倒崔旰之徒妙在不直贬公孙而讥刺见於言外尤为微婉黄生曰老去人扶写题中上字正见作者登临慿吊之槩若无五六则题意不完而诗人胸次眼光俱不出矣诗有悲角句故知公孙当指崔旰也杜臆意何长言虽负雄心而不能久据天壁谓壁髙挿天宋之问诗崖口衆山断嶔岑耸天壁释名城上垣谓之女墙言其卑小比之於城如女子之於丈夫古今注女墙城上小墙亦名睥睨郭璞江赋巴东之峡夏后疏凿左传见河洛者思禹功风赋楚襄王游於兰台之宫有风飒然而至王乃披襟当之曰快哉此风诗度其夕阳後汉书公孙述字子阳更始时起兵讨宗成王岑之乱破之遂有蜀土僭立为帝都成都色尚白改成都郭外旧仓为白帝仓筑城於鱼复号曰白帝城述立十二年为光武所灭蜀都赋临谷为塞因山为障一人守隘万夫莫向所谓恃险也又云公孙跃马而称帝"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11599":["上白帝城二首 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["江城含变态，一上一回新。","天欲今朝雨，山归万古春。","英雄余事业，衰迈久风尘。","取醉他乡客，相逢故国人。","兵戈犹拥蜀，赋敛强输秦。","不是烦形胜，深慙畏损神。"],"",[["古注·《杜詩詳註》","黄鹤编在大厯元年葢再登白帝城而作也故云一上一回新"],["古注·《杜詩詳註》","丘两切一作尚"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11600":["上白帝城二首 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["白帝空祠庙，孤云自往来。","江山城宛转，栋宇客裴回。","勇略今何在，当年亦壮哉。","後人将酒肉，虚殿日尘埃。","谷鸟鸣还过，林花落又开。","多慙病无力，骑马入青苔。"],"",[["古注·《杜詩詳註》","卢世㴶曰此诗起四句见天地之心知雨阳之性穷新旧之变领山水之神俱能朗朗写出余谓登髙而开道眼者此也唐子西文録少陵秦中记行诗如江间饶竒石未为极胜到暝色带逺客则不可及已上白帝城诗云天欲今朝雨山归万古春葢絶唱也予惠州诗亦云雨在时时黒春归处处青又云片云明外暗斜日雨边晴山转秋光曲川长暝色横皆间中所得句也"],["古注·《杜詩詳註》","次章咏白帝庙上八庙中吊古下四抚景自伤公於先主武侯説得英爽赫奕千载如生此云勇畧今何在当年亦壮哉叹其随死而俱冺也杜臆病无力何足为惭亦对勇壮而云然耳方舆胜览白帝庙在奉节县东八里旧城内鲍照诗宛转烛廻梁马援传才明勇畧非人敌也"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11601":["武侯庙","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["遗庙丹青落，空山草木长。","犹闻辞後主，不复卧南阳。"],"刘云语絶又云上句想望其风采犹在也下句伤其巳死",[["古评·《唐诗品汇》","刘云语絶又云上句想望其风采犹在也下句伤其巳死"],["古注·《杜詩詳註》","鹤注此指夔州之庙故云空山草木长当是大厯元年作张震武侯祠堂记唐夔州治白帝武侯庙在西郊张溍曰此处两絶句足尽武侯一生心事"],["古注·《杜詩詳註》","上二咏庙下二武侯朱注此诗後二语人无解者武侯为昭烈驱驰未见其忠惟当後主昏庸而尽瘁出师不复有归卧南阳之意此则云霄万古者耳曰犹闻者空山精爽如或闻之也王逸鲁灵光殿赋托之丹青陶潜诗孟夏草木长蜀志後主建兴五年亮率诸军北驻汉中临发上表又徐庶谓先主曰诸葛孔明卧龙也将军岂愿见之乎蜀志注汉晋春秋云亮家於南阳之邓县在襄阳城西二十里号曰隆中荆州图副云邓城旧县西南一里隔沔有诸葛亮宅是汉昭烈三顾处一曰南阳是襄阳墟名非南阳郡也"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗品彚（附唐诗拾遗）》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩品彚_(四庫全書本)）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11602":["八阵图","杜甫","五言绝句","大历元年（766）","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["功盖三分国，名高八阵图。","江流石不转，遗恨失吞吴。"],"此诗作于杜甫寓居夔州期间。八阵图乃诸葛亮所布之战术阵法，传说其遗迹在夔州（今重庆奉节）长江之滨。杜甫借咏古迹以追怀武侯功业，亦寓凭吊之意。",[["1. **八阵图**","诸葛亮所创之阵法，按天、地、风、云、龙、虎、鸟、蛇八种阵势布列。"],["2. **三分国**","魏、蜀、吴三分天下。"],["3. **江流石不转**","长江奔流而八阵图之石巍然不动。"],["4. **失吞吴**","刘备伐吴失败，未能吞并东吴。"],["古评·《唐诗镜》","志林云仆尝梦见人云是杜子美谓仆曰世人多误㑹余八阵圗诗以为先生武侯欲与闗羽复仇故恨不能㓕非也我意本谓吴蜀唇齿之国不当相圗晋之所以能取蜀者以蜀有吞吴之意此为恨耳"],["古注·《杜詩詳註》","江流石不转此阵图之垂名千载者所恨吞吴失计以致三分功业中遭跌挫耳下二句用分应东坡志林尝梦子美谓仆世人多误㑹吾八阵图诗以为先主武侯欲与闗公报仇故恨不能灭吴非也吾意本谓吴蜀唇齿之国不当相图晋之能取蜀者以蜀有吞吴之志以此为恨耳朱注史昭烈败秭归诸葛亮曰法孝直若在必能制主上东行就使东行必不倾危观此则征吴非孔明意也子美此诗正谓孔明不能止征吴之举致秭归挫辱为生平遗恨东坡之説殊非刘逴曰孔明以葢世竒才制为江上阵图至今不磨使先主能用其阵法何至连营七百里败绩於猇亭哉欲吞吴而不知阵法是则当时之遗恨也今按下句有四説以不能灭吴为恨此旧説也以先主之征吴为恨此东坡説也不能制主上东行而自以为恨此杜臆朱注説也以不能用阵法而致吞吴失师此刘氏之説也蒯通传功葢天下者不赏出师表今天下三分益州罢弊乐毅书蚤知之士名成而不毁旧注阵势八天地风云飞龙翔鸟虎翼蛇盘也湛方生诗盻江流兮洋洋诗我心匪石不可转也後汉王常传死无遗恨蜀志却正释讥吞嚼八区"]],{"source":"据萧涤非《唐诗鉴赏辞典》“八阵图”条（上海辞书出版社，1983 年版）","body":["此诗以二十字咏武侯千载之功。前二句“功盖三分国，名成八阵图”总括诸葛亮一生功业：其功业冠绝三分天下之世，其声名成就于八阵图之布设。两句一气呵成，以“盖”字、“成”字写出武侯功业之盛。","后二句“江流石不转，遗恨失吞吴”转入感慨。江水奔流而阵石不动，以自然之永恒反衬人事之沧桑。“遗恨失吞吴”三字沉痛，写武侯虽有经天纬地之才，终不能挽回刘备伐吴之失计。全诗以古迹咏怀，词约义丰，余味无穷。"]},[],["https://github.com/chinese-poetry/chinese-poetry","据萧涤非《唐诗鉴赏辞典》“八阵图”条（上海辞书出版社，1983 年版）","《全唐诗》（清·曹寅等编，康熙扬州诗局本）","古籍注评：《唐诗镜》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩鏡_(四庫全書本)）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11603":["谒先主庙","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["惨淡风云会，乘时各有人。","力侔分社稷，志屈偃经纶。","复汉留长策，中原仗老臣。","杂耕心未已，欧血事酸辛。","霸气西南歇，雄图历数屯。","锦江元过楚，劒阁复通秦。","旧俗存祠庙，空山立鬼神。","虚檐交鸟道，枯木半龙鳞。","竹送清溪月，苔移玉座春。","闾阎儿女换，歌舞岁时新。","绝域归舟远，荒城系马频。","如何对摇落，况乃久风尘。","孰与关张并，功临耿邓亲。","应天才不小，得士契无邻。","迟暮堪帷幄，飘零且钓缗。","向来忧国泪，寂寞洒衣巾。"],"语气浑浑若论武侯还可賛得伯仲之间见伊吕指挥若定失萧曹武侯当此未为云过",[["古评·《唐诗镜》","语气浑浑若论武侯还可賛得伯仲之间见伊吕指挥若定失萧曹武侯当此未为云过"],["古评·《唐诗品汇》","刘云来得浑浑有无限可感开基季世君臣心事不分逺近不立賔主老人口老人耳彷佛尽之矣"],["古评·《唐诗品汇》","刘云分之未㡬而复合乎彼伤感无如此两句旧解误甚"],["古评·《唐诗品汇》","刘云寂寞语竒丽"],["古评·《唐诗品汇》","刘云十字归合古今"],["古评·《唐诗品汇》","刘云使其果因天运元徳之才亦岂小哉"],["古评·《唐诗品汇》","刘云谓武侯相得无此即此便不可及"],["古评·《唐诗品汇》","刘云其自负如此"],["古评·《唐诗品汇》","刘云首尾曲折句句典实有味真大手真蜀先主庙诗评意皆合"],["古注·《杜詩詳註》","於口切呕同"],["古注·《杜詩詳註》","对於渭南毎患粮不继分兵屯田为久驻之基耕者杂於渭滨居民之间百姓安堵军无私焉锺㑹檄文劳役未已未然已然二字折开与酸辛为借对魏志亮粮尽势穷忧恚呕血一夕烧营遁走入谷道发病卒裴松之曰亮在渭滨魏人蹑迹胜负之形未可测量而云呕血葢因孔明亡而自夸大也夫以孔明之畧岂为仲达呕血乎刘琨䘮师与元帝笺亦云亮军败呕血此则引虚记以为言也阮籍诗举翼更酸辛吴越春秋范蠡曰霸王之气见於地户谢朓诗雄图怅若兹书天之厯数在尔躬"],["古注·《杜詩詳註》","此写庙中景事交鸟道庙之髙半龙鳞水之古竹送二句见岁时屡度闾阎二句见庙祀常存卢世㴶曰此见人心思汉厯数百年如一日也国语卒厯代之旧俗後汉成安侯传帝为起祠庙立谓设立神像作泣神者未安江总诗虚檐静暮雀南中八志鸟道四百里庾信诗自能枯木润子虚赋照烂龙鳞抱朴子松树其皮中有脂状如龙形杜臆清溪之月从竹稍露出故云竹送玉座之苔与春色频呈故云苔移玉座神牀也谢朓诗玉座犹寂寞东都赋闾阎且千黄注儿女即歌舞者左传歌舞不倦竺僧度诗倐忽岁时过"],["古注·《杜詩詳註》","此谒庙而有感也周甸注当此风尘摇落中孰与闗张并列而功侔耿邓乎必有真主应天之才方成君臣契合之机今年齿迟暮岂堪更参帷幄秪作磻溪钓叟已耳但忧国念深不禁泪洒衣巾也杜臆後八句一是言有君则有臣一是叹有臣而无君此思古伤今之语此诗中八句乃叙题前後各十二句全以议论成章他人无此深厚力量李陵书出征絶域谢朓诗天"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗镜》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩鏡_(四庫全書本)）","古籍注评：《唐诗品彚（附唐诗拾遗）》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩品彚_(四庫全書本)）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11604":["白盐山","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["卓立羣峰外，蟠根积水边。","他皆任厚地，尔独近高天。","白牓千家邑，清秋万估船。","词人取佳句，刻画竟谁传。"],"",[["古注·《杜詩詳註》","鹤注当是大厯元年秋作"],["古注·《杜詩詳註》","一作古一作里"],["古注·《杜詩詳註》","英华作刷练始堪传上四写山势之孤高中二记人民之聚集末则自信诗句足传也杜臆山高者基必大此山卓立羣峯之表乃蟠根於积水之边望若悬空是不任地而近天矣岂非夔府一竒观哉且绕山而上千家成邑积水之中万估船来又蜀中一都㑹也向者春望此山虽有断壁红楼之句今秋亲厯其地苦心刻划而始得此山真面目但恐词人取句未必能传耳此诗细玩始知描写之工後来选者不及论文笑自知信矣谢庄月赋任地班形东京赋岂徒局高天厚地而已哉白牓指门上扁额杜臆地志载赤甲山有孤城即鱼复县盐山不言有邑此特言其有似千家之邑耳江淹诗刻划𡷾崒兮山云而碧峯黄希曰世説周顗云刻划无盐此因山名白盐故有末句"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11605":["灩澦堆","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["巨积水中央，江寒出水长。","沈牛荅云雨，如马戒舟航。","天意存倾覆，神功接混茫。","干戈连解缆，行止忆垂堂。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11606":["灩澦","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["灧澦既没孤根深，西来水多愁太阴。","江天漠漠鸟双去，风雨时时龙一吟。","舟人渔子歌回首，估客胡商泪满襟。","寄语舟航恶年少，休翻盐井横黄金。"],"三四语有概其曰双去却刚是双去",[["古评·《唐诗镜》","三四语有概其曰双去却刚是双去"],["古评·《诗人玉屑》","与等，乃为超绝"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗镜》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩鏡_(四庫全書本)）","古籍注评：《诗人玉屑》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/詩人玉屑_(四庫全書本)）"]],"open_11607":["白帝","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["白帝城中云出门，白帝城下雨翻盆。","高江急峡雷霆鬬，翠木苍藤日月昏。","戎马不如归马逸，千家今有百家存。","哀哀寡妇诛求尽，恸哭秋原何处村。"],"",[["古注·《杜詩詳註》","鹤注当是大厯元年秋作张逺注此在白帝城而作非専咏白帝也"],["古注·《杜詩詳註》","一作城头云若屯"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11608":["白帝城楼","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["江度寒山阁，城高绝塞楼。","翠屏宜晚对，白谷会深游。","急急能鸣鴈，轻轻不下鸥。","彝陵春色起，渐拟放扁舟。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11609":["晓望白帝城盐山","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["徐步移班杖，看山仰白头。","翠深开断壁，红远结飞楼。","日出清江望，暄和散旅愁。","春城见松雪，始拟进归舟。"],"",[["古注·《杜詩詳註》","上四晓望之景下四望中之兴壁切山楼切城皆仰头所见者断壁开处见其深翠飞楼结处见其逺红此用倒装法杜臆城中见日初出从清江而望此山兼以日气暄和真足散旅人之愁旅人以即次为安谓其堪卜居也春城焉得有雪亦谓盐山似之见此佳景而始拟进舟有不忍恝然之意後入宅诗云断崖当白盐又移东屯云白盐危峤北公葢眷眷於此山矣此诗上四句整对下四句散行与早花诗同属变化之格斑杖斑竹杖也梁到溉有赠任新安斑竹杖诗隋焬帝诗飞楼倚观轩若惊杜臆地志白盐山有夷溪夷水出焉水色清照十丈名为清江申涵光曰暄和散旅愁是客中情事此与阳和不散穷愁恨各有妙理顔延之诗山明见松雪归舟本拟出峡今盻望盐山而特进舟也谢朓诗天际识归舟"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11610":["白帝城最高楼","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["城尖径昃旌斾愁，独立缥缈之飞楼。","峡坼云霾龙虎卧，江清日抱鼋鼍游。","扶桑西枝对断石，弱水东影随长流。","杖藜叹世者谁子，泣血迸空回白头。"],"",[["古注·《杜詩詳註》","旧作昃非一作翼"],["古注·《杜詩詳註》","首写楼髙次聨近景三聨逺景皆独立所想见者末乃感慨当世尖城角也径步道也旌斾亦愁言其髙而且险也韩廷延云云霾坼峡山水盘拏有似龙虎之卧日抱清江滩石波荡恍如鼋鼍之游与江光隠见鼋鼍窟石势参差乌鹊桥同一句法皆登髙临深极形客疑似之状耳朱注峡之髙可望扶桑西向江之逺可接弱水东流与朱崖着亳髪碧海吹衣裳同义海赋神仙缥缈庾信诗暗石疑藏虎磐根似卧龙曹植诗东观扶桑曜西临弱水流是正言东西也此诗扶桑西枝是就东言西弱水东影是就西言东山海经大荒之中阳谷上有扶桑十日所浴居水中有大水九日居下枝一日居上枝禹贡弱水既西淮南子弱水自穷石注穷石在张掖北其水弱不能出羽阮籍诗所怜者谁子丁仪寡妇赋涕流迸以琳琅字书迸散走也"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11611":["白帝楼","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["漠漠虚无里，连连睥睨侵。","楼光去日远，峡影入江深。","腊破思端绮，春归待一金。","去年梅柳意，还欲搅边心。"],"",[["古注·《杜詩詳註》","鹤注此大厯二年嵗晏作公於元年至䕫州今云去年梅栁意则是二年冬尽时矣"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11612":["陪诸公上白帝城宴越公堂之作","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["此堂存古制，城上俯江郊。","落构垂云雨，荒阶蔓草茅。","柱穿蜂溜蜜，栈缺燕添巢。","坐接春杯气，心伤艳蘂梢。","英灵如过隙，宴衎愿投胶。","莫问东流水，生涯未即抛。"],"",[["古注·《杜詩詳註》","鹤注编在大厯元年春晚作原注越公杨素也有堂在城上画像尚存李贻孙夔州都督府记白帝城东南斗上二百七十步得白帝庙又有越公堂在庙南而少西隋越公素所建竒构隆敌内无撑柱夐视中脊邈不可度五逾甲子无土木之隙见其人之瓌杰也朱注诗言柱穿栈缺而记云无土木之隙疑记语未足信"],["古注·《杜詩詳註》","上咏越公堂景落构屋檐頽落垂云雨言其髙蔓草茅言其荒蜂溜蜜春气融燕添巢新入堂也鲍照诗江郊霭微明朱注阁木曰栈"],["古注·《杜詩詳註》","一作水清浅"],["古注·《杜詩詳註》","下咏陪宴情事艳蘂易谢起英灵过隙宴衎投胶当及春欢饮生涯未抛不能舍夔州而东下也此章上下各六句庄子人生天地间若白驹之过隙诗嘉宾式燕以衎古乐府以胶投漆中谁能别离此"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11613":["峡隘","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["闻说江陵府，云沙静眇然。","白鱼如切玉，朱橘不论钱。","水有远湖树，人今何处船。","青山各在眼，却望峡中天。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11614":["诸葛庙","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["久游巴子国，屡入武侯祠。","竹日斜虚寝，溪风满薄帷。","君臣当共济，贤圣亦同时。","翊戴归先主，幷吞更出师。","虫虵穿画壁，巫觋醉蛛丝。","歘忆吟梁父，躬耕也未迟。"],"",[["古注·《杜詩詳註》","他本作醉杜臆作缀对穿字为工"],["古注·《杜詩詳註》","上四咏庙中景物中四遡武侯徃事下则对庙而感怀也虫蛇二句承中段来言当时勲业如此而遗庙凄凉但见画壁空穿蛛丝缀人耳与竹日二句不为犯重躬耕未迟葢借孔明以自况水经注江州县故巴子之都春秋桓九年巴子使韩服告楚请与邓好是也及七国称王巴亦王焉元和郡国志武王伐殷巴人助焉後封为巴子三巴记其地东至鱼复西至僰道北接汉中南极牂牁陈子昻诗城临巴子国台没汉王宫阮籍咏怀诗薄帷鉴明月应璩书贤圣殊品蔡邕篆书体藴若虫蛇之棼緼庾信诗龙来随画壁国语在男曰觋在女曰巫东京赋巫觋操茢扬雄蜀都赋蜘蛛作丝不可见风武侯本传躬耕陇亩好为梁父吟出师表臣本布衣躬耕南阳"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11615":["峡口二首 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["峡口大江间，西南控百蛮。","城欹连粉堞，岸断更青山。","开辟多天险，防隅一水关。","乱离闻鼓角，秋气动衰颜。"],"",[["古注·《杜詩詳註》","单复编在大厯元年秋此即瞿唐峡口也方舆胜览瞿唐峡在夔州东一里旧名西陵峡陆机辩亡论谨守三峡之门"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11616":["峡口二首 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["时清关失险，世乱戟如林。","去矣英雄事，荒哉割据心。","芦花留客晚，枫树坐猨深。","疲薾烦亲故，诸侯数赐金。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11617":["天池","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["天池马不到，岚壁鸟才通。","百顷青云杪，层波白石中。","郁纡腾秀气，萧瑟浸寒空。","直对巫山出，兼疑夏禹功。","鱼龙开辟有，菱芡古今同。","闻道奔雷黑，初看浴日红。","飘零神女雨，断续楚王风。","欲问支机石，如临献宝宫。","九秋惊鴈序，万里狎渔翁。","更是无人处，诛茅任薄躬。"],"",[["古注·《杜詩詳註》","鹤注此当是大厯二年秋瀼西作全蜀总志天池在䕫州府治东巫山县治亦有之天池山顶上有池也天池字亦见庄子"],["古注·《杜詩詳註》","此记天池气象首二言高百顷言濶层波言清腾气在晴时浸寒在隂时对峡指其地禹功叹其竒楚辞眇视目层波诗白石磷磷陆士衡诗郁纡游子情王融曲水序冠五行之秀气唐太宗诗寒空碧雾轻"],["古注·《杜詩詳註》","一作樵童"],["古注·《杜詩詳註》","此游池而有感也雁序渔翁皆池边所见者诛茅而居自叹久客夔州此章前二段各八句末段四句收南都赋结九秋之增伤曹植诗丹唇含九秋"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11618":["瞿塘两崖","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["三峡传何处，双崖壮此门。","入天犹石色，穿水忽云根。","猱攫须髯古，蛟龙窟宅尊。","羲和冬驭近，愁畏日车翻。"],"",[["古注·《杜詩詳註》","此诗旧编在大厯二年考二年之秋公在东屯矣还是元年冬作"],["古注·《杜詩詳註》","首㸃两崖中咏景物末乃叹其危险杜臆传何处三峡之名互异壮此门瞿唐一峡不移也黄希曰公作长江云瞿唐争一门又瞿唐懐古云勍敌两崖开葢瞿唐乃三峡之门又两崖对峙中贯一江望之如门然崖入天而青同一色崖穿水而下至云根乃状其势之高深黄生注惟高山水险故物得以久据深藏曰古曰尊字法俱妙杜臆冬时日行南陆正值崖上今两崖耸窄屏去日光似乎羲和亦畏车翻而却避之者朱注庾仲雍荆州记巴楚有明月峡广徳峡东突峡今谓巫峡秭归峡归郷峡峡程记三峡即明月峡巫山峡广溪峡其瞿唐灧澦燕子屏风之类皆不与三峡之数寰宇记䕫州三峡曰西峡巴峡巫峡宋肇三峡堂记又以西陵峡巫峡归峡为三峡按三峡诸説不同疑明月峡不列三峡内盖明月峡在䕫州之上也然忠州龙兴寺诗又云忠州三峡内则公於此亦无定説矣杜臆诗人多以云根为石以云触石而出也宋孝武登乐山诗屯烟扰风穴积水溺云根蔡注尔雅猱善援玃善顾尔雅注玃貑玃也似猕猴而大色苍黒能攫搏人故云玃述异记猿五百嵗化为玃玃千嵗化为老人扬雄蜀都赋猿蠝玃猱杜臆公诗龙以瞿唐㑹则知其有龙蛇矣王勃山亭序徵石髓於蛟龙之窟江赋瑰竒之所窟宅淮南子日乗车驾以六龙羲和为之驭冬驭近谓近於瞿唐非秋近於冬之谓李尤歌安得壮士翻日车"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11619":["夔州歌十绝句 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["中巴之东巴东山，江水开辟流其间。","白帝高爲三峡镇，夔州险过百牢关。"],"",[["古注·《杜詩詳註》","鹤注此当是大厯元年夏作"]],{"source":"周啸天","body":["前两句从较大角度交代出夔州的地理环境，下两句进而更具体地描绘其山川形胜。“白帝”即白帝城，城在夔州之东的北岸高峰顶上。这里是公孙述割据称雄之处，也是三国时蜀汉防东吴的要冲，因它守住瞿塘峡口，足资镇压，所以说是“三峡镇”。在湍急的瞿塘峡江心，旧时有滟滪堆，冬日出水，夏日没入水中成为暗礁，所以“人言道路古来难”（刘禹锡《竹枝词》），不可谓不险。“百牢关”在汉中，两岸绝壁相对而立，六十里不断，因为它和夔州的瞿塘相似，所以用来作比。下联十四字抓住“高”“险”特征，笔力千钧，把“高江急峡”写得极有气势。两句分承山水，句式对仗，音韵砍截，与散行作结风味全殊。","如果我们用盛唐绝句传统手法作对照，就会发现此诗在写作上有以下几个突出特点：一、传统绝句注重音调的平仄谐调、句格的稳顺；而此诗有意追求拗调，首句全用平声字，给人以奇离突兀之感。二、传统绝句注重风调，追求一唱三叹之音，尾联多取散行，一般“以第三句为主，第四句发之”（元代杨载《诗法家数》），构成转合，即使用对结，也多采取流水对；这首诗的后二句用骈偶作结，类半首律诗，诗意的转折在两联之间，结束的音调戛然而止。三、传统绝句注重情景交融的表现手法，纯写景的不多，而此诗两联皆分写山水。纯乎写景，却又并非无情。它通过奇突雄浑的自然景物的描写，取得激动人心的艺术效果，读者能感到诗人对祖国奇异山川的热爱和由衷的赞美。"]},[],["https://github.com/chinese-poetry/chinese-poetry","《全唐诗》（清·曹寅等编，康熙扬州诗局本）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11620":["夔州歌十绝句 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["白帝夔州各异城，蜀江楚峡混殊名。","英雄割据非天意，霸主幷吞在物情。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11621":["夔州歌十绝句 三","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["羣雄竞起问前朝，王者无外见今朝。","比讶渔阳结怨恨，元听舜日旧箫韶。"],"",[["古注·《杜詩詳註》","次章承前白帝三峡上二辩古蹟下二论往事朱注古白帝城在䕫州城东故曰各异城瞿唐峡旧名西陵峡与荆州西陵峡相乱故曰混殊名英雄割据谓公孙述刘马辈霸王并吞如汉髙以巴蜀收中国窃据者逆天得民者致王见在徳不在险也陆游入蜀记唐故䕫州与白帝城相连吴越春秋阖闾曰寡人欲强国霸王何由而可江淹诗物情弃疵践"],["古注·《杜詩詳註》","一作闻郭作向"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11622":["夔州歌十绝句 四","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["赤甲白盐俱刺天，闾阎缭绕接山巅。","枫林橘树丹青合，复道重楼锦绣悬。"],"",[["古注·《杜詩詳註》","四章记赤甲白盐也刺天言山势之髙接巅言居人之宻丹青谓枫橘异色锦绣谓楼阁相映卢云见䕫州既庶且富也吴论此下七章散咏䕫州景物南都赋森䔿䔿而刺天水经注孤峯刺天江淹诗缭绕华山阴藉田赋若茂松之倚山颠西京杂记终南山有树叶一青一赤望之斑驳长安谓之丹青树叔孙通传孝恵乃作复道何逊诗重楼雾中出相如答盛览书列锦绣以为质"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11623":["夔州歌十绝句 五","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["瀼东瀼西一万家，江北江南春冬花。","背飞鹤子遗琼蘂，相趁凫雏入蒋牙。"],"",[["古注·《杜詩詳註》","晋作江南江北"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11624":["夔州歌十绝句 六","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["东屯稻畦一百顷，北有涧水通青苗。","晴浴狎鸥分处处，雨随神女下朝朝。"],"",[["古注·《杜詩詳註》","五章记瀼东瀼西也一万家人烟盛春冬花地气暖遗蕋入蒋形容花草之多瀼水直流故地界东西江水横流故地分南北瀼与江有小大之别吴论鹤子鳬雏季夏之景水经注白帝山城东望瀼溪即以为隍入蜀记䕫人谓山涧之流通江者曰瀼居人分其左右谓之瀼东瀼西王勃诗江南江北互相望拟李陵别诗双鳬相背飞海赋鹤子淋渗王粲白鹤赋食灵岳之琼蘂陆机拟古上山采琼蘂皆言花之白也楚辞屑琼蘂以为粮乃言玉英耳字书趁逐也海赋鳬雏离縰蜀都赋攒蒋樷蒲注蒋菰名也"],["古注·《杜詩詳註》","杜诗瀼东瀼西一万家江北江南春冬花咏村居景物而语涉拗体白玉蟾诗云山後山前鸠唤妇舍南舍北竹生孙则调逸而意更新矣"],["古注·《杜詩詳註》","六章记东屯之胜屯可种稻溉以流泉民受其利矣多鸥常雨言涧水之不竭也用学纪闻东屯乃公孙述留屯之所距白帝城五里东屯之田可百顷稻米为蜀第一又东屯有青苖陂一统志青苖陂在瞿唐东蓄水溉田民得其利孙绰诗物我俱忘懐可以狎鸥鸟髙唐赋楚先王梦见一妇人曰妾巫山之女也旦为朝云暮为行雨朝朝暮暮阳台之下"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11625":["夔州歌十绝句 七","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["蜀麻吴盐自古通，万斛之舟行若风。","长年三老长歌里，白昼摊钱高浪中。"],"",[["古注·《杜詩詳註》","一作白马滩前"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11626":["夔州歌十绝句 八","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["忆昔咸阳都市合，山水之图张卖时。","巫峡曾经宝屏见，楚宫犹对碧峰疑。"],"",[["古注·《杜詩詳註》","七章记水次之便商贾贩货而竞趋舟人忘险而争利市舶辐辏真西南一大都㑹也江隣几杂志作白马滩前髙浪中是蒙上句连説若作白昼摊钱则长歌者舟子摊钱者贾客也常璩蜀志桑漆麻紵之饶左思吴都赋煑海为盐梁冀傅能意钱之戏注何承天纂文曰诡亿一曰射意一曰射数黄注即今之猜枚射覆之类若摊钱则以钱摊拨於地今谓之跌博与意钱不同曾季狸艇齐诗话摊钱即摊赌也"],["古注·《杜詩詳註》","八章记楚王宫也咸阳所见者画图䕫州所对者真境但楚宫难覔终成疑似即真境亦同幻相矣公诗舟人指㸃到今疑即同此意张卖张图以卖於市也西京杂记武帝为宝屏风设於桂宫江淹诗刻画𡺚崒兮山云而碧峯"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11627":["夔州歌十绝句 九","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["武侯祠堂不可忘，中有松柏参天长。","干戈满地客愁破，云日如火炎天凉。"],"",[["古注·《杜詩詳註》","唐人七絶多从首句拈韵如李太白王龙标诸作尽然杜诗有对起而不用韵者如落落出羣非榉栁青青不朽岂杨梅是也有散起而不用韵者忆昔咸阳都市合山水之图张卖时是也唐诗如卢照隣日观仙云随凤辇天门瑞雪照龙衣亦是对起无韵刘长卿天书逺召沧浪客几度临岐病未能又是散起无韵杨用修谓刘诗起句尤奇"],["古注·《杜詩詳註》","一作生祠"],["古注·《杜詩詳註》","九章记武侯祠也武侯忠义千古难忘见非英雄割据及楚宫高唐可比松柏阴森堪散愁而纳凉亦对树懐人之意薛道衡老氏碑考其故迹营建祠堂干戈满地崔旰未平也谢灵运诗云日相照媚孔融诗赫赫炎天路"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11628":["夔州歌十绝句 十","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["阆风玄圃与蓬壶，中有高堂天下无。","借问夔州压何处，峡门江腹拥城隅。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11629":["上卿翁请修武侯庙遗像缺落时崔卿权夔州","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["大贤爲政即多闻，刺史真符不必分。","尚有西郊诸葛庙，卧龙无首对江濆。"],"",[["古注·《杜詩詳註》","上二崔权州事下二请修遗像无首神像缺落也易羣龙无首王十朋祠堂记略曰武侯故祠在州之南门沿城而西三十六步无断碑遗刻以考其岁月之始见於圗经者略焉在隋唐时治白帝史载少陵诗曰西郊诸葛庙者其地於兹乎门之东去祠一百八十五步城有台下临八阵圗登台而望则常山之蛇四头八尾之势宛其在目北直郡仓仓故永安宫也据爽垲状如屏宫之北有水曰清瀼泻出乎两山之间东入於江又东过灧澦入於峡峡口有山卓然立乎羣峰之外者白盐也可谓江山之胜矣侯昔经营天下於平沙之上输忠尽诚受遗立孤於是宫之中江流淘而石如故宫阙废而地犹存陵谷虽变而精神不亡宜於两者之间祠之亦侯之志也书史传於壁之左而削其不公之论书少陵诗於壁之右以诸作者诗文次之词曰白盐峙天兮灧澦屹江风云惨淡兮翺翔卧龙龙千秋兮何之新庙貌兮江之湄前八阵兮後故宫龙兮龙兮神其中望昭烈兮隔清瀼遗庙存兮交精神於惚恍驾虚空兮云为驭臣东朝兮主西顾鱼得水而相忘兮事无今古俨闗张於左右兮一龙二虎祠有新故兮侯无重轻舍其故而新是卜兮邦人之情祠合於圗兮自今始祀事不絶兮有如此水卧龙之龙叶音龎在江韵"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11630":["偶题","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["文章千古事，得失寸心知。","作者皆殊列，名声岂浪垂。","骚人嗟不见，汉道盛於斯。","前辈飞腾入，余波绮丽爲。","後贤兼旧列，历代各清规。","法自儒家有，心从弱岁疲。","永怀江左逸，多病邺中奇。","騄骥皆良马，骐驎带好儿。","车轮徒已斵，堂构惜仍亏。","漫作潜夫论，虚传幼妇碑。","缘情慰漂荡，抱疾屡迁移。","经济慙长策，飞栖假一枝。","尘沙傍蜂虿，江峡绕蛟螭。","萧瑟唐虞远，联翩楚汉危。","圣朝兼盗贼，异俗更喧卑。","郁郁星辰劒，苍苍云雨池。","两都开幕府，万宇插军麾。","南海残铜柱，东风避月支。","音书恨乌鹊，号怒怪熊罴。","稼穑分诗兴，柴荆学土宜。","故山迷白阁，秋水隐黄陂。","不敢要佳句，愁来赋别离。"],"",[["古注·《杜詩詳註》","鹤注当是大厯元年秋作"],["古注·《杜詩詳註》","首叙诗学源流杜臆少陵一生精力用之文章始成一部诗集此篇乃一部杜诗总序而起二句乃一部杜诗所托胎者文章千古事便须有千古识力得失寸心知则寸心具有千古此文章家秘密藏为古今立言之标凖也作者殊列名不浪垂此二句又千古文人之总括谓其所就虽不同然寸心皆有独知者在也三百篇乃诗家鼻祖而骚体则裔孙也骚人不见则雅颂可知自苏李軰倡为五言汉道於斯为盛此又诗之大宗也前軰如建安黄初诸公飞腾而入至六朝尚绮丽亦其余波不可少也兼旧制取材者广各清规命意特新杜臆公诗尝言文章本小技於道未为尊此须识其道之所尊者安在得所尊则文垂千古失所尊则文止小技初无二义也魏文帝典论文章经国之大业不朽之盛事此即千古事也曹植曰文之佳恶我自知之此即寸心知也典论古之作者寄身於翰墨荀子彼贵我名声胡夏客曰骚人已往汉即有诗非悲骚人之不见也谢举诗望逺骚人歌汉文帝纪登我汉道梅福书汉之得贤於斯为盛张缵赋前軰宿逹楚辞吾令鳯凰飞腾兮书余波入於流沙刘桢诗绮丽不可忘徐景休叅同契序立法以传後贤前汉朱博传奉尊旧制杜预左传序据旧例而发义宋书谢灵运传自灵均以来多歴年代魏志太祖令曰邴原名高徳大清规邈世"],["古注·《杜詩詳註》","此下叙客䕫情事杜臆縁情用陆机语谓作诗也诗縁情生止自慰其漂荡而抱疾累迁又自疏其漂荡也经济以下备述漂荡之意陆机文赋诗縁情而绮靡魏武诗播越西迁移左思诗巢林借一枝"],["古注·《杜詩詳註》","此承飞栖假一枝言漂荡之迹蜂虿蛟螭乃峡中景物唐虞四句伤蜀乱未平赵曰治莫盛於唐虞战莫急於楚汉故并举言之蔡琰胡笳疾飞千里兮吹尘沙南都赋惮虬龙兮怖蛟螭四皓歌唐虞世逺吾将何归前汉书赞楚汉之际豪杰相王盗贼谓崔旰喧卑谓夔土诗序国异政家异俗舞鹤赋厌人寰之喧卑"],["古注·《杜詩詳註》","此承经济慙长䇿言漂荡之故星剑云池喻抱䇿莫施幕府四句伤四方未靖朱注星辰剑用张华事云雨池用周瑜语自叹如寳剑埋狱而未出蛟龙在池而未跃残铜柱粤寇初平避月支吐蕃西劲也越絶书寳剑篇观其鈲烂如列星之行班固有两都赋幕府注见别巻牛𢎞诗恭已临万㝢沈约碑文军麾命服之序铜柱见十五巻匈奴传东湖强而月支盛溍注月支即月氐西域国名"],["古注·《杜詩詳註》","朱云当作皇"],["古注·《杜詩詳註》","此客䕫而念故都也恨乌鹊家信不来怪熊罴山居厌闻稼穑柴荆夔州居食白阁皇陂长安山水杜臆漂荡之中安得复有佳句但愁来则赋别离耳别离即漂荡意此章前二各十句後二各六句中四句为腰末八句为尾西京杂记乾鹊噪而行人至魏武苦寒行熊罴对我蹲书稼穑作甘左传无失其土宜"]],{"source":"易可情","body":["曹丕《典论•论文》道：“盖文章，经国之大业，不朽之盛事。年寿有时而尽，荣乐止乎其身，二者必至之常期，未若文章之无穷。”使杜甫感到欣慰的是，尽管“致君尧舜上，再使风俗淳”（《奉赠韦左丞丈二十二韵》）的壮志未酬，迭经挫折，饱尝动乱之苦，倒却取得了诗歌创作的丰硕成果。于是开篇之首，便吟出了“文章千古事，得失寸心知”的饱含哲理的名句。当然，这个“寸心知”，既是指己之所知，亦是指知己之所知。","接着，在佐证这“不朽”的“千古事”的同时，谈到了由古及今的诗歌艺术的传承和发展。历代的诗人可以排出一个次第来，如果没有独到的成就，怎么能够名留后世？骚体乃至再早的诗经已被两汉以降的五言、七言诗体所替代，前辈诗人驰骋才思、腾跃文坛，余风所及，给后世以强烈的影响。后世的贤才总是在继承前人的基础上，兼收并蓄，从而有所创新，以至于不同时代的创作皆能形成独特的清新的规范。再想到自己的创作，原是出自儒家的体系，从童年时便开始竭尽情思致力于创作。忘不了像“”“骥”等良马般驱驰的西晋诗人潘岳、陆机等人的影响，更得感谢如马中“骐”“”带着千里驹驰骋于诗坛的邺下三曹父子所给予的激励。值得叹息的是，尽管而今已如轮扁斫轮一样“得之于手而应于心”，然而于治国安民又有何补益？即使写出王符《潜夫论》、邯郸淳《曹娥碑》一样的文字来，也不过空传后世罢了。反过来又一想，写诗毕竟是自己的兴趣爱好、自己的思想寄托，是自己带病迁徙、漂荡流寓生涯的一种慰藉啊，还侈谈什么经世济民之策？像疲敝的飞鸟一样，能有一枝栖息之处也算不错了。","回到而今的现实中来，世尘中蜂虿横行，江峡里蛟螭出没——触目萧瑟凄怆，离唐虞之世愈来愈远了；军阀联翩抗轭，似乎又重现了楚汉的危局。所谓的圣明之朝却是盗贼蜂起，边鄙之地的异俗风景就更是喧阗卑下了。郁郁盘结、上绕星辰的剑气下是兵锋森列，苍苍无际、如云雨笼罩池上的是战气蒸腾。东、西各镇都设起了将军的幕府，到处都是军旗在飘荡。东汉马援立于南海交趾极界的铜柱已被残毁，像西风渐紧、东风避之不及似的，西边的月支（指吐蕃）又屡次入侵。自己流寓异域，乌鹊啼鸣却空报亲人的音信，又时时听见山野的熊罴怒号，这样的心境岂是“恨”“怪”能道得分明的？只好将每日的稼穑生活以吟诗的兴致来表达，柴门茅屋里的自食其力的生活也能使一个读书人自得其乐。想到长安故居烟草迷茫的白阁和白阁下秋水弥漫的皇陂，有家难归，只好以吟诗来分解自己的离情乡思——不敢期盼能写出真能传之于后世的绝章妙句。","杜甫对诗歌艺术的传承发展和自己一生诗歌创作的主旨的思考和见解，却是以这样的五言排律的形式来表达，格律严谨，对仗工稳，一韵到底，丝毫不受约束，记事、议论、抒情均得心应手，足以表现出其诗歌造诣已到了炉火纯青的地步。"]},[],["https://github.com/chinese-poetry/chinese-poetry","《全唐诗》（清·曹寅等编，康熙扬州诗局本）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11631":["秋兴八首 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["玉露凋伤枫树林，巫山巫峡气萧森。","江间波浪兼天涌，塞上风云接地阴。","丛菊两开他日泪，孤舟一系故园心。","寒衣处处催刀尺，白帝城高急暮砧。"],"大厯元年秋䕫州作刘云八诗大体沈雄富丽哀伤无限尽在言外故自不厌确实小家数不可彷佛耳",[["古评·《唐诗品汇》","大厯元年秋䕫州作刘云八诗大体沈雄富丽哀伤无限尽在言外故自不厌确实小家数不可彷佛耳"],["古评·《唐诗品汇》","刘云此七字痛甚"]],{"source":"周啸天","body":["要之，《秋兴八首》在内容上怀乡恋阙，吊古伤今，诗人生平思想得到集中的表现；在艺术上声韵沉雄，辞采高华，气象森罗，风格沉郁。而它在杜甫七律中具有特殊地位的，更因为其缜密的组诗体制——以序诗、三望、四忆的结构组成，在风格上也有变化，大体前四章即景抒怀，但章法、内容并不一样，风格则皆沉郁顿挫，一如《登楼》《登高》《白帝》等独立成篇的七律，它们合看有序性很强，分开则可以独立成章。后四章则不然，它们的章法、内容极为相似，像是一个个五彩缤纷的梦境。每章前六句大抵都用浓丽的色彩、斑斓的笔触、华丽的辞藻绘成，是一幅幅行乐图，风格类似初唐标格和诗人在宫廷中所写《奉和贾至舍人早朝大明宫》一类作品，所不同者，唯以末二句扫空前数句的繁华，好一似“七尺珊瑚只自残”（清郑燮《道情》），它们在组诗中起到了以对比手法表达今昔盛衰的压轴戏的作用，更应放到组诗中去欣赏。"]},[],["https://github.com/chinese-poetry/chinese-poetry","《全唐诗》（清·曹寅等编，康熙扬州诗局本）","古籍注评：《唐诗品彚（附唐诗拾遗）》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩品彚_(四庫全書本)）"]],"open_11632":["秋兴八首 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["夔府孤城落日斜，每依南斗望京华。","听猨实下三声泪，奉使虚随八月查。","画省香炉违伏枕，山楼粉堞隐悲笳。","请看石上藤萝月，已暎洲前芦荻花。"],"",[["古评·《唐诗品汇》","刘云语苦"],["古注·《杜詩詳註》","杨慎云当作查"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗品彚（附唐诗拾遗）》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩品彚_(四庫全書本)）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11633":["秋兴八首 三","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["千家山郭静朝晖，一日江楼坐翠微。","信宿渔人还泛泛，清秋燕子故飞飞。","匡衡抗疏功名薄，刘向传经心事违。","同学少年多不贱，五陵衣马自轻肥。"],"刘云泛泛无所得也",[["古评·《唐诗品汇》","刘云泛泛无所得也"],["古评·《唐诗品汇》","刘云既前後不相渉只用二人名亦莫知其意之所在落落可人"],["古注·《杜詩詳註》","吕东莱选本作百处"],["古注·《杜詩詳註》","三章言䕫州朝景上四咏景下四感懐秋髙气清故朝晖冷静山遶楼前故坐对翠㣲渔人燕子即所见以况已之淹留杜臆舟泛燕飞此人情物性之常旅人视之偏觉增愁曰还曰故厌之也邵注公常论救房琯忤㫖几被戮辱此功名不若衡也公尝待制集贤院试後送隷有司此传经不如向也逺注匡衡抗疏刘向传经上四字一读功名薄心事违属公自慨顾注同学少年不过志在轻肥见无闗於轻重也末句五陵起下长安拾遗记千家万戸之书谢朓诗还望青山郭陆机诗扶桑升朝晖庾信诗石岸似江楼尔雅疏山气青缥色曰翠㣲凡山逺望则翠近之则翠渐㣲诗于汝信宿注再宿曰信徐访诗渔人迷旧浦诗泛泛扬舟殷仲文诗独有清秋日能使髙兴尽古诗秋去春还双燕子文昌杂録燕子至秋杜乃去仲春复来谢灵运诗飞飞燕弄声以故对还是依旧之词非故意之谓或引子规诗故作傍人低未合匡衡传元帝初即位有日食地震之变上问以政治得失衡数上疏陈便宜上悦其言迁衡为光禄大夫太"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗品彚（附唐诗拾遗）》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩品彚_(四庫全書本)）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11634":["秋兴八首 四","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["闻道长安似弈棊，百年世事不胜悲。","王侯第宅皆新主，文武衣冠异昔时。","直北关山金鼓振，征西车马羽书迟。","鱼龙寂寞秋江冷，故国平居有所思。"],"",[["古注·《杜詩詳註》","平声一作堪"],["古注·《杜詩詳註》","一作迟非"],["古注·《杜詩詳註》","四章囘忆长安叹其洊经丧乱也上四伤朝局之变迁下是忧边境之侵逼故国有思又起下四章杜臆长安一破於禄山再䧟於吐蕃如奕棋迭为胜负即此百年中而世事有不胜悲者百年谓开国至今邵注王侯之家委弃奔窜第宅易为新主矣文武之官侥幸滥进衣冠非复旧时矣北忧回纥西患吐蕃事在广徳永泰间或指安史余孽为北冦者非顾注有所思従寂寞来故国平居之事当秋江寂寞而歴厯堪思也秋江二字㸃秋兴意杜臆思故国平居并思其致乱之由易故园心为故国思者见孤舟所系之心为国非为家也其意加切矣左传太叔文子曰今甯子视君不如奕棋其何以免乎金浚明曰自髙祖开国至大厯之初为百年左传辛有曰不及百年其为戎乎李陵答苏武书世事谬矣世説王戎悲不自胜古诗王侯多第宅後汉书传赞上方欲用文武郭泰传衣冠诸儒唐中宗授杨再思制衣冠旧齿衣冠指缙绅望族陈泽州注广徳元年吐蕃入㓂陷长安二年仆固懐恩引回纥吐蕃入冦又吐蕃冦醴泉奉天党项羌冦同州浑奴剌冦盩厔是时西北多事故金鼔震而羽书驰或谓吐蕃入长安时徵天下兵莫至故曰羽书迟非也陈又云公诗愁㸔直北是长安指䕫州之北此云直北闗山金鼓震指长安之北封禅书因其直北立五帝坛乐府有度闗山曲晋书刘琨传金鼔振於河曲崔亭伯诗戎马鸣兮金鼔震後汉书冯异拜征西大将军韩非子车马不疲弊於逺方楚汉春秋黥布反羽书至前汉息夫躬传军书交驰而辐凑羽檄重迹而狎至水经注鱼龙以秋日为夜龙秋分而降蛰寝於渊故以秋为夜也楚辞野寂寞其无人吴筠诗风起秋江上桑𢎞羊请田轮台奏皆故国地阮籍诗念我平居时又登髙有所思黄生曰下四章皆故国事特详言之以舒其悲感耳或谓寓讥明皇神仙游宴武功之事是犹其人方痛哭流涕而诬其嬉笑怒骂岂情也哉"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11635":["秋兴八首 五","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["蓬莱宫阙对南山，承露金茎霄汉间。","西望瑶池降王母，东来紫气满函关。","云移雉尾开宫扇，日绕龙鳞识圣颜。","一卧沧江惊岁晚，几回青琐照朝班。"],"刘云律句有此自觉雄浑",[["古评·《唐诗品汇》","刘云律句有此自觉雄浑"],["古注·《御选唐诗》","唐㑹要贞观间营永安宫後改为蓬莱宫咸亨初改蓬莱宫为含元殿又改大明宫北据髙原南望爽垲毎天晴日朗南望终南如指掌京城坊市阶陌俯视如在槛内剧谈録含元殿凿龙首冈以为基址左右立栖鳯翔鸾二阙史记髙祖纪萧丞相营作未央宫宫阙壮甚陈子昂诗宫阙星河低拂树诗幽幽南山括地志终南山一名南山杜审言诗北斗挂城边南山倚殿前"],["古注·《御选唐诗》","史记孝武纪其後又作柏梁铜柱承露仙人掌之属注仙人以手掌檠盘承甘露也三辅旧事建章宫承露盘髙二十六丈大七围以铜为之上有仙人掌承露和玉屑饮之班固西都赋抗仙掌以承露擢双立之金茎注金茎铜柱也卢照隣诗金茎承露起剧谈録含元殿殿门去南门五里元㑹来朝者仰瞻玉座如在霄汉"],["古注·《御选唐诗》","列子周穆王升崑仑之丘遂賔于西王母觞於瑶池之上汉武故事七月七日上斋居承华殿忽有一青鸟従西来集殿上上问东方朔朔曰西王母欲来有顷王母至魏元忠诗寒风生玉树凉月下瑶池"],["古注·《御选唐诗》","闗令内传关令尹喜周之大夫也登楼四望见东极有紫气西迈喜曰九十日之外应有圣人经过京邑至期果见老子抱朴子老子西游遇关令尹喜于散关为喜着道徳经一巻谓之老子或以为函谷关西征记关城路在谷中深险如函故名"],["古注·《御选唐诗》","陆慧晓诗旌翻玉华晦神转云光移古今注雉尾扇起於殷世髙宗时有雉雊之祥服章多用翟羽周制以为王后夫人之车服缉雉羽为扇以障翳风尘也唐书仪衞志唐制人君举动必以扇大驾卤簿雉尾障扇四小团雉尾扇四方雉尾扇十二小雉尾朱画团扇皆十二"],["古注·《杜詩詳註》","旧作宫别作仙"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗品彚（附唐诗拾遗）》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩品彚_(四庫全書本)）","古籍注评：《御选唐诗》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/御選唐詩_(四庫全書本)）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11636":["秋兴八首 六","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["瞿唐峡口曲江头，万里风烟接素秋。","花萼夹城通御气，芙蓉小苑入边愁。","朱帘绣柱围黄鹤，锦缆牙樯起白鸥。","回首可怜歌舞地，秦中自古帝王州。"],"刘云两句写幸蜀之怨懐故京之思不分逺近如将见其实焉",[["古评·《唐诗品汇》","刘云两句写幸蜀之怨懐故京之思不分逺近如将见其实焉"],["古评·《唐诗品汇》","刘云对句耳不足为雅丽"],["古注·《杜詩詳註》","卢徳水疑上四用宫殿字太多五六似早朝诗语今按赋长安景事自当以宫殿为首所谓不覩皇居壮安知天子尊也公以布衣召见感荷主知故追忆入朝觐君之事没齿不忘若必全首俱説秋景则笔下有秋意中无兴矣此章下六句俱用一虚字二实字於句尾如降王母满函闗开宫扇识圣顔惊嵗晚㸃朝班句法相似未免犯上尾叠足之病矣"],["古注·《杜詩詳註》","六章思长安曲江叹当时之逰幸也上四叙致乱之由下四伤盛时难再瞿峡曲江地悬万里而风烟遥接同一萧森矣长安之乱起自明皇故追叙昔年游幸始末杜臆城通御气前则敦伦勤政苑入边愁後则耽乐召忧见一人之身而理乱顿殊也因想边愁未入之先江上离宫珠帘围鹄江间画舫锦缆惊鸥曲江歌舞之塲回首失之岂不可怜然秦中自古建都之地王气犹存安知今日之乱不转为他日之治乎顾注宫殿宻而黄鹄之举若围舟楫多而白鸥之游忽起此皆实景旧云柱帷绣作黄鹄文者非陈泽州注曲江与乐游园杏园慈恩寺等相近地本秦汉遗迹唐开元中疏凿更为胜境故有末二句帝王州又起下汉武帝方舆胜览瞿塘峡在䕫州东一里旧名西陵峡乃三峡之门陆机辨亡论谨守峡江口剧谈録曲江池塘开元中疏凿为胜境花卉环周烟水明媚都人游赏盛於中和上已节刘餗小説园本古曲江文帝恶其名曲改名芙蓉为其水盛而芙蓉富也韦鼎诗万里风烟异刘琨诗繁英落素秋注秋西方白色故曰素秋旧唐书南内曰兴庆宫宫西南隅有花蕚相辉勤政务本之楼开元二十六年六月遣范安及於长安广花蕚楼筑夹城至芙蓉苑长安志开元二十年筑夹城入芙蓉园自大明宫夹罗城复道经通化门以达南内兴庆宫次经明春延喜门至曲江芙蓉园而外人不之知也张正见诗御气响钧天小苑指冝春苑一统志芙蓉苑即秦冝春苑地汉书萧望之传署小苑东门𠉀庾信诗停车小苑外汉苏子卿诗故乡梦中近边愁酒上寛西京杂记昭阳殿织珠为帘裴子野诗流云飘绣柱西京杂记昭帝始元元年黄鹄下建章太液池中帝作歌庾信诗锦缆回砂碛哀江南赋铁轴牙樯古诗象牙作㠶樯埤苍樯尾鋭如牙也何逊诗可怜双白鸥朝夕水上游王粲七哀诗南登灞陵岸回首望长安庾信诗正自古束歌舞地史记刘敬传轻骑一日一夜可至秦"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗品彚（附唐诗拾遗）》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩品彚_(四庫全書本)）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11637":["秋兴八首 七","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["昆明池水汉时功，武帝旌旗在眼中。","织女机丝虚月夜，石鲸鳞甲动秋风。","波漂菰米沈云黑，露冷莲房坠粉红。","关塞极天唯鸟道，江湖满地一渔翁。"],"",[["古注·《杜詩詳註》","中谢朓诗江南佳丽地金陵帝王州秦纪卫鞅説孝公曰秦据河山之固东向以制诸侯此帝王之业也泽州陈廷敬曰此承上章先宫殿而後池苑也下继昆明二章先内苑而及城外也上下四章皆前六句长安後二句䕫州此章在中间首句从瞿唐引端下六则专言长安事俱见章法变化"],["古注·《杜詩詳註》","一作月夜"],["古注·《杜詩詳註》","七章思长安昆明池而叹景物之逺离也织女二句记池景之壮丽承上眼中来波漂二句想池景之苍凉转下闗塞去於四句分截方见曲折生动旧説将中四句作伤感其衰杜臆作追遡其盛此独分出一盛一衰何也曰织女鲸鱼亘古不移而菰米莲房逢秋零落故以兴已之漂流衰谢耳穿昆明以习水战其迹起於武帝此云旌旗在眼是借汉言唐若逺谈汉事岂可云在眼中乎公寄岳州贾司马诗无复云䑓仗虚修水战船则知明皇曾置船於此矣身阻鸟道而迹比渔翁以见还京无期不复覩王居之盛也陈泽州注闗塞即塞上风云江即江间波浪带言湖者地势接近将赴荆南也公诗天入沧浪一钓舟独把钓竿终逺去皆以渔翁自比汉书元狩三年发谪吏穿昆明池臣瓒曰西南夷传越巂昆明国有滇池方三百里汉使求通身毒国为昆明所闭欲伐之故作昆明池象之以习水战在长安西南周回四十里虞茂诗昆明池在长安县西二十里虞荗诗昆明池水秋色明史记平凖书武帝大修昆明池治楼船髙十余丈旗帜加其上甚壮西京杂记昆明池中有戈船楼船各数百艘楼船上建楼橹戈船上建戈矛四角垂幡旄旌葆麾盖照灼涯涘家语旌旗缤纷徐陵诗宻意眼中来曹毗志怪昆明池作二石人东西相望象牵牛织女晋夏歌昼夜理机丝虚夜动秋静与动对西京杂记昆明池刻玉石为鲸鱼每至雷雨常鸣吼首尾皆动刘孝威诗雷奔石鲸动水濶牵牛遥蔡邕汉律赋鳞甲育其万物陈琳檄随波漂流本草图经菰即茭白其䑓中有黑者谓之茭郁後结实雕菰米也庾府吾诗黑米生菰葑青花出稻苗赵次公曰沉云黑言菰米之多一望黯黯如云之黑也鲍照诗沉云日夕昏蔡邕月令章句隂者宻云也沉者云之重也沉云意本此王褒诗塞近边云黑陶潜诗昔为三春蕖今作秋莲房庾肩吾诗秋树翻红叶寒池坠黑莲徐孝伯诗讵识铅粉红邵注莲初结子花蒂褪落故坠粉红庾肩吾诗辇道同闗塞孔丛子世人言髙者必以极天为称南中八志鸟道四百里以其险絶兽犹无蹊特上有飞鸟之道耳列子身在江湖之中隋望江南曲游子不归生满地傅𤣥诗渭滨渔钓翁乃为周所谘"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11638":["秋兴八首 八","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["昆吾御宿自逶迤，紫阁峰阴入渼陂。","香稻啄余鹦鹉粒，碧梧栖老凤皇枝。","佳人拾翠春相问，仙侣同舟晚更移。","彩笔昔游干气象，白头吟望苦低垂。"],"刘云语有悲慨可念",[["古评·《唐诗品汇》","刘云语有悲慨可念"],["古评·《唐诗品汇》","刘云甚有风韵春字又胜"],["古注·《杜詩詳註》","杨慎曰隋任希古昆明池应制诗回跳牵牛渚激赏镂鲸川便见太平宴乐气象今一变云织女机丝虚夜月石鲸鳞甲动秋风读之则荒烟野草之悲见於言外矣西京杂记太液池中有雕菰紫箨緑节鳬雏雁子唼喋其问三辅黄图云宫人泛舟采莲为巴人櫂歌便见人物游戱宫沼富贵今一变云波漂菰米沉云黑露冷莲房坠粉红读之则兵戈乱离之状俱见矣杜诗之妙在能翻古语千家注无有引此者因悟杜诗之妙如此按王嗣奭云织女鲸鱼铺张伟丽壮千载之观菰米莲房物産丰饶溥万民之利此本追遡盛事也范季随陵阳室中语曰少陵七律诗卒章有时而对然语意皆收结之词今人学之於诗尾作一景聨一篇之意无所归宿非诗法也"],["古注·《杜詩詳註》","一夲首句在汉陂之下"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗品彚（附唐诗拾遗）》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩品彚_(四庫全書本)）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11639":["咏怀古迹五首 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["支离东北风尘际，漂泊西南天地间。","三峡楼台淹日月，五溪衣服共云山。","羯胡事主终无赖，词客衰时且未还。","庾信平生最萧瑟，暮年诗赋动江关。"],"大历元年（766）杜甫寓居夔州，作《咏怀古迹五首》，此为其一。组诗借咏古迹以抒怀，此首总起，自叙漂泊之迹，并以庾信自况。庾信本南朝梁人，出使北周被留，终身不得南归，作《哀江南赋》以寄其情。",[["1. **支离**","流离漂泊貌。"],["2. **东北**","指安史之乱发源地。"],["3. **风尘**","战乱。"],["4. **三峡**","长江三峡，在今重庆、湖北间。"],["5. **五溪**","西南少数民族地区。"],["6. **羯胡**","指安禄山，本羯族。"],["7. **词客**","杜甫自指，亦指庾信。"],["8. **庾信**","南朝梁诗人，被留北朝，作《哀江南赋》。"],["1. **宗臣**","世所宗仰之臣。"],["2. **三分割据**","魏蜀吴三分天下。"],["3. **纡筹策**","曲折运筹谋划。"],["4. **一羽毛**","如云霄中一羽，独一无二。"],["5. **伊吕**","伊尹、吕尚，商、周名臣。"],["6. **萧曹**","萧何、曹参，汉初名相。"],["7. **汉祚**","汉之国运。"],["8. **身歼**","身死。"],["古注·《杜詩詳註》","鹤注此当是大厯元年䕫州作杜臆五首各一古迹首章前六句是发已懐亦五章之总冒其古迹则庾信宅也宅在荆州公未到荆而将有江陵之行流寓等於庾信故咏懐而先及之然五诗皆借古迹以见已懐非专咏古迹也又云懐庾信宋玉以斯文为已任也懐先主武侯叹君臣际㑹之难逢也中间昭君一章盖入宫见妬与入朝见妬者千古有同感焉"]],{"source":"周啸天","body":["次联概括昭君出塞，死葬青冢之始末，从南朝梁江淹《恨赋》中来——“明妃去时，仰天叹息，紫台（指汉宫）稍远，关山无极；望君王兮何期，终芜绝兮异域。”“青冢”，在今内蒙古呼和浩特市南，东汉蔡邕《琴操》说“胡中多白草而此冢独青”，这一传说饱含人民对昭君的同情。两句用流水对，“一去”明不返矣；“连字明关山无极矣；“独留”明其孤单；“向黄昏”连文，则将时间概念转为空间意象，在读者眼前展开一片胡地黄昏的天幕，独有那小小孤冢以其特有的青青之色，引人注目。","三联写昭君之恨。昭君之恨一在不得相知，而汉元帝也就成为从来昏聩之主的一面镜子。昭君之恨又并不仅在不得于君，其恨之二是去国怀乡之恨。所以下句有“环佩空归月夜魂”之想，写出更深一层的悲哀，充满故国之思，爱国之情。","末联感慨道，自今从仍作胡语的琵琶声中，分明还听得出曲中的怨情。这表明诗人堪称昭君千古知音，同时也传达出昭君寂寞千载之感。因为昭君泪中也有杜甫的泪，昭君的寂寞也是杜甫的寂寞。此诗的最大价值就在于成功地塑造了昭君之魂。"]},[],["https://github.com/chinese-poetry/chinese-poetry","《全唐诗》（清·曹寅等编，康熙扬州诗局本）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11640":["咏怀古迹五首 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["摇落深知宋玉悲，风流儒雅亦吾师。","怅望千秋一洒泪，萧条异代不同时。","江山故宅空文藻，云雨荒台岂梦思。","最是楚宫俱泯灭，舟人指点到今疑。"],"此为《咏怀古迹五首》之二，咏宋玉宅。宋玉为战国楚辞赋家，作《九辩》写悲秋之意，又作《高唐赋》《神女赋》咏楚王梦神女之事。杜甫过江陵（今湖北荆州），凭吊宋玉故宅，感异代之相知。",[["1. **宋玉**","战国楚辞赋家，屈原弟子。"],["2. **摇落**","宋玉《九辩》“悲哉秋之为气也，萧瑟兮草木摇落而变衰”。"],["3. **风流儒雅**","形容宋玉之才情风度。"],["4. **故宅**","宋玉在江陵之故宅。"],["5. **云雨荒台**","宋玉《高唐赋》写楚王梦神女，朝为行云，暮为行雨。"],["6. **楚宫**","楚国宫殿。"],["古注·《杜詩詳註》","首章咏懐以庾信自方也上四漂泊景况下四漂泊感懐公避禄山之乱故自东北而西南淹日月乆留也共云山杂处也五六宾主双闗盖禄山叛唐犹侯景叛梁公思故国犹信哀江南末应词客哀时後四章皆依年代为先後首章拈庾信従自叙带言之耳或因信曽居江陵宋玉故宅遂通首指信按子山自梁使周被留不返三峡五溪踪迹未到不当传㑹庄子夫支离其形者犹足以养其身全其天年注支离形体不全之貌此诗作流离之意蜀志许靖传漂泊风波絶粮茹草顾注东北纯是风尘西南尚留天地下字皆不苟吴迈逺诗西南穷天险东北毕地闗鹤曰峡程记三峡谓明月峡巫山峡广泽峡其有瞿塘灔澦燕子屏风之类皆不在三峡之数此云三峡盖指巫山为第三峡非兼明月广泽而言下章蜀主幸三峡亦同此义杜臆楼䑓指西阁言萧懿诗楼䑓自相隠後汉南蛮传武陵五溪蛮皆盘瓠之後盘瓠犬也得髙辛氏少女生六男六女织绩衣皮好五色衣服叙州图经五溪诸蛮遥接益州西郡故先主伐呉使马良招五溪诸蛮授以官爵水经注武陵有五溪谓雄溪樠溪酉溪沅溪辰溪也在今湖广辰州界左传饮食衣服不与华同蔡琰诗云山万里兮归路遐史记注江湖间谓小儿多狡猾为无赖庾信诗信在周虽位望通显常有乡闗之思乃作哀江南赋以致其意其辞曰信年始二毛即逢丧乱藐是乱离至於没齿燕歌远别悲不自胜楚老相逢泣将何及又云将军一去大树飘零壮士不还寒风萧瑟提挈老㓜闗河累年又伤心赋对玉闗而羇旅坐长河而暮年末二句即用其赋语庾信初在江南江闗正其地也後汉书岑彭破荆门长驱入江闗"],["古注·《杜詩詳註》","一作为主"]],{"source":"萧涤非","body":["> **出处**：据萧涤非《唐诗鉴赏辞典》“咏怀古迹五首”条（上海辞书出版社，1983 年版）","此诗凭吊宋玉，感异代相知。首联“摇落深知宋玉悲，风流儒雅亦吾师”起笔直抒。深知宋玉悲秋之意，其风流儒雅亦我之师。一“深”字写出相知之深。颔联“怅望千秋一洒泪，萧条异代不同时”为千古名句。怅望千秋，洒一同情之泪；萧条异代，恨不与之同时。此联写尽异代相知之痛。","颈联“江山故宅空文藻，云雨荒台岂梦思”写宋玉故宅。江山之间故宅犹存，空余文藻；云雨荒台岂真梦思之境？此联既写故宅之寥落，又为宋玉辩——所谓神女之事，岂真梦思？不过是寓言而已。尾联“最是楚宫俱泯灭，舟人指点到今疑”以楚宫作结。楚宫早已泯灭，舟人指点至今犹疑。全诗凭吊宋玉，情深一往，写尽异代知音之感。"]},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11641":["咏怀古迹五首 三","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["羣山万壑赴荆门，生长明妃尚有村。","一去紫台连朔漠，独留青塚向黄昏。","画图省识春风面，环佩空归月夜魂。","千载琵琶作胡语，分明怨恨曲中论。"],"此为《咏怀古迹五首》之三，咏昭君村。王昭君名嫱，汉元帝时宫人，以赐匈奴呼韩邪单于，远嫁朔漠。昭君村在归州（今湖北秭归）。杜甫过此，凭吊昭君，感其怨恨。",[["1. **明妃**","王昭君，晋人避司马昭讳，改称明妃。"],["2. **荆门**","荆门山，在今湖北宜都。"],["3. **紫台**","紫宫，指汉宫。"],["4. **朔漠**","北方沙漠，指匈奴之地。"],["5. **青冢**","昭君墓，在今内蒙古呼和浩特，上草色常青，故名。"],["6. **画图**","《西京杂记》载毛延寿画宫人像事。"],["7. **省识**","约略识得。"],["8. **环珮**","女子佩饰，代指昭君。"],["古评·《唐诗品汇》","刘云起得磊落"],["古注·《杜詩詳註》","按汉书注宋玊作赋盖假设其事讽谏滛惑也张綖云赋称先王梦神女盖以懐王之亡国警襄王也朱注云岂梦思明其为子虚亡是之説顾宸曰宋玉述懐王梦神女作髙唐赋又自述已梦作神女赋本托讽谏襄王耳国风以闗雎为思贤离骚比湘妃於君玉玉之两赋正合此㫖李义山诗云襄王枕上原无梦莫枉阳台一片云是也後人皆云襄王梦神女非矣文选刻本沿讹已乆王玉二字互混到底今只改正数字文义自明使玉赋髙唐之事其夜玉寝梦与神女遇其状甚丽玉异之明日以白王王曰其梦若何玉对云云王曰状如何也玉曰茂矣美矣云云王曰若此甚矣试为寡人赋之今按必如修逺説於王曰甚矣句方有着落其赋中王览其状亦当改作玉览其状又尾末所云颠倒失据惆怅垂涕者亦属自述语不似代王赋梦之词"],["古注·《杜詩詳註》","陈注明字犯重据负薪行作昭君村"],["古注·《杜詩詳註》","上声一作嵗"],["古注·《杜詩詳註》","平声此懐昭君村也上四记叙遗事下乃伤吊之词生长名邦而殁身塞外此足该举明妃始末五六承上作转语言生前未经识靣则殁後魂归亦徒然耳唯有琵琶冩意千载留恨而已朱瀚曰起处见锺灵毓秀而出佳人有几许珍惜结处言托身絶域而作胡语含许多悲愤曲中欣论正指昭君怨诗不作後人词曲黄生曰怨恨者怨已之逺嫁恨汉之无恩也陶开虞曰此诗风流摇曵杜诗之极有韵致者鲍照舞鹤赋雪满羣山世説千岩竞秀万壑争流汉书注文颖曰昭君本蜀郡秭归人也汉书王嫱字昭君石崇明君词序明君本昭君触晋文帝讳改焉一统志昭君村在荆州府归州东北四十里薛道衡诗一去无消息别赋明君去时仰天太息紫台稍逺闗山无极望君王兮何期终芜絶兮异域李善注紫台即紫宫也邵注汉宫名朱瀚曰此诗连字即无极意青塜句即芜絶意谢惠连雪赋朔漠飞沙尔雅朔北方也説文漠北方流沙也归州图经边地多白草昭君塚独青乡人思之为立庙香溪一统志昭君墓在古丰州西六十里琴操昭君有子曰世违单于死世违继立凢为胡者父死妻母昭君问世违曰汝为汉也为胡也世违曰欲为胡耳昭君乃吞药自杀淮南子日至虞渊是谓黄昏庄子宋元君将画图西京杂记元帝後宫既多使画工图形按图召幸之宫人皆赂画工昭君自恃其貌独不与乃恶图之遂不得见後匈奴来朝求美人为阏氏上以昭君行及去召见貌为後宫第一帝悔之穷按其事画工毛延夀弃市瀚曰省乃省约之省言但於画图中畧识其靣也江总和东宫故妃诗犹忆窥牕处还如解佩时若今归就月照见不须疑瀚曰环佩句乃总括其语史记南子环佩玉声璆然汉章帝语想望归魂於沙漠之表庾信昭君词胡风入骨冷夜月照心明方调琴上曲变入胡笳声瀚曰琵琶句乃融化其语释名琵琶本边人马上所鼔也推於前曰琵引却曰琶石崇明君词序昔公主嫁乌孙令琵琶马上作乐以慰其道路之思其送明君亦必尔也其造新曲多哀怨之声琴操昭君在外恨帝始不见遇乃作怨思之歌後人名为昭君怨昭君怨诗云秋木凄凄其叶萎黄有鸟处山集於苞桑养育毛羽形容生光既得升云上游曲房离宫絶旷身体摧蔵志念抑沉不得颉颃虽得委食心有徊徨我独伊何来往变常翩翩之燕逺集西羌髙山峩峨河水泱泱父兮母兮道路悠长呜呼哀哉忧心恻伤史记始皇纪贵贱分明前汉郊祀志天下怨恨庾信诗终是曲中啼"]],{"source":"萧涤非","body":["> **出处**：据萧涤非《唐诗鉴赏辞典》“咏怀古迹五首”条（上海辞书出版社，1983 年版）","此诗凭吊王昭君，写其远嫁之恨。首联“群山万壑赴荆门，生长明妃尚有村”起笔雄奇。群山万壑奔赴荆门，明妃生长之村尚在。一“赴”字写出山势之奔腾，为昭君之出场布置雄奇背景。颔联“一去紫台连朔漠，独留青冢向黄昏”为千古名句。一去汉宫远连朔漠，独留青冢对向黄昏。此联写尽昭君一生之悲剧——生离汉宫，死葬朔漠，唯青冢向黄昏而已。","颈联“画图省识春风面，环珮空归月夜魂”写汉宫之薄。汉元帝但凭画图约略识其面，昭君之魂空带环珮月夜归汉。一“省识”写汉帝之昏，一“空归”写昭君之恨。尾联“千载琵琶作胡语，分明怨恨曲中论”以琵琶作结。千载之后琵琶仍作胡地之音，分明是昭君怨恨之曲。全诗写昭君之恨，沉郁悲凉。"]},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗品彚（附唐诗拾遗）》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩品彚_(四庫全書本)）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11642":["咏怀古迹五首 四","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["蜀主窥吴幸三峡，崩年亦在永安宫。","翠华想像空山里，玉殿虚无野寺中。","古庙杉松巢水鹤，岁时伏腊走村翁。","武侯祠屋常邻近，一体君臣祭祀同。"],"此为《咏怀古迹五首》之四，咏先主庙。蜀先主刘备伐吴兵败，退守永安宫（在今重庆奉节），后崩于此。杜甫客居夔州，过永安宫故址，凭吊刘备与诸葛亮君臣，遂作此诗。",[["1. **蜀主**","刘备。"],["2. **窥吴**","伐吴。"],["3. **永安宫**","刘备崩于永安宫，在今重庆奉节。"],["4. **翠华**","皇帝仪仗之旗，以翠羽饰之。"],["5. **伏腊**","夏伏冬腊，古代祭祀之节。"],["6. **武侯**","诸葛亮，封武乡侯。"]],{"source":"萧涤非","body":["> **出处**：据萧涤非《唐诗鉴赏辞典》“咏怀古迹五首”条（上海辞书出版社，1983 年版）","此诗凭吊先主庙，感君臣际遇。首联“蜀主窥吴幸三峡，崩年亦在永安宫”叙刘备之事。蜀主伐吴至三峡，崩年亦在永安宫。一“幸”一“崩”，写尽刘备晚景之悲。颔联“翠华想像空山里，玉殿虚无野寺中”写故址之寥落。翠华仪仗只能想像于空山，玉殿已虚无于野寺之中。一“想像”一“虚无”，写尽盛衰之变。","颈联“古庙杉松巢水鹤，岁时伏腊走村翁”写古庙之现状。古庙之杉松上巢居水鹤，岁时伏腊祭祀唯有村翁。此联写出先主庙之冷落。尾联“武侯祠屋常邻近，一体君臣祭祀同”以武侯作结。武侯祠屋常与先主庙邻近，君臣一体，祭祀亦同。此联赞刘备与诸葛亮之君臣际遇，千古难得。全诗凭吊古迹，感慨深沉。"]},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11643":["咏怀古迹五首 五","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["诸葛大名垂宇宙，宗臣遗像肃清高。","三分割据纡筹策，万古云霄一羽毛。","伯仲之间见伊吕，指挥若定失萧曹。","福移汉祚难恢复，志决身歼军务劳。"],"刘云两语气㮣别足掩上句之劣知已语赞孔明者不能复出此也",[["古评·《唐诗品汇》","刘云两语气㮣别足掩上句之劣知已语赞孔明者不能复出此也"],["古注·《杜詩詳註》","此懐先主庙也上四记永安遗迹下四叙庙中景事幸峡崩年遡庙祀之由君臣同祭见余泽未泯卢注曰幸曰崩曰翠华曰玉殿尊昭烈为正统若春秋之笔首称蜀主因旧号耳後篇又称汉祚其帝蜀可见矣今按若论书法当云汉主征吴幸三峡尤见正大顾注巢水鹤见庙之乆走村翁见祭之勤又曰出师表宫中府中俱为一体言平日抱一体之诚千秋享一体之报朱瀚曰先主崩於白帝城其立庙宜也武侯祠自在沔阳而此处亦为立祠实以君臣一体之故陪享正合典礼见後主不允臣民之请为阙失矣寰宇记先主改鱼复为永安仍於州之西七里别置永安宫梁简文帝蜀道篇建平督邮道鱼复永安宫楚辞思故旧以想像兮原注殿今为卧龙寺庙在宫东谢庄送神歌璇庭寂玉殿虚上林赋乗虚无与神俱西京杂记髙松植巘应瑒灵河赋长杉峻檟抱朴子千嵗之鹤随时而鸣能登於木其未千嵗者终不能集於树上春秋繁露白鹤知夜半注鹤水鸟也夜半水伍感其生气则益喜而鸣杨恽报孙㑹宗书田家作苦嵗时伏腊烹羊炮羔斗酒自劳内宫外殿君庙臣祠有次第王褒四子讲徳论君为元首臣为股肱明其一体相待而成"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗品彚（附唐诗拾遗）》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩品彚_(四庫全書本)）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11644":["诸将五首 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["汉朝陵暮对南山，胡虏千秋尚入关。","昨日玉鱼蒙葬地，早时今盌出人间。","见愁汗马西戎逼，曾闪朱旗北斗殷。","多少材官守泾渭，将军且莫破愁颜。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11645":["诸将五首 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["韩公本意筑三城，拟绝天骄拔汉旌。","岂谓尽烦回纥马，翻然远救朔方兵胡来不觉潼关隘，龙起犹闻晋水清。","独使至尊忧社稷，诸君何以荅升平。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11646":["诸将五首 三","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["洛阳宫殿化爲烽，休道秦关百二重。","沧海未全归禹贡，蓟门何处尽尧封。","朝廷衮职虽多预，天下军储不自供。","稍喜临边王相国，肯销金甲事春农。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11647":["诸将五首 四","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["回首扶桑铜柱标，冥冥氛祲未全销。","越裳翡翠无消息，南海明珠久寂寥。","殊锡曾爲大司马，总戎皆插侍中貂。","炎风朔雪天王地，只在忠臣翊圣朝。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11648":["诸将五首 五","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["锦江春色逐人来，巫峡清秋万壑哀。","正忆往时严仆射，共迎中使望乡台。","主恩前後三持节，军令分明数举桮。","西蜀地形天下险，安危须仗出羣材。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11649":["秋日夔府咏怀奉寄郑监李宾客一百韵","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["绝塞乌蛮北，孤城白帝边。","飘零仍百里，消渴已三年。","雄劒鸣开匣，羣书满系船。","乱离心不展，衰谢日萧然。","筋力妻孥问，菁华岁月迁。","登临多物色，陶冶赖诗篇。","峡束沧江起，岩排石树圆。","拂云霾楚气，朝海蹴吴天。","煮井爲盐速，烧畲度地偏。","有时惊叠嶂，何处觅平川。","鸂鶒双双舞，猕猿垒垒悬。","碧萝长似带，锦石小如钱。","春草何曾歇，寒花亦可怜。","猎人吹戍火，野店引山泉。","唤起搔头急，扶行几屐穿。","两京犹薄产，四海绝随肩。","幕府初交辟，郎官幸备员。","瓜时犹旅寓，萍泛苦夤缘。","药饵虚狼藉，秋风洒静便。","开襟驱瘴疠，明目扫云烟。","高宴诸侯礼，佳人上客前。","哀筝伤老大，华屋艳神仙。","南内开元曲，常时弟子传。","法歌声变转，满座涕潺湲。","吊影夔州僻，回肠杜曲煎。","即今龙厩水，莫带犬戎羶。","耿贾扶王室，萧曹拱御筵。","乘威灭蜂虿，戮力効鹰鸇。","旧物森犹在，凶徒恶未悛。","国须行战伐，人忆止戈鋋。","奴仆何知礼，恩荣错与权。","胡星一彗孛，黔首逐拘挛。","哀痛丝纶切，烦苛法令蠲。","业成陈始王，兆喜出於畋。","宫禁经纶密，台阶翊戴全。","熊罴载吕望，鸿雁美周宣。","侧听中兴主，长吟不世贤。","音徽一柱数，道里下牢千。","郑李光时论，文章并我先。","阴何尚清省，沈宋歘联翩。","律比崑仑竹，音知燥湿弦。","风流俱善价，惬当久忘筌。","置驿常如此，登龙盖有焉。","虽云隔礼数，不敢坠周旋。","高视收人表，虚心味道玄。","马来皆汗血，鹤唳必青田。","羽翼商山起，蓬莱汉阁连。","管宁纱帽净，江令锦袍鲜。","东郡时题壁，南湖日扣舷。","远游凌绝境，佳句染华牋。","每欲孤飞去，徒爲百虑牵。","生涯已寥落，国步乃迍邅。","衾枕成芜没，池塘作弃捐。","别离忧怛怛，伏腊涕涟涟。","露菊班丰镐，秋蔬影涧瀍。","共谁论昔事，几处有新阡。","富贵空回首，喧争嬾着鞭。","兵戈尘漠漠，江汉月娟娟。","局促看秋燕，萧疎听晚蝉。","雕虫蒙记忆，烹鲤问沈绵。","卜羡君平杖，偷存子敬毡。","囊虚把钗钏，米尽坼花钿。","甘子阴凉叶，茅斋八九椽。","阵图沙北岸，市暨瀼西巅。","羁绊心常折，栖迟病即痊。","紫收岷岭芋，白种陆池莲。","色好梨胜颊，穰多栗过拳。","勅厨唯一味，求饱或三鱣。","儿去看鱼笱，人来坐马鞯。","缚柴门窄窄，通竹溜涓涓。","堑抵公畦棱，村依野庙壖。","缺篱将棘拒，倒石赖藤缠。","借问频朝谒，何如稳醉眠。","谁云行不逮，自觉坐能坚。","雾雨银章涩，馨香粉署妍。","紫鸾无近远，黄雀任翩翾。","困学违从衆，明公各勉旃。","声华夹宸极，早晚到星躔。","恳谏留匡鼎，诸儒引服虔。","不逢输鲠直，会是正陶甄。","宵旰忧虞轸，黎元疾苦骈。","云台终日画，青简爲谁编。","行路难何有，招寻兴已专。","由来具飞檝，蹔拟控鸣弦。","身许双峰寺，门求七祖禅。","落帆追宿昔，衣褐向真诠。","安石名高晋，昭王客赴燕。","途中非阮籍，查上似张骞。","披拂云宁在，淹留景不延。","风期终破浪，水怪莫飞涎。","他日辞神女，伤春怯杜鹃。","淡交随聚散，泽国绕回旋。","本自依迦叶，何曾藉偓佺。","鑪峯生转盻，橘井尚高褰。","东走穷归鹤，南征尽跕鸢。","晚闻多妙教，卒践塞前愆。","顾凯丹青列，头陀琬琰镌。","衆香深黯黯，几地肃芊芊。","勇猛爲心极，清羸任体孱。","金蓖空刮眼，镜象未离铨。"],"自注云郑在江陵李在夷陵",[["古评·《唐诗镜》","自注云郑在江陵李在夷陵"],["古评·《唐诗镜》","自注云平生多病卜筑遣懐因遭乱离故寝处宴安之地皆芜没弃损也"],["古评·《唐诗镜》","自注云市暨䕫人语也市井泊船处谓之市暨江水横通曲分处居人谓之瀼"],["古评·《唐诗镜》","自注云郑髙简得谢太傅之风"],["古评·《唐诗镜》","自注云李宗亲有燕昭之美燕周之裔也"],["古注·《杜詩詳註》","一作所向皆穷辙余生且系船"],["古注·《杜詩詳註》","首叙䕫府咏怀之故上六言客䕫巳乆意欲东行下六言去䕫不能聊资遣兴耳絶塞孤城皆指䕫州公自云安至此百三十里自永泰元年至此巳厯三年剑呜书系将去䕫也身遭乱离故易衰谢筋力二句承衰谢登临二句起下段晋封禅奏地险俗殊人望絶塞洙曰嶲州以西有鸟白蛮杜臆飘零只在百里而消渴已閲三年二句多少伤怀鲍照诗双剑将别离先在匣中鸣雌沉吴江里雄飞入楚城西京杂记开匣拔鞘谢承後汉书袁闳愽览羣书记老者不以筋力为礼卿云歌菁华既竭褰裳去之登临而见景物常藉诗篇以摩写之西京杂记栋字物色唯旧顔氏家训文章陶冶性灵从容讽咏亦乐事也洙曰陶如陶者之埏埴冶如冶工之熔铸"],["古注·《杜詩詳註》","音潮一作潮"],["古注·《杜詩詳註》","此咏䕫州风景峡东四句记山水煮井四句记地脉鸂𪆟六句记物産猎人二句记人事皆所谓登临多物色也树拂云而鬰霾楚气江朝海而浪蹴吴天此聨可以雄葢一世煮井一聨写得竒剏叠嶂一聨写得骇愕鸂𪆟数句写得幽闲春草寒花写得韶秀吹火引泉写得冷隽句句可以入画旧注石树石楠也王勃诗岩朝古树新地镜图楚气似马书江汉朝宗於海刘庭芝诗吴天积风霜蜀都赋滨以盐池刘曰盐池出巴东北新井县水出地如涌泉可煮为盐农书荆楚多畲田先纵火熂炉候经雨下种厯三岁土胍竭复熂旁山熂燹火燎草炉火烧山界也杜田曰楚俗烧榛种田曰畲王制量地以制邑度地以居民度地偏言不遗僻坏也梁武帝诗朝云生叠嶂峡中地浚故无平川何逊诗平川看逺鸟尔雅注鸂𪆟毛有五色庾信诗双双泪眼生刘安招隐猕猴兮熊罴乐府词鬰鬰累累庾肩吾诗"],["古注·《杜詩詳註》","锦石镇浮桥谢灵运诗春草亦未歇张协诗寒花发黄草赵曰时有屯戍在白帝城猎人吹火於此庾信诗猎火一山红洙曰峡民依山而居故以竹引山泉"],["古注·《杜詩詳註》","一作仍一作拘"],["古注·《杜詩詳註》","他本作常卢本作当"],["古注·《杜詩詳註》","原注都督柏中丞筵闻梨园弟子李仙奴歌"],["古注·《杜詩詳註》","此咏在䕫情事唤起扶行乃衰頽之状皆因偃蹇沦落所致二句作引端两京四句叙客䕫之由𤓰时六句病中所对之境苦中有乐意高宴八句旅中所触之怀乐处有哀思心烦闷故搔头路﨑岖故屐穿薄産田园乆荒随肩故交日替暮府二句忆严武荐引旅寓二句应前飘零药饵二句应前消疾开襟明目承上秋风高宴四句见节镇之繁华南内四句感明皇之逸豫後数语又引起下段师氏以唤起为晨鸟以扶行为竹杖冷斋诗话退之诗唤起窗前曙催归日未西无心花里鸟更与尽情啼唤起催归二鸟名催归子规也唤起声如络□圆转清亮偏於春晓鸣江南谓之春唤易林鸠杖扶老陶潜归去来辞策扶老以流憩西京杂记武帝过李夫人取玉簪搔头晋书阮孚尝自蜡屐因叹曰未知一生能着几两屐两京谓长安洛阳沈佺期诗上京无薄産记五年以长则肩随之蔡邕荐边让於何进曰幕府初开博选清英申屠嘉传为丞相备员而巳左传齐侯使连称管至父戍葵丘曰瓜时而徃及瓜而代谢灵运诗苹萍泛㴱沉吴都赋夤縁山岳之岊韵㑹夤縁连络也谢灵运诗药饵情所止狼籍出汉书谢灵运诗还得静者便登楼赋向北风而开襟唐书韦思谦曰须明目张胆以报天子顔延之城阙生云烟庾信诗将军高宴罢古诗主人爱上客魏文帝书哀筝倾耳曹植箜篌引空存华屋处古诗金屋罗神仙唐书兴庆宫在皇城东南距京城之东开元初置至十四年又增广之谓之南内唐㑹要开元二年上於梨园自教法曲号皇帝梨园弟子又太常梨园别教院法歌乐章曲等朱注白居易诗法曲法曲合夷歌夷声邪乱华声和以乱干和天宝末明年胡尘犯宫阙自注云𤣥宗虽雅好度曲然未尝使蕃汉杂奏天宝十三年始诏诸道调法曲与胡部新声合作识者㴱叹异之明年冬禄山反隋李孝贞诗间关既多绪变转复无穷孔子丘陵歌涕霣潺湲"],["古注·《杜詩詳註》","川本作教"],["古注·《杜詩詳註》","川作首恶"],["古注·《杜詩詳註》","一作频烦"],["古注·《杜詩詳註》","此回忆长安时事䕫州句承上杜曲句领下龙廐水羶吐蕃陷京也耿贾四句思灵武将相旧物四句恶当时叛将奴仆四句推祸本於程元振哀痛以下指代宗还京之事旧物谓帝京如故凶徒如李怀玉之逐侯希逸仆固怀恩之诱吐蕃是也王道俊博议公以代宗不能徃问河北之罪而但慕止戈之名养成祸乱故曰国须行战伐人忆止戈鋋葢伤之也卢注程元振以奴仆而错与大权致将士懈心外夷入冦而生民困苦旧指禄山为奴仆者非朱注旧纪永泰元年正月下制罪巳二年十一月大赦改元停什亩税一法此所谓哀痛切烦苛蠲也陈"],["古注·《杜詩詳註》","劭曰泰阶天之三阶也上阶为天子中阶为诸侯公卿下阶为士庶人王俭作禇渊碑文外矅台阶魏神武帝传檄方镇曰天方与魏必将有主翼戴圣明洪容斋随笔史记载西伯出猎而遇太公其卜辞乃非龙非彲非虎非罴崔駰达㫖引史记作非熊非罴此杜诗所本也诗序鸿雁美宣王也美其能劳来还定安集也"],["古注·《杜詩詳註》","原注郑在江陵李在夷陵"],["古注·《杜詩詳註》","此段承前起後作通篇过峡每欲十句承杜曲一段伤故里难归共谁十句承郑李一段喜知交足慰百虑牵包下八句生涯愁在身国歩忧在国衾枕池塘无家可问矣别离悲弟妹㐲腊思祖父丰镐涧瀍念及东西二京也又言故人凋谢如此巳亦懒於进取矣今托身兵戈江汉之间徒增局促萧条耳幸䝉二公记问真旧交中不可多得者雪赋羡云鸠之孤飞江淹诗抚枕怀百虑庄子吾生也有涯诗国歩斯频蔡邕述行赋涂迍邅其蹇连兮锦衾角枕见毛诗隋孙万夀诗蓬莱虽巳变池塘尚所思吴越春秋体骨弃捐诗劳心怛怛汉杨恽传岁时伏腊风俗通曰腊者猎也猎取兽以祭祖先师古曰建丑之月为腊祭诗泣涕涟涟又作邑於丰又镐京辟雍注镐京在丰水之东相去三十五里周书我乃卜涧水东瀍水西张华诗昔事厯厯记独坐向谁论风俗通阡谓之冡崔融诗京兆新阡辟世説刘琨曰常恐祖生先我着鞭王褒诗漠漠村烟起鲍照"],["古注·《杜詩詳註》","此答二公之问备述居䕫秋况郑李必问及居处饮食故答词独详卜羡四句䕫州饮食甘子四句䕫州居室羁绊八句仍申饮食俗异八句仍申居室卜杖存氊生计艰难把钗折钿藉供日用沙北瀼西乃甘隂结斋之处心折病痊答书中沉绵之问紫芋数者见物産之佳隣鲛既危坐鞯复窘柴门之中唯存竹溜而巳抵畦依庙村居外景拒棘纒藤村居内景也洙曰君平卜筮於成都得百钱足自养则闭肆下帘而授老子阮宣子常步以百钱挂杖头至酒店便得酣畅子敬氊见首巻钗钏见官军临贼濠诗庾肩吾诗萦环照镜晓谁忍去花钿南史顾初牵牛隂凉木下徐陵诗茅斋本自空桓温传初诸葛亮造八阵图於鱼复平沙之上原注峡人目市井泊船处曰市暨江水横通出谷处方人谓之瀼晋载纪马能千里不免羁绊心折见别赋诗衡门之下可以栖迟货殖传岷山之下沃野千里下有蹲䲭至死不饥注蹲䲭芋也御览任昉述异记吴中有陆家白莲种顾家斑竹蜀都赋紫梨津润西京杂记上林苑有峄阳栗峄阳都尉曹龙所献大如拳穰丰穰也古陇西行谈笑未及竟右顾勅中厨王羲之传有一味之甘割而分之论语食无求饱杨震传有冠雀衔三鱣鱼飞集讲堂前谢承书鱣字皆作鱓然则鱣鳝古字通顔氏家训孙卿云鱼鼈鰌鱣韩非説苑皆曰鱣似蛇蚕似蠋并作鱣字假鱣为鱓其来乆矣按杨震传三鱣音善所谓假鱣为鱓者也尔雅释鱼音知然反陆德明音义张连反即黄鱼也此鱣鲔之鱣杜诗所谓三鱣也葢用杨震传三鱣而兼取郭陆音释未知当否吴曾曰以杨震碑考之则云贻我三鱼以辩懿德称鱓未必皆得其真也俗异犹云异俗文选鲛人织絠於泉室当作俗异隣鲛室此段本言居室不当插入鱼笱诗敝笱在梁其鱼鲂鳏注笱以竹为之鱼入其中晋书范逵尝过陶侃家时大雪乃撒所卧鞯自剉给其马朱注旧注战国策苏秦激张仪令相秦以马鞯席坐之按朋来坐马鞯犹云坐客寒无氊也与苏张事不合且旧注引国策艺文类聚又引史记今国策史记并无此文通竹溜涓涓即前野店引山泉但前是槩言䕫俗此乃专叙瀼居不妨一事两用陶辞泉涓涓而始流张耒曰公畦官园也原注京师农人指田逺近多云几棱棱岸也音去声朱注按韵书棱字无去音葢方言也陆龟䝉诗我本曾无一棱田平生笑傲空渔船棱亦作去声用晁错传凿太上皇庙堧垣师古曰堧者内垣外游地薛道衡诗卧石藤为缆"],["古注·《杜詩詳註》","此因身既辞官望二公入朝以佐主上十句公自述下十句朂郑李朝谒不预则起居自适亦何羡章署之荣乎所以黄雀卑飞唯知旧学而紫鸾高举端属明公矣朱注二公当勉为公辅之业引贤士进谠言以匡正天下今上方宵旰民多疾苦云台虽有功臣而青简垂名非二公其谁属耶萧景宗诗借问霍去病何如路傍人此用其句法沈佺期诗鷄鸣朝谒满南史朱百年饮酒醉眠前汉公卿表银章印龟钮其文曰章谓刻其官之章也赵曰省谓之兰者以诸郎官握兰含香也故云馨香又谓之画省者以粉画之也故云粉署陈子昻诗驱驰翠虬驾伊鬰紫鸾笙汉歌謡桂树华不实黄雀巢其颠鹪鹩赋育翩翾之陋体兮困学从衆俱出论语违衆谓不合时宜後汉皇甫嵩传嵩答董卓曰昔与明公俱为鸿鹄杨恽传方当盛汉之隆愿勉旃无多谈旃语助词刘峻书声华无寂殷仲文自解表宸极反正韩非子无早晚之失洙曰郎官象列星诸侯象四七宰相法三台皆星躔也束晳诗星变其躔汉书日月初躔星之纪注躔舍也匡衡传诸儒为语曰无説诗匡鼎来匡説诗解人頥张晏曰衡少时字鼎长乃易字稚圭西京杂记鼎衡小名後汉儒林传服䖍字子慎少以清苦建志入太学受业善着文举孝廉输犹献也荀子君有忠臣谓之骨鲠扬子甄陶天下在和汉书音义陶家名朴下员转者为钧以其制器为大小馈食礼纚笄宵衣左传楚君大夫其旰食乎易忧虞之象也孝经鈎命诀授图子黎元刘琨劝进表司牧黎元汉书问民疾苦轸骈凑集之意取义於车马也云台注别见文选载刘向别録治竹青作简书谓之青简又见後汉吴佑传"],["古注·《杜詩詳註》","原注郑高简得谢太傅之风"],["古注·《杜詩詳註》","平声原注李宗亲有燕昭之美燕周之裔"],["古注·《杜詩詳註》","一作晤晋作豁"],["古注·《杜詩詳註》","此欲出峡求禅与二公相晤於江陵行路招寻为通节之纲飞檝二句承行路身许四句承招寻安石四句欲访二公亦承招寻披拂四句将赴荆门亦承行路他日四句去䕫留荆双结行路招寻控鸣备不虞追宿昔遂初愿也双峯七祖言不落旁门小乗郑比安石公则仰其名高李比燕昭公则愿为燕客有地主可免途穷驾浮舟有似乗槎公诗穷途阮籍几时醒又云奉使虚随八月槎皆属自言云宁在景不延急於去䕫矣淡交指䕫人回旋徃复於郑李也古乐府有行路难杜审言诗招寻独有君海赋飞迅鼓檝西域传控者十余万按双峯有两处旧唐书道信与𢎞忍并住蕲州双峯山东山寺故谓其法为东山法门姚寛西溪丛语引宝林传云能太师传法衣在曹溪宝林寺宝林後枕双峯则曹溪亦称双峯矣周篆曰昔至岭南见曹溪地形前对三峯後拥两峯但不名双峯寺七祖亦有两𣲖达摩传慧可可传僧粲粲传道信信传𢎞忍此五祖也忍传能大师是谓六祖其徒复以荷泽当七祖此南宗之余裔也中岳越禅师记则云𢎞忍传大通大通传大照此北宗又窃附於六祖七祖也考能师既没法衣不传则南宗七祖固失真传而北宗上无承受篡名两祖尤为谬种矣诗云门求七祖禅意葢主於南宗也师氏曰自达摩至慧能谓之中华六祖六祖之道至肃宗时方盛肃宗甞自曹溪请其衣鉢供养是六祖与子美同时先後人也故求禅言七祖而不言六祖何逊诗解缆及朝风落帆依暝浦庄子孰居无事而披拂是楚辞蹇淹留而无成谢灵运诗寻异景不延风期恐是言风信虞世基诗伊昔风期早南史宗慤曰愿乗长风破万里浪孔子世家水之怪龙罔象也江赋扬鬐掉尾喷浪飞涎神女注见前蜀都赋鸟生杜鹃之魂记君子之交淡若水泽国见周礼史记汉长沙定王曰国小地狭不足回旋"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗镜》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩鏡_(四庫全書本)）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11650":["赠李八秘书别三十韵","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["往时中补右，扈跸上元初。","反气凌行在，妖星下直庐。","六龙瞻汉阙，万骑略姚墟。","玄朔回天步，神都忆帝车。","一戎才汗马，百姓免爲鱼。","通籍蟠螭印，差肩列凤舆。","事殊迎代邸，喜异赏朱虚。","寇盗方归顺，乾坤欲晏如。","不才同补衮，奉诏许牵裾。","鸳鹭叨云阁，麒麟滞玉除。","文园多病後，中散旧交疎。","飘泊哀相见，平生意有余。","风烟巫峡远，台榭楚宫虚。","触目非论故，新文尚起予。","清秋凋碧柳，别浦落红蕖。","消息多旗帜，经过叹里闾。","战连唇齿国，军急羽毛书。","幕府筹频问，山家药正锄。","台星入朝谒，使节有吹嘘。","西蜀灾长弭，南翁愤始摅。","对敭抏士卒，乾没费仓储。","势藉兵须用，功无礼忽诸。","御鞍金騕褭，宫砚玉蟾蜍。","拜舞银钩落，恩波锦帕舒。","此行非不济，良友昔相於。","去斾依颜色，沿流想疾徐。","沈绵疲井臼，倚薄似樵渔。","乞米烦佳客，钞诗听小胥。","杜陵斜晚照，潏水带寒淤。","莫话清溪发，萧萧白暎梳。"],"",[["古注·《杜詩詳註》","鹤注当是大厯元年七月作"],["古注·《杜詩詳註》","首忆秘书扈从之事反气四句上皇西巡𤣥朔四句肃宗兴复通籍以下秘书侍従也当时驾次马嵬帝自陈仓而赴蜀路经汉中太子自彭原之朔方即位灵武所谓万骑畧姚墟者指上皇也𤣥朔回天步者指肃宗也通籍李得出入行宫差肩谓随朝士而趋辇後肃宗以恢复入京非由继统嗣位故与代邸迎立者有殊梦弼曰秘书宗室故比朱虚未能优擢故云赏异洙曰扈扈从也跸鸣跸也天子出鸣跸以清道庾信赋遭东南之反气行在妖星注皆见前陆机诗厌直承明庐六龙天子之驾易时乗六龙以御天嵇康诗乘云驾六龙梁宣帝诗汉殿珊瑚支蔡邕独断大驾备千乘万骑帝王世纪瞽瞍之妻握登生舜於姚墟故得姓姚氏汉书世本妫虚在汉中郡西城县世纪安原谓之妫虚或谓之姚墟赵景真书植橘柚於𤣥朔朔方𤣥武之位故称𤣥朔诗天步艰难鲍照诗明辉铄神都史天官书斗为帝车运於中央临制四方书一戎衣公孙𢎞传臣愚驽无汗马之劳左传刘子曰㣲禹吾其为鱼乎光武纪赤睂在河东但决水"],["古注·《杜詩詳註》","一作玉除赵云石渠为正"],["古注·《杜詩詳註》","此记前後聚散之迹上六往日同朝下八䕫州重晤补衮牵裾諌官之职叨云阁公授拾遗滞石渠李迁秘书多病交疎指弃官以後飘泊二句喜逢故人风烟二句客䕫景物非论故道故者无人尚起予知音有秘书也归顺注别见汉书诸侯王表四海宴如诗衮职有阙仲山甫补之袁绍书奉诏之日魏志魏文帝欲徙冀州民十万戸实河南辛毗引帝裾而誎古诗厠迹鸳鹭行潘岳赋髙阁连云三辅故事天禄阁石渠阁并在未央宫大殿北以蔵秘书令司马相如为文园令嵇康为中散大夫作絶交书楚语先王之为台榭也世説触目皆琳琅珠玉刘孺诗言赠赋新文"],["古注·《杜詩詳註》","此秘书㕘幕府事巫峡楚宫上记相见之地栁凋蕖落此记相别之时并兴起乱离凋敝之象朱注战连军急谓崔旰与杨柏及张献诚相攻原注山剑元帅相公初屈幕府㕘筹画相公朝谒今赴後期也又云秘书比卧青城山中梁简文帝诗水照栁初碧烟含桃半红谢庄诗凌别浦兮值泉跃简文诗红蕖间青锁紫露湿丹楹汉髙纪益张旗帜於山上古诗思还故里闾左传宫之竒曰辅车相依唇亡齿寒者其虞虢之谓乎魏武帝奏事若有急则挿羽於檄谓之羽檄陈子昂诗追宴入山家"],["古注·《杜詩詳註》","吾官切旧作抗非一作抗"],["古注·《杜詩詳註》","此秘书入朝後事朱注台星使节皆谓杜鸿渐秘书盖因鸿渐表荐入朝其奏对君前当以师老财匮为言盖全蜀之势今方藉兵不得不用而诸将冐功无礼如所谓抏士卒费仓储者其可忽之而不问乎是时崔盰虽归朝而杨子琳未释甲蜀中所在聚兵军储耗蠧故因秘书赴幕而及之言外亦暗规鸿渐也又云秘书将承恩赐马有锦帕之舒且入直侍书见银鈎之落也次公指杜相公於上下语势不接逺注银鈎承宫砚锦帕承御鞍拜舞之後落笔如银鈎洙云诏书也台星注见十六巻周礼地官掌邦国之使节周礼弥灾兵弥即弭也後汉冦荣疏以宁风旱以弭灾兵旧注南翁南楚老人如项羽传所称南公古人公翁二字通用也蔡邕瞽师赋抚长笛以摅愤兮书毕命对扬文武之光命陆机集对𫾻帝祉朱注上林赋抏士卒之精费府库之财而无徳厚之恩善曰抏损也音翫呉曽漫録抏挫也吾官切平凖书百姓抏弊以巧法索隠曰三苍抏音五官切抏者耗也取此音以释此诗於义甚当王褒讲徳论惊边抏士恐亦是抏士张汤传始为小吏乾没正义谓无润及之而取他人也如淳曰豫居物以待之得利为乾失利为没三国志傅嘏传岂敢寄命洪流以徼乾没裴松之注有所徼射不许乾燥之与沉没而为之也周䇿藉兵乞食於西周赵充国传遣使至匈奴藉兵左传见无礼於君者诛之如鹰鸇之逐鸟雀焉何氏语林王僧䖍曰亡兄之𦙍不宜忽诸淮南子待腰褭飞而驾之则世莫乘车西京杂记广川王发晋灵公冢得玉蟾蜍一枚大如拳光润如新玉取以盛水滴砚呉越春秋羣臣拜舞天顔舒王僧䖍论书索靖名其字书曰银鈎虿尾西京杂记覆以锦帕"],["古注·《杜詩詳註》","吴作㠶一作斾"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11651":["寄刘峡州伯华使君四十韵","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["峡内多云雨，秋来尚郁蒸。","远山朝白帝，深水谒彝陵。","迟暮嗟爲客，西南喜得朋。","哀猨更起坐，落雁失飞腾。","伏枕思琼树，临轩对玉绳。","青松寒不落，碧海阔逾澄。","昔岁文爲理，羣公价尽增。","家声同令闻，时论以儒称。","太后当朝肃，多才接迹昇。","翠虚捎魍魉，丹极上鵾鹏。","宴引春壶满，恩分夏簟冰。","雕章五色笔，紫殿九华灯。","学并卢王敏，书偕褚薛能。","老兄真不坠，小子独无承。","近有风流作，聊从月继徵。","放蹄知赤骥，捩翅服苍鹰。","卷轴来何晚，襟怀庶可凭。","会期吟讽数，益破旅愁凝。","雕刻初谁料，纤毫欲自矜。","神融蹑飞动，战胜洗侵凌。","妙取筌蹄弃，高宜百万层。","白头遗恨在，青竹几人登。","回首追谈笑，劳歌局寝兴。","年华纷已矣，世故莽相仍。","刺史诸侯贵，郎官列宿应。","潘生骖阁远，黄霸玺书增。","乳贙号攀石，饥鼯诉落藤。","药囊亲道士，灰劫问胡僧。","凭久乌皮折，簪稀白帽棱。","林居看蚁穴，野食行鱼罾。","筋力交雕丧，飘零免战兢。","皆爲百里宰，正似六安丞。","姹女萦新裹，丹砂冷旧秤。","但求椿寿永，莫虑杞天崩。","链骨调情性，张兵挠棘矜。","养生终自惜，伐数必全惩。","政术甘疎诞，词场媿服膺。","展怀诗诵鲁，割爱酒如渑。","咄咄宁书字，冥冥欲避矰。","江湖多白鸟，天地有青蝇。"],"",[["古注·《杜詩詳註》","鹤注当是大厯二年在瀼西作唐书峡州夷陵郡属山南东道"],["古注·《杜詩詳註》","声一作劳"],["古注·《杜詩詳註》","当作治避唐讳也"],["古注·《杜詩詳註》","此追遡先世渊源文为理唐初以文治世也羣公指当时才士家声谓公祖审言令闻指刘祖允济捎魍魉小人逺遁上鲲鹏贤士登朝宴引二句言宠遇之优雕章四句言才名之盛不坠无承引起下文诗令闻令望周王褒传不以地位矜物时论称之唐书刘允济武后朝上明堂赋手诏褒美甘泉赋梢魍魉而抶獝狂注捎抶皆击也王延夀梦赋捎魍魉拂诸渠庄子北溟有鱼名曰鲲化而为鸟名曰鹏江淹诗夏簟清兮冬不暮三国典畧齐萧慤尝於秋夜赋诗邢子才曰萧之斯文可谓雕章间出周史滕赵二王雕章间发南史江淹尝宿冶亭梦一丈夫自称郭璞谓淹曰吾有笔在卿处多年可以见还淹乃探怀中得五色笔一以授之谢朓诗紫殿肃隂隂汉武内传七月七日西王母至帝扫除宫内然九光之灯西京杂记元日燃九华灯於终南山上照见百里卢王卢照邻王勃褚薛褚遂良薛稷也胡震亨曰详诗语其先当是刘宪也宪与公之祖审言同列文艺传宪在则天时累官冬官员外郎审言亦为膳部员外郎是为接迹昇也宪常受诏推按来俊臣嫉其酷暴欲因事绳之反为俊臣所构坐贬故云翠虚捎魍魉俊臣贬宪转鳯阁舍人景龙中与审言同直修文馆故云丹极上鵾鹏也朱注唐史二刘皆以来俊臣构贬官後皆转鳯阁直修文馆但宪文名不甚着史称审言雅善五言诗工书翰有能名此云学并卢王书兼褚薛以刘与审言并称必属允济无疑也审言子并以手刃周季重被杀苏頲为墓志允济为祭文则二公交契之厚可知矣新书薛稷传初虞世南褚遂良以书颛家後莫能继稷外祖魏徴家多藏虞褚书故鋭精临仿结体遒丽遂以书名天下晋书刘裕曰老兄试为卿答"],["古注·《杜詩詳註》","此叙刘君诗才上八望使君寄诗下八称其诗学独精捷如骥足健比鹰扬其雕刻非可意料纤毫尽皆惬心杜臆神融句谓文有生气战胜句谓文无敌手筌蹄弃言妙悟百万层言超出公於诗道白头犹憾知名传青简者难矣以见刘能不坠而巳独无承也朱注此数句当与文赋叅看雕刻谁能料即笼天地於形内挫万物於笔端也纤毫欲自矜即考殿最於鐍铢定去留於微芒也神融蹑飞动即精骛八极心游万仞也战胜洗侵陵即方天机之骏利夫何纷而不理也妙取二句即形不可逐响难为系孤立而特峙非常言之所纬也按杜诗必有来厯不特用其字句而并融其神理於此可以触悟宋郊祀歌月竁来宾目际奉土注竁窟也赵曰恭州有明月峡今三峡中亦有之葢石壁一窍圆透见天其明如月故以名峡也按朱注月竁犹言月脇月窟草堂及郭本作竁较继字为优又近志载夷陵州有明月峡作峡亦通列子周穆王有赤骥任昉为齐竟陵王行状所造箴锦积成巻轴张华诗襟怀拥虚景文心雕龙吟讽者衔其山川庄子"],["古注·《杜詩詳註》","刻雕衆形而不为巧魏志献帝策命纤毫之恶文心雕龙延夀灵光合飞动之势韩非子子贡见子夏肥而问之子夏曰吾义战胜故肥史记炎帝欲侵陵诸侯庄子筌者所以取鱼得鱼而忘筌蹄者所以取兎得兎而忘蹄注筌者积柴水中使鱼依而食焉一云鱼笱也蹄兎𦊰也又云兎弶也系其脚故云蹄陆机文赋恒遗恨以终篇青竹即青简"],["古注·《杜詩詳註》","此言遭遇不同亦宾主并叙追谈笑忆使君局寝兴公自叹厯尽年华世故自知不堪用世矣云阁承郎官玺书承刺史刘葢郎官而出为刺史者古诗谈笑未及竟谢混诗信此劳者歌善曰韩诗伐木废朋友之道缺劳者歌其事诗人伐木自苦其事故以为文何逊诗寝兴从闲逸庾信诗年华改岁隂嵇康书世故繁其虑翟方进奏曰古选诸侯贤者以为州伯今部刺史居牧伯之位□一州之统请罢御史置州牧汉明帝曰□官上应星宿出宰百里苟非其人民受其殃潘岳秋兴赋序余以太尉椽兼虎贲中郎将寓直於散骑之省高阁连云阳景罕曜汉循吏传二千石有"],["古注·《杜詩詳註》","治理效者辄报玺书勉厉增秩赐金"],["古注·《杜詩詳註》","一作行一作幸"],["古注·《杜詩詳註》","一作昔一作旹"],["古注·《杜詩詳註》","此序客䕫近况乳贙饥鼯触景无聊药囊怜身病刼灰忧世乱凭乆见身衰簪稀言性懒无事故看蚁近水故待鱼筋力二句言垂老飘泊之状朱注言我亦为郎官县皆出宰百里今飘零若此是亦六安丞之见贬斥耳赵云公出为华州司功故用六安丞事亦通但於百里宰难贯旧注以乳贙二句属公自况於上哀猿落雁犯重卢注以贙号比豪强敛迹鼯诉比穷民待泽涉刘公言失之太凿今皆不取尔雅贙有力注出西海大秦国似狗多力犷恶张正见诗饥鼯落剑锋神仙传壶公卖药市中口不二价所治皆愈曹毗志怪汉武帝穿昆明池极㴱悉是灰墨无复土以问东方朔曰臣愚不足以知之可问西域僧後汉明帝时外国道人来洛阳有忆朔言者试以灰墨问之其人曰经云天地大刦将尽则刦烧此刦烧之余也朱注按髙僧传西域国人乃竺法兰世説韩康伯母隐古几毁坏乌皮几见十三巻杜臆凡戴冠必先簪发惟懒事稀簪故帽棱如故通典宋时制高屋白纱帽宋明帝纪建安王休仁以白㡌代之齐和帝纪百姓皆着下屋白纱帽易林蚁封户穴大雨将集晋欢闻变歌张罾不得鱼兀橹罾空归陆机乐府旧交皆雕丧诗战战兢兢免战兢不免战兢也後汉书桓谭谏用谶帝大怒出为六安郡丞意忽忽不乐道病卒注六安郡故城在今夀州安丰县南"],["古注·《杜詩詳註》","此叙寄诗本意杜臆公因多病与道士讲修炼之术故言姹女丹砂椿夀永承上药囊杞天崩承上刼灰錬丹养生又承夀永张兵伐叛又承天崩公托身世外故求服药永年不必怀杞人之虑刘身任民社则卫生固所宜讲而惩乱皆其职分也张逺注时蜀寇未靖故有张兵伐叛等语政术词塲二句必刘曾以此推服故答云政甘疎诞而词愧服膺诗酒所以遣兴於诗则诵鲁推刘君为诗宗於酒则割爱时以消病断饮也杜臆自孔子删诗诗宗於鲁称刘诗得其正宗也朱注谓公作诗以赠使君犹史克之颂鲁侯前説作诵後説作颂两意不同今从前説萦新裹新錬药也冷旧秤弃旧丹也裹砂以养火必秤量其轻重魏伯阳叅同契河上姹女灵而最神得火则飞不染垢尘又曰丹砂木精得金乃并汉真人大丹诀曰姹女隐在丹砂中注姹女汞也庄子上古有大椿者以八千岁为春八千岁为秋晋庾阐诗椿夀自有极列子杞国有人忧天地崩坠身无所寄朱注谓多欲戕生犹将兵伐性将二句作借喻又依草堂本作伐数因解为尅伐年数终觉牵强庾阐诗赤松游霞乗烟封子錬骨凌仙徐栾传陈涉起穷巷奋棘矜师古曰棘㦸也矜者棘之把秦销兵器故但有戟之把耳嵇康有养生论袁绍书奉辞伐叛潘岳西征赋思夫人之政术实干时之良具思𤣥赋潜服膺其永清兮江淹别赋割慈忍爱左传有酒如渑有肉如陵原注平生所好消渴止之"],["古注·《杜詩詳註》","以慨叹身世作结咄咄伤去官㝠㝠欲遯世白鸟比贪夫青蝇比谗人皆承避矰意此章起结四句中腰八句前二段各十六句後二段各十二句世説殷浩被废在长安终日常画空作字扬州吏人窃视唯作咄咄怪事四字而巳扬子法言鸿飞㝠㝠戈人何簒焉杜修可曰白鸟有二説一谓鸥鹭之类如诗言白鸟鹤鹤此喻贤者之㓗白也一谓白鸟乃蚊蚋以譬小人之侵侮也言贤者居乱世欲隐则为蚊蚋所噆欲出则为青蝇所汚是无逃於天地间矣朱注大戴礼夏小正丹鸟羞白鸟丹鸟丹良也白鸟蚊蚋也凡有翼者为鸟梁元帝纳凉诗白鸟翻帷暗丹萤入帷明杜臆梁元帝金楼子云齐威公卧於柏寝白鸟营饥而求饱公开翠纱之厨而进焉有不知足者长嘘短吸而食及其饱腹为之溃葢戒贪也毛诗以青蝇刺谗蔡梦弼曰韩昌黎诗蝇蚊满人区可与尽力格寓意正相同篇中用二矜矜无二音止有两解一云矛柄音勤者作𥎊"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11652":["夔府书怀四十韵","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["昔罢河西尉，初兴蓟北师。","不才名位晚，敢恨省郎迟。","扈圣崆峒日，端居灧澦时。","萍流仍汲引，樗散尚恩慈。","遂阻云台宿，常怀湛露诗。","翠华森远矣，白首飒凄其。","拙被林泉滞，生逢酒赋欺。","文园终寂寞，汉阁自磷缁。","病隔君臣议，惭纡德泽私。","扬镳惊主辱，拔劒拨年衰。","社稷经纶地，风云际会期。","血流纷在眼，涕洒乱交颐。","四渎楼船泛，中原鼓角悲。","贼壕连白翟，战瓦落丹墀。","先帝严灵寝，宗臣切受遗。","恒山犹突骑，辽海竞张旗。","田父嗟胶漆，行人避蒺藜。","总戎存大体，降将餙卑词。","楚贡何年绝，尧封旧俗疑。","长吁翻北寇，一望卷西夷。","不必陪玄圃，超然待具茨。","凶兵铸农器，讲殿辟书帷。","庙算高难测，天忧实在兹。","形容真潦倒，荅效莫支持。","使者分王命，羣公各典司。","恐乖均赋歛，不似问疮痍。","万里烦供给，孤城最怨思。","绿林宁小患，云梦欲难追。","即事须尝胆，苍生可察眉。","议堂犹集凤，正观是元龟。","处处喧飞檄，家家急竞锥。","萧车安不定，蜀使下何之。","钓濑疎坟籍，耕岩进弈棊。","地蒸余破扇，冬煖更纤絺。","豺遘哀登楚麟伤泣象尼。","衣冠迷适越，藻绘忆游睢。","赏月延秋桂，倾阳逐露葵。","大庭终反朴，京观且僵尸。","高枕虚眠昼，哀歌欲和谁。","南宫载勳业，凡百慎交绥。"],"",[["古注·《杜詩詳註》","鹤注当是大厯元年秋作"],["古注·《杜詩詳註》","所追切首叙遭遇偃蹇乃书懐之故上四为通节之纲身受郎官须惊主辱名位巳晚故拨年衰扈圣端居又作一提萍流六句为郎而思扈圣也拙被六句辞官而居灔澦也主辱年衰承上起下天宝十四年公授河西尉不拜值禄山叛扈从肃宗於鳯翔未几入蜀以严武荐除工部员外郎又辞幕府至䕫州首尾凡十二年公未尝至崆峒而云扈圣崆峒者以肃宗自平凉而至崆峒在其地也汲引指严武恩慈谓朝命宿云台宴湛露望翠华皆想为拾遗事杜臆放迹林泉而云酒赋所欺此公省愆语也病卧文园惭居汉阁以蜀中马扬自方杜臆扬镳拔剑愤激悲壮之情形於词色矣朱注主辱谓车驾幸陕鲍照诗出自蓟北门呉越春秋札虽不才鼂错传名位不失施於後世蔡质汉仪尚书郎入直台中牛𢎞诗端居留眷想海赋萍流而浮转刘向传转相汲引樗树散木出庄子萧渊明书被此恩慈云台仗见八哀诗诗序湛露天子燕诸侯也南都赋望翠华之葳蕤谢灵运诗怀贤亦凄其北史韦夐淡於荣利所居之宅枕带林泉西京杂记梁孝王集诸游士於园邹阳作酒赋汉书司马相如拜为文园令後病免家居茂陵扬雄校书汉阁此特借比西阁磷缁犹云磨砺惭纡徳泽自愧退居枉沐君恩耳或解璘缁为名玷朝班不合谢灵运诗磷缁谢清旷忠经沐浴徳泽舞鹤赋龙骧横举扬镳飞沬善曰镳马勒旁鐡史记主辱则臣死汉书叔孙通传拔剑击柱拨奋起也淮南子年衰志悯"],["古注·《杜詩詳註》","一作泗非"],["古注·《杜詩詳註》","此陈救时筹䇿承上拔剑拨年衰铸农器望息兵端辟书帷望开言路二句皆当时急务自庙算无闻恐前乱未靖而後患复生矣此段乃上下文闗捩处朱注代宗甞幸陕州故用周穆黄帝事言当此多事之秋我岂必陪车驾於𤣥圃乎但望求贤问道如黄帝之下访具茨则凶兵可销讲殿可御治平不难致矣孰知庙算不然杞人忧天实在於此惜衰老无补为足叹耳次公解都支离𤣥圃周穆王西游事陆机豪士赋超然自引髙拆而熙庄子黄帝将见大隗於具茨之山至於襄城之野七圣皆迷遇牧马童子问涂焉唐书许州阳翟县有具茨山老子兵者凶器家语铸剑㦸以为农器东方朔传文帝集上书囊为殿帷岑文本诗书帷通竹径杜诗博议通监永泰元年九月庚寅朔置百髙座於资圣西明两寺讲仁王经甲辰吐蕃十万衆至奉天京城戒严丙午罢百髙座讲十月巳未复讲经於资圣寺时羌人外讧藩镇内叛而帝与宰相元载等俱好佛息於政事讲殿辟书帷葢以讽也孙子兵未战而庙算胜者得算多也天忧用列子杞人忧天崩事嵇康书潦倒麄疎鲁灵光殿赋支持以保汉室"],["古注·《杜詩詳註》","此伤䕫州民困承上天忧实在兹使者八句叹凶兵未息而军赋日烦孤城最怨思见民穷可虑即事八句叹讲帷不开而旧章难复贞观是元龟乃起敝之方使者索饷之官典司牧民之吏疮痍蜀有崔旰之乱也绿林云梦民将为盗矣尝胆痛惩前失察眉深悉民情朱注朝议多人奈何不法贞观之治致盗贼羣起诛求益急虽然防守之犹恐不定彼蜀使频下又何为乎呉越春秋王命见符东都赋各有典司刘安谏出兵书缓刑罚薄赋敛史记季布传创痍未瘳魏志衞顗传若有归民以供给之谢承後汉书耿恭以甲兵守孤城於絶域淮南子悲则感怨思之气张咏曰緑林云梦言荆楚将乱後汉刘元传诸亡命共攻离乡聚藏於緑林中緑林山在荆州当阳县东北卢注左传楚昭王涉睢济江入云中盗攻之注云中云梦泽中也时代宗幸陕犹昭王出国故引往事为鉴欲难追追悔无及矣呉越春秋越王欲报呉怨悬胆於户出入甞之列子晋有郄雍者能视盗察眉睫之问而得其情杜臆察眉恐其蹙额也梅福书庙堂之议非草茅所当言後汉书邓隲等并奉朝请有大议诣朝堂与公卿叅谋贺循诗集鳯动春枝书今我即命於元龟刘琨劝进表前事之不忘後代之元龟也元龟大龟卜龟以大者为灵何逊诗处处皆城市左思诗边城苦鸣镝羽檄飞京都魏志王粲曰家家欲为帝王江淹书竞刀锥之利前汉萧育传南郡江中多盗贼拜育为太守上以育耆旧名臣乃以三公使车载育入殿中受策注使车三公奉使之车司马相如为郎使蜀谕巴蜀父老"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11653":["解闷十二首 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["草阁柴扉星散居，浪翻江黑雨飞初。","山禽引子哺红果，溪友得钱留白鱼。"],"説苑绳枢草舍聊庇风雨范云诗冇客欵柴扉刘琨书翕尔云合忽复星散",[["古注·《御选唐诗》","説苑绳枢草舍聊庇风雨范云诗冇客欵柴扉刘琨书翕尔云合忽复星散"],["古注·《御选唐诗》","骆宾王诗惊风湍浪翻谢朓诗朔风吹飞雨萧条江上来"],["古注·《御选唐诗》","张正见诗夏户响山禽易林鸟鸣呼子哺以酒脯李峤诗树红山果熟"],["古注·《御选唐诗》","东观汉纪赵勤従人贷钱或曰汝起拜即与勤曰拜汝得钱非义终不拜水经注圣水有白鱼出穴数日而返人有采捕食之者美珍奇味"],["古注·《杜詩詳註》","鹤注诗云一辞故国十经秋当是大厯元年䕫州作杜臆公当闷时随意所至吟为短章以自消遣耳"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《御选唐诗》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/御選唐詩_(四庫全書本)）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11654":["解闷十二首 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["商胡离别下扬州，忆上西陵故驿楼。","爲问淮南米贵贱，老夫乘兴欲东流。"],"",[["古注·《杜詩詳註》","前二首即事兴感此従䕫州风景叙起上二句山水对言山禽引子山间之景溪女留鱼江边之事杜臆草阁公所居山禽句见与物俱适溪女句见人我两忘庾信诗客园星㪚居公云安诗负盐出井此溪女又负薪行男当门戸女出入则溪女卖鱼可知"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11655":["解闷十二首 三","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["一辞故国十经秋，每见秋瓜忆故丘。","今日南湖采薇蕨，何人爲觅郑瓜州。"],"",[["古注·《杜詩詳註》","一作流此欲去䕫而游呉也朱注时有胡商下扬州来别因道其事西陵驿楼公少逰呉越时所登洛阳伽蓝记商胡贩客日奔塞下隋炀帝诗言族旧镇下扬州晋书王述年三十未知名人谓之痴导以门第辟之既见唯问江东米价述张目不答越絶书秦皇帝东逰之㑹稽㑹稽志晋宋人指㑹稽剡中皆曰东如谢安传海道还东是也"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11656":["解闷十二首 四","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["沈范早知何水部，曹刘不待薛郎中。","独当省署开文苑，兼泛沧浪学钓翁。"],"",[["古注·《杜詩詳註》","已下五章皆感懐诗人此则懐郑审也故丘有𤓰洲即郑秘监所居今已谪居南湖无复有访觅者矣盖伤其寥落也黄生曰此诗两故字两秋字两𤓰字连环鈎撘亦絶句弄笔之法大家时一为之耳原注郑秘监审水经注长安第二门本名霸城门又名青门门外旧出佳𤓰其南有下杜城西京杂记杜子夏葬文何必故丘然後即化南湖郑监所在公䕫州咏懐诗云南湖日扣舷张礼游城南记济潏水陟神禾原西望香积寺下原过𤓰洲村注𤓰洲村在申店潏水之隂许浑集有和淮南相公重游𤓰洲别业诗淮南相公杜佑也朱注𤓰州村与郑庄相近郑庄䖍郊居也审为䖍之侄其居必在𤓰州村故有末语与秋𤓰忆故丘𦂳相应或以大厯中郑审尝任袁州刺史改作袁州则生趣索然矣"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11657":["解闷十二首 五","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["李陵苏武是吾师，孟子论文更不疑。","一饭未曾留俗客，数篇今见古人诗。"],"",[["古注·《杜詩詳註》","此懐薛据也何薛同为水部但何有知音而薛无同调故为惜之当省署昔为部郎泛沧浪今客荆楚陈师道曰省署开文苑沧浪学钓翁即薛璩诗也杜臆此处称薛孟之诗知公别崔潩云荆州遇薛孟为报欲论诗非漫语也原注水部郎中薛据梁书何逊传范云见其对䇿大相称赏因结忘年交好一文一咏云輙嗟赏沈约亦爱其文尝谓逊曰吾每读卿诗一日三复犹不能已锺嵘诗品曹刘殆文章之圣陆谢为体贰之才曹植刘桢为建安才人之冠能推奬名士此云不待者犹言恨古人不及见耳唐㑹要天寳六年风雅古调科薛据及第韩文公薛公达墓志据为尚书水部郎中赠给事中"],["古注·《杜詩詳註》","一本第二句作首句"],["古注·《杜詩詳註》","此懐孟云卿也苏李吾师此述其论诗今见古人此称其作诗便知云卿诗格独能力追西汉原注校书郎孟云卿僧皎然曰五言始於苏李二子天与其性发言自髙未有作用如十九首则词义炳婉而成章矣"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11658":["解闷十二首 六","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["复忆襄阳孟浩然，清诗句句尽堪传。","即今耆旧无新语，漫钓槎头缩颈鯿。"],"",[["古注·《杜詩詳註》","洪容斋随笔曰文选编李陵苏武诗凢七篇人多疑俯观江汉流之语以为苏武在长安所作何为乃及江汉东坡云皆後人所拟也子观李诗云独有盈觞酒与子结绸缪盈字系惠帝讳汉法触讳者有罪不应陵敢用之益知东坡之言为可信矣蔡寛夫曰五言起於苏李今所见唯文选中七篇耳世或疑武诗俯观江汉流仰视浮云翔以为不当有江汉之言遂疑其伪此但注者浅陋直指为使匈奴时作故人多惑之其实无据也安知武未尝至江汉耶冯惟讷曰古诗云盈盈一水间又髙帝讳邦而韦孟诗云实絶我邦古人临文或不讳也"],["古注·《杜詩詳註》","此懐孟浩然也上二忆其诗句下二叹其人亡新句无闻而徒然把钓则耆旧为之一空矣槎头缩颈鯿即用浩然句孟诗鸟泊随阳雁鱼蔵缩项鰝又试垂竹竿钓果得槎头鯿此独记名以别於云卿也傅咸诗人之好我赠我清诗文心雕龙五言流调清丽为宗汉陆贾作新语赵曰习凿齿襄阳耆旧传云岘山下汉水中出鯿鱼味极肥而美襄阳人采捕遂以槎断水因谓之槎头缩项鯿杨慎曰説文查浮木也今作槎非槎音诧邪斫也国语山不槎药是也今多混用莫知其非畧证数条於此王子年拾遗记尧时巨查浮西海上十二年一周天名贯月查一曰挂星查道蔵歌诗扶桑不为查水经注临海江边有查浦字并作查唐王勃诗澁路拥崩查又送行序云夜查之客犹对仙家坐菊之宾尚临清赏骆宾王有浮查诗皆用正字不従俗体杜工部诗查上觅张骞又沧海有灵查惟七言絶空钓槎头缩颈鯿七言律奉使虚随八月槎古体近体不应用字互异盖七言絶与律乃俗夫竞玩遂肆笔𡚶改古体则俗目未击幸存旧文耳"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11659":["解闷十二首 七","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["陶冶性灵在底物，新诗改罢自长吟。","孰知二谢将能事，颇学阴何苦用心。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11660":["解闷十二首 八","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["不见高人王右丞，蓝田丘壑漫寒藤。","最传秀句寰区满，未绝风流相国能。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11661":["解闷十二首 九","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["先帝贵妃今寂寞，荔枝还复入长安。","炎方每续朱[樱]献，玉座应悲白露[团]。"],"",[["古注·《杜詩詳註》","此懐王维也右丞虽没而佳句犹传况有相国诗名则风流真可不坠矣缙党附元载人不足取特以一家诗学可称故连类及之或以缙能表章维集故云风流未絶诗中似无此意原注右丞弟今相国缙抱朴子知名之髙人洽闻之硕儒旧唐书王维传乾元中转尚书右丞晚年得宋之问蓝田别墅墅在辋口水周於舍下竹洲花坞与裴迪浮舟往来啸咏终日所赋诗号辋川集晋书谢安传放情丘壑庾信诗寒藤抱树踈锺荣诗品竒章秀句往往警遒王洙曰伐宗时缙为宰相帝求维文缙集上之金壶记王维与弟缙名冠一时时议云论诗则王维崔颢论笔则王缙李邕祖咏张説不得与焉卢氏杂记王缙好与人作碑铭有送润毫者误叩其兄门维曰大作家在那边李东阳曰唐诗李杜之外孟浩然王摩诘足称大家王诗丰缛而不华靡孟却专心古澹而悠逺深厚自无寒俭枯瘠之病由此言之则孟为尤胜储光羲有孟之古而深逺不及岑参有王之缛而又以华靡掩之故杜子美称吾怜孟浩然称髙人王右丞而不及储岑有以也夫"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11662":["解闷十二首 十","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["忆过泸戎摘荔枝，青峰隐暎石逶迤。","京中旧见无颜色，红颗酸甜只自知。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11663":["解闷十二首 十一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["翠瓜碧李沈玉甃，赤梨葡萄寒露成。","可怜先不异枝蔓，此物娟娟长远生。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11664":["解闷十二首 十二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["侧生野岸及江蒲，不熟丹宫满玉壶。","云壑布衣骀背死，劳生重马翠眉须。"],"",[["古注·《杜詩詳註》","此讥异味之惑人也杜臆宫中食荔不过为其味甘寒可以消暑止渇因比之水晶绦雪然𤓰李沉之井中梨萄采之露下亦何减於荔只縁诸果枝蔓寻常初不以为异独荔枝生自逺方故慕其色味而珍重之耳魏文帝书浮甘𤓰於清泉沉朱李於寒冰江逌井赋构玊甃之百节南史扶桑国有赤梨经年不壊娟娟言其质弱而色鲜"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11665":["复愁十二首 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["人烟生处僻，虎迹过新蹄。","野鹘翻窥草，村船逆上溪。"],"",[["古注·《杜詩詳註》","鹤注此当是大厯二年秋瀼西作时吐蕃寇邠灵州京师戒严故有万国尚防寇之句卢注复愁者前愁未巳後愁复至非谓愁已释而复生公之愁怀固未尝得放也"],["古注·《杜詩詳註》","卢本作僻处一作逺处"],["古注·《杜詩詳註》","一作鹤又作鹞晋作雉"],["古注·《杜詩詳註》","首章记瀼峡愁景烟僻则居人少迹新则虑患多鹘窥草见求食之难船上溪见行舟之险水经注两岸石上有虎迹甚多或深或浅皆悉成就自然之势"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11666":["复愁十二首 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["钓艇收缗尽，昏鸦接翅归。","月生初学扇，云细不成衣。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11667":["复愁十二首 三","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["万国尚防寇，故园今若何。","昔归相识少，早已战场多。"],"",[["古注·《杜詩詳註》","一作防宼"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11668":["复愁十二首 四","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["身觉省郎在，家须农事归。","年深荒草径，老恐失柴扉。"],"",[["古注·《杜詩詳註》","三章怀思故乡而愁戎马谓吐蕃侵境故园指东都旧居昔年暂归而人少地残则今日更觉荒凉矣杜臆次句作问词下二乃答语朱注乾元初公自华州曾归东都"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11669":["复愁十二首 五","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["金丝镂箭镞，皂尾制旗竿。","一自风尘起，犹嗟行路难。"],"",[["古注·《杜詩詳註》","五章洊经世乱而愁箭饰金丝旗装皂尾贼恃利器以作逆者风尘十载而归路犹难则愁绪真不能歇矣吴论此一章因乱後而作"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11670":["复愁十二首 六","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["胡虏何曾盛，干戈不肯休。","闾阎听小子，谈话觅封侯。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11671":["复愁十二首 七","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["贞观铜牙弩，开元锦兽张。","花门小前好，此物弃沙场。"],"",[["古注·《杜詩詳註》","六章人心好乱而愁杜臆定外寇易定人心难人竞尚武此干戈所以不息也卢注仆固怀恩恐贼平宠衰奏留薛嵩等分帅河北自为党援此正干戈不肯休息"],["古注·《杜詩詳註》","宋本避讳作正"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11672":["复愁十二首 八","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["今日翔麟马，先宜驾鼓车。","无劳问河北，诸将觉荣华。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11673":["复愁十二首 九","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["任转江淮粟，休添苑囿兵。","由来貔虎士，不满凤皇城。"],"",[["古注·《杜詩詳註》","朱鹤龄曰河北诸将方以爵上竞相雄长朝廷虽有战马安所用之时降将羁縻代宗専事姑息公度非兵力所制故云然耳薛苍舒谓公欲息兵休战失其㫖矣"],["古注·《杜詩詳註》","罗大经曰此诗言虽翔麟之马亦必先使之驾鼔车由贱而後可以致贵今诸将骤登贵显如马之未驾鼓车而遽驾玉辂安於安华志得意满无复驱攘之志河北叛乱决难计除无劳问也又云杂虏横戈数功臣甲第高亦此意"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11674":["复愁十二首 十","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["江上亦秋色，火云终不移。","巫山犹锦树，南国且黄鹂。"],"",[["古注·《杜詩詳註》","卢元昌曰当时漕运取给江淮故史有唐得江淮济中兴之语刘晏均节赋役岁运江淮米数十万石以给关中若宿衞冗军不裁立见其匮也此独孤及有倾天下之财给不用之兵等语至唐制府兵有为兵之利无飬兵之害田不井而兵藏于民最为近古自张说建议请召募壮士充宿衞更番上下兵农遂分乃神策军尤为非古时鱼朝恩以神䇿军屯禁中分为左右厢居北军右公曰由来𧴀虎士不满凤凰城隠述祖制以讽时事"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11675":["复愁十二首 十一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["每恨陶彭泽，无钱对菊花。","如今九日至，自觉酒须赊。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11676":["复愁十二首 十二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["病减诗仍拙，吟多意有余。","莫看江总老，犹被赏时鱼。"],"",[["古注·《杜詩詳註》","末章总结藉吟诗以遣愁也杜臆吟多意有余所以写其愁者犹未尽矣朱注末言已年虽老犹有江总银鱼之赐则流落亦未足为恨也公尝检校员外郎赐绯鱼袋故云卢注十二章收结於此盖以望治之意迫为趋朝之想也玉海苏氏记云永徽以来正员官始佩鱼开元八年九月中书令张嘉贞奏致仕及内外官五品以上检校试判及内俱奉官准正员例佩鱼自是恩制赏绯紫必兼鱼袋谓之章服齐书谢朓传萧子隆在荆州好辞赋朓尤被赏"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11677":["承闻河北诸道节度入朝欢喜口号绝句十二首 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["禄山作逆降天诛，更有思明亦已无。","汹汹人寰犹不定，时时鬬战欲何须。"],"",[["古注·《杜詩詳註》","朱注唐史大厯二年正月淮安节度使李忠臣入朝三月汴宋节度使田神功来朝八月鳯翔等道节度使李抱玉入朝河北入朝事史无明文疑公在夔州特传闻而未实耳杜臆纲目代宗大厯元年冬十月帝生日诸道节度使上夀当指此事诗葢作於二年三月也"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11678":["承闻河北诸道节度入朝欢喜口号绝句十二首 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["社稷苍生计必安，蛮夷杂种错相干。","周宣汉武今王是，孝子忠臣後代看。"],"",[["古注·《杜詩詳註》","首章喜河北冦平天寳之乱起於安史今元恶并除小丑复何觊乎末句乃戒词後汉书往者王莽作逆汉天人致诛六合相灭前汉冯奉世传师不久暴而天诛亟决李徳林集半天之下汹汹鼎沸司马相如谕巴蜀檄战鬬之患"],["古注·《杜詩詳註》","次章喜边境初静安史既平戎狄亦退此君臣戮力而民社奠安时也末句乃劝词杂种指吐蕃回鹘党𦍑言沈约诗杂种寇轮台吕氏春秋此孝子忠臣亲父交友之大事"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11679":["承闻河北诸道节度入朝欢喜口号绝句十二首 三","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["喧喧道路多歌谣，河北将军尽入朝。","始是乾坤王室正，却交江汉客魂销。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11680":["承闻河北诸道节度入朝欢喜口号绝句十二首 四","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["不道诸公无表来，茫然庶事遣人猜。","拥兵相学干戈锐，使者徒劳百万回。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11681":["承闻河北诸道节度入朝欢喜口号绝句十二首 五","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["鸣玉锵金尽正臣，修文偃武不无人。","兴王会静妖氛气，圣寿宜过一万春。"],"",[["古注·《杜詩詳註》","此遡往时不朝而惜之也曰不道曰遣人猜据迹而疑其心也至是则诸镇之心迹可白矣朱注旧觧引吐蕃陷京师诸镇不入援者误矣"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11682":["承闻河北诸道节度入朝欢喜口号绝句十二首 六","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["英雄见事若通神，圣哲爲心小一身。","燕赵休矜出佳丽，宫闱不拟选才人。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11683":["承闻河北诸道节度入朝欢喜口号绝句十二首 七","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["抱病江天白首郎，空山楼阁暮春光。","衣冠是日朝天子，草奏何时入帝乡。"],"",[["古注·《杜詩詳註》","此因其朝献而规讽君心也大厯元年十月上生日诸道节度使献金帛器服珍玩骏马共直緍钱二十四万常衮请却之而帝不聴据此则诸镇将有逢迎以献佳丽者诗云英雄见事当指常衮言圣哲为心豫防逸欲也小一身言不侈天下以自奉孝经通乎神明左传并建圣哲古诗燕赵多佳人战国䇿赵天下善为音佳丽之所出也前汉翼奉传未央建章甘泉宫才人各以百数唐制才人正二千石"],["古注·《杜詩詳註》","此遥闻入朝之事叹不能身见也三章言武将入朝此章兼及在朝文臣王莽传孙竦为崇草奏顔注草谓创立其文庄子华封人曰乗彼白云至於帝乡"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11684":["承闻河北诸道节度入朝欢喜口号绝句十二首 八","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["澶漫山东一百州，削成如桉抱青丘。","苞茅重入归关内，王祭还供尽海头。"],"",[["古注·《杜詩詳註》","已下三章备记入朝诸事此言节镇朝而贡赋至也山东诸州即河北地包茅正供与进佳丽者不同西京赋澶浸靡迤作镇於近澶漫广逺貌山海经泰华之山削成而四方削成虽云形势亦指削平祸乱而言寰宇记青丘在青州千乗县齐景公田於青丘是也左传尔贡包茅不入王祭不供"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11685":["承闻河北诸道节度入朝欢喜口号绝句十二首 九","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["东逾辽水北滹沱，星象风云喜共和。","紫气关临天地阔，黄金台贮俊贤多。"],"",[["古注·《杜詩詳註》","一作气色"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11686":["承闻河北诸道节度入朝欢喜口号绝句十二首 十","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["渔阳突骑邯郸儿，酒酣并辔金鞭垂。","意气即归双阙舞，雄豪复遣五陵知。"],"",[["古注·《杜詩詳註》","此言强域广而人才盛也辽水滹沱亦河北地共和言一统大顺函关西控可以收罗天地贤才矣水经大辽水出塞外卫白平山东南入塞过辽东襄平县西又小辽水出𤣥莵高句丽县辽山西南至辽隧县入大辽水山海经大戏之山滹沲之水出焉後汉书注滹沲河在今代州繁畤县东流经定州深泽县东南一统志属保定府束鹿县史记周厉王出奔周公召公二相行政号曰共和□注紫气关即函谷关鲍照诗岂伊白璧赐将起黄金台上谷郡图经黄金台在易水东南十八里阮藉奏记俊贤抗足"],["古注·《杜詩詳註》","此言主将归心而士卒効力也突骑健儿昔为贼党者今为国用矣双□谓都中五陵指郊外杜臆此并开导诸道之叛卒後汉光武克邯郸置酒高㑹从容谓马武曰吾得渔阳上谷突骑欲今将之唐书磁州有邯郸县属河北道蔡邕陈留太守碑意气精朗晋书慕容翰性雄豪多权畧"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11687":["承闻河北诸道节度入朝欢喜口号绝句十二首 十一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["李相将军拥蓟门，白头虽老赤心存。","竟能尽说诸侯入，知有从来天子尊。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11688":["承闻河北诸道节度入朝欢喜口号绝句十二首 十二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["十二年来多战场，天威已息阵堂堂。","神灵汉代中兴主，功业汾阳异姓王。"],"",[["古注·《杜詩詳註》","此以戡乱致治推崇郭子仪也自天寳十四载至大厯二年首尾十二年其间讨安史父子却回纥吐蕃平仆固懐恩斩周智光等皆子仪百战而後息兵独以异姓王配中兴主见其君臣一徳始终无间也左传天威不达顔咫尺孙武子无击堂堂之阵史记黄帝生而神灵刘孝绰诗齐楚磐石贵韩卢异姓王郭子仪传寳元年进封汾阳郡王"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11689":["喜闻盗贼蕃寇总退口号五首 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["萧关陇水入官军，青海黄河卷塞云。","北极转愁龙虎气，西戎休纵犬羊羣。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11690":["喜闻盗贼蕃寇总退口号五首 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["赞普多教使入秦，数通和好止烟尘。","朝廷忽用哥舒将，杀伐虚悲公主亲。"],"",[["古注·《杜詩詳註》","首章喜王师能御冦也萧陇军入路嗣恭歼卤於此也河海云巻塞外之风烟已静矣时宦官典兵内忧方切故云北极转愁吐蕃暂退而祸根未除故曰西戎休纵按逺注龙虎军葢禁旅也此时鱼朝恩掌禁兵中外受制公故深愁之此从来无人注及者鹤注萧闗与灵州相近正指吐蕃冦灵州西路嗣㳟破之也赵曰萧闗在灵州之傍陇水则陇州之水又曰青海在西蕃之地黄河则自积石而往"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11691":["喜闻盗贼蕃寇总退口号五首 三","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["崆峒西极过崑仑，驼马由来拥国门。","逆气数年吹路断，蕃人闻道渐星奔。"],"",[["古注·《杜詩詳註》","此追咎边将之起衅者当时吐蕃请和正可息兵自哥舒翰迎合上意纵兵恣杀而边衅从此开矣据此章则哥舒翰当服善战之刑前赠哥舒翰开府诗又盛夸其武功能免谀词乎唐书开元末金城公主薨吐蕃遣使告哀因请和明皇不许天寳七载以哥舒翰节度陇右攻拔石堡城収九曲故地"],["古注·《杜詩詳註》","此记吐蕃叛服之不常也驼马入贡徃时归顺自逆命数年而今乃奔散喜之也赵注崆峒在西郡之西崑仑又在崆峒西极之西言其从化之地逺也谢瞻书裹粮擕弱匍匐星奔广絶交论靡不望影星奔"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11692":["喜闻盗贼蕃寇总退口号五首 四","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["勃律天西采玉河，坚昆碧盌最来多。","旧随汉使千堆宝，少荅胡王万匹罗。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11693":["喜闻盗贼蕃寇总退口号五首 五","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["今春喜气满乾坤，南北东西拱至尊。","大历二年调玉烛，玄元皇帝圣云孙。"],"",[["古注·《杜詩詳註》","此忆徃时和戎之有道也勃律采玉坚昆碧盌来多答少此朝廷羁縻逺夷之法惜今不可复见耳唐书大勃律直吐蕃西与小勃律接小勃律去京师九千里而赢距吐蕃牙帐东八百里酉阳杂俎天寳初安思顺进五色玉带又於左藏库中得五色玉杯上怪近日西賮无五色玉命责安西诸蕃蕃言比常进皆为小勃律所刼上怒欲征之羣臣多谏独李右座林甫赞成上意且云武臣王天运谋勇可将乃命将四万人兼统诸蕃兵伐之及逼城勃律君长恐惧请罪悉出寳玊愿岁贡献天运不许即屠城掳二千人及其珠玑而还勃律中有术者言将军无义不祥天将大风雪矣行数百里忽风四起雪花如翼风吹小海水成氷柱起而复摧经半日小海涨涌四万人一时冻死惟蕃汉各一人得还具奏帝大惊异即令中使随二人验之至小海侧冰犹峥嵘如山隔冰见兵士死立者坐者莹彻可数中使将反冰忽消释衆屍亦不复见师氏曰晋平居海为张邺使于阗判官作行程记云其国采玉之地玉河在于阗城外其源出崑山西流一千三百里至于阗界牛头山乃流为三河一曰白玊河在东二曰绿玉河在城西三曰乌玉河在绿玉河西其源虽一而其玊随地而变每嵗五六月大水暴涨则玊随流而至至秋水退乃可采人谓之捞玊唐书坚崑国在康居西葱岭北寰宇记黠戛斯西北荒之国也本名结骨又名居易又谓之坚昆酉阳杂俎坚昆部落其上代有神与㹀牛交而生其人发黄目绿赤髭髯其髭髯俱黒者汉将李陵及其兵衆之後也碧盌琉璃盌"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11694":["洞房","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["洞房环佩冷，玉殿起秋风。","秦地应新月，龙池满旧宫。","系舟今夜远，清漏往时同。","万里黄山北，园陵白露中。"],"赵次公云此诗思长安而懐帝阙也",[["古评·《唐诗品汇》","赵次公云此诗思长安而懐帝阙也"],["古评·《唐诗品汇》","刘云何限言外"],["古注·《杜詩詳註》","鹤注明皇以广徳二年三月塟泰陵诗云园陵白露中又曰仙游终一閟女乐乆无香则去塟年逺矣梁权道编在大厯元年得之杜臆八章皆追忆长安往事语兼讽刺以警当时君臣图善後之䇿也每首先成诗而撮首二字为篇名乃三百篇遗法赵曰此下八篇盖一时所作"],["古注·《杜詩詳註》","首章従秋夜感兴有故国旧君之思上四长安秋夜之景所感在妃子下四䕫州秋夜之景所感在明皇秦地二句旧注云月虽新而宫则旧有物是人非之感满指池水不指月色盖章内秋风秋月秋水秋露皆各举时景言耳赵汸注今夜应新往时应旧往时清漏公为拾遗时宿省所闻者时上皇初还京也故下接以园陵句长门赋徂清夜於洞房史记南子环佩玉声璆然记行则有环佩之声曹植诗欢坐玉殿汉武辞秋风起兮白云飞杨妃过温泉行云玉殿空掩扉秋风动琪树昔日繁华事尽逐流水去国䇿张仪曰秦地半天下鲍泉诗新扇如新月唐㑹要明皇在藩邸居兴庆里有龙池涌出日以浸广至开元中为兴庆宫唐太宗诗丹陵幸旧宫薛道衡诗今夜寒车出鲍照诗啸歌清漏毕晋灼曰黄山宫名在槐里前汉叔孙通传先帝园陵寝庙诗白露为霜"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗品彚（附唐诗拾遗）》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩品彚_(四庫全書本)）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11695":["宿昔","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["宿昔青门里，蓬莱仗数移。","花娇迎杂树，龙喜出平池。","落日留王母，微风倚少儿。","宫中行乐秘，少有外人知。"],"刘云猥䙝不凡风刺俱有",[["古评·《唐诗品汇》","刘云猥䙝不凡风刺俱有"],["古注·《杜詩詳註》","此追叙明皇逸豫之事上四叙游幸下四叙女宠昔於青门城内见仙㐲数移自蓬莱而往曲江南苑也花迎龙出景物亦若増新矣日将落而留连王母贵妃专宠也风㣲起而慿倚少儿秦虢得幸也当时恣意行乐不令人知今果安在哉上章已説园陵此处复追叙生前故用宿昔二字另提下二章俱䝉此曹植诗宿昔秉良弓顾注青门长安城东门也鹤注龙朔二年髙宗置仗朝㑹之仗三卫分上为五仗李翰林别集序开元中禁中初重木芍药得四本红紫浅红通白者上因移植於兴庆池东沉香亭前㑹花方繁开上乗照夜白太真妃以歩辇从鲍照诗杂树茂寒峯天寳中兴庆池小龙常出游宫垣水沟中蜿蜒奇状靡不瞻覩銮舆西幸龙一夕乗云雨望西南而去此见明皇十七事中龙池即兴庆池卢注杨妃曾度为道士故唐人比为王母汉武内传王母言语麄毕啸命灵官驾龙严车欲去帝下席叩头请留殷勤王母乃坐卫青传卫媪长女君孺次女少儿次女则子夫少儿先与霍仲孺通生去病及卫皇后立少儿更为陈掌妻飞燕外传帝令后所爱侍郎冯无方吹笙以倚后歌歌酣风起后扬袖曰仙乎仙乎去故而就新乎帝乃令无方持后履朱注㣲风倚少儿盖合用少儿飞燕事汉书周仁为郎中令慎重不泄以是得幸入卧内後宫秘戏仁尝在旁终无所言於外杨恽传人生行乐耳杜臆行乐汚䙝必有不可使外人闻者黄生曰此章畧见风刺然其词㣲而婉如禄山宫里虢国门前之句非唯失风人之意亦全无臣子之礼矣"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗品彚（附唐诗拾遗）》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩品彚_(四庫全書本)）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11696":["能画","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["能画毛延寿，投壶郭舍人。","每蒙天一笑，复似物皆春。","政化平如水，皇恩断若神。","时时用抵戏，亦未杂风尘。"],"",[["古注·《杜詩詳註》","晋作明一作恩"],["古注·《杜詩詳註》","此记当时优宠技巧也在四句分截舍人投壶足动天顔之笑延寿善画能令物色生春此一时适意之事若使当年政平威断即时用抵戯亦何至风尘杂起乎惜乎明皇之不然也卢注𤣥宗时画鹰画马有冯绍正韩干軰其侏儒黄㼐帝尝呼为肉几此即毛郭之流故借汉事为比杜臆抵戯用以当戯剧旧引汉书角觝戱未合杂风尘指流离播迁既涉风尘则不平不断可知言外见意此风人温厚之㫖也西京杂记画工有杜陵毛延夀写人好丑老少必得其真又云武帝时郭舍人善投壶以竹为矢不用棘古之投壶取中而不求还故入小豆恶矢跃而出也郭舍人则激矢令还一矢百余反谓之骁言於軰中为骁杰也每投壶帝輙赐金帛神异经东荒山中有大石室东王公居焉与一玉女投壶设有入不出者天为之笑张华曰笑者开口流光今电是也隋辛徳源诗云衘天笑明庄子与物为春汉安帝诏达於政化後汉第五访传政平化行班固两都赋天人合应以发皇明魏都赋皇恩绰矣晋史论神畧独断"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11697":["鬬鸡","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["鬬鸡初赐锦，舞马既登牀。","帘下宫人出，楼前御柳长。","仙游终一閟，女乐久无香。","寂寞骊山道，清秋草木黄。"],"",[["古注·《杜詩詳註》","一作解胡买切"],["古注·《杜詩詳註》","此章有乐极悲来之感上四铺张盛事见生前之乐下四追惟遗迹致没後之悲逺注仙游句反上御曲长女乐句反上宫人出黄生曰第五句是通盘一大关节盖不以荒宴直接播迁径及崩驾之感则有伤痛而无刺讥是温柔敦厚之遗教也季郈之鸡鬬见左传齐有鬬鸡走犬见国䇿陈思王得大宛紫骝马教令习与皷节相应见魏志吐谷浑遣使献舞马谢庄为作舞马赋见宋书是鬬鸡舞马其来乆矣此诗则专指明皇事耳陈𢎞祖东城父老传𤣥宗在藩邸时乐民间清明节鬬鸡戱及即位立鸡坊於两宫间索长安雄鸡金毫铁距髙冠昂尾千数养於鸡坊选六军小儿五百人使驯扰教饲之帝出游见贾昌弄木鸡於云龙门道旁召入为五百小儿长天子甚爱幸之金帛之赐日至其家天下号为神鸡童传又云明皇以乙酉生而喜鬬鸡是兆乱之象也黄庭坚曰观风楼南起鬬鸡殿明皇杂録上尝令教舞马四百匹各分左右部目为某家龙某家骄时塞外以善马来贡者上俾之教习无不曲尽其妙因命衣以文绣络以金铃饰其鬃鬛间以珠玉其曲谓之倾盃乐者数十回奋首鼓尾縦横应节又施三层板牀乗马於上拚转如飞或令壮士举榻舞於榻上乐工数十人环立皆衣淡黄衫文玉带必求年少姿美者每千秋节命舞於勤政楼下明皇杂録上每宴赐酺则御勤政楼太常陈乐教坊大陈寻橦走索丸剑角觝鬬鸡令宫人数百饰以珠翠衣以锦绣自帏中撃雷鼓为破阵乐又云𤣥宗制新曲四十余又新制乐谱每初年望夜御勤政楼观灯作乐贵臣戚里设看楼观望夜阑太常乐府悬㪚乐毕即遣宫女於楼前缚架出眺歌舞以娱之开元传信録明皇梦游月宫诸仙子娱以上清之乐其曲凄楚动人明皇以玉笛寻得之曲名紫云回异闻録开元六年八月望上与申天师洪都客作术夜游月宫见素娥十余人笑舞於广庭桂树之下音乐清丽遂归制霓裳羽衣之曲卢注白乐天勤政楼前御栁诗中有开元栁一株别作御栁亦有本赵曰仙游言明皇上昇洙曰禄山乱後女乐流散也南部新书骊山华清宫毁废已乆惟存缭垣朝元阁在山岭之上最为崭絶础柱尚在山腹即长生殿殿东西盘石道自山麓而上道侧有饮酒亭明皇吹笛楼宫人走马楼故址犹存邵注骊山在今西安府临潼县东南二里因骊戎所居故名温泉在焉明皇建华清宫於其下秋风词草木黄落兮雁南飞"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11698":["鹦鹉","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["鹦鹉含愁思，聪明忆别离。","翠衿浑短尽，红觜漫多知。","未有开笼日，空残旧宿枝。","世人怜复损，何用羽毛奇。"],"",[["古注·《杜詩詳註》","此下八章乃杂咏物类盖即所见以寓意也鹤注此诗句句含不遇之意盖托以自况梁权道编大厯元年䕫州诗内近之明皇杂録开元中岭南献白鹦鹉养之宫中嵗乆颇聪慧洞晓言词上及贵妃皆呼为雪衣娘有鹰搏之而毙遂瘗苑中呼为鹦鹉塚今详诗意乃泛咏鹦鹉与彼无涉"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11699":["历历","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["历历开元事，分明在眼前。","无端盗贼起，忽已岁时迁。","巫峡西江外，秦城北斗边。","爲郎从白首，卧病数秋天。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11700":["洛阳","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["洛阳昔陷没，胡马犯潼关。","天子初愁思，都人惨别颜。","清笳去宫阙，翠盖出关山。","故老仍流涕，龙髯幸再攀。"],"",[["古注·《杜詩詳註》","此叹西狩之事也上四叙幸蜀之由下四记还京之事别顔流涕上下相应禄山於天寳十四年十二月陷东京所谓洛阳没也次年六月七日灵寳败绩贼入潼闗所谓犯潼闗也是夕平安火不至明皇惧而谋幸蜀所谓初愁思也十三日帝出延秋门至咸阳驿而従官骇散所谓惨别顔也至徳二年九月郭子仪收复西京贼衆夜遁所谓去宫阙也十月肃宗入长安上皇发蜀郡所谓出闗山也十二月上皇至自蜀百姓舞拚路侧曰不图今日复见二圣所谓故老流涕龙髯再扳也此叙出狩还宫之事首尾详明真可谓诗史矣杜臆初愁思盖向不知愁者流涕攀髯则开元美政去国仁言真足以系人心者考唐史帝之出奔经过左蔵杨国忠请焚之上曰贼来无得必更敛百姓不如与之无重困赤子上既过便桥国忠使人焚桥上曰人各避贼求生奈何絶其路留髙力士扑灭之皆去国之仁言也邵注洛阳属河南府唐髙宗以此为东都潼闗在陕西西安府华隂县乃秦闗要地前凉主实书忽闻北地陷没㓂逼长安古诗胡马依北风马融与谢伯世书愤愤愁思杜挚笳赋操笳扬清谢朓诗寥戾清笳转梁鸿歌宫阙崔巍兮髙唐赋以翠羽为盖淮南子建翠盖江淹恨赋闗山无极晋书懐帝纪故老或歔欷流涕前汉郊祀志黄帝采首山铜铸鼎於荆山下鼎既成有龙垂胡𩓿下迎黄帝上骑羣臣後宫七十余人従上龙乃去余小臣不得上乃悉持龙𩓿龙𩓿拔堕堕黄帝之弓百姓乃抱其弓与龙𩓿号後世因名其处曰鼎湖弓曰乌号"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11701":["骊山","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["骊山绝望幸，花萼罢登临。","地下无朝烛，人间有赐金。","鼎湖龙去远，银海雁飞深。","万岁蓬莱日，长悬旧羽林。"],"刘云使人不忍言好",[["古评·《唐诗镜》","三四殆不忍读"],["古评·《唐诗品汇》","刘云使人不忍言好"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗镜》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩鏡_(四庫全書本)）","古籍注评：《唐诗品彚（附唐诗拾遗）》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩品彚_(四庫全書本)）"]],"open_11702":["提封","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["提封汉天下，万国尚同心。","借问悬车守，何如俭德临。","时徵俊乂入，草窃犬羊侵。","愿戒兵犹火，恩加四海深。"],"",[["古注·《杜詩詳註》","一作草窃"],["古注·《杜詩詳註》","此章总结直究当时致乱之由以垂为永戒也言当此一统天下万国同心世事尚可为也但勿更寻前辙耳自明皇好邉功而尚奢侈故有悬车俭徳之语不听张九龄而致禄山终叛故有俊乂犬羊之语使当时息兵爱民焉有天寳之祸哉故以戒兵加恩终之此诗反覆丁宁无非览已往以告将来若云指讽代宗时事则当年吐蕃入㓂叛将不恭恐非罢兵可以止乱也三四即所谓在徳不在险五六即所谓汲黯在朝淮南寝谋杜臆俭者不夺民心自懐此无形之险也俊乂在朝折冲樽俎何忧於犬羊乎兵勿轻动则恩加四海矣公之谋国堂堂正正即孟子所告齐梁之君者自许稷契以此东方朔传提封顷亩注谓提举四封之内总计其数汉书刑法志一同百里提封万井古史禹㑹诸侯於涂山执玊帛者万国左传吕相曰戮力同心又悬车束马以踰太行书慎乃俭徳又俊乂在官晋愍帝檄石虎敢率犬羊渡河縦毒左传兵犹火也不戢将自焚也魏志陈羣曰皇恩溥遍海岱"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11703":["覆舟二首 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["巫峡盘涡晓，黔阳贡物秋。","丹砂同陨石，翠羽共沈舟。","羁使空斜影，龙居閟积流。","篙工幸不溺，俄顷逐轻鸥。"],"",[["古注·《杜詩詳註》","诗言巫峡当是夔州所作但年次不可考梦弼以此诗为追讽𤣥宗事朱云唐世人主多好神仙岂必𤣥宗也张溍曰求仙本荒唐事故托覆舟以讽新序孔子曰水则覆舟"],["古注·《杜詩詳註》","此章记夔江覆舟之事黔阳之贡经於巫峡丹砂翠羽八贡之物空斜影侧身落水閟积流没入深渊矣舟逐轻鸥篙工以脱身为幸也旧以空斜影为使者怅快於斜日之下此説不然玩诗意先叙砂羽之坠继叙羇使之亡末则幸篙工之不溺耳於篙工加一幸字知使者为不幸矣江赋冲巫峡以迅激又盘涡谷转一统志重庆府彭水县自三国至唐皆名黔阳县随置彭水县为黔州治所又唐以黔江县属黔州唐志黔阳嵗贡廾砂等物本草丹砂久服通神明不老轻身神仙能化为汞衍义云出辰州蛮峒老鸦井者最良左传陨石於宋五尔雅注翠鹬似燕绀色生郁林汲塜周书王会解苍梧翡翠所以取羽邹阳书积羽沉舟王僧孺诗翠枝结斜影徐陵寺碑夜动龙宫十洲记南海有龙绡宫海赋茫茫积流刘孝威诗循汀俄顷回"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11704":["覆舟二首 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["竹宫时望拜，桂馆或求仙。","姹女临波日，神光照夜年。","徒闻斩蛟劒，无复爨犀船。","使者随秋色，迢迢独上天。"],"",[["古注·《杜詩詳註》","次章讽当时求仙之妄竹宫桂馆借汉比唐姹女凌波言丹砂已落江水神光照夜言宫中犹望成仙此见其誙妄也且方士既神竒其説何独无斩蛟之剑照水之犀以解此水厄乃至身罹覆舟而沓然上天乎朱注使者即指方士一辈旧以上天为还朝非是閟积流魄沉水也独上天魂升天也杜臆云帝未必昇天而使者已独上天矣讥之也汉礼乐志正月上辛用事甘泉圜丘昏祠至明夜常有神光集於祠坛天子自竹宫而望拜百官侍祠者数百人皆肃然心动焉师古曰竹宫去坛三里郊祀志公孙卿曰仙人好楼居於是上令长安作飞廉桂馆甘泉作益夀延夀观使卿持节设具而𠉀神人师古曰飞廉桂馆二舘名参同契河上姹女灵而最神得火则飞不染垢尘顾注汉真人大丹诀姹女隐在丹砂中谓砂中有汞也洛神赋凌波微歩郊祀志宣帝筑世宗庙神光兴於殿旁如烛状武帝纪祭后土神光三烛吕氏春秋荆人佽飞得寳剑渡江中流两蛟绕舟几没佽飞㧞剑斩蛟乃得济晋书温峤宿牛渚矶水深不可测世云其下多怪物峤遂燃犀角照之须㬰见水族覆火竒形异状宋王微咏赋秋色隂兮白露商陆机诗迢迢造天庭呉越春秋羣臣上天欧冶死矣"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11705":["垂白","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["垂白冯唐老，清秋宋玉悲。","江喧长少睡，楼迥独移时。","多难身何补，无家病不辞。","甘从千日醉，未许七哀诗。"],"",[["古注·《杜詩詳註》","鹤注此亦䕫州西阁作故云江喧楼逈诗成後拈垂白二字为题非专咏垂白也汉书杜周传老姊垂白注白髪下垂也"],["古注·《杜詩詳註》","一云白首"],["古注·《杜詩詳註》","此章乃老去悲秋之意下六申言其悲少睡移时忧在国家也醉千日付之不知未七哀伤心更多矣杜臆公年老为郎有似冯唐当秋而悲复如宋玊少睡无聊故起立移时时难身何补作愤语无家病不辞"],["古注·《杜詩詳註》","作苦语赵注公妻孥在蜀而云无家盖以故乡为家也汉书冯唐以孝着为郎中署长文帝辇过唐曰父老何自为郎庾信诗髙花出逈楼魏都赋醇酎中山沈湎千日搜神记狄希中山人能造千日酒饮之一醉千日七哀诗见十六巻"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11706":["草阁","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["草阁临无地，柴扉永不关。","鱼龙回夜水，星月动秋山。","久露清初湿，高云薄未还。","泛舟惭小妇，飘泊损红颜。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11707":["江月","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["江月光於水，高楼思杀人。","天边长作客，老去一沾巾。","玉露团清影，银河没半轮。","谁家挑锦字，灭烛翠眉嚬。"],"",[["古注·《杜詩詳註》","唐韵则个切又臧祚切"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11708":["江上","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["江上日多雨，萧萧荆楚秋。","高风下木叶，永夜揽貂裘。","勳业频看镜，行藏独倚楼。","时危思报主，衰谢不能休。"],"三四格老五六情难看镜倚楼毕竟是少陵隐语",[["古评·《唐诗镜》","三四格老五六情难看镜倚楼毕竟是少陵隐语"],["古注·《杜詩詳註》","鹤注当是大厯元年䕫州作顾注诗言江上倚楼此䕫州西阁所作也"],["古注·《杜詩詳註》","上四叙景旅客悲秋之况下四言情旧臣忧国之懐夜不眠以至曙故对镜倚楼看容色而计行藏但以报主心切虽衰年未肯自诿此公之笃於忠爱也黄生注勲业老尚无成故频看镜行藏抑郁谁语故独倚楼鲍照诗江上气早寒春秋正义荆楚一木二名故以为国号亦得二名庄公之世经皆书荆僖之元年乃书楚人伐郑葢始改为楚也晋书罗含传可谓荆楚之秋江𨔁诗髙风吹节变楚辞洞庭波兮木叶下谢灵运罗浮山赋发潜梦於永夜杜笃吴汉诛勲业既崇庾信诗匣中取明镜披图自照看江淹诗竖儒守一经未足识行藏"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗镜》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩鏡_(四庫全書本)）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11709":["中夜","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["中夜江山静，危楼望北辰。","长爲万里客，有媿百年身。","故国风云气，高堂战伐尘。","胡雏负恩泽，嗟尔太平人。"],"",[["古注·《杜詩詳註》","顾注诗有江山危楼亦䕫州西阁所作当在大厯元年司马绍诗中夜不能寐"],["古注·《杜詩詳註》","此客䕫而伤乱离也在四句分截望北辰思长安也万里一身危楼所感故国髙堂北望之意风云气变易无常战伐尘屡经残破负恩泽追恨禄山盖自天寳初而祸绵不息致不能为太平之人也何逊诗暂有江山趣隂铿诗接路上危楼庾信诗髙荣据北辰鲍照诗争先万里途各事百年身颜延之诗故国多乔木空城疑塞云史记风云天之客气者也梦弼以髙堂为杜陵屋庐今按曹植诗乃为髙㑹宴此髙堂沈约诗青鸟去复还髙堂云不歇刘孝绰诗长门隔青夜髙堂梦容色此皆槩言华屋或因前诗有髙堂天下无之句遂指为䕫州地名误矣晋载记石勒上党武乡羯人年十四随邑人行贩洛阳倚啸上东门王衍见而异之顾谓左右曰向者胡雏吾观其声视有竒志唐书张九龄见禄山入奏气骄蹇曰乱幽州者此胡雏也旧注误以吐藩为胡雏前汉郊祀志亦施恩泽书云嗟尔万方有衆路温舒传囹圄空虚天下太平"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11710":["江汉","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["江汉思归客，乾坤一腐儒。","片云天共远，永夜月同孤。","落日心犹壮，秋风病欲疎。","古来存老马，不必取长途。"],"此诗余幼而学书有此古印本为式云杜牧之书也味之久矣愈老而愈见其工中四句用云天夜月落日秋风皆景也以情贯之",[["古注·《杜詩詳註》","旧编在䕫州今依蔡氏入在湖南诗内与下首江汉山重阻为同时之作葢大厯四年秋也"],["古注·《杜詩詳註》","此身滞江汉而有感也上四言所处之穷下四言才犹可用思归之旅客乃当世一腐儒自嘲亦复自负天共逺承江汉客月同孤承一腐儒心壮病苏见腐儒之智可用故以老马自方周甸曰不必取长途取其智而不取其力逺注全首是老骥伏志在千里烈士暮年壮心未巳意易林久客无牀思归故乡史记黥布传髙帝谓随何为腐儒为天下安用腐儒黄生注世不见用而心常忧国乾坤之内此腐儒能有几人杜臆楚邱先生对孟尝君曰决嫌疑定犹豫吾始壮矣何老之有即所云日暮而心犹壮也老马之智可用出韩非子注巳别见陆冲诗命驾遂长途"],["古评·《瀛奎律髓》","此诗余幼而学书有此古印本为式云杜牧之书也味之久矣愈老而愈见其工中四句用云天夜月落日秋风皆景也以情贯之共逺同孤犹壮欲苏八字絶妙世之能诗者不复有出其右矣○公之意自比於老马虽不能取长途而犹可以知道释惑也"]],{"source":"黄宗壤","body":["颔联用片云、孤月两个鲜明的意象来生发首联：片云一无依傍，况在罡风劲吹的高天；孤月清辉惨淡，况值深沉无尽的长夜；此二句借写片云孤月，道尽自己的漂泊孤独之感。","颈联也用了“落日”“秋风”两个鲜明的意象，上句为比喻，下句是实写，衰飒的情绪一转而为慷慨：虽然自感来日无多，已像日薄崦嵫，但是想一展抱负的初衷仍然未改，这与曹操“烈士暮年，壮心不已”（《步出夏门行•龟虽寿》）的襟怀是一样的；虽是秋风萧瑟的季节，而自觉病体差可，甚至还有好转的迹象。这一来，就为尾联的情绪转为高扬提供了契机。","然而不然。此时的杜甫已入老境，早已不是当年“饮酣视八极，俗物都茫茫”（《壮游》）意气飞扬的年龄，因而尾联并不作“论功还欲请长缨”（唐祖咏《望蓟门》）式的慷慨激昂的表态，而依旧是以委婉而执著的语气，曲折地表达自己的壮心，含而不露，此杜甫之所以是杜甫。“老马”的典故出于《韩非子•说林上》：春秋时代，管仲和隰朋随齐桓公北伐孤竹国，春往冬返，归途因无向导而迷路。管仲说：“老马是很聪明的，可以靠它来寻路啊。”于是就让老马走在前面，队伍随之，终于找到出路而回到了齐国。杜甫谦逊地把自己比作识途老马，这个比喻实在太贴切太精彩，有两层意思：一、自我明志。“老骥伏枥，志在千里”，我虽然已至暮年，但报国壮心犹在。二、自我定位。我虽然精力和能力不堪大任，但正如一匹老马，经事多，有智慧，总可以派一点用场，帮着出出点子，而不必非得到战场上去驰驱。此外，也蕴含着第三层意思，就是遗憾庙堂的肉食者竟没有管仲那样知人善任能够使人尽其才的眼光。","然而杜甫已经没有机会了！大约作此诗两年之后他就去世，他毕生追求“致君尧舜上，再使风俗淳”的政治理想终未能实现，这是他的悲剧，也是像他那样的空怀理想而不能用世的文人的悲剧。但他那种尽人事以待天命、知其不可而为之的进取精神是积极的。这首诗可以说是他抒发壮心的绝唱，惟其如此，更使人在感佩之余亦为之扼腕。","从技巧来看，此诗情景交融，先写漂泊的况味，后写用世的情怀，抑扬之际，转换自然，结尾老马之喻，言辞平实恳切，尤为感人，体现了杜诗沉郁顿挫的风格。"]},[],["https://github.com/chinese-poetry/chinese-poetry","《全唐诗》（清·曹寅等编，康熙扬州诗局本）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）","古籍注评：《瀛奎律髓》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/瀛奎律髓_(四庫全書本)）"]],"open_11711":["白露","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["白露团甘子，清晨散马蹄。","圃开连石树，船渡入江溪。","凭几看鱼乐，回鞭急鸟栖。","渐知秋实美，幽径恐多蹊。"],"",[["古注·《杜詩詳註》","鹤注当是大厯二年秋在瀼西作以首句白露为题乃咏秋候也"],["古注·《杜詩詳註》","上四从瀼西徃东屯晓时之景下四从东屯归瀼西傍晚之景杜臆白露团聚於甘上则甘将熟矣连石之树开圃而见入江之溪乗船而渡连字属树不属圃入字属溪不属船方看鱼乐而心急鸟栖秋日短也幽径多蹊恐有窃取亦爱甘而故为戏词耳庾信诗白露水银团薛道衡诗高秋白露团庄子子非鱼焉知鱼之乐古语云桃李无言下自成蹊"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11712":["孟氏","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["孟氏好兄弟，养亲唯小园。","承颜胝手足，坐客强盘[飧]。","负米力葵外，读书秋树根。","卜邻惭近舍，训子学谁门。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11713":["吾宗","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["吾宗老孙子，质朴古人风。","耕凿安时论，衣冠与世同。","在家常早起，忧国愿年丰。","语及君臣际，经书满腹中。"],"公自注云卫仓曹崇简也",[["古评·《唐诗品汇》","公自注云卫仓曹崇简也"],["古评·《唐诗品汇》","刘云山林尘士婉有余情"],["古注·《杜詩詳註》","原注卫仓曹崇简鹤注编在大厯元年又曰按世系表崇简出襄阳房为益州司马叅军左传晋吾宗也"],["古注·《杜詩詳註》","赵汸注次句领起中四其安时处顺勤家忧国皆所谓质朴古风也末乂称其通经术而知大义杜臆崇简仕为仓曹葢性行惇质而兼有学问者非村民愿朴比也魏志陈羣传陈寔曰此儿必兴吾宗景福殿赋宜尔孙子荀悦汉纪周勃质朴忠诚汉永光诏举质朴敦厚逊让有行者魏志曹操谓毛玠曰君有古人之风庄"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗品彚（附唐诗拾遗）》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩品彚_(四庫全書本)）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11714":["有叹","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["壮心久零落，白首寄人间。","天下兵常鬬，江东客未还。","穷猨号雨雪，老马怯关山。","武德开元际，苍生岂重攀。"],"",[["古注·《杜詩詳註》","鹤注当是大厯二年冬作诗云兵鬭葢指吐蕃之乱原注云传蜀官军自普还却另是一事"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11715":["冬深","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["花叶随天意，江溪共石根。","早霞随类影，寒水各依痕。","易下杨朱泪，难招楚客魂。","风涛暮不稳，舍棹宿谁门。"],"",[["古注·《杜詩詳註》","诸本作随犯重当是惟字盖声近而讹"],["古注·《杜詩詳註》","一作泪非"],["古注·《杜詩詳註》","上四冬深之景下四舟行有感此章全用倒挿花叶惟天意以早霞随类影也江溪共石根以寒水各依㾗也易下杨朱泪以风涛暮不稳也难招楚客魂以舍棹宿谁门也杜臆谓此在五律中另一竒格初疑寒水与石根紧承早霞与花叶似不相贯後见杜臆方悟霞状变化如花如叶耳盖霞有红紫青诸色故比之花叶且玩天意二字明属早霞矣起句特竒宋子侯诗花叶正低昻赵曰随类影随其所类而呈影也挚虞祈礼表随类合之旧注杨朱泣岐路谓其可南可北也古诗风涛暮不止几日到潇湘"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11716":["不寐","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["瞿塘夜水黑，城内改更筹。","翳翳月沈雾，辉辉星近楼。","气衰甘少寐，心弱恨和愁。","多垒满山谷，桃源无处求。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11717":["月圆","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["孤月当楼满，寒江动夜扉。","委波金不定，照席绮逾依。","未缺空山静，高悬列宿稀。","故园松桂发，万里共清辉。"],"",[["古注·《杜詩詳註》","此亦西阁所作谢灵运诗放舟𠉀月圆"],["古注·《杜詩詳註》","此章月下思乡上六景下二情满言月圆动言月影委波申动扉照席申当楼未缺髙悬申月圆之状末想故园秋景也杜臆江月倒影水摇而阁上之扉为动大是画意月注波中金光摇而不定月临席上绮文依而愈妍将金波绮席拆开颠倒赵汸谓诗家用古语之法梁武帝诗慅慅孤月帷何逊诗寒江复寂寥庾肩吾诗髙楼开夜扉月赋委照而吴业昌郊祀歌月穆穆以金波六韬纣时以绮为席邹阳酒赋"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11718":["中宵","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["西阁百寻余，中宵步绮疏。","飞星过水白，落月动沙虚。","择木知幽鸟，潜波想巨鱼。","亲朋满天地，兵甲少来书。"],"刘云语无诡时冩景入微",[["古评·《唐诗品汇》","刘云语无诡时冩景入微"],["古注·《杜詩詳註》","鹤注当是大厯元年在西阁作中夜指长夜言中宵尚在黄昏以後陶潜诗中宵竚遥念"],["古注·《杜詩詳註》","中宵独步领起通章星月属赋中宵所见鱼鸟属比中宵所感末伤孤身漂泊不如物情之自适也飞星过水而白下半因上落月动於沙虚上半因下一就迅疾中取象一従恍惚中描神黄生注五六即"],["古注·《杜詩詳註》","水深鱼极乐林茂鸟知归意此系夜景故以知想字面鈎画之言外则以物之得所形人之失所而人之失所由亲朋不相存济也阁在山上故髙至百寻西京赋巨兽百寻梁冀传牕牖皆有绮疏注绮疏镂为绮文也陆机诗振风薄绮疏过字动字白字虚字知字想字皆句中眼天文志星自上而降曰流自下而升曰飞庾信诗沙虚马迹深左传鸟能择木木岂能择鸟郭璞诗潜波涣鳞起王褒颂沛乎若巨鱼之縦大壑晋书谢安传亲朋毕集韩国䇿缮治兵甲以益其强"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗品彚（附唐诗拾遗）》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩品彚_(四庫全書本)）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11719":["遣愁","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["养拙蓬爲户，茫茫何所开。","江通神女馆，地隔望乡台。","渐惜容颜老，无由弟妹来。","兵戈与人事，回首一悲哀。"],"",[["古注·《杜詩詳註》","通首皆言愁绪欲借诗以遣之江可通而地犹隔叹不能往䕫也兵戈阻则弟妹难来人事蹇则容顔易老故不胜悲哀回首对开户而言潘岳闲居赋终优游以养拙尚书大传子夏曰深山之中作壤室编蓬戸庾信诗原野正茫茫水经注丹山西即巫山宋玉所谓帝女居之名曰瑶姬为之立庙号朝云祠方舆胜览神女庙在巫山县治西北二百五十步有阳云台淮南子悲哀抱於情"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11720":["秋清","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["高秋苏病气，白发自能梳。","药饵憎加减，门庭闷扫除。","杖藜还客拜，爱竹遣儿书。","十月江平稳，轻舟进所如。"],"",[["古注·《杜詩詳註》","首句总领下五句皆承肺气苏轻舟出峡言秋尽冬初之事憎加减嫌其无效闷扫除懒於应接答拜还须扶杖题竹仍遣儿书此摹写病後情状极肖黄生注三四追述五六现前七八豫期进所如得遂意中欲徃之处也内经无外其志使肺气清此秋气之应谢灵运诗药饵情所止衰疾忽在斯易不出门庭後汉书陈蕃不好扫室客怪之蕃曰大丈夫当为国扫除天下庄子原宪杖藜应门世説王子猷尝暂寄人空宅便令种竹曰何可一日无此君爱竹暗用此事按赵云遣儿书谓题字竹上杜臆云遣儿代书乞竹以栽二説不同今从前説楚辞世莫知其所如"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11721":["伤秋","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["林僻来人少，山长去鸟微。","高秋收画扇，久客掩荆扉。","嬾慢头时栉，艰难带减围。","将军犹汗马，天子尚戎衣。","白蒋风飙脆，殷柽晓夜稀。","何年减豺虎，似有故园归。"],"",[["古注·《杜詩詳註》","一作藏羽"],["古注·《杜詩詳註》","此从客䕫叙起乃伤秋之景收扇兴下掩扉夏过则扇捐犹乆客则人厌而柴门常掩也头时栉不冠也带减围身瘦也范彦龙诗有客欵柴扉嵇康书懒与慢相成梁昭明太子传体素壮腰带十围至是减削过半"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11722":["秋峡","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["江涛万古峡，肺气久衰翁。","不寐防巴虎，全生狎楚童。","衣裳垂素发，门巷落丹枫。","常怪商山老，兼存翊赞功。"],"",[["古注·《杜詩詳註》","江峡衰翁首联并提中二承江峡下四承衰翁万古峡边衰翁独处起语不寒而栗夜须防虎昼宜狎童物性人情盖种种可畏矣且素髪老人对此丹枫零落暮年秋景万事灰心若商山四皓老立功名常怪其精力过人也赵曰作客逺方虽童稚亦须亲狎欲免猜忌以全生耳杜臆楚童与巴虎并观则难狎等於防虎矣末聨乃自伤筋力之衰非讥刺四皓之出诗寤言不寐杨德周曰狎楚童谓樵采也秋兴赋素髪飒以垂领淮南子何谓七舍室堂庭门巷术野谢灵运诗晓霜枫叶丹"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11723":["南极","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["南极青山衆，西江白谷分。","古城疏落木，荒戍密寒云。","岁月虵常见，风飙虎或闻。","近身皆鸟道，殊俗自人羣。","睥睨登哀柝，矛弧照夕曛。","乱离多醉尉，愁杀李将军。"],"",[["古注·《杜詩詳註》","鹤注当是大厯元年冬在夔州作赵曰南极星名晋天文志南极在井柳之中正是南方之星故用之夔州黄希曰此是用尔雅四极中之南极夔在长安之极南也"],["古注·《杜詩詳註》","一作外非"],["古注·《杜詩詳註》","一作矛赵作蝥"],["古注·《杜詩詳註》","此公不欲久居南土而作也卢注首二南方山水三四南方风景中四南方人物末四南方时事杜臆西江至白谷而分此楚蜀之交也古城白帝旧城荒戍戍土之兵皆鸟道居高峡也自人羣非我族也柝弧城上戒严醉尉小人横行据公诗云白谷气候变又云白谷㑹深游则白谷当在䕫州杜臆谓即白帝城之谷朱超诗荒戌久无楼陶潜诗寒云没西山庾信哀江南赋风颷凛然王褒颂虎啸而风生司马彪续汉书种暠为益州刺史开晓殊俗古诗临高台篇辞仙俗归人羣古今注女墙亦名睥睨左传郑伐许颍考叔取郑伯之旗蝥弧以先登谢灵运诗夕曛岚气隂説文日入曰曛李广传广屏居蓝田南山中射猎尝夜出从人饮还至渟灞陵尉醉呵止广广骑曰故李将军尉曰今将军尚不得夜行何故也宿广亭下杜臆末用醉尉事必有所感"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11724":["摇落","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["摇落巫山暮，寒江东北流。","烟尘多战鼓，风浪少行舟。","鹅费义之墨，貂余季子裘。","长怀报明主，卧病复高秋。"],"",[["古注·《杜詩詳註》","上四对景伤时下则自写心事也巫山秋暮而一望烟尘则欲留不可江水自流而沮於风浪则欲去不能今但亲翰墨而揽寒裘亦何救於国事乎虽有报主宿心徒托诸秋山卧病而巳报明主此公一生大志复高秋见在䕫已厯两秋矣何逊诗寒江复寂寥庾信诗寒风战鼓鸣西京杂记船随风浪莫知所之顾注公诗九龄书大字有作成一囊公本善书故自比羲之战国策苏秦仕赵赵王负貂裘黄金使説秦书十上而説不行黒貂之裘敝宋之问诗卧病人事絶"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11725":["耳聋","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["生年鶡冠子，叹世鹿皮翁。","眼复几时暗，耳从前月聋。","猨鸣秋泪缺，雀噪晚愁空。","黄落惊山树，呼儿问朔风。"],"此诗足见游戱翰墨後四句俱谓耳全无闻猿鸣雀噪既不闻矣而朔风吹落木叶亦不之闻至呼儿以问之予谓果真聋矣儿所",[["古注·《杜詩詳註》","此伤老年遯世欲付之不见不闻也下四写耳聋之状但五六属无闻七八说有见仍与眼耳相关杜臆眼复几时暗乎耳幸前日聋矣语含感愤刘向七畧鶡冠子常居深山以鶡为冠袁淑真隠传鶡冠子或曰楚人衣敝履穿因服成号着书言道家亊列仙传鹿皮翁菑川人衣鹿皮居峚山上食芝草饮神泉百余年下卖药於市沈炯乐府泪尽眼方暗髀伤耳自聋巴东记猿鸣三声泪沾裳泪缺愁空以不闻故也傅毅七激仰归云愬朔风"],["古评·《瀛奎律髓》","此诗足见游戱翰墨後四句俱谓耳全无闻猿鸣雀噪既不闻矣而朔风吹落木叶亦不之闻至呼儿以问之予谓果真聋矣儿所答又何闻乎史记谓豫让呑炭为哑然请赵襄子之衣三斩之未尝哑也"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）","古籍注评：《瀛奎律髓》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/瀛奎律髓_(四庫全書本)）"]],"open_11726":["独坐二首 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["竟日雨冥冥，双崖洗更青。","水花寒落岸，山鸟暮过庭。","煖老须燕玉，充饥忆楚萍。","胡笳在楼上，哀怨不堪听。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11727":["独坐二首 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["白狗斜临北，黄牛更在东。","峡云常照夜，江月会兼风。","晒药安垂老，应门试小童。","亦知行不逮，苦恨耳多聋。"],"",[["古注·《杜詩詳註》","平声诗以独坐命题伤村居寥落也上四景物下四感怀杜臆雨洗双崖无人来往但见花落鸟过而已煖老须被充饥须食若燕玉楚萍乃世间必不可得之物而思及於此盖甚言衣食之艰难耳楼上哀笳耳不忍聴怨从心生非闗笳也公诗翠柏苦犹食明霞髙可餐正当与燕玊楚萍参看朱注双崖瞿唐两崖黄生曰水花二句抽换可得八聫此辘轳句也张正见诗楫渡岸花沈逺注水花乃岸间所落之花非荷也禽经山鸟岩栖旧注古诗燕赵多佳人美者顔如玉须燕玉所谓八十非人不煖也家语楚童谣云楚王渡江得萍实大如斗赤如日剖而食之甜如蜜晋刘畴避乱为贾人欲害畴援笳而"],["古注·《杜詩詳註》","吹之作出塞声以动其归思皆啼哭而走楼上指城楼"],["古注·《杜詩詳註》","此亦对景而叹寂寥格同上章白狗临北黄牛在东而身坐两峡之间唯见夜中云映日下风生常伴旅人耳晒药应门旅居差堪自给乃足行不逮而此身无复有为耳聴多聋而世事并且不闻平生壮志雄心至此销歇言之不胜悲怅矣末聫另作转语方有曲折杜臆谓行不逮故待药以扶衰耳多聋故藉童以将命四句作倒挿未免直致杜臆白狗峡在归州黄牛峡在夷陵又在归州之东矣水经注秭归白狗峡蜀江中流两面如削絶壁之际隠出白石如狗形状具足故以名焉又曰黄牛滩前有重岭叠起其最外髙崖间有石色如人负刀牵牛人黒牛黄成就分明杜臆以云照夜为返照非也後章云终年常起峡毎夜必通林可见照夜指云光之掩映试小童试其能否也李密陈情表应门无五尺之童黄注行不逮本论语耻躬不逮公以济世自命而□瞶如此是行不逮其言矣今按公诗言容易收病脚作足行不逮为平顺"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11728":["远游","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["江阔浮高栋，云长出断山。","尘沙连越巂，风雨暗荆蛮。","雁矫衔芦内，猨啼失木间。","弊裘苏季子，历国未知还。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11729":["夜","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["露下天高秋水清，空山独夜旅魂惊。","疎灯自照孤帆宿，新月犹悬双杵鸣。","南菊再逢人卧病，北书不至雁无情。","步蟾倚杖看牛斗，银汉遥应接凤城。"],"宋玉九辩白露既下降百草𠔃奄离披此梧楸王勃序金风生而景物清白露下而光隂晚九辩泬寥兮天高而气清寂漻兮收潦",[["古注·《御选唐诗》","宋玉九辩白露既下降百草𠔃奄离披此梧楸王勃序金风生而景物清白露下而光隂晚九辩泬寥兮天高而气清寂漻兮收潦而水清庄子秋水时至百川灌河潘岳秋兴赋澡秋水之涓涓𠔃玩逰鯈之潎潎届原渔父沧浪之水清兮可以濯我缨"],["古注·《御选唐诗》","江淹诗懐此书兮望空山陶𢎞景诗空山霜满高烟平王粲诗独夜不能寐摄衣起抚琴谢瞻诗独夜无物役寝者亦云宁骆宾王诗劳歌徒自奏客魂谁为招乂惊魂闻叶落危魄逐轮埋"],["古注·《御选唐诗》","玉篇镫锭也初学记无足曰镫有足曰锭案镫灯通用司马相如长门赋悬秋月以自照兮徂清夜於洞房梁简文帝与刘孝绰书夕鸟归林悬孤帆而未息陈子昻诗古木生云际孤帆出雾中"],["古注·《御选唐诗》","鲍泉诗新花满新树新月丽新辉何逊诗庭花枝上发新月雾中生易悬象着明莫大乎日月庾信诗月悬惟返照晋子夜歌佳人理寒服万结砧杵劳庾信夜听捣衣诗石燥砧逾响桐虚杵絶鸣唐汝询注杵即砧杵两人对𢷬故曰双"],["古注·《御选唐诗》","礼记季秋之月鞠冇黄华释文鞠本又作菊黄鹤注甫以去年秋至云安故云南菊再逢谢朓在郡卧病诗淮扬股肱郡高卧犹在兹"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《御选唐诗》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/御選唐詩_(四庫全書本)）"]],"open_11730":["暮春","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["卧病拥塞在峡中，潇湘洞庭虚暎空。","楚天不断四时雨，巫峡常吹千里风。","沙上草阁柳新闇，城边野池莲欲红。","暮春鸳鹭立洲渚，挟子翻飞还一丛。"],"",[["古注·《杜詩詳註》","此依朱氏编在大厯二年玩诗意是久卧峡中有厌居意其不在元年明矣"],["古注·《杜詩詳註》","此诗卧病峡中而作上四峡中景下四暮春景杜臆公本欲初春下峡病至暮春则舟不可行矣故有慨於卧病拥塞也拥塞则潇湘不可到而虚此映空水色矣风雨不絶旅人増闷而柳暗莲红又日月如流对此鸳鹭立渚挟子羣飞何以为情耶梁简文帝诗春色映空来夔州地暖故莲欲吐红杜臆公诗用鸳鹭皆有意如空惭鸳鹭行年衰鸳鹭羣寒空见鸳鹭回首忆朝班故此诗鸳鹭亦是借以自比楚辞望大河之洲渚兮魏文帝短歌翩翩飞鸟挟子巢栖王筠诗庭禽挟于栖楚辞翾飞兮翠层庾信春赋一丛香草足碍人説文丛聚也"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11731":["晴二首 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["久雨巫山暗，新晴锦绣文。","碧知湖外草，红见海东云。","竟日莺相和，摩霄鹤数羣。","野花乾更落，风处急纷纷。"],"草碧指言湖外云红指言海东其善於张大如此",[["古注·《杜詩詳註》","鹤注当是大厯元年初到䕫州时作"],["古评·《瀛奎律髓》","草碧指言湖外云红指言海东其善於张大如此"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）","古籍注评：《瀛奎律髓》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/瀛奎律髓_(四庫全書本)）"]],"open_11732":["晴二首 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["啼乌争引子，鸣鹤不归林。","下食遭泥去，高飞恨久阴。","雨声冲塞尽，日气射江深。","回首周南客，驱驰魏阙心。"],"",[["古注·《杜詩詳註》","此章对晴景而感懐啼乌下食鸣鹤髙飞见物情厌雨而喜晴雨声日气㸃明题意末伤羇旅不归也冲塞射江与魏阙相照易鸣鹤在阴史记太史公留滞周南公借以自喻太史公乃司马谈周南在今西安府泾阳县吕氏春秋中山公子谓詹子曰身在江湖之上心居魏阙之下"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11733":["雨","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["始贺天休雨，还嗟地出雷。","骤看浮峡过，密作渡江来。","牛马行无色，蛟龙鬬不开。","干戈盛阴气，未必自阳台。"],"",[["古注·《杜詩詳註》","鹤注当是大厯元年作洙注诗云蛟龙鬬干戈盛是张献诚杨子琳柏茂林并起兵讨崔旰时也"],["古注·《杜詩詳註》","一作巫非"],["古注·《杜詩詳註》","一作塞宻"],["古注·《杜詩詳註》","乍晴复雷雨将作矣中四状其雨至而势大末言此闗人事所召非由地气使然诗葢有感而作也卢注行无色从雨宻来鬬不开从雨骤来上句喻凋残未起下句喻战争不休易雷出地奋豫庄子秋水时至两涘渚涯之间不辩牛马汉武帝歌蛟龙骋兮放逺游龙鬬野出汉书阮籍诗朔风厉严寒阴气下微霜"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11734":["月三首 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["断续巫山雨，天河此夜新。","若无青嶂月，愁杀白头人。","魍魉移深树，虾蟆动半轮。","故园当北斗，直指照西秦。"],"",[["古注·《杜詩詳註》","此当是大厯二年六月初旬所作曰巫山曰二十四回则在夔州已二年矣曰半轮曰六上则是二年之六月矣"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11735":["月三首 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["并照巫山出，新窥楚水清。","羁栖愁里见，二十四回明。","必验升沈体，如知进退情。","不违银汉落，亦伴玉绳横。"],"",[["古注·《杜詩詳註》","此章见月而动归思是咏初晴之月嶂月新悬故旅愁暂解空照西秦则客愁仍在上是玩月而喜下是思家而悲移深树避明月动半轮上月也故园指杜曲沈约诗崚嶒起青嶂黄生注魍魉虾蟆如此粗丑字惟少陵能用然终不可训左传注疏魍魉川泽之神也淮南子状如三嵗小儿赤黒色赤目长耳美发酉阳杂俎月中有金背虾蟆刘孝绰诗轮光缺不半秦城上当北斗公故居所在"],["古注·《杜詩詳註》","一作愁见里"],["古注·《杜詩詳註》","此章见月而伤久客是通计两年之月并照承上来照从月言舍下明字窥就人言含下见字公客䕫二年故曰二十四回升沉进退乃二十四回中所见者升沉谓月有出没进退谓月有盈亏上之月早升故夜违银汉而先落下之月迟升故晓伴玉绳而犹横二句言久暂迟速之不同正见其升沉进退也不亦二字活看谓不是如彼亦是如此他注谓望夜之月自昏待旦不落而常横却於上文不相贯矣以羇栖愁对二十四乃借对法庾信马射赋横弧於楚水之蛟鲍照诗银汉倾露落天文志杓三星为玉衡春秋元命苞玉衡北两星为玉绳"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11736":["月三首 三","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["万里瞿塘峡，春来六上弦。","时时开暗室，故故满青天。","爽合风襟静，高当泪脸悬。","南飞有乌鹊，夜久落江边。"],"",[["古注·《杜詩詳註》","此章对月而念孤栖是专论半年之月杜臆中四有一喜一恨意时开暗室则喜之而爽合风故满青天则恨之而空当涙脸一月而分作两般景随情转故也夜落江边则无枝可栖借乌鹊以自伤飘泊王褒月诗上如半壁故故犹云屡屡宋玉风赋有风飒然而至王乃披而当之张正见诗泪脸年年流乌鹊南飞出魏武诗"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11737":["雨","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["万木云深隐，连山雨未开。","风扉掩不定，水鸟过仍回。","鲛馆如鸣杼，樵舟岂伐枚。","清凉破炎毒，衰意欲登台。"],"",[["古注·《杜詩詳註》","丄六雨中之景下二雨後之情云深而万木隠藏者以雨气连山而不开也风扉不定水鸟仍廻风雨并至也雨落空江声如鸣杼樵人阻雨不能伐枚江边雨骤也卢注登阳台而袭快风衰意欲藉以少舒胡夏客曰风扉一聨意在言外比兴无穷非仅摹景而已文选鲛人织绡於泉室江赋鲛人构舘於悬流诗伐其条枚注枝曰条干曰枚古艶歌夏节纯和天清凉"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11738":["晚晴","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["返照斜初彻，浮云薄未归。","江虹明远饮，峡雨落余飞。","凫雁终高去，熊罴觉自肥。","秋分客尚在，竹露夕微微。"],"",[["古注·《杜詩詳註》","鹤注当是大厯元年秋分作何逊诗褰裳对晚晴"],["古注·《杜詩詳註》","上四晚晴之景下四晚晴有感夕照映虹有似下垂而饮承上返照雨後云过尚带余㸃飘飞承上浮云鸟兽逄秋而自得兴已之久客未归张正见诗镜如临风月流如饮涧虹前汉燕王旦时有大虹下於宫中饮井水竭按虹见则雨晴矣杜臆鳬不高飞字恐有误陶潜诗闲雨纷微微"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11739":["夜雨","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["小雨夜复密，回风吹早秋。","野凉侵闭户，江满带维舟。","通籍恨多病，爲郎忝薄游。","天寒出巫峡，醉别仲宣楼。"],"",[["古注·《杜詩詳註》","此章对雨而动归思上四写景下四述怀野气骤凉而侵户见秋风之早江水添满而系舟见夜雨之宻多病薄逰言客况无聊公在䕫则思出峡徃荆又思别楼意在急於北归也任彦昇诗序维舟久之洙曰汉卜式不愿为郎夏侯湛东方朔画赞序以为浊世不可富乐也故薄游以取位黄生曰诗有正写不出须用反撃始透者如野凉而戸始闭江满而舟且维反撃出峡之无縁也人只赏侵字带字不知苦景真情全在闭字维字五托多病六托浪游反撃朝廷非弃已也七以天寒挽一二出峡挽三四是预期之词未经出峡便思去荆乂反撃欲出之难也"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11740":["更题","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["只应踏初雪，骑马发荆州。","直怕巫山雨，真伤白帝秋。","羣公苍玉佩，天子翠云裘。","同舍晨趋侍，胡爲淹此留。"],"",[["古注·《杜詩詳註》","朱注与前首同作故曰更题"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11741":["归","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["束带还骑马，东西却渡船。","林中才有地，峡外绝无天。","虚白高人静，喧卑俗累牵。","他乡悦迟暮，不敢废诗篇。"],"",[["古注·《杜詩詳註》","杜臆此诗与前章相继而作前是徃园此是园中归也"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11742":["返照","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["楚王宫北正黄昏，白帝城西过雨痕。","返照入江翻石壁，归云拥树失山村。","衰年肺病唯高枕，绝塞愁时早闭门。","不可久留豺虎乱，南方实有未招魂。"],"刘云语不轻易感恨更多",[["古评·《唐诗品汇》","刘云字字着意"],["古评·《唐诗品汇》","刘云语不轻易感恨更多"],["古注·《杜詩詳註》","杜臆谓诗作於西阁阁临白帝城西故见返照演义诗成後偶举二字为题非专咏返照也後有五律一首是全写返照"],["古注·《杜詩詳註》","上四雨後晚晴之景下四衰病乱离之感雨痕初过故日照江而石壁之影摇动黄昏乍暝故云拥树而山邨之路遮迷此时方欲髙枕闭门乃思及豺虎为乱则兹地不堪久留矣但恐惊散之旅魂未必能招之北归耳愁时指乱招魂自谓顾注楚王宫在巫山县西北孙登诗飘扬楚王宫楚辞黄昏以为期吴均诗九茎日返照江淹诗缅映石壁素傅毅七激仰归云愬朔风庾信诗山村落猎围史张仪传大王髙枕而卧晋封禅奏人望絶塞胡夏"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗品彚（附唐诗拾遗）》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩品彚_(四庫全書本)）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11743":["热三首 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["雷霆空霹雳，云雨竟虚无。","炎赫衣流汗，低垂气不苏。","乞爲寒水玉，愿作冷秋菰。","何似儿童岁，风凉出舞雩。"],"",[["古注·《杜詩詳註》","鹤注大厯元年䕫州作诗云十年可解甲自天宝十四载至此为十年也"],["古注·《杜詩詳註》","此诗为䕫州苦热而作上四记酷热下四思解热也易鼔之以雷霆繁露王者言不从则金不从革秋多霹雳霹雳者金气也国策宫中虚无人傅毅赋践朱夏之炎赫司马相如喻巴蜀檄流汗相属相如美人赋黼帐低垂山海经堂庭之山多水玉子虚赋水玉磊砢郭璞曰水玉水精也杜臆水玉恐是𤓰之别名故对秋菰园人送𤓰诗浮沈寒水玉可证菰蒲也成於深秋故性冷仲长统乐志赋风於舞雩之下味归髙堂之上"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11744":["热三首 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["瘴云终不灭，泸水复西来。","闭户人高卧，归林鸟却回。","峡中都似火，江上只空雷。","想见阴宫雪，风门飒踏开。"],"",[["古注·《杜詩詳註》","黄生曰诗中説冷易佳説热难工如炎赫衣流汗低垂气不苏又林热鸟开口又气暍肠胃融如此句法在杜公亦不免褦襶矣"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11745":["热三首 三","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["朱李沈不冷，雕胡炊屡新。","将衰骨尽痛，被褐味空频。","歘翕炎蒸景，飘颻征戍人。","十年可解甲，爲尔一沾巾。"],"",[["古注·《杜詩詳註》","一作褐非"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11746":["日暮","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["牛羊下来久，各已闭柴门。","风月自清夜，江山非故园。","石泉流暗壁，草露滴秋根。","头白灯明里，何须花烬繁。"],"刘云人人能言人人不能言与可惜欢娯地同耳",[["古评·《唐诗品汇》","刘云人人能言人人不能言与可惜欢娯地同耳"],["古注·《杜詩詳註》","鹤注当是大厯二年瀼西作"],["古注·《杜詩詳註》","上二日暮之亊三四思故乡也五六日暮之景末二感衰年也本是暗泉流石壁秋露滴草根却用颠倒出之觉声谐而句警杜臆风月一聫意极悲凉结意尤为凄惋公志在济时而伤於头白反怪灯烬繁开与待尔嗔乌鹊同意诗日之夕矣羊牛下来南史褚彦囘传初秋凉夕风月甚美楚辞饮石泉兮䕃松柏北山移文石泉咽而下怆王粲诗草露沾我衣沈约诗草根滴露霜世俗谓有喜事则灯结花"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗品彚（附唐诗拾遗）》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩品彚_(四庫全書本)）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11747":["八月十五夜月二首 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["满目飞明镜，归心折大刀。","转蓬行地远，攀桂仰天高。","水路疑霜雪，林栖见羽毛。","此时瞻白兔，直欲数秋毫。"],"",[["古注·《杜詩詳註》","鹤注当属大厯二年瀼而作与翫月对月两章盖一时所作也"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11748":["八月十五夜月二首 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["稍下巫山峡，犹衔白帝城。","气沈全浦暗，轮仄半楼明。","刁斗皆催晓，蟾蜍且自倾。","张弓倚残魄，不独汉家营。"],"",[["古注·《杜詩詳註》","此咏中秋之月明镜喻月刀环思归三四承归心下四承明镜顾云归心如大刀之折恨不能还也蓬桂皆秋时物行地逺在夔州仰天髙望长安霜雪羽毛皆写月色之明秋毫即指兎毫盖因月中之兎想见地下之兎也古乐府藁砧今何在山上复有山何当大刀头破镜飞在天吴竞解题藁砧砆也重山出也大刀头刀头有环问夫何时当还也破镜飞上天言月半缺当还也赵汸注以环为还犹言放臣待命境上赐环则返李徳林诗月桂近将攀枣璩诗仰攀桂树杪天问月中何冇玉兎捣药胡夏客曰毫毛同押㣲觉有碍"],["古注·《杜詩詳註》","此咏将晓之月上四月下之景下四月下感时月傍山头光气沈而全浦皆暗浦在山下也月射城西轮影侧而半楼尚明楼居城上也时将达旦军士犹张弓而仰残月盖竟夜防警矣末见军旅非一处也全浦鱼复浦也刁十以铜为之军中警夜者孟康曰昼炊饭食夜击持行五经通义曰月中有兎与蟾蜍何也月隂也蟾蜍阳也而与并明隂系於阳也老子天之道其犹张弓乎朱注此倚字即长剑倚天外之倚记月者三日成魄"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11749":["十六夜翫月","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["旧挹金波爽，皆传玉露秋。","关山随地阔，河汉近人流。","谷口樵归唱，孤城笛起愁。","巴童浑不寝，半夜有行舟。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11750":["十七夜对月","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["秋月仍圆夜，江村独老身。","卷帘还照客，倚杖更随人。","光射潜虬动，明翻宿鸟频。","茅斋依橘柚，清切露华新。"],"",[["古注·《杜詩詳註》","鹤注编在大厯二年瀼西作以诗内有茅齐句也"],["古注·《杜詩詳註》","秋月仍圆喜其未缺江村独老不觉凄然矣下六句自近而逺自逺而近皆写出江村月下之景皆写出老身对月之情卢云照客随人正映独老之身逺注仍字还字更字俱照十七夜言黄生注结以清切字绾题以茅斋字见卷帘倚杖所在作法周密朱超诗惟余故楼月逺近必随人邵注潜虬无角龙也蜀都赋下高鹄出潜蚪谢灵运诗潜蚪媚幽姿洙曰宿鸟出文选"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11751":["村雨","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["雨声传两夜，寒事飒高秋。","挈带看朱绂，开箱覩黑裘。","世情只益睡，盗贼敢忘忧。","松菊新沾洗，茅齐慰远游。"],"",[["古注·《杜詩詳註》","鹤注当是广徳二年在草堂作"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11752":["雨晴","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["雨时山不改，晴罢峡如新。","天路看殊俗，秋江思杀人。","有猨挥泪尽，无犬附书频。","故国愁眉外，长歌欲损神。"],"",[["古注·《杜詩詳註》","鹤注当是大厯元年䕫州作"],["古注·《杜詩詳註》","上四雨晴有感下四思乡之意雨时总是此山及晴罢而峡洗如新喜初晴矣晴则可以出峡而犹然留滞故不胜愁思殊俗指䕫州泪尽蒙此秋思念家乡无书蒙此故国指洛阳愁睂外心愁而眼不能见也凢引古典须用翻新猿声沾泪黄犬附书情已悲矣此説猿多而泪零已尽无犬而频覔附书语倍凄惨上句用水经注渔父歌下句用陆机入洛亊注皆别见萧子显诗雨罢叶增菉山峭夹水曰峡天路犹云天边即指䕫州枚乘诗天路隔无期诗序国异政家殊俗释亡名诗愁眉独向阙陆机诗长歌赴促节"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11753":["晚晴吴郎见过北舍","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["圃畦新雨润，媿子废鉏来。","竹杖交头拄，柴扉隔径开。","欲栖羣鸟乱，未去小童催。","明日重阳酒，相迎自醱醅。"],"",[["古注·《杜詩詳註》","醱音泼醅铺杯切初喜其过既惜其去而又望其来此直叙情事有朴质自然之致黄注吴取捷径而来叩其後扉故诗言扫径而题曰舍北即所谓鉏斫舍北果林枝蔓者也庄子汉隂丈人方将为圃畦庾信春赋石榴聊泛葡萄醱醅李白诗葡萄自醱醅黄生注醱与泼同旋入水也自醱醅以亲酌为敬也"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11754":["暝","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["日下四山阴，山庭岚气侵。","牛羊归径险，鸟雀聚枝深。","正枕当星劒，收书动玉琴。","半扉开烛影，欲掩见清砧。"],"",[["古注·《杜詩詳註》","牛羊鸟雀是山暝属外景当剑动琴是庭暝属内景末二则写全暝之𠉀矣四山东屯四面皆山也险字深字俱从暝字想出逺注正枕而误当剑收书而误动琴以室暝故耳既夕应传呼於无形处想出有声欲掩见清砧於无声处描出冇影摹夜景入细如此谢庄宣贵妃诔山庭侵日谢灵运诗夕曛岚气隂越絶书寳剑篇观其䤨烂如列星之堂观其光如水溢於塘吴越春秋此吾前君之剑中有七星江淹画扇赋玉琴兮珠徽琴赋徽以荆山之玉刘庭芝捣衣篇盼青砧兮怅盘桓"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11755":["云","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["龙似瞿唐会，江依白帝深。","终年常起峡，每夜必通林。","收获辞霜渚，分明在夕岑。","高斋非一处，秀气豁烦襟。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11756":["月","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["四更山吐月，残夜水明楼。","尘匣元开镜，风帘自上钩。","兔应疑鹤发，蟾亦恋貂裘。","斟酌姮娥寡，天寒耐九秋。"],"",[["古注·《杜詩詳註》","梁氏编在大厯二年今按诗云残夜水明楼当是元年西阁作"],["古注·《杜詩詳註》","音恒一作嫦"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11757":["雨四首 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["微雨不滑道，断云疎复行。","紫崖奔处黑，白鸟去边明。","秋日新沾影，寒江旧落声。","柴扉临野碓，半得捣香秔。"],"",[["古注·《杜詩詳註》","鹤注当是大厯二年冬瀼西作"],["古注·《杜詩詳註》","黄生作沾新"],["古注·《杜詩詳註》","黄作落旧"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11758":["雨四首 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["江雨旧无时，天晴忽散丝。","暮秋沾物冷，今日过云迟。","上马迥休出，看鸥坐不辞。","高轩当灧澦，润色静书帷。"],"",[["古注·《杜詩詳註》","葛常之曰紫崖奔处黒白鸟去边明而江碧鸟逾白山青花欲燃之句似之赠王侍御云晓鸎工迸泪秋月解伤神而感时花溅泪恨别鸟惊心之句似之殆同是一机轴陈师道曰余登多景楼南望丹徒有大白鸟飞近青山而得句云白鸟过林分外明谢朓亦云黄鸟度青枝语巧而弱老杜云白鸟去边明语少而意广余毎还里而自觉老复得句云坐下渐多人杜云坐深乡党敬句穏而语益工乃知杜诗无不有也"],["古注·《杜詩詳註》","次章记雨中𠉀晴之景朱彝尊曰微雨断云俗谓之过云雨旧无时不时常雨过云迟云中带雨也回马看鸥避雨之事润色入帷观雨之趣上二首咏雨尚在怡情处下二章咏雨却在伤心处矣梁简文雨後诗散丝与山气忽合复俄晴古诗宻雨如散丝杜臆鸥一作鸦埤雅云俗𠉀乌飞翅重知其将雨看鸦卜其晴也"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11759":["雨四首 三","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["物色岁将晏，天隅人未归。","朔风鸣淅淅，寒雨下霏霏。","多病久加饭，衰容新授衣。","时危觉凋丧，故旧短书稀。"],"",[["古注·《杜詩詳註》","去声一作丧乱"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11760":["雨四首 四","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["楚雨石苔滋，京华消息迟。","山寒青兕呌，江晚白鸥饥。","神女花钿落，鲛人织杼悲。","繁忧不自整，终日洒如丝。"],"",[["古注·《杜詩詳註》","三章叙雨中客况首二总提三四应物色将晏下四应天隅未归淅淅风细声霏霏雨微貌加饭授衣旅人自慰故旧书稀又觉自伤矣杜臆病虽稍安念及时危便觉凋丧乃故交之书稀至则世亦以废人待我矣又云近者短书逺者长书短书犹稀况长书乎近者且然况逺者乎西京杂记栋宇物色惟旧邵注天隅䕫州在天之西南隅谢惠连诗淅淅振条风楚辞江云霏霏而承宇古诗努力加餐饭"],["古注·《杜詩詳註》","诗九月授衣江淹诗袖中有短书愿寄双飞燕"],["古注·《杜詩詳註》","四章叙雨中忧绪此诗结构人但知首尾相闗二与七应一与八应而不知中间即景寓意俱是双关杜臆云中四比凶人得志清士失所寡妇穷民苦於兵赋忧多不能自理故对雨丝而兴怆雨沮消息承上亲故书稀兕呌雨中所闻鸥饥雨中所见神女钿落应山雨鲛人杼悲应江雨黄生注忧不自整则心乱故接以雨洒如丝诗律工细如此巫山有神女庙薛梦符注唐志命妇之服两博鬓饰以寳钿金花刘遵诗髩转匝地钿江赋鲛人构馆於悬流吴都赋泉客潜织而巻绡沈约庭雨应诏诗非烟复非云如丝复如雾洪仲曰接句不测与羣盗尚纵横句同杜诗接句有写景不测者秋风落日斜是也有用句不测者京华消息迟是也意景虽殊而法则一故曰杜诗惯法二必开七必阖"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11761":["夜","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["绝岸风威动，寒房烛影微。","岭猨霜外宿，江鸟夜深飞。","独坐亲雄劒，哀歌叹短衣。","烟尘绕阊阖，白首壮心违。"],"",[["古注·《杜詩詳註》","猿宿鸟飞承风威此夜中景独坐哀歌承烛影此夜中事末承三聫伤暮年不能靖乱也杜臆岭猿不啼畏风而宿江鸟不宿畏风而飞皆夜景之可悲者亲雄剑尚思救世叹短衣不能庇身矣鹤注大厯二年九月吐蕃寇灵州邠州郭子仪屯泾阳京师戒严故有末二语木华海赋絶岸万丈芜城赋蔌蔌风威江总诗芦花霜外白史记孟子传恵王屏左右独坐而再见之列士传楚王命镆邪铸双剑一雌一雄左思诗哀歌和渐离淮南子甯戚饭牛车下击牛角而为商歌曰南山粲白日烂短布单衣适至骭长夜漫漫何时旦史记叔孙通服短衣蔡琰胡笳烟尘蔽野兮胡卤盛水经注魏明帝上法太极在洛阳南起太极殿於汉崇徳殿故处改雉门为阊阖门乐府词烈士暮年壮心不巳"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11762":["晨雨","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["小雨晨光内，初来叶上闻。","雾交才洒地，风逆旋随云。","暂起柴荆色，轻沾鸟兽羣。","麝香山一半，亭午未全分。"],"",[["古注·《杜詩詳註》","黄鹤依梁氏编在大厯二年今姑仍之"],["古注·《杜詩詳註》","黄生曰光处始见叶上始闻体物既精而布置风雨云雾四字能将是日景色曲折描出山色未分上云雾赵汸注必雾起而方能洒地经风折而旋即随云细之甚也此与烟添才有色风引更如丝相似葢着题处所必用者曰暂曰轻皆言其细小自晨至午全诗皆用顺冩工细入妙柴荆小木梦弼曰䕫州图经麝香山在䕫州东南一百二十里山出麝香故名"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11763":["返照","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["返照开巫峡，寒空半有无。","已低鱼复暗，不尽白盐孤。","荻岸如秋水，松门似画图。","牛羊识童仆，既夕应传呼。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11764":["向夕","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["畎亩孤城外，江村乱水中。","深山催短景，乔木易高风。","鹤下云汀近，鸡栖草屋同。","琴书散明烛，长夜始堪终。"],"",[["古注·《杜詩詳註》","此是大厯二年冬瀼西作梁昭明太子诗寒色向夕敛"],["古注·《杜詩詳註》","黄生曰此诗伤客居寥落情寓景中三四衰疾之悲五六离索之感藉琴书以消长夜拈一始字方露本意杜臆冬日苦短深山蔽之其晷更促岁寒多风乔木惹之其声益悲黄注曰近曰同即麋鹿共为羣意烛光散射於琴书句用倒装啸赋青飈振乎乔木诗鸡栖于埘束晳贫家赋有陋狭之草屋无蔽覆之受尘朱注兰膏明烛"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11765":["晓望","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["白帝更声尽，阳台曙色分。","高峯寒上日，叠岭宿霾云。","地坼江帆隐，天清木叶闻。","荆扉对麋鹿，应共尔爲羣。"],"刘云语至不可解则妙耳",[["古评·《唐诗品汇》","刘云语至不可解则妙耳"],["古注·《杜詩詳註》","鹤注当是大厯二年东屯作"],["古注·《杜詩詳註》","上声一作初上杜臆作上寒"],["古注·《杜詩詳註》","一作未收"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗品彚（附唐诗拾遗）》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩品彚_(四庫全書本)）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11766":["雷","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["巫峡中宵动，沧江十月雷。","龙虵不成蛰，天地划争回。","却碾空山过，深蟠绝壁来。","何须妒云雨，霹雳楚王台。"],"",[["古注·《杜詩詳註》","姑依蔡编属在大厯二年之冬"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11767":["雨","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["冥冥甲子雨，已度立春时。","轻箑烦相向，纤絺恐自疑。","烟添才有色，风引更如丝。","直觉巫山暮，兼催宋玉悲。"],"",[["古注·《杜詩詳註》","诗为甲子逢雨而作首聮记异三四承立春时怪其乍暖五六承雨㝠㝠形其细微巫山暮雨後昏翳也宋玉悲客况凄凉也楚辞雷填填兮雨㝠㝠朝野佥载春雨甲子赤地千里秋兴赋於时乃屏轻箑释纤絺注箑扇也纤絺细葛洙曰扇可相向则葛疑其可着矣张协诗腾云似涌烟宻雨如散丝高唐赋妾在巫山之阳暮为行雨"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11768":["朝二首 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["清旭楚宫南，霜空万岭含。","野人时独往，云木晓相参。","俊鹘无声过，饥乌下食贪。","病身终不动，摇落任江潭。"],"",[["古注·《杜詩詳註》","依蔡编入在大厯二年"],["古注·《杜詩詳註》","首章对朝景而兴乆客之悲在四句分截叶落霜空故万岭皆含日色既而独往山上又见木杪停云参在眼前矣杜臆日出之际虽禽鸟各有所营而病身不动如草木之任其揺落耳时独往间步田间也终不动未能出峡也郭璞江赋视雰祲於清旭谢灵运诗千圻邈不同万岭状皆异无声过飞之疾也庾信枯树赋昔年杨柳依依汉南今看揺落凄怆江潭"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11769":["朝二首 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["浦帆晨初发，郊扉冷未开。","村疎黄叶坠，野静白鸥来。","础润休全湿，云晴欲半回。","巫山冬可怪，昨夜有奔雷。"],"",[["古注·《杜詩詳註》","起聫本以下句抱上句黄生云若用直叙只是万岭楚宫南霜空清旭含三聫乌鹘并列黄生云饥乌贪而下食不知俊鹘之在其上此伤怀禄而被䜛者故暂借江潭以息机耳"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11770":["晚","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["杖藜寻晚巷，炙背近墙暄。","人见幽居僻，吾知拙养尊。","朝廷问府主，耕稼学山村。","归翼飞栖定，寒灯亦闭门。"],"",[["古注·《杜詩詳註》","一作晚巷"],["古注·《杜詩詳註》","首记薄晚之亊末记薄晚之景中乃自叙已情僻则与世无关尊则自得其趣朝问府主耕学山农见野人不知国事矣末言与物偕息写出优游自在之意黄生注初贪暴背傍晚始归起二用倒装幽居承上拙养起下末句灯字应巷晚寒字应墙暄诗律之细宜公自道也庄子原宪杖藜而应门邵注府主太守也晋书孙楚传参军不敬府主曹植诗归鸟赴乔林翩翩厉羽翼庾信诗鸟寒栖不定"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11771":["夜二首 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["白夜月休弦，灯花半委眠。","号山无定鹿，落树有惊蝉。","暂忆江东鱠，兼怀雪下船。","蛮歌犯星起，空觉在天边。"],"",[["古注·《杜詩詳註》","一作委半"],["古注·《杜詩詳註》","此章先景後情从夜月叙起无心看月故云休待灯花半落身方就眠却闻号鹿惊蝉虽眠不寐矣故思及鲈鱠雪船如身游吴越之间忽聴蛮歌四起方觉身在天边孤栖如故也卢注不宜然而然曰犯公用犯字都有谓将晓诗曰飘飘犯百蛮言老还入蛮也对雪诗曰北雪犯长沙言北却侵南也此曰蛮歌犯星起言夜终冒晓也杜臆佛家以前半月为白夜诗云蝉惊当是秋夜上初七八之月张翰思江东鲈脍王子猷雪夜访戴逵事已别见䕫本蛮地故云蛮歌当星而起即"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11772":["夜二首 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["城郭悲笳暮，村墟过翼稀。","甲兵年数久，赋歛夜深归。","暗树依岩落，明河绕塞微。","斗斜人更望，月细鹊休飞。"],"",[["古注·《杜詩詳註》","指歌者邵云公聴歌而起非是"],["古注·《杜詩詳註》","次章景情夹叙将月细作结一二将夜之景三四伤䕫人之重困五六夜尽之景七八伤一己之孤栖此亦虚实相间格过翼稀见村野荒凉公欲北归而嫌鹊南飞故嘱其休飞也杜臆两首非一时之作前首夜中犹眠此首彻夜不寝矣人更望属自已对鹊言故曰人黄生注末句翻魏武乐府"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11773":["宗武生日","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["小子何时见，高秋此日生。","自从都邑语，已伴老夫名。","诗是吾家事，人传世上情。","熟精文选理，休觅彩衣轻。","凋瘵筵初秩，欹斜坐不成。","流霞分片片，涓滴就徐倾。"],"",[["古注·《杜詩詳註》","此以家学朂宗武小子何时见其生乎此日正其堕地时也起作问答之词都邑语成都之人夸语也公祖审言善诗世情因而传述故当精文选以绍家学何必为彩衣娯亲乎此乃面命之语非遥寄宗武也宋子侯诗髙秋八九月大戴礼百里而有都邑顔氏家训吾家风教素为整密吕氏春秋精而熟之将告之梁昭明太子萧统在东宫有书三万巻集古人文词诗赋为文选三十巻列女传老莱子养二亲行年七十着五色彩衣戏於亲侧"],["古注·《杜詩詳註》","一作几片"],["古注·《杜詩詳註》","此叙生日情事宗武侍庭故有筵秩凋瘵欹斜自述老病流霞涓滴思得仙浆以起疾也此章上八句下四句海赋为凋为瘵诗賔之初筵左右秩秩庾信小园赋行欹斜兮得路抱朴子项曼都自言到天上遇紫府仙人以流霞一杯饮之辄不饥渴庾信诗片片红顔落鲍照诗铜溪画森沉孔窦夜涓滴"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11774":["又示宗武","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["觅句新知律，摊书解满牀。","试吟青玉案，莫羡紫罗囊。","假日从时饮，明年共我长。","应须饱经术，已似爱文章。","十五男儿志，三千弟子行。","曾参与游夏，达者得升堂。"],"",[["古注·《杜詩詳註》","与上章同时作"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11775":["熟食日示宗文宗武","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["消渴游江汉，羇栖尚甲兵。","几年逢熟食，万里逼清明。","松柏邛山路，风花白帝城。","汝曹催我老，回首泪纵横。"],"",[["古注·《杜詩詳註》","鹤注当是大厯二年在夔州作盖元年春晚方迁夔三年正月已下峡矣洙注熟食日即寒食节也秦人呼寒食为熟食日言其不动烟火预办熟食物过节也齐人呼为冷节又曰禁烟节鹤曰天寳十载二月勑礼标纳火之禁语有钻燧之文今後寒食并禁火三日"],["古注·《杜詩詳註》","旧作卭杜田定作邙"],["古注·《杜詩詳註》","首章逢寒食而念先茔也杜臆客游羇栖茫茫过去至熟食之日忽惊清明已逼清明在次日也邙山旧陇拜扫久荒故对白帝风花不胜怵惕况子年日长已年日衰有似催之老者故山不见惟回首而泪零耳旧注公先茔在洛流寓不能展省故有此句陆机诗坟垄日月多松栢郁芒芒黄希曰唐制寒食百官有墓茔在城外及在京畿外者任往拜扫元和郡县志北邙山在河南府偃师县北二里沈佺期洛城记邙山古今东洛九原之地梁孝元帝诗风花下砌傍马援戒兄子书愿汝曹效之顾注云汝曹催我老谓已亦将为松栢中人矣今按只言老不能归以接回首故茔方於松栢邙山相"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11776":["又示两儿","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["令节成吾老，他时见汝心。","浮生看物变，爲恨与年深。","长葛书难得，江州涕不禁。","团圆思弟妹，行坐白头吟。"],"",[["古注·《杜詩詳註》","此足前章之意兼忆弟妹也言老不归乡他时奉先省墓见汝曹之用心耳我看物𠉀屡迁而先茔长隔恨与年俱深矣汝曹当体此意也且弟留长葛妹托江州当此令节不能一室团圆惟有头白哀吟而已汝曹并母忘此意也恨字有两意一恨久违坟墓一恨逺离弟妹前有送弟往齐州诗长葛与齐州相近故知长葛指弟七歌云有妹在锺离江州与锺离相近故知江州指妹令节指寒食唐以中和上已九日为三令节汉明帝诏吹时律观物双旧书长葛属许州隋分许昌县置江州浔阳郡属江南西道本九江郡天寳元年更名史正义封豕主沟凟不欲团圆"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11777":["社日两篇 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["九农成德业，百祀发光辉。","报効神如在，馨香旧不违。","南翁巴曲醉，北雁塞声微。","尚想东方朔，诙谐割肉归。"],"",[["古注·《杜詩詳註》","首章见社祭而思家农事告成故社祀皆举报効言致祭之诚馨香言祭品之洁南翁北雁对社时而怀故郷东方割肉因社事而念颁赐也顾注扈水鸟也扈有九种以九扈为九农之号各随其事以教民亊百祀即社祭谷非土不生故报祭於社神光辉言祭之盛也左传少皥氏以九扈为九农史记秦纪山川百祀之礼江总碑文思曷深於报効谢朓送神歌敬如在礼将周书至治馨香又黍稷非馨明徳惟馨不违祭不失时南翁指老人之与祭者因醉而歌巴渝之曲顾注南翁即南公项籍传注南方之老人也秋时北雁南来曰塞声微者怜其逺飞而力竭矣或云借言音书断絶即所谓北书不至雁无情东方朔传伏日诏赐从官肉朔拔剑割肉谓同官曰伏日当早归请受赐即怀肉去大官奏之诏朔自责朔曰拔剑割肉一何壮也割之不多又何㢘也归遗细君又何仁也西溪丛语此诗诙谐割肉社日用伏日亊苏黄皆以为误按史记诸侯年表古者只有春社秦徳公二年始用伏日为秋社磔狗四门以御灾䖝社乃同日至汉方有春秋二社与伏分也汉叙□东方赡辞诙谐倡优"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11778":["社日两篇 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["陈平亦分肉，太史竟论功。","今日江南老，他时渭北童。","欢娱看绝塞，涕泪落秋风。","鸳鹭回金阙，谁怜病峡中。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11779":["九日五首 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["重阳独酌杯中酒，抱病起登江上台。","竹叶於人既无分，菊花从此不须开。","殊方日落玄猨哭，旧国霜前白雁来。","弟妹萧条各何往，干戈衰谢两相催。"],"",[["古注·《杜詩詳註》","一作独一作岂"],["古评·《诗人玉屑》","尝与公论对偶，如……，以镜名对酒名，虽为亲切，至如杜子美云：「"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）","古籍注评：《诗人玉屑》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/詩人玉屑_(四庫全書本)）"]],"open_11780":["九日五首 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["旧日重阳日，传杯不放杯。","即今蓬鬓改，但媿菊花开。","北阙心长恋，西江首独回。","茱萸赐朝士，难得一枝来。"],"旧与苏司业兼随郑广文采花香泛泛坐客醉纷纷野树歌还倚秋砧醒却闻欢娱两㝠漠西北有孤云老杜九日五言律凡九首",[["校注·《瀛奎律髓》","三首取二"],["古注·《杜詩詳註》","一作萸房"],["古注·《杜詩詳註》","次章思朝士也上四伤老下四怀君首聫亦承前章来因今日之不饮而思旧日之传杯也菊花茱萸㸃九日事杜臆传杯不放杯见古人只用一杯诸客传饮唐制九日赐宴及茱茰"],["古注·《杜詩詳註》","刘禹锡曰茱萸二字经三诗人皆已道亦有能否焉杜公言醉把茱茰子细看王右丞徧挿茱萸少一人朱仿学他年少挿茱茰杜公为最优也今按杜公五律亦屡用茱萸此云茱茰赐朝士难得一枝来亦见韵致"],["古评·《瀛奎律髓》","旧与苏司业兼随郑广文采花香泛泛坐客醉纷纷野树歌还倚秋砧醒却闻欢娱两㝠漠西北有孤云老杜九日五言律凡九首今取其四如缀席茱萸好浮舟菡萏衰季秋时欲半九日意兼悲如坐开桑落酒来把菊花枝如旧采黄花賸新梳白髪微皆佳句九日舍萸菊不用则何以成诗容斋随笔言之详矣予谓老杜九日三用茱萸明年此㑹知谁健醉把茱萸子细看此为第一茱萸赐朝士难得一枝来此为第二缀席茱萸好此为第三王维有云遥知兄弟登高处遍揷茱萸少一人亦佳用事同而用意异也奉和圣制重阳节上寿应制王维"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《瀛奎律髓》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/瀛奎律髓_(四庫全書本)）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11781":["九日五首 三","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["旧与苏司业，兼随郑广文。","采花香泛泛，坐客醉纷纷。","野树歌还倚，秋砧醒却闻。","欢娱两冥漠，西北有孤云。"],"",[["古注·《杜詩詳註》","一作簇簇一云漠漠"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11782":["九日五首 四","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["故里樊川菊，登高素滻源。","他时一笑後，今日几人存。","巫峡蟠江路，终南对国门。","系舟身万里，伏枕泪双痕。","爲客裁乌帽，从儿具绿尊。","佳辰对羣盗，愁绝更谁论。"],"",[["古注·《杜詩詳註》","三章思故交也上四叙往日欢娯下四叹今此寂寞客醉承前传盃㝠漠谓苏郑俱亡司业苏源明也广文郑䖍也哀江南赋於时朝野懽娱陆机吊魏武悼繐帐之㝠漠长安在䕫州之西北魏文帝诗西北有浮云陶潜诗有停云章言思念亲友也"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11783":["九日诸人集於林","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["九日明朝是，相要旧俗非。","老翁难早出，贤客幸知归。","旧采黄花賸，新梳白发微。","漫看年少乐，忍泪已沾衣。"],"",[["古注·《杜詩詳註》","此诗梁权道编在大厯元年与九日五首不同时按五首云独酌此题云诸人集知为两嵗重九矣鹤曰诗云九日明朝是则此题应云诸人约九日集于林今按集乃公㑹是他人相约而公先作诗以告之盖因老年难于早出故预道其意也若公为主人不应以难早出缓客至之期又末语漫㸔年少乐句亦非要客之词世説谢安顾谓诸人曰今日可谓彦㑹时既不可留此集固亦难常"],["古注·《杜詩詳註》","上四故乡之思是对集林言下四衰老之感是对诸人言九日之期明朝犹是而相邀之地旧俗已非盖有懐于樊川故里也归谓归集林中采花多前有余兴梳髪稀今苦力衰矣漫看二句乃预言来日事或云九日登髙起於费长房以此日避灾乃旧俗之非或云九日之㑹当不速而至必待相邀方集此旧俗之非後两説与题相反今主王洙之説新梳句暗照孟嘉事"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11784":["大历二年九月三十日","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["爲客无时了，悲秋向夕终。","瘴余夔子国，霜薄楚王宫。","草敌虚岚翠，花禁冷叶红。","年年小摇落，不与故园同。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11785":["十月一日","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["有瘴非全歇，爲冬亦不难。","夜郎溪日暖，白帝峡风寒。","蒸裹如千室，焦糟幸一柈。","兹辰南国重，旧俗自相欢。"],"",[["古注·《杜詩詳註》","一作不亦"],["古注·《杜詩詳註》","上四记风土下四记民俗瘴未全消而忽焉交冬记节𠉀也溪暖犹带瘴峡寒则涉冬矣二句申上意杜臆蒸衷焦糖夔俗如此盖以是日为佳节幸一盘以满盘赠遗为幸自相欢言与客居无与也或云冬而有瘴不亦难乎为冬乃怪叹之词或曰冬初有瘴则过冬不见苦难乃欣幸之词两说俱不如前水经注温水出牂牁夜郎县县故夜郎侯国也朱注唐黔中道黔施珍思等州皆古夜郎地与巴夔接境溪即五溪齐民要术蒸裹方七寸准鼔汁煮秫米生姜橘皮胡芹小蒜盐细切熬糁膏油涂箬十字裹之糁在上复以糁屈牖纂之陆机诗千室非良隣方言云饧谓之糖齐民要术云煑白饧宜缓火火急则焦气饧音呈又四民月令云十月先冰冻作京饧煑暴饴西京杂记曹元礼曰厨中荔枝一柈古月柈字"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11786":["孟冬","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["殊俗还多事，方冬变所爲。","破甘霜落爪，尝稻雪飜匙。","巫峡寒都薄，乌蛮瘴远随。","终然减滩濑，暂喜息蛟螭。"],"",[["古注·《杜詩詳註》","上四冬日人事下四冬日风景在殊俗而犹多事前此课督田园也冬变所为则喜於无事惟破甘尝稻而已霜落言其鲜雪翻形其白寒薄瘴随地气尚暖浪减蛟藏水患方免也䕫子国楚王宫夜郎溪白帝峡与巫峡黔溪连章叠用地名而句法各有变化"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11787":["冬至","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["年年至日长爲客，忽忽穷愁泥杀人。","江上形容吾独老，天边风俗自相亲。","杖蓼雪後临丹壑，鸣玉朝来散紫宸。","心折此时无一寸，路迷何处见三秦。"],"",[["古注·《杜詩詳註》","一作明主"]],{"source":"管遗瑞","body":["杜甫这首《冬至》七律诗，像他的另一首著名的七律《登高》一样，在平仄、对偶上不仅铢两悉称，完全合律，而且本可以不用对偶的首联与尾联也用了工对的形式，显得更加工整而谨严，这在杜诗中是不多见的。但是《冬至》有意安排了首句不入韵，第二句与第七句又基本采用散文的句法，而且“泥杀人”还完全是口语，似乎与凝重的律诗用字不合，这就在谨严之中透出了疏放的气息。另外，“形容”对“风俗”，“雪后”对“朝来”，“心折”对“路迷”等等，乍一看来好像不准确，但他采用借对等修辞手法，仔细推敲却又非常工稳。也就是说，此诗在稳中有不稳，在精严中有疏放，读起来绝没有沉重、板滞的感觉，这在七律中达到了新的境界，是晚年杜甫对七律创作的一个新的贡献。"]},[],["https://github.com/chinese-poetry/chinese-poetry","《全唐诗》（清·曹寅等编，康熙扬州诗局本）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11788":["小至","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["天时人事日相催，冬至阳生春又来。","刺绣五纹添弱线，吹葭六琯动浮灰。","岸容待腊将舒柳，山意冲寒欲放梅。","云物不殊乡国异，教儿且覆掌中杯。"],"唐㑹要开元八年中书门下奏开元新格冬至日祀圆丘遂用小冬日视朝按小冬日即小至也谓至前一日犹小寒食之义",[["古注·《御选唐诗》","唐㑹要开元八年中书门下奏开元新格冬至日祀圆丘遂用小冬日视朝按小冬日即小至也谓至前一日犹小寒食之义"],["古注·《御选唐诗》","易後天而奉天时荀子上得天时下得地利国语人事不起勿为之始尉缭子天官时日不若人事也史记自序春秋上明三王之道下辨人事之纪陶潜诗野外罕人事张説诗共知人事何尝定且喜年华去复来苏味道诗玉漏莫相催"],["古注·《御选唐诗》","礼记仲冬之月日短至左传日南至注自秋分日行南陆至冬至之日日南极史记律书日冬至则一隂下蔵一阳上舒易七日来复疏五月一隂生十一月一阳生孝经説斗指子为冬至阳气始生武平一诗东郊上苑望春来"],["古注·《御选唐诗》","周礼五采备谓之绣注此刺绣采所用也又绣以为裳者谓刺绣於裳史记货殖传刺绣文不如倚市门嵗时记晋魏间宫中以红线量日影冬至後日添长一线唐杂録唐宫中以女功揆日之长短冬至後日晷渐长比常日増一线之功"],["古注·《御选唐诗》","扬子调律者度竹为管芦莩为灰列之九闭之中漠然无动寂然无声微风不起纎尘不形冬至夜半黄钟以应後汉书律厯志候气之法为室三重户闭涂衅周宻布缇缦室中以木为案毎律各一内庳外髙従其方位加律其上以葭莩灰抑其两端案律而候之气至者灰去其为气所动者其灰散人及风所动者其灰聚嵗华纪丽舜为玉琯以定律吕唐太宗守嵗诗四时运灰琯一夕变冬春刘允济天赋托璇枢之妙术应玉琯之浮灰萧慤诗缇室已飞灰"],["古注·《御选唐诗》","梁简文帝诗岸栁垂长叶史记秦纪恵文君十二年初腊注十二月腊日也晋童谣二月尽三月初华生襄藩柳叶舒傅休奕柳赋长茎舒而増茂兮"],["古注·《御选唐诗》","谢朓诗苍翠望寒山萧慤诗山寒石道冻梁简文帝梅花赋怜早花之惊节讶春光之遣寒马懐素诗就暖风光偏着柳辞寒雪影半蔵梅"],["古注·《御选唐诗》","周礼保章氏以五云之物辨吉凶水旱降丰荒之祲象左传凡分至启闭必书云物孔融书观象云物察应寒温晋书王导传过江人士每至暇日相要出新亭饮宴周顗中坐而叹曰风景不殊举日有河山之异王勃春思赋盛年眇眇辞乡国"],["古注·《御选唐诗》","广韵覆倒也杜审言诗兴尽闻壶覆鲍照诗临流竞覆杯陈後主诗极眺且倾杯"],["古注·《杜詩詳註》","鹤注诗云舒柳放梅当是大厯元年作是年冬煖故云唐㑹要开元八年中书门下奏开元新格冬至日祀圜丘遂用小至日视朝相传小至为冬至前一日据㑹要小至是第二日杜臆若以小至为冬至前一日则诗不当云添线动灰矣薛梦符谓阳大隂小冬至隂极故曰小至此説亦非冬至一阳初生不当取隂小之义"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《御选唐诗》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/御選唐詩_(四庫全書本)）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11789":["览物","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["曾爲掾吏趋三辅，忆在潼关诗兴多。","巫峡忽如瞻华岳，蜀江犹似见黄河。","舟中得病移衾枕，洞口经春长薜萝。","形胜有余风土恶，几时回首一高歌。"],"",[["古注·《杜詩詳註》","此公在峡而思乡也上四追忆华州下四峡中有感向贬司功而诗兴偏多以华岳黄河足引壮思也今峡江相似而卧病经春无复前此兴㑹矣葢此间形胜虽佳风土殊恶几时得回首北归仍动长歌之兴乎题曰览物指山水言舟中承江洞口承峡形胜在此风土亦在此移衾枕舍舟登岸也赵曰公曾为华州司功故曰掾吏三辅京兆扶风冯翊也华属扶风希曰潼闗在华阴县即桃林之塞华岳在其地黄河亦经华而东庾信枯树赋横洞口而倾卧谢灵运诗想见山阿人薜萝若在眼陈允锡注洞口五溪之口风谓其俗杂夷土谓其地多瘴後汉唐羌疏南州土恶"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11790":["忆郑南玭","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["郑南伏毒寺，潇洒到江心。","石影衔珠阁，泉声带玉琴。","风杉曾曙倚，云峤忆春临。","万里沧浪外，龙蛇只自深。"],"玭音泚玉色也言石似玉公忆之而赋",[["古评·《唐诗品汇》","玭音泚玉色也言石似玉公忆之而赋"],["古注·《杜詩詳註》","梁氏编在大厯元年朱注旧作忆郑南玭玭浦眠切珠名吴若注玭疑作玼音泚玉色鲜洁也按郑南华州郑县之南详诗意只是忆郑南寺旧游耳赵云师民瞻削去玭字草堂本作忆郑南"],["古注·《杜詩詳註》","旧作守赵定作寺"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗品彚（附唐诗拾遗）》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩品彚_(四庫全書本)）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11791":["怀灞上游","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["怅望东陵道，平生灞上游。","春浓停野骑，夜宿敞云楼。","离别人谁在，经过老自休。","眼前今古意，江汉一归舟。"],"",[["古注·《杜詩詳註》","黄鹤编在大厯二年以诗有江汉归舟句也楚汉春秋汉高帝西入武关居灞上"],["古注·《杜詩詳註》","旧作宿敞"],["古注·《杜詩詳註》","上四忆旧游景事下则念同游而动归思也昼停骑夜宿楼极尽一时游兴唯聚散无常故有古今之慨夜宿对春浓不工当云夜敞宿云栖顾注东陵道即长安城东门乃秦东陵侯种𤓰处杜臆唐都关中即今西安城东三十里有灞水又东乃文帝霸陵出长安东门为东陵道得名以此灞水桥曰灞桥乃长安饯别之所灞上当即在其处详诗意则行乐之地也杨炯少室山庙碑璇宫夜敞银牓朝开隋辛徳源诗戏笑上云楼"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11792":["愁","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["江草日日唤愁生，巫峡泠泠非世情。","盘涡鹭浴底心性，独树花发自分明。","十年戎马暗万国，异域宾客老孤城。","渭水秦山得见否，人经罢病虎纵横。"],"",[["古注·《杜詩詳註》","原注强戏为呉体黄生注皮陆集中亦有呉体诗乃当时俚俗为此体耳诗流不屑效之杜公篇什既衆时出变调凡集中拗律皆属此体偶发例於此曰戏者明其非正律也杜臆胸有抑郁不平之气而以拗体发之公之拗体诗大都如是翫诗意当是大厯二年春夔州作"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11793":["昼梦","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["二月饶睡昏昏然，不独夜短昼分眠。","桃花气暖眼自醉，春渚日落梦相牵。","故乡门巷荆棘底，中原君臣豺虎边。","安得务农息战鬬，普天无吏横索钱。"],"",[["古注·《杜詩詳註》","顾注大厯元年暮春公至夔州此诗作於次年二月呉越春秋呉王过姑胥之台忽然昼梦"]],{"source":"田耕宇","body":["“二月饶睡”四句，解释昼寝入梦的缘由。冬至以后，日影渐长，黑夜日短，二月桃花盛开，蜂蝶成群，暖气洋洋，催人昏昏欲睡。金圣叹说：“‘不独’二字，一直注到‘眼自醉’‘梦相牵’，此是何等笔力，亦何等章法！言眼自醉耳，非我欲睡也；梦相牵耳，非我欲睡也……世人皆醉，我何独醒？世人皆梦，我何不梦”？（《杜诗解》）他看到“不独”二字所蕴含的部分意义，颇有识见。然而“不独”二字，还有深意在，不管诗人怎样解释昼寝的理由，但前四句诗只说明一个问题，即诗人神思倦怠。造成这种倦怠的原因固然很多，而最根本的原因就是积思劳神、操心焦虑。杜甫平生忧念家国，身值乱离，优思更深，“自经丧乱少睡眠，长夜沾湿何由彻”（《茅屋为秋风所破歌》），“不眠忧战伐，无力正乾坤”（《宿江边阁》），即便是耿耿长夜，亦难以入睡，何况“夜短”。夜既不能寐，加之贫病缠身，体力不支，白日里疲乏也就在情理之中。诗人不说自己如何关怀时事，积劳成疾，反说自己如宰予一样碌碌无为，白日深睡，更推口言“桃花气暖眼自醉”。但“不独”二字，却深婉曲折地透露了诗人忧劳积思的心态。人云杜甫“平生无饱饭，抵死只忧时”（元马祖常《石田集杂咏》），正因为如此，方才有昼寝之事。这样，“不独”二字，就为下面记梦暗中留下伏笔。","“故乡门巷荆棘底，中原君臣豺虎边”，记梦中所见，以梦的形式，表现了诗人的家国之思。梦是人的潜意识作用，俗云“日有所思，夜有所梦”，白日成梦，可见思情之深。这两句所写梦境，荒凉萧瑟，情势险恶，与前四句所写春景看似不太协调，但却真实地将诗人晚年心境刻画出来。自乾元二年（759）诗人“支离东北风尘际，漂泊西南天地间”（《咏怀古迹五首》其一），此时不觉已近十年，这期间朝廷万方多难，诗人“亲朋无一字”（《登岳阳楼》），国仇家恨使他魂牵梦萦。一合上眼，诗人仿佛回到故园，自安史乱军掠夺烧杀后，那里已是荒凉冷落，加之回纥、吐蕃屡次出兵，战火烧残了村庄，蒿草丛生，荆棘遍地，墙头门前除去栖鸦野狐，更无人迹。故国君臣前门拒狼，后门遇虎，唐王朝面临着种种困扰。这两句诗，用一“底”一“边”字，将国家的危难、社会的灾难刻画得淋漓尽致，又一次抒发了诗人“感时花溅泪，恨别鸟惊心”（《春望》）乱离伤痛的悲哀。","“安得务农息战斗，普天无吏横索钱”，这两句是梦醒后的议论，它紧承梦境写来，中原君臣处在虎狼之中，故国门巷为荆棘所蔽，国事凋零，民生多艰，唐王朝向何处去？诗人认为只有尽快结束战争，让农民回到土地上去安居乐业，普天之下没有骄横的官吏横征暴敛，唐王朝才会恢复“煌煌太宗业”（《北征》）。结尾两句诗，充满了诗人对战争的厌恶、对贪官污吏的憎恨、对人民的无限同情，以及对清明政治的向往。沉痛中渗透着希望。","此诗题为“昼梦”，前四句写昼梦之由，笔触浓丽，所写春景暖气融融，五、六句记梦中所见，刻画环境惨淡险恶，末二句就“昼梦”所见发表议论，写得沉痛至极。全诗前后所写虽有景物气氛的不同，但丽景的描写，是为写心境愁惨服务的，春光可喜，但值故乡荆棘、中原豺虎、兵燹遍地、横吏索钱之时，世界昏昏，喜从何来！故贯穿全诗的感情是悲哀沉重的。诗人巧妙地借说“昼梦”，将自己晚年忧国思家的强烈感情抒发出来，于自然流转中凝聚深厚的意绪，很能表现杜甫晚年诗风沉郁苍茫的特色。"]},[],["https://github.com/chinese-poetry/chinese-poetry","《全唐诗》（清·曹寅等编，康熙扬州诗局本）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11794":["览镜呈柏中丞","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["渭水流关内，终南在日边。","胆销豺虎窟，泪入犬羊天。","起晚堪从事，行迟更学仙。","镜中衰谢色，万一故人怜。"],"",[["古注·《杜詩詳註》","鹤注栢中丞大厯元年为䕫州都督公以是年至䕫尝为栢作谢上表谢灵运诗览镜睨頺容"],["古注·《杜詩詳註》","上四廻忆长安叹乱不可归下则自伤衰老而有望於中丞也胆销泪入起晚行迟皆衰谢之状从览镜而思及之豺虎犬羊京师为盗侵蕃陷也或指蜀中叛将松州吐蕃於上二句不接赵注凢仕者必早起起晚矣尚堪从事乎仙者必轻歩行迟矣更可学仙乎杜臆公与中丞素厚故末二自陈苦衷非乞怜语西都赋帯以洪河泾渭之川表以泰华终南之山渭水在长安北五十里南山在长安南五十里史记高"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11795":["即事","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["暮春三月巫峡长，皛皛行云浮日光。","雷声忽送千峰雨，花气浑如百和香。","黄莺过水飜回去，燕子衔泥湿不妨。","飞阁卷帘图画里，虚无只少对潇湘。"],"後四语似楚歌越吟当是遣愁漫兴所为",[["古评·《唐诗镜》","後四语似楚歌越吟当是遣愁漫兴所为"],["古注·《御选唐诗》","梁元帝纂要三月季春亦曰暮春末春晚春邱迟与陈伯之书暮春三月江南草长荆州记渔者歌曰巴东三峡巫峡长一统志巫峡在巫山县东三十里与西陵峡归乡峡并称三峡"],["古注·《御选唐诗》","说文皛胡了切显也陶潜诗皛皛川上平陆云南征赋若溟海之引回流岱灵之吐行云何逊诗水底见行云天边㸔逺树刘桢遂志赋荣日华以舒光阴铿诗映日动浮光唐太宗诗拂潮云布色穿浪日舒光"],["古注·《御选唐诗》","易天地解而雷雨作又雷雨之动满盈礼记月令是月也日夜分雷乃发声说文雷霆余声铃铃所以挺出万物也史记龟策传风雨送之流水行之梁简文帝诗百岭相迂蔽千峯共隐天卢照隣诗惊涛乱水脉骤雨暗峯文"],["古注·《御选唐诗》","陈子良诗花气近薫衣汉武内传七月七日设座殿上以紫罗荐地燔百和之香古乐府博山炉中百和香欝金苏合及都梁"],["古注·《御选唐诗》","诗黄鸟于飞又有莺其羽义疏黄鸟鹂鶹也或谓之黄栗留一名仓庚齐人谓之抟𥞫谢偃诗黄莺始哢即娇人谢朓诗地逈翻旗廽邹阳赋龙盘鸟廽凤去鸾归谢灵运诗风来不可托鸟去岂为聴"],["古注·《御选唐诗》","尔雅燕燕乙也陶隐居本草紫胸轻小者是越燕胸斑黑声大是胡燕薛道衡诗空梁落燕泥古诗思为双飞燕衔泥巢君屋夏侯湛赋衔泥构巢营居传桷"],["古注·《御选唐诗》","崔駰七依丹柱雕楹飞阁层楼东京赋飞阁神行莫我能形刘孝绰诗虹霓拖飞阁古乐府巻帘天自髙海水揺空绿梁简文帝诗正衣还向镜迎春试巻帘庾信文玉门亭障无劳图画"],["古注·《御选唐诗》","後汉书乗飈忽兮驰虚无司马相如赋乗虚无与神俱曹植诗朝逰江北岸夕宿潇湘沚谢朓诗洞庭张乐地潇湘帝子逰"],["古注·《杜詩詳註》","黄鹤编在大厯二年诗云卷帘飞阁知是在西阁时作"],["古注·《杜詩詳註》","此诗峡中对景而作上六春景所谓即事末乃自道出峡之意云浮日光而过其色皛皛然雷雨将作矣乍雨忽晴香气扑人莺来燕往物各适情卷帘一望真如图画但以久卧峡中故思江湖之映空耳莺畏雨故翻回燕乗雨故衔泥飞阁即西阁虚无空旷貌丘迟与陈伯之书暮春三月江南草长荆州记巴东三峡巫峡长陶潜诗皛皛川上平隂铿诗映日动浮光陈子良诗花气近薰衣邵注汉武帝时月支国进百和香"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗镜》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩鏡_(四庫全書本)）","古籍注评：《御选唐诗》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/御選唐詩_(四庫全書本)）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11796":["即事","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["天畔羣山孤草亭，江中风浪雨冥冥。","一双白鱼不受钓，三寸黄甘犹自青。","多病马卿无日起，穷途阮籍几时醒。","未闻细柳散金甲，肠断秦川流浊泾。"],"",[["古注·《杜詩詳註》","鹤注此亦大厯二年秋作也"],["古注·《杜詩詳註》","一作州非"],["古注·《杜詩詳註》","朱瀚曰此即孤亭风雨而发长铗之叹上四景物下四感怀起聫言客居之萧瑟白鱼承江黄甘承山不钓犹青言食味艰难也多病穷途而当秦地用兵则归京无日所以肠断耳黄生注羇旅贫病公尝频言此又借古人以自况瀚曰天畔秦川首尾照应顾注草亭瀼西草堂也西京杂记随船风浪莫知所之楚辞雷塡塡兮雨"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11797":["闷","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["瘴疠浮三蜀，风云暗百蛮。","卷帘唯白水，隐几亦青山。","猨捷长难见，鸥轻故不还。","无钱从滞客，有镜巧催颜。"],"",[["古注·《杜詩詳註》","姑依旧次列在大厯二年"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11798":["戏作俳谐体遣闷二首 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["异俗吁可怪，斯人难竝居。","家家养乌鬼，顿顿食黄鱼。","旧识能爲态，新知已暗疎。","治生且耕凿，只有不关渠。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11799":["戏作俳谐体遣闷二首 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["西历青羌板，南留白帝城。","於菟侵客恨，粔籹作人情。","瓦卜传神语，畲田费火声。","是非何处定，高枕笑浮生。"],"",[["古注·《杜詩詳註》","同都切一作榖於"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11800":["得舍弟观书自中都已达江陵今兹暮春月末行李合到夔州悲喜相兼团圆可待赋诗即事情见乎词","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["尔到江陵府，何时到峡州？","乱难生有别，聚集病应瘳。","飒飒开啼眼，朝朝上水楼。","老身须付托，白骨更何忧。"],"",[["古注·《杜詩詳註》","此章冩离合悲喜之情语根至性江陵峡州照题叙清生别是悲聚集是喜闲眼登楼将到则可喜付托何忧既到则免悲矣诗乱离瘼矣王融诗春尽风飒飒"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11801":["喜观即到复题短篇二首 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["巫峡千山暗，终南万里春。","病中吾见弟，书到汝爲人。","意荅儿童问，来经战伐新。","泊船悲喜後，款款话归秦。"],"",[["古注·《杜詩詳註》","此与上章乃先後同时作"]],{"source":"刘友竹","body":["三、四句各自与一、二句相应承。乌鹊尚在枝间，这是一喜；我们兄弟就像鹊鸽在原一样，都曾身处困境之中，这是一悲。诗人接读来书后悲喜相兼的感情波澜久久不能平静。但他抒发感情并不是平铺直叙，而是通过乌鹊、鹡鸰这样的具体形象以及这些形象所蕴含的丰富内涵委婉地表达出来的，这就增加了作品的艺术感染力。同时，这种隔句应承的表现手法也使行文有串珠双垂之美，笙箫合奏之妙。","诗人盼望观弟早日到来，曾经“朝朝上水楼”。此诗又有深入一层的描写：“江阁嫌津柳。”登上江边楼阁，希望快点看到观弟来船的帆影，但令人讨厌的是柳荫遮住了视线。春风杨柳，本是美好的形象，但这时却成了讨人嫌的东西。这进一步反衬出诗人渴盼兄弟团聚的强烈感情。《三国演义》描写刘备送徐庶，嫌树林碍眼，下令把树林砍掉。其表现手法也当是从此类描写中化出。“风帆数驿亭”，旧注多不得其解。明末清初的仇兆鳌云：“嫌津柳，遮眼不见；数驿亭，来程可计。即前章‘朝朝上水楼’也。”（《杜诗详注》）明代的王嗣奭云：“‘江阁’‘风帆’二句，总是急望其至，而较前‘朝朝上水楼’，光景又别。”（《杜臆》）他们把“嫌津柳”“数驿亭”都解作杜甫的行为，这是由于没有弄清楚这两句被省略的主语所代表的客体是不同的。按，“风帆”，是杜观所乘之船；“数驿亭”，是杜观的行为。这两句，前一句是实写，后一句是悬揣。诗人发挥了丰富的想象力，弟之盼兄，亦当如兄之盼弟。我在这里嫌津柳之密，量他亦在来船上嫌驿亭之多也。这种悬揣法诗人在其他篇章中也使用过。如《春日忆李白》：“渭北春天树，江东日暮云。”是说自己在渭北怀念李白，李白也一定在江东怀念自己。清人黄生云：“五句寓言己忆彼，六句悬度彼忆己。”（《杜诗说》）这样就能把诗人的感情表现得更加强烈，更加深沉。","“应论十年事，愁绝始星星。”“愁绝”亦作“撚绝”，“星星”亦作“惶惺”。对末联的诠释历来众说纷纭，莫衷一是。按，“愁绝”，谓愁得要命；“星星”，指稀疏的白发，谢灵运诗：“星星白发垂。”细揣诗意这两句是预想兄弟会面之后，详细叙谈十年来颠沛流离的苦楚，当年正是由于愁得要命，头发才开始白起来的。诗人稍后作《第五弟丰独在江左，近三四载寂无消息，觅使寄此二首》云：“十年朝夕泪，衣袖不曾干。”衣袖常湿，正是愁得要命的意思。这两处可以互相印证。","这两首五言律诗，格律精绝，技巧纯熟，经验达于老成，笔法臻于化境。“晚节渐于诗律细”（《遣闷戏呈路十九曹长》），正是指的这种境界。后人不仅尊之为“诗圣”，而且称之为“情圣”。这两首诗所抒发的感情之真挚，爱心之炽烈，是十分突出的，所以清人杨伦云：“诸怀弟诗情事切至，总有一片真气流注其间，便觉首首都绝。”（《杜诗镜铨》）"]},[],["https://github.com/chinese-poetry/chinese-poetry","《全唐诗》（清·曹寅等编，康熙扬州诗局本）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11802":["喜观即到复题短篇二首 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["待尔嗔乌鹊，抛书示鶺鴒。","枝间喜不去，原上急曾经。","江阁嫌津柳，风帆数驿亭。","应论十年事，愁绝始星星。"],"",[["古注·《杜詩詳註》","此章亦兼悲喜意首二是悲三四是喜五六喜中之悲七八悲後之喜千山迷暗公不见弟万里春行弟在途中也病中见弟书到知其身尚无恙乃十字为句战伐新经答以书中之意此亦十字句法黄生注开书之时其子在傍询叔动定且答且读兄弟叔侄之情俱见泊船巫峡归秦终南按谭元春云书到汝为人即妻孥怪我在意以下句来经战伐证之良是杜臆谓书到而如对其人是题中即到语意亦通汉书梁孝王传书到明以谊晓主神仙传蓟子训随主人意答乃不同也卢注是年郭子仪讨周智光命大将浑臧李懐光军渭上是来经战伐新也淮南子悲喜转而相生任昉诗何因送欵欵半饮杯中渌"],["古注·《杜詩詳註》","黄生曰杜诗有两句断续看者两京三十口虽在命如经上七字连説下三字另住病中见吾弟书到汝为人亦然"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11803":["舍弟观归蓝田迎新妇送示两篇 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["汝去迎妻子，高秋念却回。","即今萤已乱，好与雁同来。","东望西江水，南游北户开。","卜居期静处，会有故人杯。"],"",[["古注·《杜詩詳註》","此当是大厯二年夏作杜臆题云送示送弟北归示之以意也前有得舍弟观书喜观即到诸诗盖观既到䕫州复归蓝田迎妇也"],["古注·《杜詩詳註》","旧作水赵定作永"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11804":["舍弟观归蓝田迎新妇送示两篇 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["楚塞难爲路，蓝田莫滞留。","衣裳判白露，鞍马信清秋。","满峡重江水，开帆八月舟。","此时同一醉，应在仲宣楼。"],"",[["古注·《杜詩詳註》","普宫切正作拌"],["古注·《杜詩詳註》","此亦送别而望其早回难为路惜其逺去莫滞留嘱其早回衣裳鞍马弟从陆路而来江满帆开公从水程而徃醉饮楼前期相㑹於江陵也楚塞即䕫州峡险则路难行判是𢬵着之意信是任他之意公诗春风自信牙樯动此信字正同江淹诗奉诏至江汉始知楚塞长王粲诗白露沾衣襟顾注重江如北江中江大江之水皆自峡而下鲍照芜城赋重江复关之隩赵注王粲在荆州作赋故後"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11805":["第五弟丰独在江左近三四载寂无消息觅使寄此二首 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["乱後嗟吾在，羇栖见汝难。","草黄骐骥病，沙晚鶺鴒寒。","楚设关城险，吴吞水府宽。","十年朝夕泪，衣袖不曾乾。"],"",[["古注·《杜詩詳註》","鹤注诗云十年朝夕泪自天寳十五载避乱与诸弟相别至大厯元年为十年当是其时作"],["古注·《杜詩詳註》","一作晓一作暖"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11806":["第五弟丰独在江左近三四载寂无消息觅使寄此二首 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["闻汝依山寺，杭州定越州。","风尘淹别日，江汉失清秋。","影盖啼猨树，魂飘结蜃楼。","明年下春水，东尽白云求。"],"",[["古注·《杜詩詳註》","音干此章兄弟别离而致相思之意草黄句承乱後自怜贫老沙晚句承羇栖伤弟飘零闗城险巳不能往水府寛弟不可知故乆别悲哀而涕泪常流也顾注诗云十年而题曰三四载盖相别者十年无消息者三四载耳䕫峡最险如设闗城三江震泽水府甚寛孔融论马之骏者名曰骐骥枚乗传深壁髙垒副以闗城史记蜀伐楚楚为扞闗以距之後汉郡国志巴郡鱼复县有扞闗海赋尔其水府之内极深之庭"],["古注·《杜詩詳註》","一作共非"],["古注·《杜詩詳註》","一作游次章念弟逺离而致欲访之意首聨弟在江左次聨身在䕫州五六客䕫而想江左七八去䕫而寻江左也邵注定越州言不在杭州定在越州风尘指兵戈杜臆失清秋谓淹别之乆又蹉过一秋矣赵汸注尽宇正应定字惟传闻莫定故须尽歴云水以求之顾注古人望白云而思亲公於手足之谊亦然唐书杭州余杭郡越州㑹稽郡俱属江南西道邵注杭州即今浙江省治越州今为绍兴府在杭州东二百里何逊诗凄清江汉秋卢照隣巫山髙诗莫辨啼猿树史天官书海旁蜃气象楼台广野气成宫阙陈蔵器本草车螯是大蛤一名蜃能吐气为楼台海中春夏间依约岛漵常有此气"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11807":["舍弟观赴蓝田取妻子到江陵喜寄三首 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["汝迎妻子达荆州，消息真传解我忧。","鸿雁影来连峡内，鶺鴒飞急到沙头。","嶢关险路今虚远，禹凿寒江正稳流。","朱绂即当随彩鷁，青春不假报黄牛。"],"",[["古注·《杜詩詳註》","鹤注此当是大厯二年冬作邵注天宝初荆州为江陵"],["古注·《杜詩詳註》","首章弟到江陵而喜下半叙欲往之志鸿雁影来承消息句鶺鴒飞急承荆州句弟到沙头则嶢关不见其逺矣身在寒江则穏流正可出峡矣从此乗舟东下无烦报书峡中也衣朱绂而乗彩鷁兄弟骨肉须作此慰劳语不嫌侈张也此诗末二句与即从巴峡穿巫峡便下襄阳向洛阳语意相似但彼诗语势轩豁此将朱彩青黄作对不免拙滞矣礼记雁行比先後有序毛诗鶺鴒比急难相须故以二鸟喻兄弟古诗兄弟雁行序方舆胜覧沙头市去江陵十五里嶢闗即蓝田闗从蓝田迎妻子必经嶢闗之险嶢音尧故与禹作借对汉髙帝纪秦王子婴遣将将兵据嶢闗嶢闗在上洛北蓝田南武闗之西长安志杜氏通典曰七盘十二䋫蓝田之险路也䋫坡在县东南庾信诗春江下白帝画舸向黄牛"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11808":["舍弟观赴蓝田取妻子到江陵喜寄三首 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["马度秦关雪正深，北来肌骨苦寒侵。","他乡就我生春色，故国移居见客心。","賸欲提携如意舞，喜多行坐白头吟。","巡檐索共梅花笑，冷蘂疎枝半不禁。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11809":["舍弟观赴蓝田取妻子到江陵喜寄三首 三","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["庾信罗含俱有宅，春来秋去作谁家。","短墙若在从残草，乔木如存可假花。","卜筑应同蒋诩径，爲园须似邵平瓜。","比年病酒开涓滴，弟劝兄酬何怨嗟。"],"",[["古评·《唐诗镜》","闲中托契"],["古注·《杜詩詳註》","平声次章悯弟逺来之情下半写喜慰之意卢世㴶曰他乡就我故国移居还题明净而意更温深欢剧喜多尚与弟相隔许程於是步绕檐楹索梅花共笑此时梅花半开即冷蘂疎枝亦若笑不能禁矣説得无情有情极迂极切他乡指江陵故国指蓝田弟在客途故云客心世说王戎好作如意舞朱瀚曰孔徳绍夜宿荒村诗劳歌欲叙意终是白头吟袁朗秋夜独坐诗如何悲此曲坐作白头吟六朝人皆通用不必专属文君炀帝幸江都诗鸟声争劝酒梅花笑杀人索笑句本此"],["古注·《杜詩詳註》","黄生曰浣花溪里花饶笑肯信吾兼吏隠名言其不信已衷巡檐索共梅花笑冷蘂疎枝半不禁言其善㑹人意此严沧浪所谓诗有别趣非闗理也"],["古注·《杜詩詳註》","三章谋卜居江陵下半喜同室聚首也庾罗旧宅久厯春秋未知今属谁家倘故宅犹存虽一草一木亦不忍伤也若须别为营构亦当开蒋经以延客学邵𤓰而治生兄弟劝酬乃豫道新居乐事庾信罗含就江陵而言蒋诩邵平本长安人物公以故里先贤偶忆及之非谓欲卜居长安也黄生曰此借先贤旧宅以寓意乃见诗肠之曲诗趣之灵庾信因侯景之乱自建康遁归江陵居宋玉故宅宅在城北三里罗含为桓温别驾於江陵城西三里小洲上立茅屋而居布衣蔬食宴如也从任从也蒋诩舍前竹下开三径惟求仲羊仲从之游为兖州刺史及王莽居摄以病免归田里邵平瓜注见四巻王制比年一小聘卢世㴶曰三诗句句是喜句句是寄若竟像对面浃洽语便不是寄矣朱瀚曰一首云解我忧二首云欢剧喜多三首云何怨嗟顾题中喜寄二字次第天然"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗镜》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩鏡_(四庫全書本)）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11810":["江雨有怀郑典设","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["春雨闇闇塞峡中，早晚来自楚王宫。","乱波分披已打岸，弱云狼籍不禁风。","宠光蕙叶与多碧，点注桃花舒小红。","谷口子真正忆汝，岸高瀼滑限西东。"],"",[["古注·《杜詩詳註》","鹤注此当是大厯二年瀼西作唐书东宫官有典设郎四人"],["古注·《杜詩詳註》","音色晋作发"],["古注·《杜詩詳註》","上四江上雨景下四对景懐郑楚王宫用神女云雨事波撼云飞未雨而狂风先发患碧桃红经雨而花木争妍不禁不能耐风也洞箫赋若凯风纷披张华诗僵禽正狼藉诗为龙为光注龙宠也易林嘉乐君子为国宠光古赋天雨之施恵於蕙叶梁元帝诗雨罢禁生光锺㑹孔雀赋五色㸃注华羽参差沈约诗桃枝红若㸃紫桃杂组曰宠光㸃注唐诗有此二语施之官职选授间则宠光乃特恩之意㸃注乃注授之意顾注此诗宠光㸃注加之蕙叶桃花见雨露之恩蕙桃独沾也公自赤甲迁居瀼西则郑必居瀼东矣"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11811":["王十五前阁会","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["楚岸收新雨，春台引细风。","情人来石上，鲜脍出江中。","邻舍烦书札，肩舆强老翁。","病身虚俊味，何幸饫儿童。"],"",[["古注·《杜詩詳註》","黄鹤编在大厯二年春以诗有楚岸春台句也前有送王十五扶侍诗"],["古注·《杜詩詳註》","上二前阁春景三四王君宴㑹下序始终欵曲之情杜臆以隣舍而致札迎舆见其殷勤又且饫及儿童见札中并招其子邵注䕫州古楚地故云楚岸此指阁下石台陆云诗遣情春台托荫寒水鲍照诗留酌待情人七发鲜鲤之鱠世説王献之乗平肩舆径入顾辟疆园陆云答车安茂书东海之俊味肴膳之至妙"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11812":["寄韦有夏郎中","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["省郎忧病士，书信有柴胡。","饮子频通汗，怀君想报珠。","亲知天畔少，药味峡中无。","归楫生衣卧，春鸥洗翅呼。","犹闻上急水，早作取平途。","万里皇华使，爲僚记腐儒。"],"",[["古注·《杜詩詳註》","黄鹤编在大厯元年䕫州诗内潘淳曰顔鲁公东方朔碑阴有朝城主簿韦有夏殆斯人耶"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11813":["陪柏中丞观宴将士二首 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["极乐三军士，谁知百战场。","无私齐绮馔，久坐密金章。","醉客沾鹦鹉，佳人指凤皇。","几时来翠节，特地引红妆。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11814":["陪柏中丞观宴将士二首 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["绣段装檐额，金花帖鼓腰。","一夫先舞劒，百战後歌樵。","江树城孤远，云台使寂寥。","汉朝频选将，应拜霍嫖姚。"],"",[["古注·《杜詩詳註》","次章言堂下事复称美中丞绣叚金花器物之华舞剑歌樵声乐之盛江城使寂慨其目前将拜嫖姚望其将来装檐额即今人宴㑹结彩於檐之类江淹丽色赋铢金花於珠履古辞鼓腰铃椑各相竞庾信诗□花钉鼓床陈琳与魏文帝书一夫挥㦸项羽纪军中无以为乐请以舞剑古诗百戏起鱼龙赵曰歌樵戏作䕫峡樵歌公诗云夷歌负樵客杜臆樵歌乃䕫俗歌名如巴渝歌之类别作歌鐎谓军中击刁斗以歌未然云台使䇿功之使臣也汉霍去病为嫖姚校尉後拜骠骑大将军"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11815":["七月一日题终明府水楼二首 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["高栋曾轩已自凉，秋风此日洒衣裳。","翛然欲下阴山雪，不去非无汉署香。","绝辟过云开锦绣，疎松夹水奏笙簧。","看君宜着王乔履，真赐还疑出尚方。"],"",[["古注·《杜詩詳註》","鹤注此当是䕫州作故云楚江巫峡半云雨终明府当是奉节宰故云为政风流今在兹按杜诗凡称月称日者皆指节候言此七月一日乃立秋之日故曰秋风此日洒衣裳後有诗题大厯二年九月三十日而诗云悲秋向夕终则恰好秋尽矣"],["古注·《杜詩詳註》","此章从水楼説起结终明府首切水楼次贴初秋楼高风飒如此翛然疑下隂山之雪今对之不忍舍去非为无郎署而留此正以壁开锦绣松奏笙簧楼上见闻絶胜故耳终在此间去仙何逺故遂以王乔此之且望其即真也张华诗穆如洒清风洙曰隂山匈奴山名吐谷浑西附隂山其地四时常有冰雪虽六七月雨雹甚盛广志代郡隂山五月犹宿雪又曰尚书郎汉置四人口衔鸡舌香以奏事答对欲使气息芬芳谢灵运诗晨策寻絶壁刘绘诗交错锦啸陈诗吹笙皷簧王乔履见四巻原注终明府功曹也兼摄奉节令故有此句尹翁归传满岁为真孝平帝纪吏在二百石以上一切满秩如真如淳曰诸官吏初除皆试守一岁乃为真食之俸汉百官公卿表少府属官一曰尚方师古曰尚方主作禁器物"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11816":["七月一日题终明府水楼二首 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["宓子弹琴邑宰日，终军弃繻英妙时。","承家节操尚不泯，爲政风流今在兹。","可怜宾客尽倾盖，何处老翁来赋诗。","楚江巫峡半云雨，清簟疎帘看弈棊。"],"",[["古注·《杜詩詳註》","音伏旧作宓误宓音宻"],["古评·《诗人玉屑》","其用事若，虽字字皆本出处，然比……，虽无出处一字，而语意自到"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）","古籍注评：《诗人玉屑》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/詩人玉屑_(四庫全書本)）"]],"open_11817":["季秋苏五弟缨江楼夜宴崔十三评事韦少府侄三首 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["峡险江惊急，楼高月迥明。","一时今夕会，万里故乡情。","星落黄姑渚，秋辞白帝城。","老人因酒病，坚坐看君倾。"],"",[["古注·《杜詩詳註》","鹤注编在大厯二年"],["古注·《杜詩詳註》","黄注一二江楼五六季秋三四兼叙賔主七八専述已意此虚实相间格也一时今夕㑹万里故乡情能将同㑹賔主括在两句之中夜将尽故星落秋将谢故云辞顾注已不能饮而待人饮老人恋恋故乡之情也荆楚岁时记黄姑即河鼔方以智通雅黄姑当为河鼔见天官书说文引河鼔是荷负也故俗名担鼔星古乐府东飞伯劳歌黄姑织女时相见杜诗用星落黄姑渚盖因河鼔音近而讹为黄姑耳尔稚河皷谓之牵牛博议遂以黄姑为牛宿之异名恐非杜臆黄姑渚即天河季秋昏定天河没而星亦俱落矣伪苏注所引忠州黄恵女事本属妄撰近㑹粹又托为十道志更谬"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11818":["季秋苏五弟缨江楼夜宴崔十三评事韦少府侄三首 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["明月生长好，浮云薄渐遮。","悠悠照边塞，悄悄忆京华。","清动杯中物，高随海上查。","不眠瞻白兔，百过落乌纱。"],"",[["古注·《杜詩詳註》","户江切此承上坚坐看君倾江月既可寻欢歌舞又堪发兴此时添酒对鸥诸君正宜取醉也公以病酒断饮故曰心降旧编误在末今移作次章为当那无酒言何尝无酒笑舞见舞而笑拓秋窻观月色也曹植七启盛以翠樽酌以雕觞浮蚁鼎沸酷烈馨香诗我心则降"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11819":["季秋苏五弟缨江楼夜宴崔十三评事韦少府侄三首 三","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["对月那无酒，登楼况有江。","听歌惊白鬓，笑舞拓秋窗。","尊蚁添相续，沙鸥竝一双。","尽怜君醉倒，更觉片心降。"],"",[["古注·《杜詩詳註》","黄生曰五六缀入天文舆地又拈出星秋二字特见工巧与水落鱼龙夜山空鸟雀秋地濶峩睂晚天高岘首春皆名对也又曰漫看年少乐忍泪已沾衣令人刻不可耐老人因酒病坚坐看君倾令人恋不容舍匡説诗解人頥予於杜公亦云"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11820":["九月一日过孟十二仓曹十四主簿兄弟","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["藜杖侵寒露，蓬门啓曙烟。","力稀经树歇，老困拨书眠。","秋觉追随尽，来因孝友偏。","清谈见滋味，尔辈可忘年。"],"",[["古评·《唐诗镜》","三四意境自然"],["古注·《杜詩詳註》","上四叙事言过访之诚下四叙情言访孟之故黄注寒露虽㸃曙色亦见此日正交此节也前诗言读书秋树根故知经树拨书皆指孟园中公因其孝友故偏与追随不觉将尽二句乃倒装清谈见滋味有徳且有言也作蓬门启是门启作起曙烟是起烟以上句例之作起为当何逊诗厯稔共追随诗张仲孝友黄注地一隅曰偏人一意亦曰偏言不他往也公诗好用偏字东汉书孔公绪清谈高论嘘枯吹生文心雕龙滋味流於字句後汉书□衡始弱冠孔融年四十与为忘年交"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗镜》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩鏡_(四庫全書本)）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11821":["过客相寻","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["穷老真无事，江山已定居。","地幽忘盥栉，客至罢琴书。","挂壁移筐果，呼儿问煮鱼。","时闻系舟楫，及此问吾庐。"],"",[["古注·《杜詩詳註》","诗云江山定居当从黄鹤编在瀼西诗中"],["古注·《杜詩詳註》","去声蔡作间一作问"],["古注·《杜詩詳註》","卜居无事可以见客三四客至之事下言待客之情忘盥栉不期客至罢琴书喜而岀迎移果供客间杂鱼傍杜率之中不失殷勤也汉游侠传吕公故旧穷老沈君攸诗地幽吟不断唐书虞世南十年精思不懈至累旬不盥栉世説谢太傅徃看戴安道但与论琴书薛道衡诗挂壁屡移鈎北齐书邢子才脱畧简易果饵之属置之梁上客至下而共食世説孔君平诣杨氏呼儿出为设果古乐府呼童烹鲤鱼黄生注移筐果亦呼儿为之以下句绾上句与次第寻书札呼儿觅赠诗一例解问煮鱼者家偶烹鲜客至即以同享因呼儿问其熟否耳此即盘飱市逺无兼味之意今按张九成诗疏果间溪鱼可悟杜诗筐果间煮鱼之语"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11822":["孟仓曹步趾领新酒酱二物满器见遗老夫","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["楚岸通秋屐，胡牀面夕畦。","藉糟分汁滓，瓮酱落提携。","饭粝添香味，朋来有醉泥。","理生那免俗，方法报山妻。"],"",[["古注·《杜詩詳註》","鹤注当是大厯二年秋作黄生注制题即见手法二物系新成兼又满器且自领而来皆深荷来客之意刘桢诗步趾慰我身"],["古注·《杜詩詳註》","通屐而来面畦遥见叙出步趾亲领志其意之诚酒可醉朋酱多流落又叙满器见遗言其情之厚末则兼美制法之精也黄注起聫賔主对叙洪注此诗前新後趣中四不嫌朴拙魏裴潜为兖州太守尝作一胡牀及其去留以挂柱枕𱋐籍糟出刘伶酒徳颂此对瓮酱言籍乃漉酒之具嵇康哀乐论簁酒之囊笮具不同杨慎曰古书中笮具仅见此笮或作醡俗字也或以分汁滓为分恵非也竹牀笮酒分出汁滓其清汁为酒浊滓则糟也周礼醴齐注云醴犹体也成而汁滓相将邵注即今之甜酒周礼酱用一百二十瓮此瓮酱所本凡新酱入瓮有时浮溢故提携而来常有旁落者司马迁传尧舜粝粱之食汉书孔顗之传一日不斋醉如泥谓醉後頽倒如泥旧注谓泥乃东海䖝名得水则活失水则醉恐属臆说公诗有云组练去如泥亦可云海䖝乎抱朴子退则参陶白之理生世说阮咸曰未能免俗聊复尔耳髙士传陈仲子賛楚相敦求山妻了算"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11823":["柳司马至","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["有使归三峡，相过问两京。","函关犹出将，渭水更屯兵。","设备邯郸道，和亲逻些城。","幽燕唯鸟去，商洛少人行。","衰谢身何补，萧条病转婴。","霜天到宫阙，恋主寸心明。"],"",[["古注·《杜詩詳註》","苏个切唐书作娑韵㑹云娑或作逤通作些"],["古注·《杜詩詳註》","首二栁至夔而问信也中六栁答词下四公自叙出将屯兵设备和亲此指西京吐蕃事幽燕路梗商洛人稀此指东京叛将事杜臆霜天望阙千里明净唯恋主丹心与之共明耳此十字句法汉书文帝至霸陵慎夫人从帝指视新丰道曰此走邯郸道也旧唐书吐蕃传其人或随畜牧而不常厥居然颇有城郭其国都城号逻些城新书吐蕃賛普居跋布川或居逻娑川髙士传四皓共入商洛刘桢诗余婴沉疴疾薛道衡诗霜天㫁雁声"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11824":["简吴郎司法","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["有客乘舸自忠州，遣骑安置瀼西头。","古堂本买藉疎豁，借汝迁居停宴游。","云石荧荧高叶曙，风江飒飒乱帆秋。","却爲姻娅过逢地，许坐曾轩数散愁。"],"",[["古注·《杜詩詳註》","鹤注大厯二年公移居东屯以瀼西草堂借吴寓居而简之也杜臆此即用诗当简顾注吴必公之姻娅故称为郎亲之也朱注唐书府州各有司法㕘军事"],["古注·《杜詩詳註》","此章为吴郎借居而作也乘舸而至遣骑往迎见賔主之情昔藉疎豁今停宴游以借居故也五六疎豁之景七八迁居後事逺注次聫上四字连读下三字另读顾注云石之间光彩闪动以髙叶当曙也风江之上气象肃森以乱帆逢秋也此本公堂欲坐轩而散愁反问呉见许此相谑之词也忠州古本巴地今属四川重庆府湛茂之诗离离挿天树磊磊间云石秦嘉诗荧荧华烛栁晖诗飒飒避霜叶诗𤨏𤨏姻娅尔雅妇之父母壻之父母相谓为昏姻两壻相谓曰娅繁钦酷暑赋蒸我层轩杜臆堂为吴之内室故坐层轩"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11825":["又呈吴郎","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["堂前扑枣任西邻，无食无儿一妇人。","不爲困穷宁有此，祗缘恐惧转须亲。","即防远客虽多事，使插疎篱却甚真。","已诉徵求贫到骨，正思戎马泪盈巾。"],"",[["古注·《杜詩詳註》","此章告以恤怜之道也上四悯隣妇下四谕吴郎无食无儿一妇人句中含四层哀矜意通章皆包摄於此三言宜见谅其心四言当曲全其体妇防客时怀恐惧吴挿篱不怜困穷矣诉徴求述隣妇平日之词思戎马念乱离失所者衆也陶潜诗桃李罗堂前诗八月剥枣毛注云剥击也陆徳明音普卜切正是扑也容斋随笔王安石作诗新经解剥枣云剥者剥其皮而进之所以养老也後从蒋山郊步至民家问其翁安在曰去扑枣始悟前非甚矣注书之难也汉书王吉居长安东家有大枣树垂吉庭中吉妇取枣以噉吉吉知之乃去妇庾肩吾啓池通西舍之流𥦗映东隣之枣西隣见易既济贾谊新书大禹曰民无食也则我弗能使也晋书皇天无知邓伯道无儿宋玉神女赋见一妇人潜夫论怀忧愦愦皆易恐惧楚辞去乡离家兮徕逺客晋书郑冲传任真自守老子其精甚真应琏诗徴求倾四海"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11826":["覃山人隐居","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["南极老人自有星，北山移文谁勒铭。","徵君已去独松菊，哀壑无光留户庭。","予见乱离不得已，子知出处必须经。","高车驷马带倾覆，怅望秋天虚翠屏。"],"",[["古注·《杜詩詳註》","鹤注公诗有云南极青山衆乃指䕫州而言今此诗亦云南极知覃山人在䕫州也顾注覃山人必老而就徴者公过其隠居之所而伤其隠之不终也"],["古注·《杜詩詳註》","范濂本作常"],["古注·《杜詩詳註》","上四讥徴君之轻出下责其不能审时见几也吴论老人在山谁得移文诮之无如一去之後松菊虽存而山川少色矣因叹乱离以来予不已而奔走今出处之途子必经厯而始知耳毎见荣宠所在倾覆随之何若隠居自得乎祗令我怅望秋山而伤翠屏之虚设也黄生注结句深秀足救前路之朴素此诗旧作山人已卒公过其故居而称美之以出处必须经谓山人能守经也今依朱注语含讽刺赵次公曰老人星一名南极在井栁之间乃南方之星山人隠居此地可当此星选注周顒先隠都北锺山後出为海盐令欲过北山孔稚圭乃假山灵意作文移之中云驰文驿路勒移山庭朱注齐书元徽中顒出为剡令建元中为山隂令未尝令海盐选注误一统志因而误又曰徴君二句即移文诱我松桂欺我云壑也演义汉魏以来隠士名之曰徴君後汉韩康传亭长以韩徴君当到方修道桥归去来辞三径就荒松菊犹存殷仲文诗哀壑叩虚牝易不出户庭诗乱离瘼矣道徳经吾见其不得巳传咸凤赋随时宜以行藏兮谅出处之有经四皓歌驷马高盖其忧甚大天台赋搏壁立之翠屏"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11827":["柏学士茅屋","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["碧山学士焚银鱼，白马却走身岩居。","古人已用三冬足，年少今开万卷余。","晴云满户团倾盖，秋水浮阶溜决渠。","富贵必从勤苦得，男儿须读五车书。"],"",[["古注·《杜詩詳註》","鹤注依旧次编在大歴二年盖寄诗在先而题屋在後也顾注公过学士茅屋羡其立品之高读书之勤故题其茅屋如此按诗言读书以取富贵於学士尚不相似黄氏谓朂其子侄者得之"],["古注·《杜詩詳註》","学士茅居旧有藏书上四叙事五六屋前秋景七八勉其子侄下截承上银鱼见焚白马却走遭禄山之乱也云如倾盖之团言其浓水似决渠之溜言其急也江淹诗游豫碧山隅银鱼学士所佩之章後汉张湛常乘白马光武每见曰白马生且复谏东方朔传臣年十二学书三冬文史足用沈氏蘧说曰古人春诵夏秋学礼冬读书故读书者曰三冬而不言春夏秋梁元帝曰读书万巻犹有今日萧子云诗重叠晴云新周王褒诗俯观云似盖低望月如弓邹阳传倾盖如故汉白公穿渠民歌之曰举挿为云决渠为雨陆机诗丰注溢修溜黄潦浸堦除云隂结不解通衢化为渠後汉蓟子训传诸贵人共呼太学生曰子勤苦读书欲规富贵陆机诗男儿多逺志庄子惠施多方其书五车其道蹖驳"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11828":["题柏大兄弟山居屋壁二首 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["叔父朱门贵，郎君玉树高。","山居精典籍，文雅涉风骚。","江汉终吾老，云林得尔曹。","哀弦绕白雪，未与俗人操。"],"",[["古注·《杜詩詳註》","黄鹤谓柏大葢柏贞节子侄柏为中丞是即朱门贵一门四美是即玉树高也黄生谓柏大乃柏学士子侄诗云山居精典籍即前诗叹彼幽居载典籍也又云野屋流水山篱带云即前诗浮云满戸秋水浮阶也後説近是此应是大厯二年䕫州作"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11829":["题柏大兄弟山居屋壁二首 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["野屋流寒水，山篱带薄云。","静应连虎穴，喧已去人羣。","笔架沾窗雨，书签映隙曛。","萧萧千里足，个个五花文。"],"",[["古注·《杜詩詳註》","首章记柏氏好学喜得知音精典籍则博古涉风骚则能文此正玉树之姿不囿於朱门者哀白雪言相与弹琴咏歌不与俗人同调此承云林句来是赋非比郑𤣥曰朱门洞启当阳之正色郭璞诗朱门何足荣应璩与满公琰书外嘉郎君谦下之徳注璩常事其父故称郎君玉树用谢𤣥语详见前孙绰诗山居感时变魏志向朗优游无事垂三十年潜心典籍曹植诗文雅纵横飞虞茂诗睿藻风骚风骚国风离骚也鲍照诗宁能与尔曹瑕瑜稍辨论七发游涉於云林记丝声哀哀以立亷宋玉对楚襄王曰客有歌郢中者其始下里巴人国中属和数千人其为阳春白雪国中属而和者数十人而已谢希逸琴论白雪师旷所作商调曲也鲍照诗蜀琴抽白雪郢曲绕阳春"],["古注·《杜詩詳註》","次章叙山居景亊而赞其多材境幽地僻之中见此笔架书籖知真能精典籍而涉风骚矣上章玉树高比其质秀此章千里马比其才良个个该柏氏兄弟也吴志吕䝉传不入虎穴焉得虎子楚辞离人羣而遁逸何逊诗霏霏入窗雨诗萧萧马鸣汉文帝有千里马说苑使骥得王良造父骥无千里之足乎郦炎诗舒吾凌霄羽奋此千里足五花毛有五色也丹元子步天歌五个花文王良星"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11830":["戏寄崔评事表侄苏五表弟韦大少府诸侄","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["隐豹深愁雨，潜龙故起云。","泥多仍径曲，心醉阻贤羣。","忍待江山丽，还披鲍谢文。","高楼忆疎豁，秋兴坐氛氲。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11831":["秋日寄题郑监湖上亭三首 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["碧草逢春意，沅湘万里秋。","池要山简马，月净庾公楼。","磨灭余篇翰，平生一钓舟。","高唐寒浪减，髣髴识昭丘。"],"",[["古注·《杜詩詳註》","一作灭非"],["古注·《杜詩詳註》","首章想秋日湖亭之胜故题诗而神往也上四景下四情草非春意则楚地皆秋矣山池切湖庾楼切亭用事工贴篇翰犹存能寄题也钓舟素具将往游也黄生注首句见时次句见地因其谪官故托秋草以起兴发端之妙可比西掖梧桐树一起矣吴论亭在荆州沅湘山简庾公高唐昭丘皆引荆州事别赋春草碧色邵注沅水在辰州府西南五里源出四川播州湘水在长沙府西环城而下至沅州与沅水合㑹衆流以达洞庭晋山简传时时能骑马倒着白接䍦庾公楼注见十六巻书序其余错乱磨灭此诗磨灭犹云岁月销磨刘孝绰诗钓舟画彩鷁髙唐赋序楚襄王与宋玉游於云梦之台望高唐之观汉书注高唐在云梦华容县朱注後人因巫山神女遂传在巫峡此诗高唐寒浪减髣髴识昭丘及䕫州歌中有高唐天下无皆指在巫峡者言之长杨赋从者彷佛骫属注彷佛读曰髣髴谢灵运诗髣髴丹丘徒登楼赋北弥陶牧西接昭丘李善曰荆州圗记当阳东南七十里有楚昭王基登楼则见所谓昭丘"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11832":["秋日寄题郑监湖上亭三首 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["新作湖边宅，还闻宾客过。","自须开竹迳，谁道避云萝。","官序潘生拙，才名贾傅多。","舍舟应转地，邻接意如何。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11833":["秋日寄题郑监湖上亭三首 三","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["暂阻蓬莱阁，终爲江海人。","挥金应物理，拖玉岂吾身。","羹煮秋蓴滑，杯迎露菊新。","赋诗分气象，佳句莫频频。"],"",[["古注·《杜詩詳註》","三章从郑监说归湖亭欲重题其胜也昔蓬阁而今江海可见郑之达识挥金乃物理应然则江海正可行乐拖玉於吾身无预则蓬阁不必久居矣蓴菊想湖亭食品赋诗懝到後题诗朱注分气象分咏湖亭之气象赵注莫频频言莫不频频有佳句乎杜臆云郑之佳句莫频频先出使我不能追和盖戏之也从前説为顺黄生注此章结聫申首章五句之意公有夔府咏怀寄郑审诗云蓬莱汉阁连赵次公注郑乃秘书少监故用蓬莱阁事与此可互证华峤後汉书学者称东观为老氏藏室道家蓬莱桓帝时始置秘书监鱼豢魏畧兰台为外台秘书为内阁庄子就薮泽处闲旷此江海之士避俗之人也汉书疏广为太傅归乡里数问其家所赐金余尚有几趣卖以具酒食请族人故旧与妓娱乐张协咏二疏诗挥金乐当年岁暮不留储顾谓四座賔多财为累愚王羲之帖天下物理岂可以意求西征赋飞翠緌拖鸣玉以出入禁门者衆矣吴均诗拖玉人含辉老子人之大患以吾有身晋齐王囘辟张翰为大司马东曹掾因秋风起思呉中菰莱蓴羮鲈鱼脍曰人生贵适意何能要名爵乎命驾归俄而回败人谓见几陶潜诗秋菊有佳色裛露掇其英一觞虽独进盃尽壶复倾刘桢诗赋诗连篇章江淹丽色赋非气象"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11834":["谒真谛寺禅师","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["兰若山高处，烟霞嶂几重。","冻泉依细石，晴雪落长松。","问法看诗忘，观身向酒慵。","未能割妻子，卜宅近前峰。"],"",[["古注·《杜詩詳註》","黄生注前半到寺之景後半进谒之意又曰首句言髙次句言深结用前峰字应转又曰身妄故一切俱妄平日所最躭者莫如诗酒今亦索然无味此作悟後语杜臆妻子难割甚於诗酒故自叹未能末聫十字为句天台赋䕃落落之长松赵注宋周顒长於佛理於锺山西丘隠舍终日长蔬虽有妻子独处山谷此卜宅近寺之一证也"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11835":["别崔潩因寄薛据孟云卿","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["志士惜妄动，知深难固辞。","如何久磨砺，但取不磷缁。","夙夜听忧主，飞腾急济时。","荆州过薛孟，爲报欲论诗。"],"",[["古注·《杜詩詳註》","原注内弟潩赴湖南幕职姑从黄鹤入大厯元年"],["古注·《杜詩詳註》","陈作深知"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11836":["送李八秘书赴杜相公幕","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["青帘白舫益州来，巫峡秋涛天地回。","石出倒听枫叶下，橹摇背指菊花开。","贪趋相府今晨发，恐失佳期後命催。","南极一星朝北斗，五云多处是三台。"],"刘云两句皆目击自然而险易天出极舟行之妙也",[["古评·《唐诗品汇》","刘云两句皆目击自然而险易天出极舟行之妙也"],["古注·《御选唐诗》","唐书百官志秘书郎三人従六品上掌四部图籍以甲乙丙丁为部虞集注大厯二年六月剑南节度使杜鸿渐入朝辟李秘书入幕杜葢先行李追赴之也当是其年九月作"],["古注·《御选唐诗》","荆州记巴东三峡巫峡长一统志巫峡在巫山县西三十里即巫山也曹毘观涛赋伊山水之辽㢠何秋月之凄清瞻沧洲之腾起观云涛之来征左思蜀都赋流汉汤汤惊浪雷奔望之天回即之云昏木华海赋状如天轮胶戾而激转又似地轴挺拔而争回"],["古注·《御选唐诗》","王绩诗时时㫁嶂遮往往孤峯出顔延之诗侧聴风薄木谢灵运诗晓霜枫叶丹夕曛岚气隂楚辞洞庭波兮木叶下梁武帝𢷬衣诗中州木叶下边城应早霜"],["古注·《御选唐诗》","呉志吕䝉传䝉至寻阳使白衣摇橹作商贾装服昼夜兼行王勃采莲曲桂棹兰桡下长浦罗裠玉腕摇轻橹王绩诗春酿煎松叶秋杯浸菊花虞集注枫树悬崖而生者则聴其落叶之声船橹向後而摇者则背指岸菊花开之处"],["古注·《御选唐诗》","史记张苍传苍以列侯居相府晋百官表注汉丞相府门无䦨不设铃不警鼓言其深大阔逺无节限也王襃入朝诗严驾早凌晨任昉诗朝发富春渚"],["古注·《御选唐诗》","楚辞与佳期兮夕张谢庄月赋佳期可以还微霜沾人衣左传宰孔谓齐侯曰且有後命无下拜陆机诗薄寒肃後命改服就藩臣张正见诗良时不可再驺驭郁相催"],["古注·《御选唐诗》","汉书天文志老人星曰南极崔駰颂夀如南极子孙千亿晋书天文志老人一星在弧南一曰南极常以秋分之旦见於景春分之夕没于丁见则治平主夀昌诗维北有斗淮南子北斗之神有雌雄雄左行雌右行星经北斗星谓之七政天之诸侯亦谓帝车魁四星为璇玑杓三星为玉衡齐七政斗为人君号令之主"],["古注·《杜詩詳註》","原注相公朝谒今赴後期也黄鹤注大厯二年六月剑南节度使杜鸿渐入朝辟李秘书入幕杜盖先行李追赴之也当是其年九月作顾注唐制秘书郎从六品李注按史杜鸿渐还朝仍以平章事领山剑副元帅故称相公幕"],["古注·《杜詩詳註》","一作皆非"],["古注·《杜詩詳註》","上四舟行之景下四赴幕情事蜀舟赴峡其波涛激荡势若天地回旋即所谓大声吹地转高浪蹴天浮也毛竒龄曰石崖横出则落叶之声在上故曰倒听飞橹迅行则菊岸之移忽後故曰背指上句作上下两层説下句作前後两际説杜臆三四肰舟行之疾五六明疾行之故毛又曰汉天文志南极星在益州分野觜参之傍而三台三公又在北斗傍时杜相还朝李从益州来赴京故言南极而向北者以三公在北斗傍也倦游録刘濬白舫百棹皆绣帆青帘多载妓女首句用此邵注青帘白舫官舟也成都即汉之益州石出指峡中山崖旧指灧澦堆非是杨慎曰倒听句与包佶诗被影倒江枫同意恐催後命故今晨发舟两句倒叙左传宰孔谓齐侯曰且有後命董仲舒曰太平之时云则五色而为庆五云谓京城瑞气或指长安宫阙"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗品彚（附唐诗拾遗）》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩品彚_(四庫全書本)）","古籍注评：《御选唐诗》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/御選唐詩_(四庫全書本)）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11837":["巫峡敝庐奉赠侍御四舅别之澧朗","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["江城秋日落，山鬼闭门中。","行李淹吾舅，诛茅问老翁。","赤眉犹世乱，青眼只途穷。","传语桃源客，人今出处同。"],"",[["古注·《杜詩詳註》","上四庐中舅至下四感懐送别黄生曰山句突语竒险以见侍御来访有空谷足音之喜世乱难归途穷寡援故愿作桃源避世之人与为於耆旧内试觅姓龎人同法杜臆行李诛茅用借对法赤睂二句乃答问词桃源在朗州故有末二语屈原九歌有山篇史记秦始皇三十六年使者夜过华隂平舒道有人持璧遮使者曰今年祖龙死使者以闻始皇黙然曰山不过知一年事耳庾信小园赋诛茅宋玉之宅汉光武时有赤睂贼此比崔旰也晋阮籍能为青白眼黄生注白眼固当取嫉於世今青眼亦只途穷此自伤自怪之词石崇昭君词传语後世人"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11838":["奉送十七舅下邵桂","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["绝域三冬暮，浮生一病身。","感深辞舅氏，别後见何人。","飘缈苍梧帝，推迁孟母邻。","昏昏阻云水，侧望苦伤神。"],"",[["古注·《杜詩詳註》","上四旅中送别之情下四别後相思之意絶域病躯何堪离别感深二字上下俱关薛道衡诗絶漠三秋暮穷隂万里生鹤注九域志苍梧山在道州与邵为邻湛方生诗人运互推迁潘岳闲居赋孟母所以三徙注轲少居近墓乃戏为墓轲母曰此非所以居去居市傍轲又戏为商贾移居学宫之傍遂为大儒朱注时舅氏必奉母同往故有孟母句蜀都赋望之天迥即之云昏张衡四愁诗侧身东望涕沾翰别赋造分手而衔涕感寂寞而伤神"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11839":["送覃二判官","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["先帝弓劒远，小臣余此生。","蹉跎病江汉，不复谒承明。","饯尔白头日，永怀丹凤城。","迟迟恋屈宋，渺渺卧荆衡。","魂断航舸失，天寒沙水清。","肺肝若稍愈，亦上赤霄行。"],"",[["古注·《杜詩詳註》","此申言别後思归之意身卧荆衡而见乗舸逺去者何堪复滞水滨乎故欲寒时一返旧京也曰承明曰丹鳯曰赤霄怀君恋阙之诚篇中盖三致意焉此章两叚各六句屈宋自比赋诗荆衡谓荆门衡岳太宗实録贞观六年二月宴三品已上於九成宫赤霄殿"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11840":["季夏送乡弟韶陪黄门从叔朝谒","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["令弟尚爲苍水使，名家莫出杜陵人。","比来相国兼安蜀，归赴朝廷已入秦。","舍舟策马论兵地，拖玉腰金报主身。","莫度清秋吟蟋蟀，早闻黄阁画麒麟。"],"",[["古注·《杜詩詳註》","原注韶比兼开江使通成都外江下峡舟船使去声"],["古注·《杜詩詳註》","必二切一作此"],["古注·《杜詩詳註》","今本一作开"],["古注·《杜詩詳註》","题本送韶因陪黄门朝谒故诗中兼及鸿渐首句提杜韶次句起鸿渐安蜀入秦此叙朝谒之故舍舟策马杜韶陪行拖玉腰金鸿渐朝服莫度清秋望韶速徃早闻黄阁期渐功成也下四皆弟叔双关杜臆弟为苍水使而加一尚字见官未称其才谢灵运诗末路值令弟吴越春秋禹登衡岳梦见赤绣衣男子自称苍水使者曰闻帝使文命於此故来𠉀之王洙曰杜陵有南北杜最称名家韶出峡後从荆州陆道归故曰舍舟策马吴越春秋舍舟而去又策马飞舆遂还宫阙洙曰西征赋拖鸣玉以出入禁门岑文本颂腰金鸣玉执贽奉璋韶行在六月嘱其勿逗遛中途而听蟋蟀秋吟旧注引王褒颂蟋蟀俟秋吟是也卢注引潘岳秋兴赋蟋蟀鸣於轩屏葢以潘岳为黄门侍郎取其与杜黄门相合不知此句乃説杜韶非説鸿渐也鹤曰汉有给事黄门侍郎晋有黄门侍郎唐志龙朔二年改黄门侍郎曰东台侍郎乾元元年又曰黄门演义黄阁萧何所作"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11841":["送十五弟侍御使蜀","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["喜弟文章进，添余别兴牵。","数杯巫峡酒，百丈内江船。","未息豺狼鬬，空催犬马年。","归朝多便道，搏击望秋天。"],"",[["古注·《杜詩詳註》","鹤注当是大厯元年作诗云豺狼鬬盖指崔旰軰相攻也"],["古注·《杜詩詳註》","上四别送五六慨身世七八望侍御顾注公恨不能身讨豺狼嘱弟归朝而弹击之北史卢恺作露布帝读大悦曰恺文章大进舆地广记涪州内江即黔江也益州记内江至闗头滩滩长百步悬崖倒水舟楫莫通朱注通监朱龄石伐蜀衆军従外水取成都臧僖従中水取广汉老弱乗髙舰从内水向黄虎史照释文巴郡正对二水口右则涪内水左则蜀外水内水自渝上合州至绵州外水自渝上或泸至蜀杨慎谓外水即岷江内水即涪江中水即沱江陶氏叙侃临终表曰犹冀犬马之齿尚可少延萧望之传便道之官旧唐书桓彦范举杨峤为御史不乐搏击之任师氏曰御史搏击奸回如秋鹰之搏撃鸟兽"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11842":["送田四弟将军将夔州柏中丞命起居江陵节度阳城郡王卫公幕","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["离筵罢多酒，起地发寒塘。","回首中丞座，驰牋异姓王。","燕辞枫树日，雁度麦城霜。","空醉山翁酒，遥怜似葛强。"],"",[["古注·《杜詩詳註》","从杜臆旧作地"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11843":["送王十六判官","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["客下荆南尽，君今复入舟。","买薪犹白帝，鸣橹少沙头。","衡霍生春早，潇湘共海浮。","荒林庾信宅，爲仗主人留。"],"",[["古注·《杜詩詳註》","此亦夔州诗年次难考"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11844":["奉送卿二翁统节度镇军还江陵","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["火旗还锦缆，白马出江城。","嘹唳吟笳发，箫条别浦清。","寒空巫峡曙，落日渭阳明。","留滞嗟衰疾，何时见息兵。"],"",[["古注·《杜詩詳註》","鹤注当是大厯二年作卿二翁姓崔乃公舅氏江陵即湖广荆州府"],["古注·《杜詩詳註》","上四崔还之事下四送别之情朱旗锦缆军士列舟以待也白马出城统军将启行矣於时笳声悲惨不觉别浦萧条自曙而夕惜别情深何时息兵有感世乱也朱旗红旗也诸侯所建考工记龙旗九旒以象火火鸟旟七旒以象鹑火注大火苍龙宿之心鹑火朱雀宿之柳吴甘宁以锦维舟龎徳好骑白马号白马将军谢朓诗寥戾清笳转萧条边马烦别浦用送别南浦语舅称渭阳本诗秦风汉章帝留马光诏有司勿复请以慰朕渭阳之情"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11845":["送鲜于万州迁巴州","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["京兆先时杰，琳琅照一门。","朝廷偏注意，接近与名藩。","祖帐排舟数，寒江触石喧。","看君妙爲政，他日有殊恩。"],"",[["古注·《杜詩詳註》","此是䕫州作年次难考今附在大厯元年之後二年之前顔真卿鲜于仲通碑仲通子六人皆有令闻叔曰万州刺史炅雅有父风颇精吏道作牧万州政"],["古注·《杜詩詳註》","绩尤异有诏迁秘书监㝷又改牧巴州九域志万州至逹州二百七十里逹州至巴州又二百二十里"],["古注·《杜詩詳註》","一作杂陈作维"],["古注·《杜詩詳註》","间氏音促"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11846":["寄杜位","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["寒日经檐短，穷猨失木悲。","峡中爲客恨，江上忆君时。","天地身何在，风尘病敢辞。","封书两行泪，沾洒裛新诗。"],"",[["古注·《杜詩詳註》","寒日穷猿对景有感为客久承穷猿忆君时承寒日五六申客久之况七八申忆君之情杜臆漂流天地既无定在憔悴风尘病又奚辞凄凉之况真堪流涕穷猿失木乃叹无家可归或云偒严武之亡非也武在日公已辞回草堂矣淮南子猿狖颠蹶而失木世説穷猿奔林岂暇择木裛新诗手裛纸上泪也"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11847":["奉寄李十五秘书二首 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["避暑云安县，秋风早下来。","暂留鱼复浦，同过楚王台。","猨鸟千崖窄，江湖万里开。","竹枝歌未好，画舸莫迟回。"],"",[["古注·《杜詩詳註》","鹤注当是大厯元年夏在䕫州作"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11848":["奉寄李十五秘书二首 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["行李千金赠，衣冠八尺身。","飞腾知有策，意度不无神。","班秩兼通贵，公侯出异人。","玄成负文彩，世业岂沈沦。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11849":["奉送韦中丞之晋赴湖南","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["宠渥徵黄渐，权宜借寇频。","湖南安背水，峡内忆行春。","王室仍多故，苍生倚大臣。","还将徐孺子，处处待高人。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11850":["送李功曹之荆州充郑侍御判官重赠","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["曾闻宋玉宅，每欲到荆州。","此地生涯晚，遥悲水国秋。","孤城一柱观，落日九江流。","使者虽光彩，青枫远自愁。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11851":["送孟十二仓曹赴东京选","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["君行别老亲，此去苦家贫。","藻镜留连客，江山顦顇人。","秋风楚竹冷，夜雪巩梅春。","朝夕高堂念，应宜彩服新。"],"",[["古注·《杜詩詳註》","去声鹤注当是大厯二年作唐志太宗时以岁旱榖贵东人选者集於洛州谓之东选洛即东京也殆自此为例故至大厯年间犹然公大厯元年至夔常与孟仓曹兄弟往还赋孟氏好兄弟是也"],["古注·《杜詩詳註》","亲老家贫而赴选上四写孝子之心春秋朝夕之系念下四说慈亲之意只现前寻常语而关於至性读之悱恻入情铨部鉴别人材故曰藻镜楚竹去夔之时巩梅到京之日末聫十字成句韩诗外传曾子曰吾初为吏禄不及釡尚欣欣而喜者非以为多也乐其逮亲也既没之後吾尝南游於楚得尊官焉堂高九尺传车百乘然犹北面而涕泣者非为贱也悲不逮亲也故家贫亲老不择禄而仕晋书太康四年制曰藻镜铨衡易林贵货贱身乆留连客後汉逸民传憔悴江海之上周𢎞正诗齐纨将楚竹从来本相逺何逊与范云连句诗洛阳城东西却作经年别昔去雪如花今来花似雪夜雪巩梅本此唐书巩县属东都河南府"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11852":["凭孟仓曹将书觅土娄旧庄","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["平居丧乱後，不到洛阳岑。","爲历云山问，无辞荆棘深。","北风黄叶下，南浦白头吟。","十载江湖客，茫茫迟暮心。"],"",[["古注·《杜詩詳註》","鹤注公以乾元戊戌冬往洛阳次年春归华州至大厯二年丁未为十载土娄河南地名公昔居偃师旧庄在焉时孟仓曹赴东都故托以访问旧庄"],["古注·《杜詩詳註》","首二旧庄三四凭孟五六别时景七八将书意杜臆末云迟暮心盖有丘首之思诗丧乱既平蔡琰曲云山万重兮归路遐道徳经师之所处荆棘生焉楚辞交余手兮东行送美人兮南浦别赋送"],["古注·《杜詩詳註》","君南浦伤如之何时在鱼复浦也吕氏春秋中牟子身在江湖之上"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11853":["别苏徯（赴湖南幕）","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["故人有游子，弃掷傍天隅。","他日怜才命，居然屈壮图。","十年犹塌翼，绝倒爲惊吁。","消渴今如在，提携媿老夫。","岂知台阁旧，先拂凤皇雏。","得实飜苍竹，栖枝把翠梧。","北辰当宇宙，南岳据江湖。","国带风尘色，兵张虎豹符。","数论封内事，挥发府中趋。","赠尔秦人策，莫鞭辕下驹。"],"",[["古注·《杜詩詳註》","原注赴湖南幕鹤注此亦大厯元年作"],["古注·《杜詩詳註》","次喜苏逢知已台阁旧人必徯父交而力能提携者得实栖枝从此有所依托矣记长者与之提携魏志夏侯𤣥传铨衡掌於台阁蜀志龎统号鳯雏诗注鳯凰非竹实不食非梧桐不栖"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11854":["存殁口号二首 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["席谦不见近弹棊，毕曜仍传旧小诗。","玉局他年无限笑，白杨今日几人悲。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11855":["存殁口号二首 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["郑公粉绘随长夜，曹霸丹青已白头。","天下何曾有山水，人间不解重骅骝。"],"",[["古注·《杜詩詳註》","呉论据不见仍传四字遂云席殁毕存今按梓州诗云髙门蓟子过是与席相见时此云不见近弹棊公独往䕫州矣向在长安赠毕曜诗云流传江鲍体是平日作诗此云仍传旧小诗是死後诗传也若云毕尚存则当云新诗不当云旧矣或据搜神记南谷山中有白玉碁局引以证弹碁非也若依此则下句白杨何独不承小诗乎又卢注引隋书白杨何妥以证毕曜未亡使事隠僻萧萧白杨树自当以古诗为据耳"],["古注·《杜詩詳註》","原注髙士荣阳郑䖍善画山水曹霸善画马此谓郑殁而曹存也郑䖍既亡世更无山水之竒曹霸虽存人谁识骅骝之价乎一伤之一惜之也或云得䖍之图几令天下山水无色得霸之马能使人间骅骝减价乃极赞其笔墨之神妙亦通又一説何曽有谓世不收藏不解重谓人弗珍惜意义似浅抱朴子粉绘表形着图李陵诗严父辞长夜慈母去中堂左思呉都赋丹青图其珍玮"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11856":["奉汉中王手札报韦侍御萧尊师亡","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["秋日萧韦逝，淮王报峡中。","少年疑柱史，多术怪仙公。","不但时人惜，祗应吾道穷。","一哀侵疾病，相识自儿童。","处处邻家笛，飘飘客子蓬。","强吟怀旧赋，已作白头翁。"],"",[["古注·《杜詩詳註》","鹤注编在大厯元年"],["古注·《杜詩詳註》","上声一作小"],["古注·《杜詩詳註》","此闻报而深痛韦萧柱下史得长年侍御以少年而亡故疑之萧史乘鹤昇仙尊师以多术而卒故怪之两引古人一切官一切姓存亡关於吾道见其人足重也公羊传西狩获麟孔子曰吾道穷矣"],["古注·《杜詩詳註》","此悼友而自伤衰老哀之切为交久也隣家笛触耳生悲客子蓬怜巳流落白头懐旧恐将继萧韦而逝也杜臆一哀侵疾病相见自儿童信笔冩去不对之对惟杜有之此章上下各六句向秀思旧赋为嵇康吕安而作其序曰於时日薄虞渊寒冰凄然隣人有吹笛者发声寥亮追想曩昔游讌之好感音而叹故作赋云曹植诗转蓬离本根飘飘随长风类此游客子捐躯逺从戎潘岳怀旧赋为杨暨杨潭而作魏文帝曰巳成老翁但未白头耳"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11857":["哭王彭州抡","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["执友惊沦没，斯人已寂寥。","新文生沈谢，异骨降松乔。","北部初高选，东堂早见招。","蛟龙缠倚劒，鸾凤夹吹箫。","历职汉庭久，中年胡马骄。","兵戈闇两观，宠辱事三朝。","蜀路江干窄，彭门地里遥。","解龟生碧草，谏猎阻清霄。","顷壮戎麾出，叨陪幕府要。","将军临气候，猛士寒风飙。","井漏泉谁汲，烽疎火不烧。","前筹自多暇，隐几接终朝。","翠石俄双表，寒松竟後凋。","赠诗焉敢坠，染翰欲无聊。","再哭经过罢，离魂去住销。","之官方玉折，寄葬与萍漂。","旷望渥洼道，霏微河汉桥。","夫人先即世，令子各清标。","巫峡长云雨，秦城近斗杓。","冯唐毛发白，归兴日萧萧。"],"",[["古注·《杜詩詳註》","鹤注当是大厯元年作公初到成都时有王侍御抡许携酒至草堂诗王盖先以御史罢官後在严武幕中又迁彭州刺史而卒也"],["古注·《杜詩詳註》","音潮此従殁後追溯生前新文二句称其才品北部四句记其婚宦厯职四句叙其内任北部髙选如剑跃蛟龙抡盖令尉起家东床见招如箫迎鸾鳯抡必缔姻宗室也胡马兵戈指禄山之乱宠辱三朝谓𤣥肃代宗此句该一生履歴曲礼执友称其仁古歌倐忽沦没别无期斯人指同軰世説殷荆州语王恭曰适见新文甚可观沈谢沈约谢灵运松乔赤松子王子乔也列仙传王君平谓茅盈曰子有异骨可学仙又李徳林集风骨异人战国䇿有松乔之寿魏志武帝年二十举考亷为郎除洛阳北部尉迁顿丘令通典吴时余曹通为髙迁而吏部特一时之俊抱朴子髙选忠能旧注晋郄诜迁还雍州刺史武帝於东堂㑹问诜曰卿自以为何如诜对曰臣举贤良对䇿为天下第一杜臆东堂必东牀之误见招是招王为婿故下有鸾鳯句今按坦腹东牀用王逸少事越絶书辞烛曰当造剑之时蛟龙奉炉天帝装炭秦萧史教弄玉吹箫而鳯凰降东京赋建象魏之两观老子宠辱皆惊"],["古注·《杜詩詳註》","一作干戈"],["古注·《杜詩詳註》","一作漏一作漏"],["古注·《杜詩詳註》","一作多自"],["古注·《杜詩詳註》","此申厯年宠辱之故初由髙选陞御史宠也继则解龟而阻谏辱也其在蜀而就幕僚辱也後则作刺於彭州宠也公与抡同幕故详叙陪接之情戎麾出谓严武镇蜀幕府要谓辟为㕘谋上佐军机下练士卒则智畧过人矣井泉不汲烽火不烧则边境无事矣皆其筹画所致谢灵运诗解龟在景平注解去所佩龟甲也龟生碧草犹云委之草莾谏猎用司马相如事按黄希云唐人多言戎麾如杜佑制出总戎麾是也朱注引顔延之一麾出守即指"],["古注·《杜詩詳註》","抡出守彭州非也晋书庾亮镇武昌问戴洋气𠉀朱注气𠉀用兵之气𠉀刘㰴七畧有风𠉀孤虚二十巻猛士塞风颷即大风歌意赵曰军旅所在必瀹井泉边有惊急必举烽燧易井渫不食注渫不停汚也淮南子军井通然後敢饮张良传请借前箸以筹之"],["古注·《杜詩詳註》","此叙殁後情事双表谓墓表松凋惜人亡赠诗抡所作染翰公挽章赵曰昔尝哭抡之死今榇过䕫州而再哭也之官玉折是住而销魂寄塟萍漂是去而销魂公诗得三百篇遗意赋中必兼兴比此章蛟龙鸾鳯是比渥洼河汉是兴於排律中见之尤不易得潘岳"],["古注·《杜詩詳註》","懐旧赋岩岩双表列列行楸北史魏毛鸿宾传武帝曰寒松劲草所望於卿也梁简文帝诗染翰独踟蹰广川惠王传歌曰愁莫愁兮居无聊心重结兮意不舒汉书萧望之便道之官顔延之祭屈原文兰薰"],["古注·《杜詩詳註》","而摧玉缜则折萍漂注别见谢朓诗旷望极髙深渥洼河汉注俱别见王僧孺诗霏㣲商云散左传穆后及太子夀早夭即世注即世卒也李陵书令子无恙常景严君平讃素向迈金贞清标凌玉彻"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11858":["见萤火","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["巫山秋夜萤火飞，帘疎巧入坐人衣。","忽惊屋里琴书冷，复乱檐边星宿稀。","却绕井阑添个个，偶经花蘂弄辉辉。","苍江白发愁看汝，来岁如今归未归。"],"",[["古注·《杜詩詳註》","一作帘疎"],["古注·《杜詩詳註》","萤火飞领下五句自山而帘自帘而衣从外飞入内自屋而檐自井而花从近飞出逺六句皆摩写见字杜臆本意全在末二借萤发端正诗之兴也坐如黄莺并坐之坐却如却立苍石之却琴书添冷夜凉故也星宿同稀高飞故也邵云却遶见聚散不常偶经见明灭不定照入井中一萤两影若添个个闪过花间其光互映如弄辉辉顾注萤尾耀光迭开迭阖不停一瞬如弄光然弄字工於肖物刘孝绰诗萤隐光息梁元帝萤诗着人疑不热庾信诗琴声遍屋里刘歆遂初赋玩琴书以涤畅萧和萤赋与列宿而俱浮前汉刘向传夜观星宿南史齐江夏王铎倚井栏为书梁简文帝萤诗井疑神火照纪少瑜萤诗临池影更双梁简文萤诗拂树若花生潘岳萤火赋若丹英之照葩简文诗时送花蘂来鲍照诗翾翾燕弄风此弄字所本"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11859":["吹笛","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["吹笛秋山风月清，谁家巧作断肠声。","风飘律吕相和切，月傍关山几处明。","胡骑中宵堪北走，武陵一曲想南征。","故园杨柳今摇落，何得愁中曲尽生。"],"",[["古注·《杜詩詳註》","鹤注梁权道编在大厯元年按诗云胡骑中宵堪北走当指吐蕃而言通监永泰元年吐蕃与回纥入冦子仪免胄释甲投枪而进回纥酋长皆下马罗拜再成和约吐蕃闻之夜引兵遁去即此事也"],["古注·《杜詩詳註》","去声一作倚"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11860":["孤雁","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["孤雁不饮啄，飞鸣声念羣。","谁怜一片影，相失万重云。","望尽似犹见，哀多如更闻。","野鵶无意绪，鸣噪自纷纷。"],"唐末有鲍当为孤鴈诗因谓之鲍孤鴈亦未能逮此",[["古注·《杜詩詳註》","鹤注此托孤雁以念兄弟也当是大厯初䕫州作"],["古注·《杜詩詳註》","一作声声非"],["古注·《杜詩詳註》","一作更复"],["古评·《瀛奎律髓》","唐末有鲍当为孤鴈诗因谓之鲍孤鴈亦未能逮此"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）","古籍注评：《瀛奎律髓》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/瀛奎律髓_(四庫全書本)）"]],"open_11861":["鸥","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["江浦寒鸥戏，无他亦自饶。","却思飜玉羽，随意点春苗。","雪暗还须浴，风生一任飘。","几羣沧海上，清影日萧萧。"],"",[["古注·《杜詩詳註》","鹤注当是大厯初䕫州作江浦指䕫江鱼复浦也"],["古注·《杜詩詳註》","咏鸥怜其少自得之致此在六句分截叹浦鸥之劳不如海鸥之逸也罗大经曰浦鸥闲戏使无他事尽自寛饶却以谋食之故翻玉羽而弄青苖虽风雪凌厉亦不暇顾矣何似羣飞海上者清影翛然不为泥滓所染耶此兴士当髙举逺引归洁其身不当逐逐於声利之塲以自取贱辱也既云寒鸥不当言春苖矣以青对玉为工㸃如㸃水蜻蜓之㸃南越志江鸥一名海鸥在涨海中颇知风云若羣飞至岸必风渡海者以此为𠉀玉羽白羽也舞鹤贼叠霜毛而弄影振玉羽而临霞卢注春苖当是青苖䕫有青苗陂公䕫州歌北有涧水通青苖晴浴狎鸥分处处江晖诗雪暗马行迟胡夏客曰因海上狎鸥事故云沧海上气象自逺大萧萧闲暇之意"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11862":["猨","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["褭褭啼虚壁，萧萧挂冷枝。","艰难人不见，隐见尔如知。","惯习元从衆，全生或用奇。","前林腾每及，父子莫相离。"],"",[["古注·《杜詩詳註》","咏猿称其有见几之智中间隠见二字为通章之眼啼壁声相近挂枝形尚逺此为隠见发端人不如猿取其用智以脱险也従衆能挂枝用竒能腾踔此为隠见指实父子不离取其用智以全身也杜臆人於乱世往往父子不保公尝携子避乱而恐其不能两全具见苦情袅袅声之长也萧萧羣之寡也谢朓秋竹曲从风既袅袅楚词风飒飒兮木萧萧隂铿诗猿挂入櫩枝艰难犹云险阻诗遇人之艰难兮贾谊䇿习惯如自然按後诗有猿挂时相学故知惯习指挂枝也淮南子倍是従衆赵曰全生如搏矢避矢之类列子虽全生不可不有其身通监晋安帝纪沈田子曰兵贵用竒庄子独不见夫腾猿乎腾及腾跃而相及也吴都赋猿父哀唫𤟤子长啸卢注桓温入蜀至三峡部伍中有得猿子者其母攀崖哀号又齐武帝至景阳山见一猿悲号问丞此猿何意答曰猿子前坠崖死其母求之不见耳此父子相离之证也"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11863":["黄鱼","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["日见巴东峡，黄鱼出浪新。","脂膏兼饲犬，长大不容身。","筒桶相沿久，风雷肯爲神。","泥沙卷涎沫，回首怪龙鳞。"],"",[["古注·《杜詩詳註》","鹤注当是大厯元年䕫州作故诗云日见巴东峡"],["古注·《杜詩詳註》","音统一作筩"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11864":["白小","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["白小羣分命，天然二寸鱼。","细微沾水族，风俗当园蔬。","入肆银花乱，倾箱雪片虚。","生成犹拾卵，尽取义何如。"],"",[["古注·《杜詩詳註》","鹤注当是大厯元年䕫州作与前数首连类而咏物也旧注即今面条鱼"],["古注·《杜詩詳註》","咏白小叹细㣲之不免也杜臆此诗起结蔼然有万物一体之念物虽㣲细同沾水族乃俗当园疏用之贱矣乱肆倾筐取之多也但此羣分之命亦属造物生成今犹拾卵而尽取之有伤於义矣黄生注三四形容其小五六形容其白语甚松秀生成应上分命尽取则不仁而讥其非义者用物撙节之谓义也卢注黄鱼以长大不容白小以细㣲尽取不幸生䕫大小俱尽以叹民俗之不仁也羣分命各分一命也易物以羣分曹植橘赋体天然之素分庾信小园赋一寸二寸之鱼宾退録靖州图经载其俗居丧不食酒肉盐酪而以鱼为蔬今湖北多然谓之鱼菜䕫与湖北为隣故云陶潜诗园蔬有余滋诗不盈倾筐西京赋获胎拾卵蚳蝝尽取末二句用之"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11865":["麂","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["永与清溪别，蒙将玉馔俱。","无才逐仙隐，不敢恨庖厨。","乱世轻全物，微声及祸枢。","衣冠兼盗贼，饕餮用斯须。"],"",[["古注·《杜詩詳註》","咏麂叹其不当鸣而鸣也上四代麂写意自悔不能见几逺害下乃慨世之贪味而残生者一二作痛心语三作自责语四作自解语乱世叹其生不逢辰微声推出致祸之本衣冠乃食肉者盗贼乃捕兽者徇口腹之欲而戕命於斯须则衣冠亦等於盗贼矣此骂世语亦是醒世语黄生曰此物颇难入咏前半写得如许风致妙在以清溪字陪对玉馔以仙隐字陪对庖厨遂觉烟火之气都尽後半慨世不离咏物而却不徒咏物此之谓大手笔旧注清溪山多麂左思吴都赋矜其宴居则珠服玉馔王筠诗玊馔骈罗琼浆泛溢神仙传葛仙翁於女凡山学道数十年登仙化为白麂二足时出山上谢灵运诗一老四五少仙隠不可别説苑鹿生於山命悬於庖厨乱世重杀物而轻全物全乃全活之全庄子不敢以全物与之阮籍诗髙"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11866":["鸡","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["纪德名标五，初鸣度必三。","殊方听有异，失次晓无慙。","问俗人情似，充庖尔辈堪。","气交亭育际，巫峡漏司南。"],"",[["古注·《杜詩詳註》","咏鸡叹其当鸣而不鸣也上六叙事是案末二归结是断徳常标五鸣必度三此鸡之职也今在殊方听之则异夜鸣失次矣比晓能无慙乎乃问之习俗人情皆云如是彼既不能司晨亦但堪充庖已耳当子半亭育之时而巫峡漏声早有司南之报鸡鸣果安在哉顾注将问俗二句作借鸡警人言人情无徳无信与鸡相似而充庖则独用鸡乎杜臆谓刺巫峡之人可杀皆非也韩诗外传夫鸡头戴冠文也足傅距武也见敌而鬬勇也得食相呼义也鸣不失时信也鸡有五徳君犹瀹而食之其所由来近也记鸡初鸣史厯书鸡三号卒明注夜至鷄三鸣始为正月一日赵曰失次犹三国志言失旦之鸡也蔡邕赋时牢落以失次胡夏客曰楚国语有鸡次之典此次字所本左传充君之庖列子亭之毒之注化育之意刘孝标启一物之㣲遂留亭育韩非子先王立司南以端朝夕梁元帝诗刻漏铭司南按司南有四説朱云䕫州在南鸡司昏晓今失其"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11867":["玉腕骝","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["闻说荆南马，尚书玉腕骝。","顿骖飘赤汗，踞蹐顾长楸。","胡虏三年入，乾坤一战收。","举鞭如有问，欲伴习池游。"],"",[["古注·《杜詩詳註》","上四咏骝马之神骏下则有功成身退之意赤汗如珠而长楸欲奋言今有余勇三年伐叛而一战收功言昔能陷阵事平之後思伴习池结语竒儁杜臆举鞭欲问问马也欲伴习池代马对也此虽咏马兼讽卫公吴都赋䟃𧽼翋𦑶李善注相随驱逐衆多貌温庭筠诗白马䟃𧽼衆尘起杜诗作骖驔义葢相同诗注局曲也蹐累足也曹植诗走马长楸间旧唐书乾元二年卫伯玉击史思明大破於强子坂积尸满野以功迁神䇿军节度上元二年大破史朝义於永宁进封河东郡公广徳元年冬吐蕃寇京师乗舆幸陕以伯玉有干畧使节度江陵封阳城郡王"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11868":["见王监兵马使说近山有白黑二鹰罗者久取竟未能得王以爲毛骨有异他鹰恐腊後春生骞飞避暖劲翮思秋之甚眇不可见请余赋诗 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["雪飞玉立尽清秋，不惜奇毛恣远游。","在野只教心力破，千人何事网罗求。","一生自猎知无敌，百中争能耻下韝。","鹏碍九天须却避，兔藏三穴莫深忧。"],"",[["古注·《杜詩詳註》","一作干一作千"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11869":["见王监兵马使说近山有白黑二鹰罗者久取竟未能得王以爲毛骨有异他鹰恐腊後春生骞飞避暖劲翮思秋之甚眇不可见请余赋诗 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["黑鹰不省人间有，度海疑从北极来。","正翮抟风超紫塞，立冬几夜宿阳台。","虞罗自各虚施巧，春雁同归必见猜。","万里寒空祗一日，金眸玉爪不凡才。"],"",[["古注·《杜詩詳註》","次章咏黒鹰上四遡其来之逺下四悯其去之速北极紫塞𤣥冬皆为黒鹰㸃染正翮言直北正飞几夜言暂时停宿虞罗自觉言其机警春雁同归言皆北向虚施巧取之未得也必见猜恐其击也万里一日见飞腾之迅金眸玉爪谓形质之竒首句明提其黒末句反衬其黒卢照隣㕍诗万里南翔渡海来庄子抟扶摇羊角而上扶摇羊角风也抟风本此綖注紫塞雁门也其山髙入霄汉雁飞不能踰从两山断处而过故谓之雁门今黒鹰超越此门故曰超紫塞芜城赋紫塞雁门曹植离缴雁赋逺𤣥冬於南裔兮避炎夏於朔方楚王阳台在巫山魏彦深鹰赋何虞者之多巧运横罗以羁束刘孝威诗猜鹰鸷隼无由逐此猜字所本西京杂记茂陵少年李亨以鹰鹞逐雉兔鹰则有青翅黄眸青㝠金距高洋获白兔鹰目色紫爪本白"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11870":["太岁日","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["楚岸行将老，巫山坐复春。","病多犹是客，谋拙竟何人。","阊阖开黄道，衣冠拜紫宸。","荣光悬日月，赐与出金银。","愁寂鸳行断，参差虎穴邻。","西江元下蜀，北斗故临秦。","散地逾高枕，生涯脱要津。","天边梅柳树，相见几回新。"],"",[["古评·《唐诗品汇》","刘云寻常大礼"],["古注·《杜詩詳註》","鹤注此是大厯三年正月初三日作旧书是年正月丙午朔则戊申乃初三日也潘鸿曰太岁日疑当时以是为庆故诗有阊阖衣冠等句"],["古注·《杜詩詳註》","此抚时有感陆机云吾将老而为客竟何言不得比於何人祖延年诗存殁竟何人"],["古注·《杜詩詳註》","此伤不与朝班也上四思朝事下四念归京楚辞吾令帝阍开闗兮倚阊阖而望予大人赋排阊阖而入帝居汉天文志日有中道中道者黄道一曰光道晋志黄道日之所行也半在赤道外半在赤道内宋之问诗清跸喧黄道乗舆降紫宸後汉书朱晖家世衣冠鹤注唐紫宸殿正殿之名李锐上疏紫宸殿者周之路寝汉之前殿也尚书中𠉀帝尧之时荣光出河休气四塞江淹诗青云浮洛荣光四塞齐书永明中天忽黄色照地王融上金天颂王摛曰是非金天所谓荣光武帝大悦易悬象着明莫大乎日月蜀志先主取蜀城中金银钱赐将士北齐乐曲懐黄绾白鸳鹭成行楚辞憭兮栗虎豹穴赵曰䕫州近虎狼之穴楚人谓蜀江为西江旧注秦城上直北斗"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗品彚（附唐诗拾遗）》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩品彚_(四庫全書本)）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11871":["元日示宗武","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["汝啼吾手战，吾笑汝身长。","处处逢正月，迢迢滞远方。","飘零还柏酒，衰病只藜牀。","训喻青衿子，名慙白首郎。","赋诗犹落笔，献寿更称觞。","不见江东弟，高歌泪数行。"],"",[["古注·《杜詩詳註》","黄鹤编在大厯三年正月元日据次章言十五男儿志时年葢十五岁矣"],["古注·《杜詩詳註》","一作浆一作叶"]],{"source":"李亮伟","body":["二至四联，都紧扣“元日”生发，触景伤怀。“处处”二句，乃每逢佳节倍思亲之意，说自己的大家庭的亲人们，各在一方，新年也不能相聚。“滞远方”的原因，在不言之中，极沉郁顿挫。“飘零”二句，说在流落之中过新年，再穷困，一家人无论如何还是要共饮柏酒，祈愿寿康的；自己长期以来衰病缠身，都是在藜床上度过的呀！苦中作乐，苦长乐短，令人读之酸鼻。但可见一家老小患难与共，对生存的渴望，何其强烈。“训喻”二句，是说教导宗武勤奋好学，立志成才；而惭愧自己已年老无成。寄望于儿子，何其殷切。“赋诗”二句，叙写自己赋诗时笔都掉了，照应“手战”；家人一齐举杯祝寿，照应“柏酒”。","尾联，原注“第五弟丰漂泊江左，近无消息”，诗人忆江左弟不见而悲，高歌当哭，泪作数行下，此又见为兄者之慈爱，手足情深。对宗武来说，这也是一种潜移默化的家教。","下面两段话对我们理解该诗很有启发。清人浦起龙《读杜心解》：“情真语质之篇，自然合律。起四句，四意，提尽通篇。‘柏叶’‘藜床’从‘逢正’‘滞远’衍出。‘青衿’‘白首’从‘笑汝’‘啼吾’衍出。‘落笔’‘称觞’，过递语脉。临觞而忆弟，正欲辍饮；振笔而高歌，联托悲吟。一时情事，历历在目。此四句，亦从‘处处’‘迢迢’内衍出也。”仇兆鳌《杜诗详注》：“此诗皆悲喜并言。啼手战是悲，笑身长是喜；逢正月是喜，滞远方是悲；对柏酒是喜，坐藜床是悲；子可教是喜，身去官是悲；赋诗称觞又是喜，忆泪行又是悲。只随意序述，而各有条理。”"]},[],["https://github.com/chinese-poetry/chinese-poetry","《全唐诗》（清·曹寅等编，康熙扬州诗局本）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11872":["远怀舍弟颖观等","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["阳翟空知处，荆南近得书。","积年仍远别，多难不安居。","江汉春风起，冰霜昨夜除。","云天犹错莫，花萼尚萧疎。","对酒都疑梦，吟诗正忆渠。","旧时元日会，乡党羡吾庐。"],"",[["古注·《杜詩詳註》","张逺注此诗亦元日所作因前诗不见江东弟句故又有此诗观落句旧时元日㑹可见"],["古注·《杜詩詳註》","从頴观叙起頴在阳翟仍逺别矣观赴荆南不安居矣二句分承唐书阳翟县贞观元年属许州龙朔二年𨽻洛州多难谓遭䘮乱"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11873":["续得观书迎就当阳居止正月中旬定出三峡","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["自汝到荆府，书来数唤吾。","颂椒添讽咏，禁火卜欢娱。","舟楫因人动，形骸用杖扶。","天旋夔子国，春近岳阳湖。","发日排南喜，伤神散北吁。","飞鸣还接翅，行序密衔芦。","俗薄江山好，时危草木苏。","冯唐虽晚达，终觊在皇都。"],"",[["古注·《杜詩詳註》","此亦大厯三年岁初所作唐书当阳县属荆州府"],["古注·《杜詩詳註》","一作呼首记续得观书颂椒属正月禁火属寒食此接来书而计欢聚之期世说谢安谓谢万曰汝为元帅宜数唤诸将宴㑹颂椒注见本巻周礼司烜氏仲春修火禁於国中为季春将出火也荆楚岁时记寒食禁火三日"],["古注·《杜詩詳註》","此叙出峡之意天旋阳和初转发日发行有日排舟而南则离散於北矣接翅喻随肩而行衔芦喻旅中防患杜臆公本北人以江陵为南方喜而忽吁即下文觊皇都意岳阳湖在巴陵魏畧孙权称臣太子与钟繇书曰得报知喜南方诗题彼鶺鴒载飞载鸣淮南子雁顺行以爱气力衔芦而翔以避矰弋"],["古注·《杜詩詳註》","末及当阳风土而终思北归也此章起结各四句中间八句"],["古注·《杜詩詳註》","陈辅之曰柳迁南荒云愁向公筵问重译欲投章甫作文身李白云我似鹧鸪鸟南迁懒北飞皆褊忮躁辞非畎畎惓惓之义杜诗冯唐虽晚达终觊在皇都又愁来有江水焉得北之朝赋张曲江云归老守故林恋阙悄延颈其乃心王室可知"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11874":["将别巫峡赠南卿兄瀼西果园四十亩","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["苔竹素所好，萍蓬无定居。","远游长儿子，几地别林庐。","杂蘂红相对，他时锦不如。","具舟将出峡，巡圃念携锄。","正月喧莺末，兹辰放鷁初。","雪篱梅可折，风榭柳微舒。","托赠卿家有，因歌野兴疎。","残生逗江汉，何处狎樵渔。"],"",[["古注·《杜詩詳註》","鹤注此大厯三年正月作仲长统曰场圃筑前果园树後"],["古注·《杜詩詳註》","首述行踪㡬地自秦而蜀又自阆而䕫也杜臆苔竹萍蓬凑合生新海赋萍流而蓬转"],["古注·《杜詩詳註》","黄生曰蘂当作菓"],["古注·《杜詩詳註》","此叙果园之胜果红如锦忆从前秋色雪梅风柳写现在春光莺未喧而鷁初放记临别时𠉀公於此园有不胜低徊缱绻之意焉"],["古注·《杜詩詳註》","末赠园而兼叙情离园则林泉兴少恐无复渔樵之侣矣此章首尾四句中间八句洛阳伽蓝记山情野兴之士游以忘归说文逗投合也阴监诗行舟逗逺树"],["古注·《杜詩詳註》","赵次公曰果园四十亩公直举以赠人此一叚美事而古今未尝揄扬其美可叹也锺惺曰以果园赠好友全写出一片爱惜郑重之意方见诗人情趣若说作轻弃所有反觉寻常肤浅矣胡孝辕曰八韵诗除梅柳一韵外并语对意不对极贯珠之妙陆放翁有野饭诗自注云杜氏家谱谓子美下峡畱一子守浣花旧业其後避乱成都徙睂州大垭或徙大蓬云今按当时若畱子在䕫应见於诗章集中既无或谱説未可信耶"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11875":["送大理封主簿五郎亲事不合却赴通州主簿前阆州贤子余与主簿平章郑氏女子垂欲纳郑氏伯父京书至女子已前许他族亲事遂停","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["禁脔去东牀，趋庭赴北堂。","风波空远涉，琴瑟几虚张。","渥水出骐骥，崑山生凤皇。","两家诚款款，中道许苍苍。","颇谓秦晋匹，从来王谢郎。","青春动才调，白首缺辉光。","玉润终孤立，珠明得闇藏。","余寒折花卉，恨别满江乡。"],"",[["古注·《杜詩詳註》","首段叙事还题风波句承北堂琴瑟句承东床晋谢混传孝武帝为晋陵公主求婚谓王珣曰主壻但如刘真长王子敬便足珣曰谢混虽不及员长不减子敬未㡬帝崩袁崧欲以女妻之珣戏曰卿莫近禁脔初元帝始镇建业公私窘罄毎得豚以为珍膳项下一脔尤美輙以荐帝呼为禁脔故珣因以为戏混竟尚主王羲之传郄鉴使门生求女壻於王导子弟咸自矜持唯一人在东床坦腹卧乃羲之也士昏礼妇洗在北堂注房半以北为北堂者房室所居之地总谓之堂朱曰赴北堂封至通州省毋也诗琴瑟友之又妻子好合如鼔瑟琴㡬及也"],["古注·《杜詩詳註》","此记封郑约婚之事骐骥阆州子鳯凰郑氏女苍苍指天以誓也秦晋王谢比𡛸娅相敌东京赋鸣女床之乌鸟舞丹穴之鳯凰繁钦定情诗中情既欵欵庄子苍苍者天之正色耶左传秦晋匹也何以卑我晋江左以王谢为胄族尝通婚姻"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11876":["人日两篇 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["元日到人日，未有不阴时。","冰雪莺难至，春寒花较迟。","云随白水落，风振紫山悲。","蓬鬓稀疎久，无劳比素丝。"],"东方朔占书一日为鸡二日为狗三日豕四日羊五日牛六日马七日人八日谷其日晴主所生之物盛隂则灾",[["古注·《杜詩詳註》","鹤注此大厯三年作蔡绦诗话都人刘克穷该典籍尝与客论云子美人日诗元日到人日未有不阴时人知其一不知其二起就架上取书示客曰此东方朔占书也岁後八日一日为鸡二日为狗三日为豕四日为羊五日为牛六日为马七日为人八日为榖其日晴主所生之物育阴则灾少陵意谓天寳离乱四方云扰人物岁岁俱灾岂春秋书王正月意耶申涵光曰此诗首二句纪实也旧注引东方朔占书以证天寳乱离人物俱灾凿之极果尔则八日为谷较余日尤要独不言阴何耶"],["古评·《瀛奎律髓》","东方朔占书一日为鸡二日为狗三日豕四日羊五日牛六日马七日人八日谷其日晴主所生之物盛隂则灾"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）","古籍注评：《瀛奎律髓》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/瀛奎律髓_(四庫全書本)）"]],"open_11877":["人日两篇 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["此日此时人共得，一谈一笑俗相看。","尊前柏叶休随酒，胜里金花巧耐寒。","佩劒冲星聊暂拔，匣琴流水自须弹。","早春重引江湖兴，直道无忧行路难。"],"",[["古注·《杜詩詳註》","首章感人日阴寒而作也上四写阴惨气象下乃触景而増忧杜臆昔此素丝蓬鬓犹在今又稀疎愧於素丝矣山海经白水至蜀而东南注江入江州城下江州县属巴郡後汉地志紫岩山绵水之所出"],["古注·《杜詩詳註》","次章当人日而思出峡也人共得举世同此人日俗相看流俗相沿为乐柏叶休随言元日巳过金花耐寒见人日尚阴杜臆琴劎乃作客随行之物醉後拔劎鸣琴则江湖兴动直谓行路无难矣直道句旧引忠信可涉风波解作直道而行者非是直道处世固属正理但用之此诗却非本意当时一救房琯十载流离尝云薄俗防人面又云全生狎楚童艰难险阻备尝之矣岂敢自矜其直与世无患哉李梦阳诗中年独觉沧洲稳直道谁非行路难是翻用杜句却是错看杜句崔实四民月令元日进椒柏酒椒是玉树星精服之令人却老柏是仙药能驻年却病尊卑次列以年少者为先各饮毕遂献尊长夀庾信诗柏叶随铭至椒花逐颂来荆楚岁时记人日剪彩为人或镂金箔为人以贴屏风亦戴之头鬓贾充李夫人典戒人日造华胜相遗像瑞图金胜之形又像西王母戴胜也汉书注胜妇人首饰汉代谓之华胜杜臆胜取人胜人之意沈佺期诗百福香奁胜里人晋舆服志自天子至百官无不佩劎晋书牛斗之间有紫气雷焕曰宝劎之精上彻於天吕氏春秋伯牙鼔琴志在流水锺子期曰善哉汤汤乎若流水行路难古乐府曲名"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11878":["江梅","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["梅蘂腊前破，梅花年後多。","绝知春意好，最奈客愁何。","雪树元同色，江风亦自波。","故园不可见，巫岫郁嵯峨。"],"庾肩吾诗瑞雪坠尧年因风入绮钱飞花洒庭树凝瑛结井泉史记天官书五星同色天下偃兵百姓安宁襄阳乐古辞三春虽同",[["古注·《御选唐诗》","庾肩吾诗瑞雪坠尧年因风入绮钱飞花洒庭树凝瑛结井泉史记天官书五星同色天下偃兵百姓安宁襄阳乐古辞三春虽同色嵗寒非处侬阳缙照帙秋萤诗忽聚还同色"],["古注·《御选唐诗》","梁元帝诗江风当夏清庾信诗日落江风静龙吟回上游九章顺风波以従流兮焉洋洋而为客晋书呉猛传因还豫章风波甚急"],["古注·《御选唐诗》","虞炎诗方掩故园扉何胥诗秋风生故园古乐府故乡不可见长望始此回何逊诗乡园不可见江水独自清"],["古注·《御选唐诗》","广韵山有穴曰岫沈约修竹弹甘蕉文巫峡敛云秦楼开照陆敬巫山髙巫岫郁迢嶤髙髙入紫霄陆机歌长风万里举庆云郁嵯峨又诗云山郁嵯峨"],["古注·《杜詩詳註》","鹤注当是大厯二年春作若三年之春公将下峡不当云巫峡郁嵯峨矣赵曰此咏江边之梅也如在岭曰岭梅在野曰野梅官所种者曰官梅後人见梅便谓之江梅误矣"],["古注·《杜詩詳註》","此见江梅而有感也客愁二字乃全首之眼梅占春意景物自好而反动客愁者葢见腊前映雪年後飘风花开花谢都非故园春色是以对巫岫而添愁耳陆机诗云山郁嵯峨"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《御选唐诗》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/御選唐詩_(四庫全書本)）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11879":["庭草","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["楚草经寒碧，逢春入眼浓。","旧低收叶举，新掩卷牙重。","步履宜轻过，开筵得屡供。","看花随节序，不敢强爲容。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11880":["大历三年春白帝城放船出瞿塘峡久居夔府将适江陵漂泊有诗凡四十韵","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["老向巴人里，今辞楚塞隅。","入舟飜不乐，解缆独长吁。","窄转深啼狖，虚随乱浴凫。","石苔凌几杖，空翠扑肌肤。","叠壁排霜劒，奔泉溅水珠。","杳冥藤上下，浓澹树荣枯。","神女峰娟妙，昭君宅有无。","曲留明怨惜，梦尽失欢娱。","摆阖盘涡沸，欹斜激浪输。","风雷缠地脉，冰雪耀天衢。","鹿角真走险，狼头如跋胡。","恶滩宁变色，高卧负微躯。","书史全倾挠，装囊半压濡。","生涯临臬兀，死地脱斯须。","不有平川决，焉知衆壑趋。","乾坤霾涨海，雨露洗春芜。","欧鸟牵丝扬，骊龙濯锦纡。","落霞沈绿绮，残月坏金枢。","泥笋苞初荻，沙茸出小蒲。","雁儿争水马，燕子逐樯乌。","绝岛容烟雾，环洲纳晓晡。","前闻辨陶牧，转眄拂宜都。","县郭南畿好，津亭北望孤。","劳心依憩息，朗咏划昭苏。","意遣乐还笑，衰迷贤与愚。","飘萧将素发，汩没听洪鑪。","丘壑曾忘返，文章敢自诬。","此生遭圣代，谁分哭穷途。","卧疾淹爲客，蒙恩早厠儒。","廷争酬造化，朴直乞江湖。","灧澦险相迫，沧浪深可逾。","浮名寻已已，嬾计却区区。","喜近天皇寺，先披古画图。","应经帝子渚，同泣舜苍梧。","朝士兼戎服，君王按湛卢。","旄头初俶扰，鹑首丽泥涂。","甲卒身虽贵，书生道固殊。","出尘皆野鹤，历块匪辕驹。","伊吕终难降，韩彭不易呼。","五云高太甲，六月旷抟扶。","回首黎元病，争权将帅诛。","山林托疲苶，未必免崎岖。"],"",[["古注·《杜詩詳註》","鹤注诗言舟行所经之地至宜都而止则此诗作於宜都也按诗本四十二韵目四十者举成数言耳"],["古注·《杜詩詳註》","此言放船佳景峡窄船转时闻猿狖啼㴱虚舟随水毎见浴鳬惊乱二句山水并言石苔若凌几杖空翠直扑肌肤二句舟行傍岸峭壁排劎飞泉溅珠藤垂上下树间荣枯此舟中近见者神女之峰云雨梦杳昭君之宅琵琶留恨此舟中逺望者杜臆神女峰在目故云娟妙昭君宅未经故云有无多恨少欢借二女以自慨也陈後主诗石苔侵緑藓空翠山中阴寒之气病人畏其侵肤谢灵运诗空翠难强名鲍照诗奔泉冬激射谢朓诗离离水上蒲结水散为珠江淹诗白云上杳㝠陆游入蜀记过巫山凝眞观谒妙用眞人祠即世所谓巫山神女也祠正对巫山峰峦上揷霄汉山脚直入江中神女峰最为竒峭盛𢎞之荆州记巫山有神女峰寰宇记归州巴东有王昭君宅神女赋序寐而梦之寤不自识惘兮不乐怅尔失志"],["古注·《杜詩詳註》","此言放船经险盘涡之沸轰若风雷激浪所输白如氷雪过鹿角狼头宁免变色诚恐猝罹水患负此残躯也倾压㡬危故以死地得生为幸摆阖欹斜舟行簸荡之象日知録鬼谷子有捭阖篇摆捭古今字输送也江赋流风蒸雷闗令尹内传地脉亦如之一统志鹿角狼头虎须三滩在夷陵州最险左传徳则其人也不徳则其鹿也铤而走险急何能择水经注江水又东流狼头滩其水并峻激奔暴鱼鼈所不能游其歌曰滩头白浡坚相持倐忽沦没别无期诗狼䟦其胡跋躐也胡颔下悬肉江淹诗揆日粲书史易困於葛藟于臲卼广韵臲卼不安也通作臬兀史记致之死地而後生曹植诗变故在斯须"],["古注·《杜詩詳註》","此出峡所见景物起二句反接陡健峡过则川平矣因水行之快故知衆流所趋霾涨海形其渺茫洗春芜言其嫩绿鸥鸟羣飞有类牵丝骊龙出水丽如濯锦落霞映於绮波残月没於金枢皆平川中变幻也荻笋舍泥蒲茸出沙雁争水马燕逐𣞸乌平川中生动之致也絶岛之中能容烟雾环洲之外常纳晓晡平川之大观尽此矣陶牧可辩江陵近也宜都将拂夷陵至也出宜都县郭则南畿在前登峡州津亭则长安在北希曰荻笋蒲茸皆仲春时物而雁燕去来亦不同时葢放船在正月而作诗在二月公以三月至江陵故前後所见如此何逊诗平川看逺鸟宋之问诗天香衆壑满汉书陈茂常渡涨海列子千金之珠必在骊龙颔下沈懐逺南越志蟠龙身长四丈青黒色赤带如锦文谢朓诗余霞散成绮周王褒诗残月半山低木华海赋大明㩠辔於金枢之穴注金枢西方月没处诗维笋及蒲尔雅笋竹之初生者陆玑云薍或谓之荻其初生三月中其心挺出其下如箸以锐而细扬州人谓之马尾其萌为虇郭云今江东人呼芦笋为虇许慎说文云蒲水草也泽陂传云蒲草柔滑茸乃芽之初出者朱注以为蒲花恐非是谢灵运诗初箟苞绿箨新蒲含紫芽雁儿争食水马葢虾䖝之类子瞻二䖝诗云君不见水马儿步步逆流水大江东流日千里此䖝趯趯长流此或引江赋之㹀马或引竞渡之水车或引本草之海马俱非周篆曰宋巴长卿妻李氏诗池中罗水马庭下列蜗牛水马对蜗牛疑即水靣四足䖝方以智物理小识云水马能化蜻蜓则水鼈䖝耳非四足之水秀才也一名虾扒䖝蜻蜓入水生子所化故复变为蜻蜓阴铿诗亭嘶背枥马樯转向风乌赵曰樯乌船樯上刻为乌形以占风者朱云此处樯乌当从旧注与西阁"],["古注·《杜詩詳註》","义从去声读用平声"],["古注·《杜詩詳註》","此自叙漂泊苦情憇谓舟泊宜都衰迷谓老年混俗返故丘而着诗文此应前北望意穷途作客目前流落之感廷争朴直前救房琯之事身到沧浪而奔走区区此应前南畿意丘壑曽忘返文章敢自诬是慰心语此生遭圣代谁分哭穷途是痛心语廷争酬造化朴直乞江湖是惬心语天台赋朗咏长川划昭苏谓忽然开豁记蛰虫昭苏王粲传鼓洪鑪以燎毛髪谢灵运诗昔余游京师未尝废丘壑曽忘谓不曽忘谁分犹云谁料厠儒身列儒官也前汉王陵传陈平曰面折廷争臣不如君酬造化言不负天地杜臆武当县有川曰沧浪禹贡所云汉水东流为沧浪也字书寻俄也已已本楚狂已而已而羲之书俯仰悲咽实无已已世说何扬州曰使人情何能已已古诗一心抱区区"],["古注·《杜詩詳註》","上文厯叙中途情景下文又写到荆心事此四句乃上下关键近寺披图想古迹依然经渚泣帝伤圣治难逢原注此寺有晋王右军书张僧繇画孔子及顔子十哲形像厯代名画记张僧繇呉人梁武帝崇饰佛像多僧繇画江陵天皇寺明帝置也内有柏堂僧繇画庐舎那佛及仲尼十哲像帝怪问释门之内如何画孔圣僧繇曰後当赖此耳及後周灭佛法焚天下寺墖独此殿以有宣尼像得不毁拆九歌帝子降兮北渚帝子尧二女湘夫人也同泣欲与二妃同哭记舜塟於苍梧之野而二妃未之从焉"],["古注·《杜詩詳註》","自此至末皆申明不乐长吁之故此为生遭世乱而思救时也戎服按劎臣主俱忧总以吐蕃俶扰而长安涂炭耳此时武夫得志儒术不尊岂知出羣厯块吾道固堪济世乎公之自负仍不浅矣孔融书朝士益重儒术赵国策武灵王好戎服吴越春秋越王允常使欧冶子作名劎五一曰湛卢允常以献之呉呉公子光弑呉王湛卢去如楚晋天文志昴为旄头书俶扰天纪晋天文志自东井十六度至柳八度为鹑首於辰为未秦之分野属雍州淮南王安书甲卒不下数十万世说嵇绍在稠人中昻昻如野鹤之在鸡羣王褒颂过都越国蹶如厯块前汉灌夫传局趣作辕下驹"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11881":["巫山县汾州唐使君十八弟宴别兼诸公携酒乐相送率题小诗留於屋壁，","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["卧病巴东久，今年强作归。","故人犹远谪，兹日倍多违。","接宴身兼杖，听歌泪满衣。","诸公不相弃，拥别惜光辉。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11882":["春夜峡州田侍御长史津亭留宴","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["北斗三更席，西江万里船。","杖藜登水榭，挥翰宿春天。","白发烦多酒，明星惜此筵。","始知云雨峡，忽尽下牢边。"],"",[["古注·《杜詩詳註》","得筵字鹤注此大厯三年正月作津亭在峡州又诗云津亭北望孤即此"],["古注·《杜詩詳註》","上四留宴之事下四惜别之情三更留席为饯长行也水榭指津亭挥翰同赋诗也峡尽下牢从此分手矣崔湜诗水榭宜时涉山楼向晚看诗明星有烂杜臆前诗有上牢下牢语注未详其处读是诗知下牢设关峡州而巫山之峡亦尽於此也峡州本冶下牢戍又夷陵县有下牢鎭"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11883":["泊松滋江亭","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["沙帽随鸥鸟，扁舟系此亭。","江湖深更白，松竹远微青。","一柱全应近，高唐莫再经。","今宵南极外，甘作老人星。"],"",[["古注·《杜詩詳註》","首二泊江亭三四亭前景下四泊舟感怀黄生注前诗言生涯临兀臬死地脱斯须㡬有性命之忧今幸而获免则虽老人星亦甘为之矣邵寳曰公大厯五年卒於湘潭道中岂此诗为之谶与杜臆一柱观即在松滋县其观犹在县东丘家湖故云全应近史记天官书狼星北地有大星曰南极老人老人见治安不见兵起常以秋分时𠉀之南郊正义老人一星在弧南䕫州诗云南极青山衆南极指䕫州此曰南极外去䕫至江陵也但玩诗意乃取南极老人而折用之"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11884":["行次古城店泛江作不揆鄙拙奉呈江陵幕府诸公","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["老年常道路，迟日复山川。","白屋花开里，孤城麦秀边。","济江元自阔，下水不劳牵。","风蝶勤依浆，春鸥嬾避船。","王门高德业，幕府盛才贤。","行色兼多病，苍茫泛爱前。"],"",[["古注·《杜詩詳註》","此亦大厯三年春作水经注江水又东迳陆抗故城北荆州图记夷陵县南对岸有陆抗故城周𮞉十里即山为墉四靣天险"],["古注·《杜詩詳註》","此呈幕府诸公原注卫伯玉为江陵节度时封阳城郡王故云王门黄生曰结句隐动诸公盻睐苍茫二字舍许多难言之情此章上八句下四句陆韩卿诗王门所以贵自古多俊人蔡邕荐边让文幕府初开博选清英荀悦汉纪观其温良泛爱賙急殷仲文诗广筵散泛爱此指幕府诸公也"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11885":["乘雨入行军六弟宅","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["曙角凌云罢，春城带雨长。","水花分堑弱，巢燕得泥忙。","令弟雄军佐，凡才污省郎。","萍漂忍流涕，衰飒近中堂。"],"诗全言景物易令弟凡才一聨却难他人为之则陈腐大手笔为之则高古",[["古注·《杜詩詳註》","朱作乱旧作罢"],["古注·《杜詩詳註》","上四春时雨景下四入宅有感角声齐起故曰乱雨气连城故曰带分堑弱荷初抽叶也得泥忙燕急营巢也省郎公自谓中堂位聴事潘徽诗潮落水花翻羊佑与弟琇书凡才而居重任"],["古评·《瀛奎律髓》","诗全言景物易令弟凡才一聨却难他人为之则陈腐大手笔为之则高古"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）","古籍注评：《瀛奎律髓》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/瀛奎律髓_(四庫全書本)）"]],"open_11886":["宴胡侍御书堂","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["江湖春欲暮，墙宇日犹微。","闇闇春籍满，轻轻花絮飞。","翰林名有素，墨客兴无违。","今夜文星动，吾侪醉不归。"],"",[["古注·《杜詩詳註》","原注李尚书之芳郑秘监审同集得归字韵此大厯三年春江陵作"],["古注·《杜詩詳註》","上四侍御书堂下四李郑同宴闇闇句贴日微轻轻句贴春暮翰林指李郑墨客公自谓文星兼宾主言徳星聚也呉论书翰文墨俱㸃书堂法书闇闇在上长杨赋序藉翰林为主人子墨为客卿以风後汉陈仲弓从诸子过荀季和家其夜徳星聚左传吾侪小人"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11887":["书堂饮既夜复邀李尚书下马月下赋绝句","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["湖水林风相与清，残尊下马复同倾。","久判野鹤如霜鬓，遮莫邻鸡下五更。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11888":["上巳日徐司录林园宴集","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["鬓毛垂领白，花蘂亚枝红。","欹倒衰年废，招寻令节同。","薄衣临积水，吹面受和风。","有喜留攀桂，无劳问转蓬。"],"鬂毛垂领白言我之形容情也花蘂亚枝红言彼之物色景也既如此开劈下面似乎难继却再着一句应上句形容其老为可怜",[["古注·《杜詩詳註》","上四林园宴集五六上已之景七八司录之情杜臆髩白花红彼此相左衰年到园以令节见招也上截悲中有喜临水受风修禊乐事暂留攀桂而莫问转蓬下截喜中有悲卢注谓薄衣与吹面相对是侵薄之薄非单薄之薄又引髙适诗水气薄行衣为证今按上已御单袷之衣故云薄衣若说水气薄衣更不得用临字矣还依旧解为当秋兴赋斑髩彪以承弁兮素髪飒以垂领花亚见十八巻刘安招隐士攀援桂枝兮聊淹留曹植诗转蓬离根本"],["古评·《瀛奎律髓》","鬂毛垂领白言我之形容情也花蘂亚枝红言彼之物色景也既如此开劈下面似乎难继却再着一句应上句形容其老为可怜又着一句言不孤物色之意然後五六一聨皆是以情穿景然结句亦不弱也尚双峙力缴惟老杜能之惟黄陈能之惟曾茶山赵章泉能之如重过何氏四句云蹉跎暮容色怅望好林泉何日沾微禄归山买薄田此等变格岂小手段分二十字巧粧纎刻者能之乎"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）","古籍注评：《瀛奎律髓》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/瀛奎律髓_(四庫全書本)）"]],"open_11889":["奉送苏州李二十五长史丈之任","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["星坼台衡地，曾爲人所怜。","公侯终必复，经术昔相传。","食德见从事，克家何妙年。","一毛生凤穴，三尺献龙泉。","赤壁浮春暮，姑苏落海边。","客间头最白，惆怅此离筵。"],"",[["古注·《杜詩詳註》","首叙李文家世才华朱注长史父必以宰相得罪故云星拆台衡但未详其人或云是适之胡夏客曰明皇时李适之为左相罢後仰药死此恐是适之之子但适之子季卿史不载为苏州长史或另是一子也张华传华为司空少子韪以中台星拆劝华逊位华不从未㡬被害汉成帝歌謡故为人所羡今为人所怜左传公侯之子必复其始汉书韦贤号称邹鲁大儒少子𤣥成复以明经厯位至宰相易讼六三食旧"],["古注·《杜詩詳註》","徳贞厉终吉或从王事䝉九二子克家曹植表终军以妙年使越南史帝谓谢庄曰超宗殊有鳯毛抱朴子丹穴之山其上有鸟焉名曰鳯凰汉髙帝纪提三尺取天下注三尺劎也越絶书欧冶子铸劎三枚一曰龙渊"],["古注·《杜詩詳註》","此送其赴任苏州此章上句下四句黄希曰赤壁有三一在汉水之侧竟陵之东一在齐安郡之步下一在江夏郡西南二百里间按魏武纪及周瑜传操自江陵而下刘备周瑜由夏口徃逆战则操所败之地乃在江夏之西南今属汉阳县李长史自江陵徃姑苏正经汉阳也越絶书阖庐起姑苏台三年聚材五年乃成髙见三百里吴郡志姑苏山连横山之北古台在其上旧图经云在吴县西三十里九域志苏州东北去海一百八十里头白自谓"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11890":["暮春江陵送马大卿公恩命追赴阙下","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["自古求忠孝，名家信有之。","吾贤富才术，此道未磷缁。","玉府标孤映，霜蹄去不疑。","激扬音韵彻，籍甚衆多推。","潘陆应同调，孙吴亦异时。","北辰徵事业，南纪赴恩私。","卿月升金掌，王春度玉墀。","熏风行应律，湛露即歌诗。","天意高难问，人情老易悲。","尊前江汉阔，後会且深期。"],"",[["古注·《杜詩詳註》","鹤注大厯三年三月作"],["古注·《杜詩詳註》","首将朝命马卿总提後汉韦彪议求忠臣必於孝子之门未磷缁谓忠孝无亏"],["古注·《杜詩詳註》","此备言其道术过人玉府比其操洁霜蹄比其才敏激扬二句言诗名独震潘陆二句言文武兼优亦异时前後相符也穆天子传天子至於羣玉之山四彻中绳先王之所谓䇿府梁简文帝集神峰标映北山移文髙霞孤映明月独举范蔚宗论激扬名声互相题拂文选音声凄以激扬前汉陆贾传贾游汉庭名声籍甚南史江右称潘陆江左称顔谢谢灵运诗谁谓古今殊异代可同调梁简文帝诗少解孙呉法家本幽并儿赵曰潘岳陆机孙武呉起"],["古注·《杜詩詳註》","此记其承命赴阙事业可徵则赴召非虚徃矣南纪记地卿月纪官王春纪时金掌谓内擢玊墀谓陛见应薫风而歌湛露预道入朝後事前汉天文志北辰一名天闗一名北极诗滔滔江汉南国之纪鲍照诗结主逺恩私洪范卿士惟月上官仪诗金掌露初稀春秋春王正月宋袁伯文诗玊墀滴"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11891":["暮春陪李尚书李中丞过郑监湖亭泛舟","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["海内文章伯，湖边意绪多。","玉尊移晚兴，桂楫带酣歌。","春日繁鱼鸟，江天足芰荷。","郑庄宾客地，衰白远来过。"],"",[["古注·《杜詩詳註》","得过字韵鹤注湖在峡州公徃江陵时过此而同游也"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11892":["奉送蜀州柏二别驾将中丞命赴江陵起居卫尚书太夫人因示从弟行军司马佐","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["中丞问俗画熊频，爱弟传书彩鷁新。","迁转五州防御使，起居八座太夫人。","楚宫腊送荆门水，白帝云偷碧海春。","报与惠连诗不惜，知吾斑鬓总如银。"],"",[["古注·《杜詩詳註》","黄蔡俱以中丞为柏贞节王道俊谓两名止是一人别驾中丞之弟黄生曰柏与卫必中表之亲故使弟起居其母旧唐书代宗纪大厯元年五月加荆南节度使卫伯玉检校工部尚书时位在江陵为行军司马"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11893":["夏日杨长宁宅送崔侍御常正字入京","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["醉酒扬雄宅，升堂子贱琴。","不堪垂老鬓，还对欲分襟。","天地西江远，星辰北斗深。","乌台俯麟阁，长夏白头吟。"],"",[["古注·《杜詩詳註》","得深字韵一作探韵得深字鹤注当是大厯三年作唐书长宁县属镇州大都䕶府秘书省有正字一人"],["古注·《杜詩詳註》","扬雄子贱借比杨长宁醉酒升堂同饮其家也三四送别崔常五六承上分襟公在江陵故曰西江崔常赴京故曰北斗乌台麟阁侍御正字官署也未句囘应垂老㸃还夏日通志汉氏图籍藏麒麟天禄二阁桓帝延熹二年始置秘书监一人唐六典秘书省天授初改为麟台监神龙元年复旧初汉御史中丞掌兰台秘书图籍故厯代置都邑建台省以秘书与御史为隣"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11894":["和江陵宋大少府暮春雨後同诸公及舍弟宴书斋","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["渥洼汗血种，天上麒麟儿。","才士得神秀，书斋闻尔爲。","棣华晴雨好，彩服暮春宜。","朋酒日欢会，老夫今始知。"],"",[["古注·《杜詩詳註》","鹤注此大厯三年季春作顾注宋少府於春雨後宴诸公及杜位席上必皆赋诗公闻而和之也"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11895":["宇文晁尚书之甥崔彧司业之孙尚书之子重泛郑监前湖","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["郊扉俗远长幽寂，野水春来更接连。","锦席淹留还出浦，葛巾欹侧未回船。","尊当霞绮轻初散，櫂拂荷珠碎却圆。","不但习池归酩酊，君看郑谷去夤缘。"],"沈约郊居赋藉外扉而为户顔延之诗郊扉常昼闭骆宾王诗俗逺风尘隔酉阳杂俎虞乡有山观甚幽寂涤阳道士居焉卢象诗",[["古注·《御选唐诗》","沈约郊居赋藉外扉而为户顔延之诗郊扉常昼闭骆宾王诗俗逺风尘隔酉阳杂俎虞乡有山观甚幽寂涤阳道士居焉卢象诗云气转幽寂"],["古注·《御选唐诗》","管子食野草饮野水刘桢诗野塘含白水谢庄诗春来雁不还刘邈诗春来谁不望魏文帝赋交采接连"],["古注·《御选唐诗》","梁武帝诗密筵重锦席江淹赋照锦地之文席淮南王招隠士攀援桂枝兮聊淹留齐竟陵王诗丘壑毎淹留鲍照采菱歌褭褭风出浦"],["古注·《御选唐诗》","宋书陶潜传郡将候潜值其酒熟取头丄葛巾漉酒毕复还着之南史吴苞传苞过江聚徒教学冠黄葛巾竹尘尾蔬食二十余年北史独孤信传尝因日暮入城其帽微侧吏人咸慕而侧帽焉梁简文帝诗人归浦口暗那得久回船"],["古注·《御选唐诗》","梁元帝诗荷珠漾水银又赋荷带水而珠圆"],["古注·《御选唐诗》","晋书山简传习氏有佳园池简毎出逰嬉多之池上置酒辄醉儿童歌曰山公出何许往至髙阳池日夕倒载归酩酊何所知"],["古注·《杜詩詳註》","{{{1}}}"],["古注·《杜詩詳註》","申涵光曰樽当霞绮轻初散补缀不成语棹拂荷珠碎复圆景眞而近俗矣"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《御选唐诗》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/御選唐詩_(四庫全書本)）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11896":["多病执热奉怀李尚书","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["衰年正苦病侵凌，首夏何须气郁蒸。","大水淼茫炎海接，奇峰硉兀火云升。","思沾道暍黄梅雨，敢望宫恩玉井冰。","不是尚书期不顾山阴野雪兴难乘。"],"",[["古注·《杜詩詳註》","之芳鹤注当是大厯三年四月作邵注执囚也囚困於热也"],["古评·《诗人玉屑》","」夏日李尚书期不赴云：「"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）","古籍注评：《诗人玉屑》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/詩人玉屑_(四庫全書本)）"]],"open_11897":["水宿遣兴奉呈羣公","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["鲁钝仍多病，逢迎远复迷。","耳聋须画字，发短不胜蓖。","泽国虽勤雨，炎天竟浅泥。","小江还积浪，弱缆且长堤。","归路非关北，行舟却向西。","暮年漂泊恨，今夕乱离啼。","童稚频书札，盘餐讵糁藜。","我行何到此，物理直难齐。","高枕飜星月，严城叠鼓鞞。","风号闻虎豹，水宿伴凫鷖。","异县惊虚往，同人惜解携。","蹉跎长泛鷁，展转屡鸣鸡。","嶷嶷瑚琏器，阴阴桃李蹊。","余波期救涸，费日苦轻齎。","支策门阑邃，肩舆羽翮低。","自伤甘贱役，谁愍强幽栖。","巨海能无钓，浮云亦有梯。","勳庸思树立，语默可端倪。","赠粟囷应指，登桥柱必题。","丹心老未折，时访武陵溪。"],"",[["古注·《杜詩詳註》","从衰年流落叙起上四与诸公致欵下四为水宿引端鲁钝多病而又逺行以故昧於逢迎耳聋髪短犹泊舟江上诸公当亦念及此耶勤雨之後故江犹积浪浅泥碍船故䌫系长堤易林目肓耳聋周礼泽国用龙节谷梁传言不雨者勤雨也注思雨之勤也鹤注此言得雨勤数与谷梁传注异"],["古注·《杜詩詳註》","一作乆客"],["古注·《杜詩詳註》","俗本作具"],["古注·《杜詩詳註》","此水宿感怀叹行踪溧荡也归北思故乡向西徃武陵是年四月杨子琳与崔寛战於成都故云乱离书频移而飱不给则此行之寥落甚矣古诗烈士暮年杜臆公因右臂偏枯故嘱儿子代书古诗遗我一书札庄子孔子在陈蔡之间七日不火藜藿不糁庄子有齐物篇"],["古注·《杜詩詳註》","此水宿景事叹旅况无聊也夜卧舟中故见星月翻动䕫蜀有警故闻鼓鼙叠响虎豹号则地险鳬鷖伴则身孤惊虚徃伤近邑无赠遗者惜解擕惜与羣公分手也泛鷁闻鸡水边不寐之状抱朴子人君恐奸衅之不时故严城以备之何逊诗严城方警夜张载诗此郭非吾城入闻鼓鼙声卫公兵法鼓三百三十槌为一通鼓止角动吹十二声为一叠芜城"],["古注·《杜詩詳註》","赋风嘷雨啸苦寒诗虎豹夹路啼蜀都赋云飞水宿哢吭清渠古乐府他乡复异县易出门同人宋之问诗骨肉初分爱亲朋忽解擕以解擕对分爱谓擕手者解散也张九龄诗义玷投分末情及解擕初岑参诗为君题惜解擕皆说分离之意"],["古注·《杜詩詳註》","此奉呈羣公之意瑚琏器谓人品不凡桃李蹊言奔趋者衆本期余波救涸乃日乆而齎资已竭矣杖䇿步行则阍者不执故门阑䆳肩舆徃拜则穷途乏费故羽翮低贱役如此谁复愍其勉强栖迟乎葢讽羣公之不见恤也公诗残杯与冷炙到处潜悲辛此云杖䇿门阑䆳肩舆羽翮低曲尽干人情状史记其色郁郁其徳嶷嶷言徳髙也瑚琏器见论语葛洪诗阴阴驱千乗李广传桃李不言下自成蹊左传其波及晋国者君之余也庄子车辙中有鲋曰吾得升水可以活矣後汉朱隽传轻齎数百金到京师虞世基诗轻齎不遑舍"],["古注·《杜詩詳註》","末述已志以遣兴钓海梯云想勲庸之得遂平时思为树立尝於语言中微露之今当旅困倘有赠我以粟者则题桥之志犹存也寸心未灰终期有济武溪之行特暂时焉耳杜臆想羣公必有许救济者故以指囷望之时武陵有故人而公将访之也此章二叚各八句裴秀九州图论峻山巨海之隔庄子任公为大鈎以五十犗为饵投钓於东海虞世基诗勲庸震边服"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11898":["奉贺阳城郡王太夫人恩命加邓国太夫人","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["卫幕衔恩重，潘舆送喜频。","济时瞻上将，锡号戴慈亲。","富贵当如此，尊荣迈等伦。","郡依封土旧，国与大名新。","紫诰鸾回纸，清朝燕贺人。","远传冬笋味，更觉彩衣春。","奕叶班姑史，芬芳孟母邻。","义方兼有训，词翰两如神。","委曲承颜体，骞飞报主身。","可怜忠与孝，双美画骐麟。"],"",[["古注·《杜詩詳註》","原注阳城郡王卫伯玉也旧书代宗纪大歴二年六月荆南节度使卫伯玉封城阳郡王公诗乃贺其母受封盖伯玉封王後母亦进封大国也阳城新旧唐书作城阳"],["古注·《杜詩詳註》","首叙阳城邓国杜臆起二擒题意完词伟且卫幕潘舆天然佳对衔恩以卫公能济时也送喜以慈亲膺锡号也富贵尊荣承上起下朱注郡封仍是阳城故曰旧夫人加号邓国故曰新汉书卫青征匈奴大克获帝就拜大将军於幕中傅咸诗衔恩非望始潘岳闲居赋太夫人乃乗板舆升轻轩上将为节度也徐陵文元戎上将"],["古注·《杜詩詳註》","次记郡王之孝及邓国之贤诰命初颁适当燕来之候膳用冬笋身服彩衣言伯玉娱亲之意义方比诸孟母词翰可继班姑又见母氏之受封不偶赵曰紫锦之诰其纸上有回鸾之势庾信贺娄慈碑台堪走马书足回鸾谢惠连诗从夕至清朝淮南子大厦成而燕雀相贺冬笋川孟宗事彩衣用老莱子事注皆别见後汉列女传扶风曹世叔妻者同郡班彪之女名昭字惠姬兄固着汉书其八表及天文志未竟而卒和帝诏昭就东观藏书阁踵而成之文心雕龙佩之则芬芳闲居赋此里仁以为美孟母所以三徙左传臣闻爱子教之以义方王俭褚渊碑凄凄辞翰"],["古注·《杜詩詳註》","胡化切一作映"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11899":["江陵望幸","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["雄都元壮丽，望幸歘威神。","地利西通蜀，天文北照秦。","风烟含越鸟，舟楫控吴人。","未枉周王驾，终期汉武巡。","甲兵分圣旨，居守付宗臣。","早发云台杖，恩波起涸鳞。"],"且悲且喜仓卒有气",[["古评·《唐诗品汇》","且悲且喜仓卒有气"],["古注·《杜詩詳註》","谓江陵人望车驾之临幸也朱注唐书上元初吕諲建请荆州置南都於是更号江陵府以諲为尹置永平军万人以遏吴蜀之冲广徳元年冬乗舆幸陕以卫伯玉有干畧可当重寄乃拜江陵尹充荆南节度观察等使诗所云甲兵分圣㫖居守付宗臣也时公在巴阆传闻代宗欲廵幸江陵故有此作封禅文太山梁父设坛望幸"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗品彚（附唐诗拾遗）》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩品彚_(四庫全書本)）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11900":["江边星月二首 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["骤雨清秋夜，金波耿玉绳。","天河元自白，江浦向来澄。","映物连珠断，缘空一镜升。","余光隐更漏，况乃露华凝。"],"",[["古注·《杜詩詳註》","朱注首章咏雨後星月首联江边星月雨後气清故云元白向澄此承首句星月夜皎故知珠连镜升此承次句更深光隐则露华凝而天欲晓矣未句逗起下章谢朓诗金波丽鳷鹊玊绳低建章汉律厯志日月如合璧五星如连珠古诗破镜飞上天公孙乗月赋蔽修堞而分镜谢庄诗露华识猿音"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11901":["江边星月二首 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["江月辞风缆，江星别雾船。","鸡鸣还曙色，鹭浴自清川。","历历竟谁种，悠悠何处圆。","客愁殊未已，他夕始相鲜。"],"",[["古注·《杜詩詳註》","朱注次章咏将晓星月星月离舟光将没矣鸡鸣鹭浴天已晓矣想星月无踪而俟之他夕葢客愁藉之以频遣也谢惠连诗亭亭映江月江总诗忽聴晨鸡曙非复楚宫歌萧慤诗野禽喧曙色袁峤之诗俯仰晴川焕古诗天上何所有厯厯种白榆谢庄月赋升清质之悠悠降澄晖之蔼蔼郭璞诗容色更相鲜"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11902":["舟月对驿近寺","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["更深不假烛，月朗自明船。","金刹清枫外，朱楼白水边。","城乌啼眇眇，野鹭宿娟娟。","皓首江湖客，钩帘独未眠。"],"",[["古注·《杜詩詳註》","鹤注当是大厯三年舟中作"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11903":["舟中","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["风餐江柳下，雨卧驿楼边。","结缆排鱼网，连樯竝米船。","今朝云细薄，昨夜月清圆。","飘泊南庭老，祗应学水仙。"],"",[["古注·《杜詩詳註》","年月同前鹤注诗云驿楼即前诗题所云对驿也"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11904":["遣闷","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["地阔平沙岸，舟虚小洞房。","使尘来驿道，城日避乌樯。","暑雨留蒸湿，江风借夕凉。","行云星隐见，叠浪月光芒。","萤鉴缘帷彻，蛛丝罥鬓长。","哀筝犹凭几，鸣笛竟沾裳。","倚着如秦赘，过逢类楚狂。","气冲看劒匣，颖脱抚锥囊。","妖孽关东臭，兵戈陇右创。","时清疑武略，世乱局文场。","余力浮於海，端忧问彼苍。","百年从万事，故国耿难忘。"],"",[["古注·《杜詩詳註》","此记舟中夜景上四泊舟初晚中四入夜景事下四坐乆见闻来驿道晚将宿也避乌樯城障日也胡夏客曰隐见言云中之星光芒言浪中之月绘景能新卢注萤光能鍳缘帷乍彻蛛丝引风掠鬓加长杜臆哀筝尚凴几而听鸣笛则泪下沾裳初犹强忍後竟难忍也二句已涉闷意溍注小洞房舟如洞房也柳𧦬诗风生叠浪起雾巻孤帆出阮籍诗薄帷鍳明月江总诗蜘蛛作丝满帐中鲍照诗丝罥千里心选注罥结也魏文帝诗哀筝顺耳"],["古注·《杜詩詳註》","此述遣闷之情上四自叙中四伤时末四感懐随地漂流身如出赘矣意多感愤迹若楚狂矣看劎壮心犹在抚囊欲试未能关东安史之乱陇右吐蕃之警时方右武故文人失志浮海思避世问苍乃悲天万事聴其自然唯故国难忘所以常闷耳此章两段各十二句贾谊传秦人家富子壮则出分家贫子壮则出赘劎气冲牛斗出张华传平原君传夫贤者处世譬如锥处囊中其末立见毛遂曰使遂早得处囊中乃脱颖而出後汉来歙传诸将方务闗东浮海见论语月赋端忧多暇诗彼苍者天"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11905":["江陵节度阳城郡王新楼成王请严侍御判官赋七字句同作","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["楼上炎天冰雪生，高飞燕雀贺新成。","碧窗宿雾蒙蒙湿，朱栱浮云细细轻。","杖钺褰帷瞻具美，投壶散帙有余清。","自公多暇延参佐，江汉风流万古情。"],"",[["古注·《杜詩詳註》","首章志新楼落成而称阳城韵事在四句分截碧窗朱栱楼新故丽雾宿云浮楼髙故凉瞻具美言文武兼优有余清言儒稚不俗延参佐暗用庾亮登楼事黄生注一席风流与江汉相为终古命意𢎞逺广雅南方曰炎天旧注晋羊球登西楼赋画栋浮细细之轻云朱栱湿蒙蒙之飞雨碧窗二句修可引羊球赋为证未知何据蒙蒙二字形容其湿细细二字形容其轻司马法左杖黄钺汉宗资为中郎将杖钺督兵後汉贾琮传琮为冀州刺史之部升车言曰刺史当逺视广聴纠察美恶何反垂帷裳以自掩塞乎命御者褰之祭遵传为将军对酒设乐必雅歌投壶谢灵运诗凌涧寻我室㪚帙问所知灵运初袭封康乐公後移籍㑹稽与隐士王𢎞之孔淳之等为娯故与祭公投壶并用说文帙书衣也谢灵运诗宻林含余清诗退食自公"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11906":["又作此奉卫公","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["西北楼成雄楚都，远开山岳散江湖。","二仪清浊还高下，三伏炎蒸定有无。","推毂几年唯镇静，曳裾终日盛文儒。","白头授简焉能赋，媿似相如爲大夫。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11907":["舟出江陵南浦奉寄郑少尹","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["更欲投何处，飘然去此都。","形骸元土木，舟檝复江湖。","社稷缠妖气，干戈送老儒。","百年同弃物，万国尽穷途。","雨洗平沙静，天衔阔岸纡。","鸣螿随泛梗，别燕赴秋菰。","栖托难高卧，饥寒迫向隅。","寂寥相喣沫，浩荡报恩珠。","溟涨鲸波动，衡阳雁影徂。","南征问悬榻，东逝想乘桴。","滥窃商歌听，时忧卞泣诛。","经过忆郑驿，斟酌旅情孤。"],"",[["古注·《杜詩詳註》","鹤注此当是大厯三年秋作是时公移居公安公安在江陵之南故出南浦也时郑审为江陵少尹"],["古注·《杜詩詳註》","此舟行有感杜臆起语突然悲不自胜言已之飘流无定皆因乱离所致今身弃途穷将安托乎申㴠光曰更欲投何处穷途堪涕干戈送老儒暮景足悲贾谊云何必怀此都嵇绍土木形骸老子圣人尝善救人故无弃物"],["古注·《杜詩詳註》","此抚景言情雨洗二句南浦之景鸣螿二句秋候之景谋栖托而不能安卧总为饥寒所驱耳杜臆人少相呴之沫而已亦旷於报恩之珠见人情不足深怪与一味责人者不同谢朓诗雨洗花叶鲜尔雅注蜺一名寒蜩又名寒螿似蝉而小青赤赵曰螿得梗而托之故随泛梗而鸣世説谢公与王右军书敬和栖托好佳徐悱诗向隅独心伤庄子鱼相呴以湿相濡以沫洙曰隋侯见伤蛇以药封之蛇衔明珠以报"],["古注·《杜詩詳註》","末乃叙怀别郑杜臆见雁影而问南征对鲸波而想东逝所徃尚未定耳商歌卞泣知已难逢也每有经过便思郑尹为其能酌酒以慰旅情如前此两饮湖亭皆是此章三叚各八句谢灵运诗溟涨无端倪曹植诗乗桴何所志吁嗟我孔公寗戚商歌注见二十巻韩非子卞和得玊璞以献楚王王刖其足乃抱璞而哭於荆山之下苏武诗愿子留斟酌叙此平生亲"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11908":["江南逢李龟年","杜甫","七言绝句","大历五年（770）春","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["歧王宅里寻常见，崔九堂前几度闻。","正是江南好风景，落花时节又逢君。"],"李龟年为开元、天宝间著名音乐家，深得玄宗宠遇。安史乱后流落江南。大历五年（770）春，杜甫漂泊至潭州（今湖南长沙），与李龟年重逢，感盛衰之变，遂作此诗。此为杜甫卒年之作。",[["1. **岐王**","玄宗之弟李范，封岐王，好文艺。"],["2. **崔九**","崔涤，玄宗宠臣，排行第九。"],["3. **江南**","此指湖南长沙一带。"],["4. **落花时节**","暮春三月，落花纷飞之时。"],["古评·《唐诗镜》","自注云崔九即殿中监崔涤中书令湜之子"],["古注·《杜詩詳註》","友议作值"],["古注·《杜詩詳註》","此诗抚今思昔世境之离乱人情之聚散皆寓於其中明皇杂録天寳中上命官中女子数百人为梨园弟子皆居宜春院北上案晓音律时有马仙期李龟年贺怀智皆洞知律度安禄山亦献白玉箫管数百事皆陈於梨园自是音响殆不类人间而龟年特承恩遇其後流落江南每遇良辰胜景常为人歌数阕座上闻之莫不掩泣罢酒蔡曰云溪友议李龟年奔江潭曾於湖南采访使筵上唱红豆生南国秋来发几枝赠公多采摘此物最相思又云清风明月苦相思荡子从戎十载余征人去日殷懃嘱归雁来时数附书此词皆王维所作也旧唐书岐王范睿宗子好学工书雅爱文章之士开元十四年病薨原注崔九即殿中监崔涤中书令湜之弟旧书崔湜弟涤与𤣥宗叹密用为秘书监出入禁中後赐名澄开元十四年卒世说过江诸人新亭饮宴周顗中座而叹曰风景不殊正自有山河之异黄鹤云开元十四年公止十五嵗其时未有梨园弟子公见李龟年必在天寳十载後诗云岐王当指嗣岐王珍据此则所云崔九堂前者亦当指崔氏旧堂耳不然岐王崔九并卒於开元十四年安得与龟年同逰耶"]],{"source":"据萧涤非《唐诗鉴赏辞典》“江南逢李龟年”条（上海辞书出版社，1983 年版）","body":["此诗以相逢写盛衰之慨。前二句“岐王宅里寻常见，崔九堂前几度闻”追忆开元盛世。岐王宅、崔九堂，皆是当年文艺胜地；李龟年之歌声，亦是当年最盛之音。“寻常见”“几度闻”二语，看似平淡，却写出当年之繁华——如此人物、如此胜地、如此歌声，皆是寻常可见、几度可闻之事。然此繁华已随安史之乱而逝，不可复得。","后二句“正是江南好风景，落花时节又逢君”转入现实。江南好风景，本是赏心乐事；然“落花时节”四字，已含暮春之衰意；“又逢君”三字，更含身世之慨——昔日王宅常客，今日落魄江南；昔日皇家乐师，今日流落民间。全诗无一字言悲而悲意自见，正是杜甫七绝之绝唱。"]},[],["https://github.com/chinese-poetry/chinese-poetry","据萧涤非《唐诗鉴赏辞典》“江南逢李龟年”条（上海辞书出版社，1983 年版）","《全唐诗》（清·曹寅等编，康熙扬州诗局本）","古籍注评：《唐诗镜》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩鏡_(四庫全書本)）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11909":["官亭夕坐戏简颜十少府","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["南国调寒杵，西江浸日车。","客愁连蟋蟀，亭古带蒹葭。","不返青丝鞚，虚烧夜烛花。","老翁须地主，细细酌流霞。"],"",[["古注·《杜詩詳註》","年月同上顾注时公在官亭夕坐侯少府不至故戏为此简汉章帝诏过止官亭无雇舎宿"],["古注·《杜詩詳註》","上四亭前夕景记其闻见下四坐待少府戏简索饮也杵声应节故曰调日影沈江故曰浸顾注用一连字倍增客情凄切用一带字愈觉亭畔苍凉鞚疑不返恐留客无人烛曰虚烧恐灯前无酒故有落句为戏庾信捣衣诗南国女郎砧调声不用琴杜臆捣衣杵有音节俗谓之花练槌司空曙诗宫响传花杵即此意也又云西江即蜀江诗十月蟋蟀入我床下又业葭苍苍白露为霜梁元帝诗宛转青丝鞚流霞注见十七巻"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11910":["秋日荆南述怀三十韵","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["昔承推奖分，媿匪挺生材。","迟暮宫臣忝，艰危衮职陪。","扬镳随日驭，折槛出云台。","罪戾宽犹活，干戈塞未开。","星霜玄鸟变，身世白驹催。","伏枕因超忽，扁舟任往来。","九钻巴噀火，三蛰楚祠雷。","望帝传应实，昭王问不回。","蛟螭深作横，豺虎乱雄猜。","素业行已矣，浮名安在哉？","琴乌曲怨愤，庭鹤舞摧颓。","秋雨漫湘水，阴风过岭梅。","苦摇求食尾，常曝报恩顋。","结舌防谗柄，探肠有祸胎。","苍茫步兵哭，展转仲宣哀。","饥籍家家米，愁徵处处杯。","休爲贫士叹，任受衆人咍。","得丧初难识，荣枯划易该。","差池分组冕，合沓起蒿莱。","不必伊周地，皆知屈宋才。","汉庭和异域，晋史坼中台。","霸业寻常体，忠臣忌讳灾。","羣公纷戮力，圣虑窅裴回。","数见铭锺鼎，真宜法斗魁。","愿闻锋镝铸，莫使栋梁摧。","盘石圭多翦，凶门毂少推。","垂旒资穆穆，祝网但恢恢。","赤雀飜然至，黄龙讵假媒。","贤非梦傅野，隐类凿颜坯。","自古江湖客，冥心苦死灰。"],"",[["古注·《杜詩詳註》","此记漂泊蜀䕫之迹超忽句承上星霜身世徃来句起下巴火楚雷望帝昭王又承巴楚遗事蛟螭豺虎比悍将羣盗素业浮名叹已志莫伸黄希曰公以乾元入蜀於大厯二年下峡是九钻火也自大厯元年秋至云安於大厯三年春下峡是三蛰雷也月令二月𤣥鸟至八月𤣥鸟归史记魏豹谓郦生曰人生一世间如白驹过隙耳超忽言时光倐忽谢灵运诗虚舟有超忽九钻句即钻燧改火意兼用栾巴噀酒为雨灭火成都事月令八月雷乃收声故曰蛰望帝化为杜䳌注见前左传昭王南征而不复君其问诸水滨湘中记益阳有昭潭其下无底湘水最深处或谓昭王没於此潭因以为名晋书陆纳怒兄子俶曰秽我素业"],["古注·《杜詩詳註》","此乃慨叹时事贫士二句承上文得䘮二句起下文杜臆划易该言划然之间荣枯易见如组冕起自蒿莱崛起者得官矣伊周不皆屈宋枢要皆武夫矣师氏曰是时官资滥进宿徳元勲多摈弃不用数语葢以讽也胡震亨曰和异域言囘纥和亲坼中台言房琯道卒霸业句言和亲乃汉道杂霸非国体之正宗臣句言房琯建诸王分鎭之议触肃宗忌讳而得祸何云曰广徳元年房琯病卒於阆州其年六月囘纥登里可汗归蕃皆代宗初元事故牵连书之楚辞注楚人谓相啁笑曰咍汉苟奴传髙帝出白登围使刘敬结和亲之约庾信伤王褒诗岂意中台坼君当风烛前晋书中台星坼张华被诛史记晋文公初立欲修霸业诸葛武侯传霸业可成前汉李寻传开大明除忌讳後汉郎顗疏禀性愚戅不识忌讳魏志魏顗传犯顔色触忌讳"],["古注·《杜詩詳註》","此望朝政更新也言今者羣臣协力圣主焦思在诸将虽勒名钟鼎尚宜法斗魁以卫宸极愿闻以下乃进䇿也销锋镝生民可以休息选栋梁相臣毋用凡材多剪圭同姓自此蟠固少推毂藩鎭免於跋扈且垂旒而法无为祝网以寛文法则赤雀黄龙嘉祥自致而天下可治平矣博议此段自属泛论不必复主房琯窅深目也庾信集功烈则钟鼎俱铭晋天文志北斗七星在太微北魁四星为璿玑杓三星为玉衡杓南三星及魁第一星西三星皆曰三公主宣徳化调七政和阴阳之官也始皇本纪秦收天下兵聚之咸阳销锋镝铸金人十二以弱天下之兵卫玠卒谢琨哭之曰栋梁折不觉哀晋陆抗拜司空谓宾客曰以我为三公是天下无人矣索酒着柱间祝曰当今之才以尔为柱石之臣莫倾人栋梁汉书髙祖封王子弟地犬牙相制所谓磬石之宗也史记成王封康叔剪桐叶为圭淮南子大将受命已则设明衣剪指爪凿凶门而出冯唐传上古王者之遣将也跪而推毂说文旒垂玉也记衮冕王十二旒诗天子穆穆又穆穆皇皇宜君宜王古史成汤祝网老子天恢恢疎而不漏春秋考异邮黄帝将起有黄雀赤头立日旁尚书中𠉀赤雀衔丹书入丰止於"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11911":["秋日荆南送石首薛明府辞满告别奉寄薛尚书颂德敍怀斐然之作三十韵","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["南征爲客久，西候别君初。","岁满归凫舄，秋来把雁书。","荆门留美化，姜被就离居。","闻道和亲人，垂名报国余。","连枝不日竝，八座几时除。","往者胡星孛，恭惟汉网疎。","风尘相澒洞，天地一丘墟。","殿瓦鸳鸯坼，宫帘翡翠虚。","钩陈摧徼道，枪櫐失储胥。","文物陪巡守，亲贤病拮据。","公时呵䝟貐，首唱却鲸鱼。","势惬宗萧相，材非一范雎。","屍填太行道，血走浚仪渠。","滏口师仍会，函关愤已摅。","紫微临大角，皇极正乘舆。","赏从频峨冕，殊私再直庐。","岂惟高卫霍，曾是接应徐。","降集飜翔凤，追攀绝衆狙。","侍臣双宋玉，战策两穰苴。","鉴澈劳悬镜，荒芜已荷锄。","向来披述作，重此忆吹嘘。","白发甘凋丧，青云亦卷舒。","经纶功不朽，跋涉体何如。","应讶耽湖橘，常餐占野蔬。","十年婴药饵，万里狎樵渔。","扬子淹投阁，邹生惜曳裾。","但惊飞熠耀，不记改蟾蜍。","烟雨封巫峡，江淮略孟诸。","汤池虽险固，辽海尚填淤。","努力输肝胆，休烦独起予。"],"",[["古注·《杜詩詳註》","此叙禄山陷京事禄山称乱由朝廷过宠故曰汉网疎风尘谓兵戈遍地丘墟谓城郭一空瓦坼谓天子出奔帘虚谓妃嫔皆走鈎陈指侍卫摧徼道巡徼皆散矣枪櫐指守御失储胥库藏尽亡矣陪巡谓衣冠扈从拮据谓宗室忧劳洙曰星指旄头其光四出孛孛然也汉书循吏传禁网疎濶洞箫赋风𣻳洞而不絶王粲诗崤函一丘墟邺中记邺城铜雀台皆鸳鸯瓦旧注魏文帝问晋宣王曰吾梦殿屋两瓦坠地化为鸳鸯对曰後宫当有暴死者洞㝠记汉武帝甘泉宫起招仙阁编翠羽麟毫以为帘西京杂记有翡翠帘西都赋周以鈎陈之位卫以严更之署又周庐千列徼道绮错汉书注游徼循禁备盗贼徼道徼循之道扬雄长杨赋木拥枪櫐以为储胥注枪櫐作木枪相櫐为栅也储胥言储蓄以待所须杜臆汉武帝作储胥馆故李义山诗风云长为䕶储胥宋子京诗宻疏叩储胥又秋色遍储胥俱作皇居用之任昉齐景陵行状地尊礼絶亲贤莫贰诗予手拮据"],["古注·《杜詩詳註》","音轧乙黠切"],["古注·《杜詩詳註》","此与薛尚书叙怀前八句叙薛交情後十句自叙旅况言尚书有知人之鍳惜已之荒芜不足有为也述作中见其吹嘘所谓鍳彻也白头无意於青云所谓荒芜也经纶指薛能戡乱跋涉谓薛曾和蕃湖橘四语述贫病流离之状淹投阁乆於蜀惜曵裾不干人熠燿飞而岁忽换故可惊蟾蜍改而月频移故不记也自峡至荆又将渡江淮过孟诸而北归矣朱注悬镜如氷镜之悬也秦嘉诗明镜可鍳形陶潜诗眷言终荷锄魏文帝与吴质书斐然有述作意原注石首处见公新文一通史记范雎传须贾曰君能自致青云之上易君子以经纶诗大夫跋涉潭州有橘洲诗熠燿宵行注萤火也张载诗下车如昨日蟾蜍四五圆禹贡导荷泽被孟诸尔雅十薮宋有孟诸郭璞注在睢阳县东北"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11912":["哭李尚书","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["漳滨与蒿里，逝水竟同年。","欲挂留徐劒，犹回忆戴船。","相知成白首，此别间黄泉。","风雨嗟何及，江湖涕泫然。","修文将管辂，奉使失张骞。","史阁行人在，诗家秀句传。","客亭鞍马绝，旅榇网虫悬。","复魄昭丘远，归魂素滻偏。","樵苏封葬地，喉舌罢朝天。","秋色凋春草，王孙若个边。"],"",[["古注·《杜詩詳註》","之芳鹤注诗当作於大厯三年秋江陵府考宗室世系表之芳乃蒋王恽之孙又旧史云安禄山奏为范阳司马禄山反自投归京师广德二年兼御史大夫使吐蕃被留二岁乃得归拜礼部尚书改太子宾客黄生曰时公在公安而李殁於江陵"],["古注·《杜詩詳註》","英华作把"],["古注·《杜詩詳註》","从哀死叙起得病随亡故曰同年挂剑将赴吊回船不果行也刘桢诗余婴沈痼疾窜身清漳滨洙曰魏文帝为太子时应瑒刘桢并见友善李厯礼部尚书薨於太子宾客故用漳滨事蒿里注见十六巻挂剑注见十四巻戴船注见九巻"],["古注·《杜詩詳註》","此记交情遗事风雨思友又值江湖更觉哀惨矣修文言精灵不没奉使指出使吐蕃下二分承潘岳诗投分寄石友白首同所归左传郑庄公曰不及黄泉无相见也诗风雨凄凄序风雨思君子也诗何嗟及矣文中子然流涕顔回卜商为地下修文郎注见十四巻魏志管辂字公明平原人举秀才谓弟辰曰天与我才明不与我年夀恐四十七八间不见女嫁男婚也是岁八月为少府丞明年二月卒年四十八杜臆修文句兼用两事周礼秋官有大行人小行人锺嵘诗品竒章秀句徃徃警遒"],["古注·《杜詩詳註》","末伤其客死逺归也马絶虫悬见空舘荒凉昭邱素滻言归途辽濶喉舌㸃尚书秋色㸃时景王孙切李姓若个边言塟於旧垒之傍此章前叚四句中後八句沈约诗网虫垂户织记复诸侯以襃衣郑司农曰复谓始死招魂复魄也昭邱楚昭王墓潘岳西征赋地有𤣥灞素滻任昉卞忠贞墓启樵苏之刑逺流於皇代後汉李固传斗为天之喉舌尚书亦犹陛下之喉舌楚辞招隐王孙游兮不归春草生兮萋萋若个唐人方言沈佺期诗京华若个边"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11913":["重题","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["涕泗不能收，哭君余白头。","儿童相识尽，宇宙此生浮。","江雨铭旌湿，湖风井径秋。","还瞻魏太子，宾客减应刘。"],"",[["古注·《杜詩詳註》","涕不能収拈重哭意下三句有身世无穷之悲江湖风雨对景凄然客减应刘李为太子宾客也申㴠光曰哭李尚书二首是挽诗絶调儿童相识尽哭及衆友宇宙此生浮兼哭自已矣黄注三四申明余字意何逊诗萧萧江雨声攉弓铭者旌也以死者为不可别已故以其旌识之芜城赋边风起兮城上寒井径灭兮邱壠残注九夫为井遂上有径黄生注井径似指隧道今形家目穴内为金井原注李公薨於太子宾客魏文帝与呉质书徐陈应刘一时俱逝"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11914":["独坐","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["悲愁回白首，倚杖背孤城。","江敛洲渚出，天虚风物清。","沧溟服衰谢，朱绂负平生。","仰羡黄昏鸟，投林羽翮轻。"],"",[["古注·《杜詩詳註》","一作服非"],["古注·《杜詩詳註》","上四独坐秋景下四独坐感懐楚辞收潦而水清此江敛洲渚出所自来天高而气清此天虚风物清所自出投林羽翮轻即还入故林栖意谢灵运诗萧条洲渚际国语风物以听之沧溟指江村文选浩浩沧溟何逊诗相顾无羽翮何由总奋飞"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11915":["暮归","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["霜黄碧梧白鹤楼，城上击拆复乌啼。","客子入门月皎皎，谁家捣练风凄凄。","南渡桂水关舟檝，北归秦川多鼓鞞。","年过半百不称意，明日看云还杖藜。"],"",[["古评·《唐诗镜》","三四语入骚意"],["古注·《杜詩詳註》","上四暮归见闻之景下四暮归流落之感一杜臆阙舟楫无钱雇船多皷鞞吐蕃为寇杖藜看云可谓安时而处顺者黄生注朝出於斯暮归於斯南渡不可北归不能年老客居失意可胜道哉起一复字结一还字见日日如是皆无可奈何之词梁鲍泉诗露色已成霜楸梧半欲黄邵氏谓鹤不木栖恐是白鹄然咏怀古迹云古庙松杉巢水鹤亦言栖木矣抱朴子千年之鹤能随时而鸣登於木上汉童謡城上乌尾毕逋易重门击柝陈後主诗乌啼汉没天应曙客子自谓史记范睢传谒君得无与诸侯客子俱来乎记客入门而左"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗镜》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩鏡_(四庫全書本)）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11916":["移居公安敬赠卫大郎","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["卫侯不易得，余病汝知之。","雅量涵高远，清襟照等夷。","平生感意气，少小爱文辞。","河海由来合，风云若有期。","形容劳宇宙，质朴谢轩墀。","自古幽人泣，留年壮士悲。","水烟通径草，秋露接园葵。","入邑豺狼鬬，伤弓鸟雀饥。","白头供宴语，乌几伴栖迟。","交态遭轻薄，今朝豁所思。"],"",[["古注·《杜詩詳註》","钧鹤注公於大厯三年秋移居公安"],["古注·《杜詩詳註》","从卫郎叙起公处贫病而卫独知之由其雅量能㴠清襟能照也者感其平时意气如江海之流易合又爱其少而能文知风云之㑹有期也余病汝知犹管仲言知我贫故也魏志曹公曰周瑜雅量高致袁粲答王俭诗老夫亦何寄之子照清襟张良传诸将皆陛下旧等夷秦嘉诗少小罹茕独锺嵘诗品文词之命世也古诗风云若遇㑹"],["古注·《杜詩詳註》","此叙公安旅况谢轩墀作幽人遁迹劳宇宙则流年已逝水烟秋露言风景凄凉狼鬬慨世乱雀饥伤旅穷也陶潜诗寓形宇宙复㡬时後汉傅毅传徂年如流陆士衡诗种葵北园中零露垂鲜泽"],["古注·《杜詩詳註》","以赠卫意作结宴语谁供惟伴乌几则交态之薄可知故得卫郎而忧思顿豁耳末句仍应雅量清襟此章前二叚各八句末叚四句结诗衡门之下可以栖迟"],["古注·《杜詩詳註》","卢元昌曰公在江陵至小吏相轻吾道穷矣於顔少府曰不易得於卫大郎亦曰不易得志幸亦志慨也是时公安有警故於山舘有世乱敢求安句後晓发则曰邻鸡野哭如昨日发刘郎浦则曰㟁上空村尽豺虎此章入邑豺狼鬬必有所指矣"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11917":["公安送韦二少府匡赞","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["逍遥公後世多贤，送尔维舟惜此筵。","念我能书数字至，将诗不必万人传。","时危兵甲黄尘里，日短江湖白发前。","古往今来皆涕泪，断肠分手各风烟。"],"",[["古注·《杜詩詳註》","鹤注当是大厯三年秋晚作是年吐蕃入冦故诗云兵甲黄尘邵注少府今之典史匡赞韦名也"],["古注·《杜詩詳註》","俗本作别"],["古注·《杜詩詳註》","一作常能"],["古注·《杜詩詳註》","上四送韦之情下四离别之感演义韦盖後辈而知慕公者故起用朴直之词诗不必传旧指韦诗演义谓公诗多伤时语故嘱其不必浪传时逢兵革身泊江湖白发之年短如秋日此情此景乃今古所同悲者况故人分手於风烟之际能不为之伤心而肠断乎四语叠递意极惨凄朱注唐书韦嗣立中宗亦封为逍遥公韦氏九房以夐後为逍遥公房嗣立後为小逍遥公房田注此诗所云逍遥公指韦夐也北史周韦夐养高不仕明帝号为逍遥公潘岳西征赋古徃今来邈矣悠哉谢瞻送王抚军诗分手东城闉别赋造分手而衔涕"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11918":["赠虞十五司马","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["远师虞秘监，今喜识玄孙。","形像丹青逼，家声器宇存。","凄凉怜笔势，浩荡问词源。","爽气金天豁，清谈玉露繁。","伫鸣南岳凤，欲化北溟鲲。","交态知浮俗，儒流不异门。","过逢联客位，日夜倒芳尊。","沙岸风吹叶，云江月上轩。","百年嗟已半，四座敢辞喧。","书籍终相与，青山隔故园。"],"",[["古注·《杜詩詳註》","上叙虞氏渊源卢注师秘监师其书法也公九龄作大字平日能书可知形象逼丹青以孙比祖家声存器宇自祖及孙也笔势词源追怀秘监爽气以下称美司马金天玉露借秋景为喻南鳯北鲲言能变化飞腾唐书虞世南余姚人太宗践阼迁太子右庶子固辞改为秘书监封永兴县子世南殁太宗勅图其像於凌烟阁唐书时称世南五絶四曰文词五曰书翰王僧䖍论书崔瑗笔势甚快而结字小疎浩荡旷逺也隋艺文传笔有余力词无竭源张衡思𤣥赋顾金天而叹息兮周祗箴清谈辍响江淹赋玉露暧天董仲舒有繁露篇刘桢诗鳯凰集南岳徘徊孤竹根庄子北海"],["古注·《杜詩詳註》","有鱼名曰鲲化为大鹏"],["古注·《杜詩詳註》","上声一作在"],["古注·《杜詩詳註》","下叙彼此交情儒门不异虞杜皆旧家过逢连客位虞为主人也㟁风江月乃成都晚景四座敢辞喧同饮兴豪也赠书於故园言两人相期北归或特过或偶逢皆与诸客连位而饮正见司马好客与俗交有别杜臆谓虞杜作客而饮他人者非是此章两叚各十句前汉艺文志儒家者流顔延之诗家崇儒门沈约诗客位紫苔生晋史论刘毕芳樽之交鲍照诗野旷沙㟁静别赋月上轩而飞光古乐府四座乐且康魏志蔡邕闻王粲在门倒屣迎之谓座客曰此王公孙也有异才吾家书籍文章尽当与之"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11919":["公安县怀古","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["野旷吕蒙营，江深刘备城。","寒天催日短，风浪与云平。","洒落君臣契，飞腾战伐名。","维舟倚前浦，长啸一含情。"],"",[["古注·《杜詩詳註》","首二遗迹三四时景下述怀古之意野旷寒侵江深浪激刘合君臣吕争战伐四句各用分承长啸含情伤迹在而人已亡矣胡夏客云此啸从抱膝吟梁父化出先主之待关张谊同兄弟其得孔明欢如鱼水所谓洒落君臣契也吕䝉之破皖城军士皆腾跃而升其擒庐陵贼帅孙权称其百鸟不如一鹗所谓飞腾战伐名也黄生注结以前浦二字绾住前半以含情二字双绾後半章法极整寰宇记公安县有孱陵城十三州志呉大帝封吕䝉为孱陵侯即此地水经注洈水东至孱陵县入油水县治故城王莽更名孱陵刘备孙夫人权妹也又更修之其城背油向泽荆州记吴大帝推刘备为左将军荆州牧镇油口即居此城时人号为左公故名其城公安也名胜志公安县北二十五里有吕䝉城即䝉所屯兵处阮籍见孙登长啸而返啸蹙口出声也先主得公安使关羽守之及羽讨樊城吕䝉乗虚袭之孙刘之战争始自公安汉业之不振亦挠於公安公至其地故吊古而有慨近年常州吕城之处有修关壮缪庙掘地得吕䝉墓者千年奸窟一朝发露事竒而快"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11920":["公安送李二十九弟晋肃入蜀余下沔鄂","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["正解柴桑缆，仍看蜀道行。","樯乌相背发，塞雁一行鸣。","南纪连铜柱，西江接锦城。","凭将百钱卜，飘泊问君平。"],"",[["古注·《杜詩詳註》","鹤注此大厯三年冬作晋肃李贺之父见韩文辩讳唐书沔州汉阳郡鄂州江夏郡俱属江南西道後并沔州入鄂郡"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11921":["宴王使君宅题二首 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["汉主追韩信，苍生起谢安。","吾徒自漂泊，世事各艰难。","逆旅招邀近，他乡思绪宽。","不材甘朽质，高卧岂泥蟠。"],"",[["古注·《杜詩詳註》","鹤注当是大厯三年秋作邵注王必荆州人闲居邑中者"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11922":["宴王使君宅题二首 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["泛爱容霜发，留欢卜夜闲。","自吟诗送老，相劝酒开颜。","戎马今何地，乡园独旧山。","江湖堕清月，酩酊任扶还。"],"",[["古注·《杜詩詳註》","一作阑一作上夜关"],["古注·《杜詩詳註》","次章𡨋时之兴爱而留宴徳使君也送老承霜鬓开顔顶留欢今当戎马之地使君独有故园不觉留连而醉归耳五六㸃王宅杜臆公诗毎用泛爱盖以衆人自居也前汉伍被传泛爱烝庶後汉书李轶曰刘伯升兄弟泛爱容衆殷仲文诗广筵散泛爱英华辩证世传杜公不避家讳其实非也卞圜集杜诗及别本自是留欢上夜关盖有投辖之意或改作夜阑人不在韵卢注王维登裴廸小楼云好客作乗月应门莫上关顾炎武曰闲乃闲暇於闲字自不相犯谢灵运诗开顔披心胸"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11923":["留别公安太易沙门","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["隐居欲就庐山远，丽藻初逢休上人。","数问舟航留制作，长开箧笥拟心神。","沙村白雪仍含冻，江县红梅已放春。","先蹋炉峰置兰若，徐飞锡杖出风尘。"],"",[["古注·《杜詩詳註》","上四赞太易诗词五六志相别时地末则望其修道庐山也泽州陈冡宰云末二句言太易当筑室罏峰以俟道成飞举旧解谓公欲先徃庐山置寺以待太易之来遂引志公争山𪋤事以证飞锡其説非也此本用庐山神仙事庐山在江西九江府周武王时匡俗先生兄弟七人隐於此因号匡庐山晋恵逺姓贾氏见庐山清净遂"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11924":["晓发公安","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["北城击柝复欲罢，东方明星亦不迟。","邻鸡野哭如昨日，物色生态能几时。","舟檝眇然自此去，江湖远适无前期。","出门转眄已陈迹，药饵扶吾随所之。"],"此以古诗行七律者",[["古评·《唐诗镜》","此以古诗行七律者"],["古评·《唐诗镜》","附阁夜歳暮隂阳催短景天涯霜雪霁寒宵五更鼔角声悲壮三峡星河影动揺野哭千家闻战伐夷歌㡬处起渔樵卧龙跃马终黄土人事音书漫寂寥三四意尽无余"],["古评·《唐诗镜》","附咏懐古迹支离东北风尘际漂泊西南天地间三峡楼台淹日月五谿衣服共云山羯胡事主终无赖词客哀时且未还庾信平生最萧瑟暮年诗赋动江闗"],["古注·《杜詩詳註》","一云生生"],["古注·《杜詩詳註》","上四晓景叹流光易逝下四发舟伤行踪莫定杜律有语承意承之法不迟承欲罢几时承如昨此句承法也隣鸡承撃柝以所闻言物色承明星以所见言此意承法也物色指物生态指人陈迹指公安之地诗东有启明西有长庚注曰旦出谓明星为启明日既入谓明星为长庚晋傅𤣥诗东方大明星光景照千里顔延之诗日暮行乐归物色桑榆时乐府满歌行居世讵能㡬时刘恢传俛仰之间已为陈迹谢灵运诗药饵情所止王嗣奭曰七律之变至此而极妙亦至此而极真此山谷所云不烦绳削而自合者盖䕫州以後诗也唐人作拗体律诗平仄多有失粘处明季萧云从作杜律细平仄用转音改拗从顺虽考证详洽但恐多此转折耳如此章仄声七字改作平声欲字音迂扬雄羽猎赋壮士慷慨殊响别趋东西南北骋势奔欲桂诗五律初月首句光细欲上可证也罢字即疲叶迟在沈氏四支韵史记汉与楚相距士卒罢弊左传师退曰疲礼少仪师役曰罢方字音访汉帝欲杀雍齿用张良计封为什方侯犹言释放也又後汉杨仁拜什方令易韵水在火上君子以慎辩物居方亦音放昨字音槎周礼大宗伯鸡人诸臣之所昨注谓诸臣酢酒尊也战国䇿苏厉上赵王书着之盘盂属之讐柞注即酬酢如周礼柞人掌攻草木者与公羊传山木不槎国语木不槎枿同中原音韵昨膈宵也曲有人作平声而分阴阳北音精戈翻南音静罗翻皆平声尔态音台司马相如封禅文𪰋𪰋穆穆君子之态盖闻其声今视其来态作台音可证自当音私説文曰仓颉作字自营为私虽不解为私音而㑹意当然耳杜五律风月自清夜及致此自僻逺皆宜作平声用矣已字音遗元人侯正卿菩萨蛮第二句心头已作平声阳音杜五律乗尔亦已乆亦读平声今按态读作台音则能字宜读作耐平仄乃各谐也"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗镜》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩鏡_(四庫全書本)）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11925":["泊岳阳城下","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["江国踰千里，山城仅百层。","岸风飜夕浪，舟雪洒寒灯。","留滞才难尽，艰危气益增。","图南未可料，变化有鲲鹏。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11926":["缆船苦风戏题四韵奉简郑十三判官","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["楚岸朔风疾，天寒鶬鸹呼。","涨沙霾草树，舞雪渡江湖。","吹帽时时落，维舟日日孤。","因声置驿外，爲觅酒家垆。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11927":["登岳阳楼","杜甫","五言律诗","大历三年（768）冬","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["昔闻洞庭水，今上岳阳楼。","吴楚东南坼，乾坤日夜浮。","亲朋无一字，老病有孤舟。","戎马关山北，凭轩涕泗流。"],"大历三年（768）冬，杜甫自夔州出峡，漂泊至岳州（今湖南岳阳），登岳阳楼而作此诗。其时杜甫已五十七岁，老病交加，亲友隔绝，又值吐蕃入侵，国事艰难，登楼远眺，感慨万千。",[["1. **岳阳楼**","在今湖南岳阳城西门城楼上，下临洞庭湖。"],["2. **坼**","分裂。言洞庭湖将吴楚之地分裂于东南。"],["3. **乾坤**","天地。"],["4. **戎马**","战争。时吐蕃入侵，西北边境不宁。"],["5. **凭轩**","倚靠窗栏。"],["古评·《唐诗品汇》","下岳阳所作"],["古评·《唐诗品汇》","刘云气压百代为五言雄浑之絶"],["古注·《杜詩詳註》","鹤注当是大厯三年作岳阳风土记岳阳楼城西门楼也下瞰洞庭景物寛濶卢注是年郭子仪将兵五万屯奉天备吐蕃白元光李抱玉各出兵撃之是戎马关山北也"],["古注·《杜詩詳註》","上四写景下四言情昔闻今上喜初登也包呉楚而浸乾坤此状楼前水势下则只身漂泊之感万里乡关之思皆动於此矣杜臆三四已尽大观後来诗人何处措手下四只写情方是做自已诗非泛咏岳阳楼也黄生曰末以凭轩二字绾合登楼国䇿呉起曰左有彭蠡之波右有洞庭之水叶秉敬曰或疑洞庭楚地何逺及於呉考荆州记君山在洞庭湖中上有道通呉之包山今呉之太湖亦有洞庭山以潜通君山故得名或疑乾坤日夜浮有似咏海考水经注洞庭湖广五百里日月若出没其中又拾遗记洞庭山浮於水上方知杜句所云皆是洞庭本色三辅黄图南极呉楚史记赵世家地坼东南谢朓诗大江日夜流又有酒招亲朋归去来辞或棹孤舟道德经戎马生於郊恨赋关山无极登楼赋凭轩槛以遥望兮张载诗登崕逺望涕泗流鼻出曰涕目出曰泗"]],{"source":"如君山","body":["写洞庭景观，纯系大处落墨。湖在春秋时属楚国，与吴国无关，但三国时孙吴已奄有洞庭，故“吴楚”并提，也是有依据的，但讲为吴楚以湖分界就不妥了。按“坼”是裂陷的意思，所谓“东南坼”即《淮南子•天文训》“地不满东南，故水潦尘埃归焉”的意思。所以下句就写其孕大涵深，“乾坤日夜浮”是说天上地下（如君山）的景象一齐纳入湖中，即“涵虚混太清”“上下天光，一碧万顷”，“浮”字写得动荡如见。这里的东南，当然是个相对方位。诗句也反映出诗人胸次的豁达，能使读者受到同样的感染。黄生读此，谓“不知少陵胸中，吞几云梦也”（《杜诗说》）。","三联直抒胸臆，多年战乱和漂泊，亲朋的书信往来是完全断绝，用“无一字”来表达这样的意思，尤见沉痛。诗人时年五十七，已一身是病（肺病、疟疾、风痹），终日生活在水上、船中，除了孤舟一叶，便一无所有，而诗人自己也就好比是一叶孤舟。清代诗人查慎行说：“于开阔处俯仰一身，凄然欲绝。”极是。盖境界的空阔，往往能加强人的孤独之感。如陈子昂登幽州台然。","最后提到国事，并为之涕泗纵横，是已超越一己之困顿，与三联处境狭阔顿异，而与次联写景的胸襟气象，正好相称。本篇笔力、胸次境界俱上，在刻满岳阳楼的“唐贤今人诗赋”中，洵为杰作。"]},[["吴楚东南坼，乾坤日夜浮。","写洞庭湖之壮阔，千古名句。"]],["https://github.com/chinese-poetry/chinese-poetry","据霍松林《唐诗鉴赏辞典》“登岳阳楼”条（上海辞书出版社，1983 年版）","《全唐诗》（清·曹寅等编，康熙扬州诗局本）","古籍注评：《唐诗品彚（附唐诗拾遗）》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩品彚_(四庫全書本)）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11928":["陪裴使君登岳阳楼","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["湖阔兼云雾，楼孤属晚晴。","礼加徐孺子，诗接谢宣城。","雪岸丛梅发，春泥百草生。","敢违渔父问，从此更南征。"],"",[["古注·《杜詩詳註》","首二登岳阳楼三四陪裴使君五六楼前春景七八自叙行踪此虚实相间格也一日之间阴晴迭换亦见登眺之乆黄生谓可当岳阳楼图是也徐穉自方谢朓比裴屈原至江滨涣父劝其与世推移公旅况依人故不敢违渔父之问而更欲南征南征指潭州杜臆落句深有意於裴言已不异屈原之放逐渔父倘肯见问岂敢违之而更南征乎此另一説濶与孤相照属当也後汉徐孺子豫章南昌人时陈蕃为太守以礼请署功曹谢朓传除秘书丞未拜仍转中书郎出为宣城太守楚辞屈原既放游於江潭渔父见而问之离騒济沅湘兮南征"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11929":["过南岳入洞庭湖","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["洪波忽争道，岸转异江湖。","鄂渚分云树，衡山引舳舻。","翠牙穿裛桨，碧节上寒蒲。","病渴身何去，春生力更无。","壤童犂雨雪，渔屋架泥涂。","欹侧风帆满，微冥水驿孤。","悠悠回赤壁，浩浩略苍梧。","帝子留遗恨，曹公屈壮图。","圣朝光御极，残孽驻艰虞。","才淑随厮养，名贤隐锻鑪。","邵平元入汉，张翰後归吴。","莫怪啼痕数，危樯逐夜乌。"],"",[["古注·《杜詩詳註》","此舟过南岳也湖水争道而趋以江湖异流故也鄂在北故曰分衡在南故曰引二句言江湖之异蒋牙蒲节春时景物谢灵运诗莫辩洪波极谁知大壑东吴越春秋二国争道楚辞乗鄂渚而返顾兮九州记鄂今武昌是也孙权自公安徙此改曰武昌刘孝威诗云树交为宻汉武帝纪舳舻千里説文舳舟尾舻舟前赵注蒋乃菰蒋之蒋盖蒲有节而蒋有牙也准南子浸潭苽蒋苽者蒋实也唐雅菰蒋其米谓之胡裛蒋蒋之瘦而未壮者"],["古注·《杜詩詳註》","此入洞庭湖也壤童二句近㟁景事风健则帆饱而舟带欹斜行速故回顾而水驿微小帝子承苍梧曹公承赤壁此逺览古迹也赵注赤壁在夏口之东武昌之西盛𢎞之荆州记薄沂县沿江一百里南㟁名赤壁赵注苍梧在洞庭西南九域志苍梧山在道州九歌帝子降兮北渚帝子指娥皇女英史记舜南巡狩崩於苍梧之野後汉献帝纪刘表卒少子琮立以荆州降操操以舟师伐孙权周瑜传瑜请得精兵三万人追徃夏口遇於赤壁大破之"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11930":["宿青草湖","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["洞庭犹在目，青草续爲名。","宿桨依农事，邮签报水程。","寒冰争倚薄，云月递微明。","湖雁双双起，人来故北征。"],"",[["古注·《杜詩詳註》","上四宿湖之事下四对景言情南有青草北为洞庭一湖两名故曰续为名孤舟防盗故须宿依农畔水程夜泊故閵驿报更筹倚薄曰争见寒冰交侵而竞廹微明曰递见云月迭掩而迭开黄生注末㸃湖字前面青草方不落空此见诗律之细顾注湖雁双飞而起岂为我之南征故意以北征示人耶见南行非木愿矣朱注邮籖驿馆更筹也隋炀帝诗投籖初报晚倚薄之薄即雷风相薄之薄言廹也杜臆月令正月侯雁北故云北征王融诗秋雁双双飞楚辞九歌驾飞龙兮北征邅吾道兮洞庭"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11931":["宿白沙驿","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["水宿仍余照，人烟复此亭。","驿边沙旧白，湖外草新青。","万象皆春气，孤槎自客星。","随波无限月，的的近南溟。"],"",[["古注·《杜詩詳註》","鹤注年月同上洙曰初过湖五里顾注湘中记湘川清照五六丈下见底石如樗蒲五色鲜明白沙如霜雪赤崕如朝霞"],["古注·《杜詩詳註》","一作景一作好"],["古注·《杜詩詳註》","上四白沙驿景下四宿驿有感黄生注曰仍曰复见水程非止一日三四即景因地见时五六即景借物形已巧法兼备前诗先见地後宿字此诗反之是章法变化处水含残照亭起夕烟此将晚之候白沙驿名青草湖名拆开用之倒装以协韵耳赵汸注皆春气见各有生意自客星见已独飘零按二句乃一进一退格楼钥云的的昭着貎谓乗月之明以到南溟也谢灵运诗客游倦水宿哀江南赋舟楫路穷星汉非乗槎可上黄注此反用之梁简文帝水月诗溶溶如溃璧的的似沈鈎呉均望新月诗的的与沙静灔灔逐波轻宋之问寒宵引明月的的寒潭中杜臆庄子南溟者天池也本属寓言此将虚语作实用妙在的的二字此用古之一法"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11932":["湘夫人祠","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["肃肃湘妃庙，空墙碧水春。","虫书玉佩藓，燕舞翠帷尘。","晚泊登汀树，微馨借渚苹。","苍梧恨不尽，染泪在丛筠。"],"",[["古注·《杜詩詳註》","鹤注此大厯四年春作祠在长沙府湘阴县山海经洞庭之山帝之二女居之檀弓舜塟於苍梧之野三妃未之从也陈澔注舜长妃娥皇次妃女英三妃癸比从尧而言皆谓帝子从舜而言皆谓之妃其曰湘君湘夫人者後人从湘起见以水神尊之水经注太湖水西流迳二妃庙南世谓之黄陵庙大舜之陟方也二妃从征溺於湘江神游洞庭之渊出入潇湘之浦民为立祠水侧焉"],["古注·《杜詩詳註》","一作香惜"],["古注·《杜詩詳註》","上四祠中之景记其凄凉下四祠外之景致其感慨首句𭶑祠次句记时苹树斑筠皆出祠後所触目而徘徊者杜臆臣望君不减妻望夫苍梧之恨不为夫人发也诗肃肃在庙虫书虫蚀如字书卫恒书势四曰虫书生注微馨用黍稷馨香渚苹用苹蘩可荐不曰荐而曰借表已欲荐之诚耳博物志舜南巡崩於苍梧二妃泪下染竹成斑"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11933":["祠南夕望","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["百丈牵江色，孤舟泛日斜。","兴来犹杖屦，目断更云沙。","山鬼迷春竹，湘娥倚暮花。","湖南清绝地，万古一长嗟。"],"",[["古注·《杜詩詳註》","公既谒湘夫人祠次夕在祠南回望也"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11934":["登白马潭","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["水生春缆没，日出野船开。","宿鸟行犹去，丛花笑不来。","人人伤白首，处处接金杯。","莫道新知要，南征且未回。"],"",[["古注·《杜詩詳註》","赵注白马潭在潭州顾注岳州巴陵县有白马湖水经注江水又东迳彭城口北对隐矶二矶之间有巨石孤立大江中东江浦世谓之白马口李白诗侧叠万古石横为白马矶诗云日出野船开明是潭前发舟杜臆谓潭在上水故云登於诗不合"],["古注·《杜詩詳註》","一作花丛"],["古注·《杜詩詳註》","义从平声读用去声"],["古注·《杜詩詳註》","上四记发舟景物下四叙经潭情事上实下虚格杜臆春水方生故系缆浸没逆流难上故日出方开此时宿鸟之成行者犹且先我而去水花之带笑者不肯向舟而来见逆水行舟之难也客舟难进如此纵使人人伤我白首处处接我金盃亦莫道新知为要事只管南征而未回也後半作虚拟之词不然艰危作逺客安得到处金盃乎呉志孙权传注权为牋与曹公春水方生公宜速去杜诗背指菊花开状顺流之速水花笑不来指逆流之迟楚辞乐莫乐兮新相知旧解要为要事新説作招要解"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11935":["归雁","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["闻道今春雁，南归自广州。","见花辞涨海，避雪到罗浮。","是物关兵气，何时免客愁。","年年霜露隔，不过五湖秋。"],"",[["古注·《杜詩詳註》","唐㑹要大厯二年岭南节度使徐浩奏十一月二十五日当管怀集县阳雁来乞编入史从之先是五岭之外朔雁不到浩以为阳为君徳雁随阳者臣归君之象也朱注诗云闻道今春雁南归自广州正是三年春所作又云是物闗兵气何时免客愁葢浩以为祥公以为异耳"],["古注·《杜詩詳註》","上六记其异下二道其常辞涨海言今春之去到罗浮遡去秋之来南方地气忽寒故北雁乗秋而至此杀气之可愁者在徃时则瘴煖无霜雁飞原不过湖也衡山一阳峰以内有霜自此峰以南有露无霜矣故曰霜露隔今询之粤东人却云有霜有雁岂地气自北而南始於大厯问耶杜臆禽鸟得气之先明年潭州果有臧玠之乱桂州又有朱济之乱此与邵子洛阳闻杜鹃无异可谓具前知之见矣谢承後汉书交趾七郡士献皆从涨海出入南史扶南国东界即大涨海海中有大洲洲上有诸薄国罗浮山记罗山浮山二山合体谓之罗浮在増城博罗二县境一统志罗浮山在今惠州府连广州境後汉唐檀因南昌妇生四子古云京师当有兵气祸发萧□地志衡山一阳峰极髙雁不能过遇春北归故名𮞉雁朱注雁至衡阳则囘此五湖当指洞庭湖言史记索隐具区洮滆彭蠡青草洞庭共为五湖则洞庭正得称五湖耳"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11936":["野望","杜甫","七言律诗","宝应元年（762）秋","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["纳纳乾坤大，行行郡国遥。","云山兼五岭，风壤带三苗。","野树侵江阔，春蒲长雪消。","扁舟空老去，无补圣明朝。"],"宝应元年（762）秋，杜甫在成都。时徐知道反蜀，吐蕃入侵，西山三城戍守。杜甫出郊野望，感国事家事两难，遂作此诗。",[["1. **西山**","岷山，在成都西。"],["2. **三城**","松、维、保三州，时为防御吐蕃之要地。"],["3. **南浦**","南郊水滨。"],["4. **清江**","锦江。"],["5. **万里桥**","在成都南门外。"],["6. **风尘**","战乱。"],["7. **涓埃**","滴水微尘，喻微小之力。"],["8. **迟暮**","年老。"],["古注·《杜詩詳註》","鹤注此亦大厯四年春作张正见诗王城野望通"],["古注·《杜詩詳註》","三四逺望承上乾坤郡国五六近望起下扁舟空去中二聨虽俱属言景然细玩语意仍是四句分截五岭在南三苖在北江涨直侵野树雪消始长春蒲五六倒装句法顾注尾聨抱负甚大感慨甚深裴逊之诗纳纳江海深乐府行行重行行贾谊传乗传而行郡国舒曰秦始皇畧定扬越谪戍五方南守五岭塞上岭一也骑归岭二也都龎岭三也畧绪岭四也越城岭五也自北徂南入越之道必由岭焉元和郡国志晋怀帝分荆州湘中诸郡置湘州南以五岭为限北以洞庭为限祖𤥻诗方城殊风壤书窜三苖於三危注三苗之国左洞庭右彭蠡潭州图经潭州为三苖国之南境"]],{"source":"据马茂元《唐诗鉴赏辞典》“野望”条（上海辞书出版社，1983 年版）","body":["此诗写野望之感，忧国思家之情交织。首联“西山白雪三城戍，南浦清江万里桥”起笔写望中之景。西山白雪三城戍守，南浦清江万里桥头。上句写西望之景——边塞戒严；下句写南望之景——江桥如画。一景一情，已含忧国之意。","颔联“海内风尘诸弟隔，天涯涕泪一身遥”为名句。海内战乱，诸弟隔绝；天涯涕泪，一身漂遥。此联写尽家国之痛——战乱使兄弟分散，漂泊使一身孤独。颈联“惟将迟暮供多病，未有涓埃答圣朝”写身世之叹。惟将迟暮之年供多病之身，未有涓埃之力答圣朝之恩。此联写尽忠而不能报国之痛。尾联“跨马出郊时极目，不堪人事日萧条”以感慨作结。跨马出郊极目远望，不堪人事日渐萧条。全诗忧国思家，沉郁悲凉。"]},[],["https://github.com/chinese-poetry/chinese-poetry","据马茂元《唐诗鉴赏辞典》“野望”条（上海辞书出版社，1983 年版）","《全唐诗》（清·曹寅等编，康熙扬州诗局本）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11937":["入乔口","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["漠漠旧京远，迟迟归路赊。","残年傍水国，落日对春华。","树蜜早蠭乱，江泥轻燕斜。","贾生骨已朽，凄恻近长沙。"],"",[["古注·《杜詩詳註》","上四自叙行踪下四流落之感言故乡遥隔而老客他方曾不如虫鸟之自适矣况长沙地近能无今古同悲乎胡夏客曰此言贾生没後乂有近长沙而凄恻者非叹贾也赵汸注公至湖南每怀贾谊盖羇旅穷愁之感神交㝠漠之情皆在於此非泛拾故事成诗也陆机诗街巷纷漠漠卢谌诗南望旧京路孟子迟迟吾行也顔延之诗水国周地险杜臆落日对春华亦涉桑榆之感崔豹古今注木蜜生南方合体皆甜嫩枝及叶皆可生噉味如蜜其老枝及根干坚不可食细破煮之煎以为蜜味倍甜浓陶隐居本草木蜜悬树枝作之色青白黄希曰言早蜂而及树蜜言轻燕而及江泥皆取其类此与望兠率寺诗树蜜当山迳江深隔寺门不同前汉丙吉传仁心感动涕泣凄恻"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11938":["铜官渚守风","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["不夜楚帆落，避风湘渚间。","水耕先浸草，春火更烧山。","早泊云物晦，逆行波浪悭。","飞来双白鹤，过去杳难攀。"],"",[["古注·《杜詩詳註》","年月同上赵注潭州长沙有铜官山云是楚铸钱处此渚盖以是得名乎水经注湘水右岸铜官涌出焉一统志铜官渚在长沙府城北六十里"],["古注·《杜詩詳註》","首二铜渚守风三四渚前之景下四守风有感未夜収帆为避风也浸草作粪烧灰拥田皆楚地春农事云物㝠晦而浪沮行舟不若飞鹤之乗风自适矣汉武诏江南之地火耕水耨应劭注烧草下水种稻草与稻俱生高七八寸因悉芟去复下水灌之草死而稻独长所谓火耕水耨烧山在冬而春火更烧故以为异悭沮滞难行也古乐府飞来双白鹤乃从西南来"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11939":["北风","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["春生南国瘴，气待北风苏。","向晚霾残日，初宵鼓大鑪。","爽携卑湿地，声拔洞庭湖。","万里鱼龙伏，三更鸟兽呼。","涤除贪破浪，愁绝付摧枯。","执热沈沈在，凌寒往往须。","且知宽疾胏，不敢恨危途。","再宿烦舟子，衰容问仆夫。","今晨非盛怒，便道即长驱。","隐几看帆席，云州涌坐隅。"],"",[["古注·《杜詩詳註》","原注新康江口信宿方行水经注晋改益阳曰新康公自潭至衡於北风为顺故喜而有作"],["古注·《杜詩詳註》","此写北风之势霾生则风至矣卑湿之处爽若擕来洞庭之中声如拔起状风之自近而逺鱼龙承湖鸟兽承地诗终风且霾霾雨上蒙雾也雨去声庄子以天地为大罏王粲传无异於鼓洪罏以燎毛发贾谊传"],["古注·《杜詩詳註》","长沙卑湿"],["古注·《杜詩詳註》","此避风之事涤除瘴气方思破浪南行奈风急可愁不敢付之摧枯也此时骤寒解热肺病得苏而容色顿起矣北魏杜弼檄文摧枯朽者易为力左传再宿曰信诗招招舟子人渉卭否"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11940":["双枫浦","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["辍櫂青枫浦，双枫旧已摧。","自惊衰谢力，不道栋梁材。","浪足浮纱帽，皮须截锦苔。","江边地有主，暂借上天回。"],"",[["古注·《杜詩詳註》","此全是托物喻意言停舟枫浦见双树乆摧自从衰谢以後人但惊其精力已竭又谁道未衰之先材堪栋梁乎今兀立江干浪高而枫顶微露似浮沙㡌波平而皮藓半呈如截锦苔其摧朽若此我欲问江边地主借作上天浮槎庶不终弃於无用耶谢朓诗停骖我怅望辍棹子夷犹刘孝标书年髪里谢庾子嵩目和峤森森如干丈松施之大厦有栋梁之用申函光曰浮纱㡌句拙截锦苔犹水涨截蒲腰之截西京杂记终南山有树叶一青一丹其色如锦绣异苑乌伤陈氏未蘸着履径上大枫树巅了无危怖举手辞诀家人而去飘耸轻越移时乃没末句暗用其事"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11941":["奉送王信州崟北归","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["朝廷防盗贼，供给愍诛求。","下诏选郎署，传声能典州。","苍生今日困，天子向时忧。","井屋有烟起，疮痍无血流。","壤歌唯海甸，画角自山楼。","白发寐常早，荒榛农复秋。","解龟踰卧辙，遣骑觅扁舟。","徐榻不知倦，颍川何以酬。","尘生彤管笔，寒腻黑貂裘。","高义终焉在，斯文去矣休。","别离同雨散，行止各云浮。","林热鸟开口，江浑鱼掉头。","尉佗虽北拜，太史尚南留。","军旅应都息，寰区要尽收。","九重思谏诤，八极念怀柔。","徙倚瞻王室，从容仰庙谋。","故人持雅论，绝塞豁穷愁。","复见陶唐理，甘爲汗漫游。"],"",[["古注·《杜詩詳註》","朱注鹤云唐颍州亦曰信州今诗有絶塞豁穷愁语乃是䕫州葢王以郎官出守䕫州今罢郡归朝而公送之旧误入湖南诗内特改正之杜臆王本□䕫而称信州袭旧名也"],["古注·《杜詩詳註》","一作能典"],["古注·《杜詩詳註》","从初守信州叙起追言朝廷为民择官以王能力苏民困也井邑有烟诛求巳息疮痍无血盗贼渐弭歌惟海甸他皆经乱矣角吹山楼䕫尚防警也白发二句自叙客䕫之况左传诛求无时帝王世纪尧时有老人击壤而歌北山移文张英风於海甸"],["古注·《杜詩詳註》","一作老尘"],["古注·《杜詩詳註》","此叙交情而惜别也解龟谓离任卧辙百姓留王觅舟王来要公也赵曰公以徐穉自方而比王崟为陈蕃言崟相待如陈蕃之於孺子我将何以酬颍川乎颍川属陈氏郡号故用之尘生笔郎官巳谢寒腻裘客乆而敝高义四句述临别之情林热二句写别时之景谢灵运诗去郡牵丝及解龟在景平後汉书侯霸为临淮太守被徴百姓相擕号哭遮使者车或当道而卧世説刘真长遣骑觅张孝亷船徐孺下榻注别见诗彤管有炜注彤赤也公为郎官得用赤管笔黒貂裘用苏秦事刘琨诗时哉不我与去矣若云浮曹植诗风流云散一别如雨又诗行止依林阻"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11942":["江阁卧病走笔寄呈崔卢两侍御","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["客子庖厨薄，江楼枕席清。","衰年病祗瘦，长夏想爲情。","滑忆雕胡饭，香闻锦带羹。","溜匙兼暖腹，谁欲致杯甖。"],"",[["古注·《杜詩詳註》","崔乃崔大涣卢乃卢十四弟也鹤注大厯五年潭州有臧玠之乱公已去潭则江阁不在潭州也诗云长夏想为情又云滑忆雕"],["古注·《杜詩詳註》","菰饭则是四年秋作意江阁在潭近境故四年之秋五年之夏皆在焉"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11943":["潭州送韦员外牧韶州","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["炎海韶州牧，风流汉署郎。","分符先令望，同舍有辉光。","白首多年疾，秋天昨夜凉。","洞庭无过雁，书疏莫相忘。"],"",[["古注·《杜詩詳註》","鹤注当是大厯四年秋作唐书世系表韦迢终岭南节度行军司马韶州属岭南道"],["古注·《杜詩詳註》","上四送韦下四望韦分符承州牧同舎承署郎公亦曾为郎官故曰有光辉赵注自洞庭而徃此间无过雁以寄书而彼中书信却不可忘也汉纪与郡守为符各分其半右留京师左以与之诗令闻令望同舎即见直不疑传秋在昨夜诗作於立秋次日矣宋纎上梁主疏声闻书疏"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11944":["江阁对雨有怀行营裴二端公","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["南纪风涛壮，阴晴屡不分。","野流行地日，江入度山云。","层阁凭雷殷，长空水面文。","雨来铜柱北，应洗伏波军。"],"",[["古注·《杜詩詳註》","一作水面"],["古注·《杜詩詳註》","平声一作意"],["古注·《杜詩詳註》","首聨为冮雨发端行地之日流光在野隂忽晴矣度山之云飘入江中晴复隂矣凭阁而隠隠雷动面空而㸃㸃波文隂且雨矣末用伏波军乃借形语此铜柱在衡阳不在交址也田氏曰南纪分野名广天文志循岭儌违瓯闽中是谓南纪所以限蛮夷也旧引毛诗南国之纪非顔延之诗春江壮风涛唐太宗诗隂晴衆壑殊释惠标诗丹霞拂层阁碧水泛蓬莱诗殷其雷言雷声隠隠也曹植霖潦赋听长空之淋淋梁元帝诗风送水文长洗兵雨出说苑注见六巻"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11945":["酬韦韶州见寄","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["养拙江湖外，朝廷记忆疎。","深慙长者辙，重得故人书。","白发丝难理，新诗锦不如。","虽无南去雁，看取北来鱼。"],"",[["古注·《杜詩詳註》","鹤注此当是大厯四年秋韦发湘潭而公酬於潭州也"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11946":["千秋节有感二首 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["自罢千秋节，频伤八月来。","先朝常宴会，壮观已尘埃。","凤纪编生日，龙池堑劫灰。","湘川新涕泪，秦树远楼台。","宝镜羣臣得，金吾万国回。","衢尊不重饮，白首独余哀。"],"按唐纪𤣥宗八月五日生宴百官於花萼楼下百官因表请以每年八月五日为中秋节王公以下献镜及承露囊此诗大厯四年",[["古评·《唐诗品汇》","按唐纪𤣥宗八月五日生宴百官於花萼楼下百官因表请以每年八月五日为中秋节王公以下献镜及承露囊此诗大厯四年秋潭州作"],["古注·《杜詩詳註》","此大厯四年八月潭州作旧书𤣥宗纪开元十七年八月癸亥上以降诞日宴百僚於花蕚楼下百僚表请毎年八月十五日为千秋节王公以下献宝镜及承露囊天下诸州咸令宴乐休假三日仍编为令通监又移社日就千秋节"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗品彚（附唐诗拾遗）》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩品彚_(四庫全書本)）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11947":["千秋节有感二首 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["御气云楼敞，含风彩仗高。","仙人张内乐，王母献宫桃。","罗袜红蕖艳，金羁白雪毛。","舞阶衔寿酒，走索背秋毫。","圣主他年贵，边心此日劳。","桂江流向北，满眼送波涛。"],"",[["古注·《杜詩詳註》","首章叙崩後节日乃伤今思昔之感在六句作截赐宴之事虽编於帝纪而龙池王气乆已销亡不但壮观尘埃也四句申千秋节罢今遥望秦中楼台之下得宝镜者旧臣凋谢为金吾者各国散归独留白首书生泪滴湘川而已六句申八月频伤封禅文此事天下之壮观鳯纪注见三巻龙池注见十七巻高僧传汉武帝穿昆明池悉是灰墨後有胡僧云此天地刼灰之余阴铿诗云里望楼台张説诗宝镜颁神节淮南子圣人之道其犹中衢而致樽耶过者斟酌多少不同而各得其所宜"],["古注·《杜詩詳註》","音佩黄生欲作骨"],["古注·《杜詩詳註》","次章叙生前节日乃乐极悲来之感在八句作截御楼受贺彩仗迎风於是梨园奏乐大真献桃舞阶之白马衔酒前来走索之宫人红蕖高露当年可谓恣情尊贵矣岂知边忧即从此日而生乎至今日送波涛不胜北望伤神也边心此日劳犹云芙蓉小苑入边愁王融曲水亭诗序时乗既位御气之驾翔焉或以云楼为楼名含风为殿名非也考㑹要千秋节宴在勤政花蕚诸楼不在含风殿且紫云楼在曲江起於太和中於此无预宋之问诗寒轻彩仗外开元传纪帝谓高力士曰吾昨夜梦游月宫诸仙娯予以上清之乐寥亮清越之音非人间所闻也力士请名曰紫云曲汉武内传王母令侍女索桃七枚大如鸭子形色正青以四枚㗖帝自食其三洛神赋陵波微歩罗袜生尘黄生注罗袜红蕖艳後人咏弓足者妍雅无及此语当时妇人裙必曵地故罕见篇咏此亦因走索之妓结束有别故特拈出耳红蕖指宫鞋白马篇白马饰金羁连翩西北驰通监明皇教舞马百匹衔盃上寿唐志明皇千秋节舞马於勤政楼下西京赋跳九剑之挥霍走索上而相逢通典注舞絙者两妓女各从一头上行於绳上相逢比肩而不倾玉海唐实録开元二十四年八月千秋节御广运楼宴羣臣奏九部乐内出舞人䋲妓颁赐有差此言两人背走索上不爽秋毫也黄注以绳挂兽足曰罥秋毫言所縁之少土门诗微径縁秋毫此在索上非罥字不足以发其意杜臆桂江乃潭州所见之水"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11948":["晚秋长沙蔡五侍御饮筵送殷六参军归澧州觐省","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["佳士欣相识，慈颜望远游。","甘从投辖饮，肯作置书邮。","高鸟黄云暮，寒蝉碧树秋。","湖南冬不雪，吾病得淹留。"],"",[["古注·《杜詩詳註》","首二殷六省觐三四蔡筵送行五六别时秋景七八别後旅情黄生注公前有送侍御四舅之澧朗诗疑即致书於此人五羡殷六悲巳景中却有寓意潘岳闲居赋寿觞举慈顔和望逺逰谓亲望子归用论语逺逰字前汉陈孟公嗜酒毎大饮宾客满座辄闗门取客车辖投井中虽有急不得去世说殷羡为豫章太守将附书百许函悉掷水中曰沉者自沉浮者自浮殷洪乔不能作致书邮古乐府黄云暮四合髙鸟各分飞寄语逺逰子月圆胡不归潘岳秋兴赋庭树摵以洒落兮劲风戾而吹衣蝉嘒嘒而寒吟兮雁飘飘而南飞江淹诗碧树先秋落得淹留聊避寒也楚辞九辨蹇淹留而无成"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11949":["湖中送敬十使君适广陵","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["相见各头白，其如离别何。","几年一会面，今日复悲歌。","少壮乐难得，岁寒心匪他。","气缠霜匣满，冰置玉壶多。","遭乱实漂泊，济时曾琢磨。","形容吾校老，胆力尔谁过。","秋晚岳增翠，风高湖涌波。","骞腾访知己，淮海莫磋跎。"],"",[["古注·《杜詩詳註》","鹤注当是大厯四年潭州作唐书扬州广陵郡属淮南道公追酬髙蜀州人日诗序有昭州敬使君超先当即其人"],["古注·《杜詩詳註》","首叙送别之情後汉书范丹别王奂曰今子逺适千里㑹面无期"],["古注·《杜詩詳註》","此叙彼此心绪嵗寒句承各头白霜匣玉壶比敬之气豪而识积遭乱济时言己之厯世而才练皆所谓心匪他也下二亦用分承卢谌诗绸缪委心自同匪他西京杂记髙帝斩蛇剑琉璃为匣十二年一磨莹刀上常如霜雪开匣拔鞘光彩射人乐府清如玉壶冰"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11950":["长沙送李十一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["与子避地西康州，洞庭相逢十二秋。","远媿尚方曾赐履，竟非吾土倦登楼。","久存胶漆应难竝，一辱泥涂遂晚收。","李杜齐名真忝窃，朔云寒菊倍离忧。"],"",[["古注·《杜詩詳註》","衔此诗黄鹤编在大厯五年西康州即同谷县公以乾元二年冬寓同谷至大厯五年为十二秋此亦五年秋自衡归潭之一证也"],["古注·《杜詩詳註》","读坚溪切"],["古注·《杜詩詳註》","上四叙别後情事下乃感李而惜别也郎官遥受不如赐履入朝南楚浪逰有似登楼寄慨此十二年来行迹也胶漆难并谓气谊过人泥涂晚收谓穷老莫振二句宾主对举故下用李杜双承朱瀚曰云菊离忧别景别情一语尽之尚方赐履用王乔事详见四巻王粲登楼赋虽信美而非吾土兮曽何足以少留後汉陈重雷义交谊至笃时人语曰胶漆虽坚不如雷陈左传赵孟谢綘县老人曰使吾子辱在泥涂久矣顾注晚收谓从此收拾也後汉党铜传杜密与李膺俱坐而名行相次故时人亦称李杜焉注前有李固杜乔故言亦也荀朂表非臣驽闇所宜忝窃赭白马赋望朔云而蹀足庾信诗菊寒花正合谢燮诗望望空离忧离忧离别生忧也"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11951":["重送刘十弟判官","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["分源豕韦派，别浦雁宾秋。","年事推兄忝，人才觉弟优。","经过辨丰劒，意气逐吴钩。","垂翅徒衰老，先鞭不滞留。","本枝凌岁晚，高义豁穷愁。","他日临江待，长沙旧驿楼。"],"",[["古注·《杜詩詳註》","鹤注当是大厯四年秋在潭州作"],["古注·《杜詩詳註》","次叚言情上四承才优下四承别浦刘之才气英利如丰剑呉鈎故能先鞭用世不似已之垂翅飘流也晚逢高义"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11952":["奉赠卢五丈参谋","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["恭惟同自出，妙选异高标。","入幕知孙楚，披襟得郑侨。","丈人藉才地，门阀冠云霄。","老矣逢迎拙，相於契托饶。","赐钱倾府待，争米驻船遥。","邻好艰难薄，氓心杼轴焦。","客星空伴使，寒水不成潮。","素发乾垂领，银章破在腰。","说诗能累夜，醉酒或连朝。","藻翰惟牵率，湖山合动摇。","时清非造次，兴尽却萧条。","天子多恩泽，苍生转寂寥。","休传鹿是马，莫信鵩如鴞。","未解依依袂，还斟泛泛瓢。","流年疲蟋蟀，体物幸鹪鹩。","辜负沧州愿，谁云晚见招。"],"",[["古注·《杜詩詳註》","从卢叙起亲谊交情官序才地俱见於此孙楚切叅谋郑侨聘晋比使长沙王褒颂㳟惟春秋惟思也朱注同自出盖参谋之母与公毋皆崔氏也黄鹤引公祖母卢氏非左传我之所自出尔雅男子谓姊妹之子曰出语林琅琊王镇广陵妙选僚佐世説李元礼高自标持王僧孺序道合神遇投分披襟左传季札聘郑见子産如旧相识世説王恂自计才地必应在已朱注前汉朱博传齎阀閲诣府车千秋传千秋无阀閲劳注阀积功也閲所经也唐六品以上通用乌头大门又曰表掲又曰阀閲义谢云表揭阀閲是也俗呼为棂星门诗言卢氏积累日月立功而致表揭高於云霄也孔融书岸㥽广堂举杯相於相於犹云相与"],["古注·《杜詩詳註》","此长沙遇卢情事素髪银章自谓老年带官説诗四句言一时诗酒兴豪所谓相於契托也白帖汉世有鞶囊者佩在腰间谓之绶囊朱注隋唐以後官不佩印止有随身鱼袋此云银章破在腰盖举银鱼言之当时金银鱼谓之章服左传牵率老夫谢瞻诗牵率酬嘉藻"],["古注·《杜詩詳註》","此慨时事以勉卢天子施恩而生民转困者以朝有奸佞外多掊克耳指鹿为马如鱼朝恩是也鵩鸟如鴞若臧玠是也曰休传莫信故婉其词以隐讽耳史记赵高持鹿献於二世曰马也鵩鸟赋序鵩似鴞不祥鸟也"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11953":["登舟将适汉阳","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["春宅弃汝去，秋帆催客归。","庭蔬尚在眼，浦浪已吹衣。","生理飘荡拙，有心迟暮归。","中原戎马盛，远道素书稀。","塞雁与时集，樯乌终岁飞。","鹿门自此往，永息汉阴机。"],"",[["古注·《杜詩詳註》","此诗王彦辅郑昻鲁尝皆谓作於大厯五年之秋黄鹤谓四年之秋欲登舟而不果行者无据元和郡国志武徳四年分沔阳都於汉阳县置沔州及汉阳县"],["古注·《杜詩詳註》","首叙登舟景事春宅秋帆就潭州言庭蔬承宅浦泿承帆"],["古注·《杜詩詳註》","叶他郎切"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11954":["暮秋将归秦留别湖南幕府亲友","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["水阔苍梧野，天高白帝秋。","途穷那免哭，身老不禁愁。","大府才能会，诸公德业优。","北归冲雨雪，谁悯敝貂裘。"],"三四极覊旅琐琐之态五六虽无华丽非老笔不能然其实雄深雅健也末句十字可怜甚矣诸亲友能无情乎",[["古注·《杜詩詳註》","上四暮秋将归下四留别亲友黄生注一见地二见时三四轻接起聨五六直趋尾聮故俱不甚用力用力在一起一接极其精猛顾注旧解谓苍捂白帝皆公经厯之地公实未尝至苍梧也此言湘江之水甚濶直接苍梧潭州图经谓其地有舜之遗风白帝司秋葢言暮秋时令如望岳诗云髙寻白帝问真源黄生注途穷在水濶之处身老如暮秋之景二句亦用暗承有才如少陵使其穷老江湖雨雪敝裘落落寡偶大府诸公亦不得辞其责矣然语却含蓄蕴藉谢朓诗云去苍梧野水还江汉流顔延之诗途穷能无恸酷吏传郅都郡中不拾遗旁十余郡守畏都如大府师古曰言犹如统属之也通监注唐时巡属诸州以节度使府为大府亦谓之㑹府班固奏记才能絶伦晋书文立传程琼雅有徳业诗雨雪霏霏"],["古评·《瀛奎律髓》","三四极覊旅琐琐之态五六虽无华丽非老笔不能然其实雄深雅健也末句十字可怜甚矣诸亲友能无情乎"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）","古籍注评：《瀛奎律髓》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/瀛奎律髓_(四庫全書本)）"]],"open_11955":["送卢十四弟侍御护韦尚书灵榇归上都二十韵","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["素幕渡江远，朱幡登陆微。","悲鸣驷马顾，失涕万人挥。","参佐哭辞毕，门阑谁送归。","从公伏事久，之子俊才稀。","长路更执绋，此心犹倒衣。","感恩义不小，怀旧礼无违。","墓待龙骧诏，台迎獬豸威。","深衷见士则，雅论在兵机。","戎狄乘妖气，尘沙落禁闱。","往年朝谒断，他日埽除非。","但促铜壶箭，休添玉帐旗。","动询黄阁老，肯虑白登围。","万姓疮痍合，羣凶嗜慾肥。","刺规多谏诤，端拱自光辉。","俭约前王体，风流後代希。","对敭期特达，衰朽再芳菲。","空里愁书字，山中疾采薇。","拨杯要忽罢，抱被宿何依。","眼冷看征盖，儿扶立钓矶。","清霜洞庭叶，故就别时飞。"],"",[["古注·《杜詩詳註》","叙侍御送韦见死生不朁之情上四韦公灵榇中八卢公䕶䘮下四结上起下龙骧承韦言殁後赠典獬豸氶卢言宿望还都深衷指送丧论兵感世乱韦榇从水程而往故素幕之涉江者逺朱幡之登陆者少也赵次公以朱幡为丹旐本於文选注旐引柩幡也王原叔引朱轓两轮轓与幡异黄鹤引卫青传注每军一校则别为幡谓部曲侯送之旗幡四皓歌驷马髙葢陆机诗挥泪广川隂参佐谓佐吏参军诗颠倒衣裳晋王濬为龙骧将军卒塟柏谷中大营茔域獬豸兽名知人曲直而触不直者旧书舆服志法冠一名獬豸冠以鐡为柱其上施珠两枚为獬豸之形左右御史台服之何逊诗深衷外有规世说陈仲举言为士则行为士范李乂诗河塞有兵机"],["古注·《杜詩詳註》","宋本误作稀"],["古注·《杜詩詳註》","此慨叹时事望侍御归朝入告戎狄乗谓吐蕃䧟京落禁闱谓侵犯宫阙朝谒断指代宗幸陕扫除非谓御戎无策铜壶二句言天子当早朝勤政毋事添兵苑中黄阁二句言庙堂当谋及老成不㤀外侮之忧疮痍谓生民困於兵赋嗜慾谓降将恣为骄侈刺规以下勉侍御面折廷诤以图治安而俭约爱民尤为当今切务故当抗章特违不可委靡令我衰朽之人亦与有荣施也米注休添玉帐旗即公诗由来貔虎士不满鳯凰城意今按俭约前王体即公诗不过行俭德威加四海深意後汉陈蕃传大丈夫处世当扫除天下司马彪绩汉书孔壶为漏浮箭为刻陆倕漏刻铭铜史司刻金徒抱箭汉书髙帝至平城胃顿纵积兵三十万围帝於白登七日孔融书羣凶破珍赵壹疾邪赋肆嗜慾於目前希言当希法前王书对扬天子之休命世说王导谓顾和曰此子圭璋特达机警有锋"],["古注·《杜詩詳註》","末叙送别之情把杯同宿不可复得从此征葢逺行唯立矶遥望而已霜凋木叶对秋增悲也此章前二段各十六句後段八句收杜臆拨杯抛杯不饮也冇拨弃潭州酒可证"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11956":["哭李常侍峄二首 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["一代风流尽，修文地下深。","斯人不重见，将老失知音。","短日行梅岭，寒山落桂林。","长安若个畔，犹想映貂金。"],"结意往往谆复是大家数",[["古评·《唐诗镜》","结意往往谆复是大家数"],["古评·《唐诗镜》","附奉济驿重送严公四韵逺送从此别青山空复情几时杯重把昨夜月同行列郡讴歌惜三朝出入荣江村独归处寂寞养残生三四毎用颠倒之法"],["古评·《唐诗镜》","附暮春题瀼西新赁草堂彩云隂复白锦树晓来青身世双蓬鬓乾坤一草亭哀歌时自短醉舞为谁醒细雨荷锄立江猿吟翠屏乾坤一草亭乾坤自大在虽瑶台十层於乾坤何际此语怨而失其㫖矣附登岳阳楼昔闻洞庭水今上岳阳楼吴楚东南坼乾坤日夜浮亲朋无一字老病有孤舟戎马闗山北凭轩涕泗流吴楚东南坼乾坤日夜浮自宋人推尊至今六七百年矣今直不解其趣吴楚东南坼此句原不得景但虚形之耳安见得洞庭在彼东南吴楚逐坼为两耶且将何以咏江也至乾坤日夜浮更悬虚之极以之咏海庶可耳其意欲驾孟浩然而过之譬之於射仰天弯弓髙则髙矣而矢过的矣附江亭坦腹江亭煖长吟野望时水流心不竞云在意俱迟寂寂春将晩欣欣物自私故园归未得排闷强裁诗三四家数最小行到水穷处坐看云起时此语如在层霄之上"],["古注·《杜詩詳註》","鹤注当是大厯三年冬江陵作李常侍盖死於广南归塟长安公逢於江汉间而哭之也唐志左右散骑常侍𨽻门下中书省掌规讽𬨨失侍从顾问"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗镜》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩鏡_(四庫全書本)）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11957":["哭李常侍峄二首 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["青琐陪双入，铜梁阻一辞。","风尘逢我地，江汉哭君时。","次第寻书札，呼儿检赠诗。","发挥王子表，不媿史臣词。"],"",[["古注·《杜詩詳註》","次章於徃日交情现前哀死身後留名曲尽之矣公昔在长安与李同入青𤨏之门後李在铜梁公疎於一辞之寄今旅榇相逢但有殁後一哭耳寻书检诗常侍手迹所在王子表李为宗室也史臣有词録其素行也唐铜梁县属渝州𨽻剑南道渝州即今重庆府周拾上云乐乃欲次第説释名弟第也言次第相生也则第字本与弟相通故可对儿古诗遗我一书札又呼儿烹鲤鱼应瑒诗赠诗见存慰汉书有王子侯表杨德周曰诗有假对法如子云清自守今日起为官次第寻书札呼儿检赠诗以日对云以第对儿是也後人滥觞借一对栢以十对迁谬矣叶石林谓杜诗对偶至严必无散句甚欲改今日为令尹则又太拘至东原録又改今日为金日谓金日磾没入官输黄门养马唐中兴时赞普入中国必有相类故杜用之更穿凿不通矣"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11958":["哭韦大夫之晋","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["凄怆郇瑕色，差池弱冠年。","丈人叨礼数，文律早周旋。","台阁黄图里，簪裾紫盖边。","尊荣真不忝，端雅独翛然。","贡喜音容间，冯招病疾缠。","南过骇仓卒，北思悄联緜。","鵩鸟长沙讳，犀牛蜀郡怜。","素车犹恸哭，宝劒欲高悬。","汉道中兴盛，韦经亚相传。","冲融标世业，磊落映时贤。","城府深朱夏，江湖眇霁天。","绮楼关树顶，飞旐泛堂前。","帟幕疑风燕，笳箫急暮蝉。","兴残虚白室，迹断孝廉船。","童孺交游尽，喧卑俗事牵。","老来多涕泪，情在强诗篇。","谁寄方隅理，朝难将帅权。","春秋褒贬例，名器重双全。"],"",[["古注·《杜詩詳註》","一作大一作士"],["古注·《杜詩詳註》","首叙交谊郇瑕记地弱冠记时礼数周旋相契之情黄图昔在京紫盖今在衡尊荣称其位端雅重其品左传晋人谋去故绦诸大夫曰必居郇瑕氏之地注河东解县西北有郇城一统志在今平阳府猗氏地曲礼二十曰弱冠文赋普词条与文律左传与君周旋江总赋览黄图之栋宇沈约集陪龙驾於伊洛侍紫盖於咸阳指紫微华荩此则指紫盖峯衡山七十二峯之一时韦先为衡州刺史也"],["古注·《杜詩詳註》","次叙哭韦之情贡喜喜韦登进冯招韦方招用公在衡韦在潭故闻讣之辰自南而思北贾生鵩鸟比其刺潭李冰石犀比其守蜀素车用范式事悬剑用季札事此存亡死生之悲絶交论王阳登位贡公喜左思诗冯公岂不伟白首不见招沈佺期诗北思日悠哉梁简文帝诗春思坐聨绵後汉书范式字巨卿少与张劭为友劭死式梦而赴焉劭塟日其母望见素车白马号哭而来母曰必巨卿也式乃修墓种树而去挂剑徐君墓注已别见"],["古注·《杜詩詳註》","此惜其生不重见城府韦治潭州江湖公客衡州也韦贤少子𤣥成复以明经为相故曰亚相南齐书张融世业清贫後汉书龎德公未尝入城府陆机赋迎朱夏而自延宋之问诗开延霁天"],["古注·《杜詩詳註》","此痛其殁後凄凉兴残公不复徃迹断韦不复来也古诗西北有高楼交䟽结绮𥦗绮楼盖韦平日所居者旧注以为奠楼恐非邵注旐铭旌也寡妇赋飞旐翻以启路王融曲水诗序缇帷宿置帟幕宵悬周礼注在旁曰惟在上曰幕愤赋弃虚白之室归长夜之台孝亷船注别见前"],["古注·《杜詩詳註》","末致哀挽之意童孺交游应上差池弱冠名器双全应上尊荣不黍此章八句者三叚六句者两叚蔡邕胡根碑嗟童孺之夭逝兮虑思道集外静方隅内康庶绩谷梁传序一字之褒宠踰华衮之赠片言之贬辱过市朝之挞左传惟名与器不可以假人双全谓名不愧其实"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11959":["舟中夜雪有怀卢十四侍御弟","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["朔风吹桂水，朔雪夜纷纷。","暗度南楼月，寒深北渚云。","烛斜初近见，舟重竟无闻。","不识山阴道，听鸡更忆君。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11960":["对雪","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["北雪犯长沙，胡云冷万家。","随风且间叶，带雨不成花。","金错囊从罄，银壶酒易赊。","无人竭浮蚁，有待至昏鸦。"],"诗家善用事者藏一字於句中银壶酒易賖非易也乃不易也钱囊既已空矣酒可以易賖乎但吟此者着些断续轻重即见意矣",[["古注·《杜詩詳註》","此当与上章先後作诗曰长沙则在潭州矣"],["古注·《杜詩詳註》","去声一作开"],["古注·《杜詩詳註》","一作从一作徒"],["古注·《杜詩詳註》","上四雪中景下四雪中情南方少雪故逺自北方而来雪飞叶落随风杂舞故曰闲雪有六花带雨而湿故不成有酒无朋此对雪凄凉之况鲍照诗胡风吹朔雪千里度龙山艺苑雌黄云张衡四愁诗美人赠我金错刀金错刀王莽所铸钱名莽变汉制以周钱有子母相权於是更造大钱径寸二分重十二铢文曰大钱五十又造契刀其环如大钱身形如刀长二寸文曰契刀五百错刀以黄金错其文曰一刀直五千舆五铢钱凡四品并行杜诗金错囊徒罄银壶酒易赊韩退之诗闻道松醪贱何须恡错刀皆谓是也後汉刘盆子传吕母酿醉酒少来酤者皆赊与之又髙祖纪贳酒注赊酒也庾信诗浮蚁对春开朱注旧本公自注何逊诗城隂度堑黒昏鸦接翅归按二语今何记室集不载公复愁诗钓艇收緍尽昏鸦"],["古评·《瀛奎律髓》","诗家善用事者藏一字於句中银壶酒易賖非易也乃不易也钱囊既已空矣酒可以易賖乎但吟此者着些断续轻重即见意矣以尾句騐之盖无人肯賖酒直待至昏黒也"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）","古籍注评：《瀛奎律髓》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/瀛奎律髓_(四庫全書本)）"]],"open_11961":["楼上","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["天地空搔首，频抽白玉簪。","皇舆三极北，身事五湖南。","恋阙劳肝肺，论材媿杞柟。","乱离难自救，终是老湘潭。"],"",[["古注·《杜詩詳註》","此当是潭州所作诗末云身在五湖南可见此及下章并依蔡氏编次"],["古注·《杜詩詳註》","此诗登楼而感怀也孤楼之上俯仰天地徒然搔首而抽簪者正以皇舆在北身事在南故也恋阙而不才沦弃既无补於皇舆乱离而终老湘潭又无济於一身此所以搔首踟蹰耳西京杂记汉武帝取李夫人玉簪搔头锺㑹赋散髪抽簪杜臆白玉簪盖朝冠所用屡思入朝而中止故云频抽陆机论旋皇舆於夷庚反帝座於紫闼地有四极皇舆在东西南之北故云三极与系辞三极不同旧注误史记索隐具区洮滆彭蠡青草洞庭共为五湖"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11962":["冬晚送长孙渐舍人归州","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["参卿休坐幄，荡子不还乡。","南客潇湘外，西戎鄠杜旁。","衰年倾盖晚，费日系舟长。","会面思来札，销魂逐去樯。","云晴鸥更舞，风逆雁无行。","匣里雌雄劒，吹毛任选将。"],"",[["古注·《杜詩詳註》","从自叙说起西戎旅冦故南客未还晋书孙楚为石苞骠骑参军初至长揖曰天子命我参卿军事因此嫌隙遂成公初为参谋今巳罢去故曰休坐幄古诗云荡子行不归空牀难独守汉宣帝纪尤乐鄠杜之间顔注鄠属扶风杜属京兆"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11963":["暮冬送苏四郎徯兵曹适桂州","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["飘飘苏季子，六印佩何迟。","早作诸侯客，兼工古体诗。","尔贤埋照久，余病长年悲。","卢绾须征日，楼兰要斩时。","岁阳初盛动，王化久磷缁。","爲人苍梧庙，看云哭九疑。"],"",[["古注·《杜詩詳註》","鹤注大厯四年十二月桂州人朱济反当是此时作鹤注通典汉司隷属官有兵曹从事葢有军事则置唐三都督府上中下州皆有之"],["古注·《杜詩詳註》","此惜苏之遇蹇贤而久埋与已之病弃者同悲矣史记苏秦为从约长佩六国相印蔡邕释诲连衡者六印磊落颜延之诗沉醉似埋照"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11964":["风疾舟中伏枕书怀三十六韵奉呈湖南亲友","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["轩辕休制律，虞舜罢弹琴。","尚错雄鸣管，犹伤半死心。","圣贤名古邈，羇旅病年侵。","舟泊常依震，湖平早见参。","如闻马融笛，若倚仲宣襟。","故国悲寒望，羣云惨岁阴。","水乡霾白屋，枫岸叠青岑。","郁郁冬炎瘴，蒙蒙雨滞淫。","鼓迎非祭鬼，弹落似鴞禽。","兴尽才无闷，愁来遽不禁。","生涯相汩没，时物自萧森。","疑惑尊中弩，淹留冠上簪。","牵裾惊魏帝，投阁爲刘歆。","狂走终奚适，微才谢所钦。","吾安藜不糁，汝贵玉爲琛。","乌几重重缚，鹑衣寸寸鍼。","哀伤同庾信，述作异陈琳。","十暑岷山葛，三霜楚户砧。","叨陪锦帐座，久放白头吟。","反朴时难遇，忘机陆易沈。","应过数粒食，得近四知金。","春草封归恨，源花费独寻。","转蓬忧悄悄，行药病涔涔。","瘗夭追潘岳，持危觅邓林。","蹉跎飜学步，感激在知音。","却假苏张舌，高夸周宋镡。","纳流迷浩汗，峻址得嶔崟。","城府开清旭，松筠起碧浔。","披颜争倩倩，逸足竞駸駸。","朗鉴存愚直，皇天实照临。","公孙仍恃险，侯景未生擒。","书信中原阔，干戈北斗深。","畏人千里井，问俗九州箴。","战血流依旧，军声动至今。","葛洪尸定解，许靖力还任。","家事丹砂诀，无成涕作霖。"],"",[["古注·《杜詩詳註》","此当是大厯五年冬作按本传及年谱但云公卒於耒阳而不载其时月今以是诗考之葢卒於五年之冬矣观此诗嵗隂冬炎语可见诗谱谓公卒於夏减却少陵半年之夀为可恨也"],["古注·《杜詩詳註》","从风疾叙起身疾而气失调故难制律弹琴错管承律伤心承琴汉律厯志黄帝使伶伦取竹於嶰谷断两节间而吹之以为黄锺之宫制十二筩以听鳯鸣其雄鸣六雌鸣亦六此黄锺之宫而皆可以生之是为律本至治之世天地之气合以生风天地之风气正十二律定记舜作五之琴以歌南风之诗而天下冶桓谭新论神农始削桐为琴七发龙门之桐高百尺而无枝其根半死半生半死心借琴以喻已"],["古注·《杜詩詳註》","以下四段皆㐲枕书懐此记湖中景物圣贤承轩虞□旅起舟泊依震欲向东北见参东方将明也马融王粲皆异地思乡者寒望嵗隂言冬令水乡枫岸言山水炎瘴滞淫言气侯之殊祭落鴞言土俗之异陆机诗後途随年侵杜臆汉阳在潭岳东北公将适汉阳故瞻依在震震东北方之卦也旧指震泽於洞庭逺隔矣鲍照诗晓星正参落杜臆马融长笛赋序有洛客舍逆旅吹笛融去京师踰年暂闲甚悲公去京师久故云王粲登楼赋凭轩槛以遥望兮向北风而开襟公病畏热故用其语顔延之诗故国多乔木空城凝寒云谢惠连雪赋嵗将暮时既昏寒风积愁云繁贺彻诗苕荛擅水乡陶潜诗郁郁荒山秀岳阳风土记岳州地极热十月犹单衣或摇扇震雷暴雨如中州六七月间呉均诗蒙蒙秋雨映张载诗初为三载别於今久滞淫风土记荆湖民俗嵗时㑹集或祷祠多击鼔令男女踏歌谓之歌塲庄子见弹而思鴞炙"],["古注·《杜詩詳註》","於旧处设酒因谓宣曰此乃弩影耳宣病遂瘳与乐广同冠上簪谓朝簪牵裾用魏辛毗事注见九巻子云被收本为刘歆子棻狱辞连及今云为刘歆借用以趂韵耳易林狂走蹶走陆机赠兄诗寤寐靡安豫愿言思所钦庄子孔子藜羮不糁晋书太守马岌造宋纎不得见铭於壁口其人如玉为国之琛乌几注见十三巻孙卿子子夏贫常悬鹑衣於壁"],["古注·《杜詩詳註》","一作过非"],["古注·《杜詩詳註》","此蜀楚浪逰之迹同庾信谓均遭丧乱异陈琳谓不草书檄十暑三霜通计行踪锦帐郎官所坐放吟仿古而吟时凊难遇隠似陆沉叹身世也分米赠金葢亲友所恵者庾信哀江南赋序信年始二毛即逢丧乱藐是流离至於暮齿赋云天意人事可为凄怆伤心者矣魏文帝与吴质书裴然有述作意魏志曹公疾发卧读陈琳所作翕然而起曰此愈我病沈佺期诗三霜弄溟岛史记楚虽三户洙曰郎官有锦帐见汉百官志淮南子巳雕巳琢还反於朴庄子与世违而心不屑与之俱是陆沉者也史记东方朔坐席中酒酣据地歌曰陆沉於俗鹪鹩赋巢林不过一枝毎食不过数粒後汉王密懐金遗杨震曰暮夜无知者震曰天知地知子知我知何谓无知遂不受四知金言金之亷洁"],["古注·《杜詩詳註》","音寻此衰年留滞之感归计不能桃源难访唯飘蓬饮药而巳此应前羁旅病侵瘗夭痛儿女之亡邓林谓老行须杖翻学步不能随俗而趋感知音穷途幸逢亲友也苏张二句谓诸公谬加奬誉刘安招隠王孙逰兮不归春草生兮萋萋封犹增也鲍照有行药至城东桥诗五臣注因病服药行以宣导之汉书外戚传霍尤夫人显使女医淳于衍投毒药以饮许后有顷曰我头涔涔也药得无有毒乎潘岳西征赋夭赤子於新安坎路侧而瘗之黄鹤以瘗夭为葬宗文山海经夸父与日逐走道渴死弃其杖化为邓林庄子寿陵余子学行於邯郸失其故步直匍匐而归耳魏文帝与呉质书伯牙絶于锺期痛知音之难遇史苏秦传今子舍本而事口舌张仪传视吾舌尚在否庄子天子之剑以燕谿石城为锋齐岱为锷晋卫为春周宋为镡韩魏为铗说文镡剑鼻也"],["古注·《杜詩詳註》","此称美幕府亲友也杜臆纳流言广而难遍峻趾言髙而难攀朱注城府松筠言幕府所在披顔逸足言归往者多逺注朗鉴二句感亲友待巳之厚世説谢万经曲阿後湖曰故当渊注渟着纳而不流孙楚书三江五湖浩汗无涯魏都赋藐藐标危亭亭峻址鲁灵光殿赋嶔崟离楼晋张载传伏死嶔崟之下杨师道诗聨翩度碧浔倩倩笑容诗巧笑倩兮徐干中论马虽有逸足而不闲舆则不为良骏诗载骤駸駸陆机诗朗鉴岂虚假取之在倾冠存是存问之存论语古之愚也直左传皇天后土实闻此言诗照临下土"],["古注·《杜詩詳註》","此慨叹乱离时事也公孙侯景指当时叛将中原指洛阳北斗指长安畏人问俗言到处可忧战血军声伤南北兵乱公孙恃险应指蜀中事永泰元年崔旰杀郭英乂据成都大厯四年杨子琳杀䕫州别驾张忠据其城侯景未擒臧玠失讨也南史侯景与慕容绍宗战败渡准绍宗追之景使人谓之曰景若就擒公复何用绍宗乃纵之臧玠杀崔瓘三州刺史合兵讨之杨子琳受赂而还与绍宗之纵侯景无异故曰木生擒玉台新咏刘勲妻王氏诗千里不唾井况乃昔所奉金陵记南朝计吏止於传舍将去以剉马革泻井中谓无再过之期矣不久复至汲水递饮遂为昔时之剉刺喉而死故後人戒曰千里井不泻剉谚云千里不反唾唾乃剉字之讹记入国而问俗左传虞人之箴曰芒芒禹迹画为九州扬雄传赞箴莫善於虞箴故作州箴唐书大厯四年冬十一月吐番复冦灵州又冯崇道朱济时反广南故有干戈北斗战血军声等句韩信传兵固有先声而後实者"],["古注·《杜詩詳註》","末叙穷老无聊之况尸定解将死道路力难任不复逺行丹砂未成则内顾无策结语葢待济於诸公矣此章起结各四句前两段各十四句中两段各十句後两段各八句排律整齐集中类然晋中兴书葛洪止罗浮山中炼丹在山积年忽与广州刺史邓岱书云当欲逺行岱得书狼狈而往洪巳亡时年八十一顔色如平生体亦软弱举屍入棺其轻如空衣时咸以为尸解得仙後汉方技传注尸解者言将登仙假托为尸以解化也许靖汝南人依吴郡走交州後入蜀为太傅年踰七十丹诀谓㸃化黄白之术後汉丁鸿传不以家事废王事"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11965":["奉赠萧二十使君","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["惜在严公幕，俱爲蜀使臣。","艰危参大府，前後间清尘。","起草鸣先路，乘槎动要津。","王凫聊暂出，萧雉只相驯。","终始任安义，荒芜孟母邻。","联翩匍匐礼，意气死生亲。","张老存家事，嵇康有故人。","食恩慙卤莽，镂骨抱酸辛。","巢许山林志，夔龙廊庙珍。","鹏图乃矫翼，熊轼且移轮。","磊落衣冠地，苍茫土木身。","埙篪鸣自合，金石莹逾新。","重忆罗江外，同游锦水滨。","结欢随过隙，怀旧益沾巾。","旷绝含香舍，稽留伏枕辰。","停骖双阙早，回雁五湖春。","不达长卿病，从来原宪贫。","监河受贷粟，一起辙中鳞。"],"",[["古注·《杜詩詳註》","首忆幕府往事严武两鎭蜀必萧先在幕而公继入是前後相间也起草应幕府乗槎应使臣王鳬用县令事萧雉用郎官事萧葢先为郎而後贬为令也朱注次公引唐志凡诏令皆舎人起草固是然此诗所云起草则以郎官言之卢谌赠刘琨诗自奉清尘於今五载"],["古注·《杜詩詳註》","此记萧君古谊任安比使君孟母比严母聨翩匍匐谓经纪两丧意气死生谓存亡一视张老之于赵武嵇康之托山涛称萧能保家而恤孤食恩二句公自谦不如也原注严公既没老母在堂使君温凊之间甘脆之礼名数若巳之庭闱马及太夫人顷逝丧事又首诸孙主典抚孤之情不减骨肉则胶漆之契可知矣汉书霍去病为骠骑将军禄秩与大将军卫青等青故人门下多去事去病辄得官爵唯任安不去诗凡民有丧匍匐救之蔡邕陈留太守碑意气精朗翟公云一死一生乃见女情晋语赵文子冠见张老而语之张老晋大夫张孟左传楚子问赵孟曰范武子之徳何如对曰夫子之家事治嵇康故人注见本巻前阮嗣宗诗凄怆抱酸辛镂骨犹言刺骨"],["古注·《杜詩詳註》","记彼此出处之殊䕫龙谓萧能济世起下鹦图熊轼巢许谓已终隠遯起下苍茫土木书䕫典乐龙纳言庄子北溟有鱼化而为鸟其名曰鹦海运则将徙於南溟赵注萧为大守故凭熊轼以移轮晋书嵇康土木形骸"],["古注·《杜詩詳註》","末乃自叙有望於萧也停骖尚早承旷絶回雁当春承稽留四句写出贫病之状使君倘能贷粟穷途庶□鳞得以顿起也不达谓萧君未之知耳注家谓因不显达而致病对下句不合此章前後三段各八句中二段各六句含香伏枕注皆别见谢朓诗停骖我怅望庄子庄周家贫往贷粟於监河侯曰昨周来有中道而呼者顾视车辙中有鲋鱼马周问之曰我东海之波臣也君岂有升斗之水而活我哉"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11966":["奉送二十三舅录事之摄郴州","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["贤良归盛族，吾舅尽知名。","徐庶高交友，刘牢出外甥。","泥涂岂珠玉，环堵但柴荆。","衰老悲人世，驱驰厌甲兵。","气春江上别，泪血渭阳情。","舟鷁排风影，林乌反哺声。","永嘉多北至，句漏且南征。","必见公侯复，终闻盗贼平。","郴州颇凉冷，橘井尚凄清。","从役何蛮貊，居官志在行。"],"",[["古注·《杜詩詳註》","鹤注当是大厯五年春作邵注唐制诸州设録事参军掌正违失莅符印郴州今𨽻湖广道"],["古注·《杜詩詳註》","当作交髙"],["古注·《杜詩詳註》","此称舅氏而兼自伤尽知名崔族多才出外甥感恩在舅下四叹穷老乱离陈诉甚悲周礼以三徳教国子二曰友行以尊贤良旧注徐庶字元直其所交者诸葛孔明龎士元司马徳操诸公蜀志徐庶与崔州平友善晋书桓𤣥曰何无忌刘牢之之甥酷似其舅世说王武子卫玠之舅见玠辄叹曰珠玉在侧觉我形秽记儒有环堵之室"],["古注·《杜詩詳註》","此因送别而作慰辞江上指相江排风谓风帆乌反哺崔有母也北至南征记其行迹公侯必复言当终贵盗贼指岭南之冦旧注误云臧玠之乱春时玠尚未反也谢朓诗江上徒离忧东晳补亡诗嗷嗷林乌受哺於子晋书永嘉之乱元帝渡江衣冠多自北至勾漏引葛洪相方楚辞洎吾南征左传公侯之子孙必复其始"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11967":["送魏二十四司直充岭南掌选崔郎中判官兼寄韦韶州","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["选曹分五岭，使者历三湘。","才美膺推荐，君行佐纪纲。","佳声斯共远，雅节在周防。","明白山涛鉴，嫌疑陆贾装。","故人湖外少，春日岭南长。","凭报韶州牧，新诗昨寄将。"],"",[["古注·《杜詩詳註》","魏往岭南称其才品选曹使者谓崔郎中才美纪纲谓魏判官山涛鉴承佳声颂崔也陆贾装豕雅节规魏也北史周宇文深传深在选曹颇有时誉五岭注见前寰宇记湘潭湘乡湘源是为三湘顔延之诗三湘沦洞庭左传纪纲之仆杜预左传序𮎛周身之防晋书山涛典选十余年甄拔人物各为题目时称山公启事记决嫌疑汉书髙祖使陆贾赐尉佗印为南越王佗赐贾槖中装直千金他送亦千金"],["古注·《杜詩詳註》","此送魏而兼寄韦也此章上八句下四句将送也诗逺于将之"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11968":["送赵十七明府之县","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["连城爲宝重，茂宰得才新。","山雉迎舟楫，江花报邑人。","论交飜恨晚，卧病却愁春。","惠爱南翁悦，余波及老身。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11969":["燕子来舟中作","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["湖南爲客动经春，燕子衔泥两度新。","旧入故园常识主，如今社日远看人。","可怜处处巢君室，何异飘飘托此身。","暂语船樯还起去，穿花落水益沾巾。"],"",[["古评·《唐诗镜》","情绪依依"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗镜》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩鏡_(四庫全書本)）"]],"open_11970":["同豆卢峰知字韵","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["炼金欧冶子，喷玉大宛儿。","符彩高无敌，聪明达所爲。","梦兰他日应，折桂早年知。","烂漫通经术，光芒刷羽仪。","谢庭瞻不远，潘省会於斯。","倡和将雏曲，田翁号鹿皮。"],"",[["古注·《杜詩詳註》","旧次在大厯五年潭州作逺注豆卢峯有贻李员外子诗公和之而作同和也唐书世系表豆卢姓慕容氏北人谓归义为豆卢因赐为氏居昌黎棘城唐志主客郎中员外郎各一人掌二王後诸藩朝见之事属礼部"],["古注·《杜詩詳註》","此称美员外父子链金喷玉唯员外能有此子符彩聪明言棐负才智梦兰折桂言生质不凡经术羽仪言学堪用世吴越春秋干将与欧冶子采五山之精合六金之英链而为剑杜定功曰穆天子东游黄泽使官乐謡曰黄之泽其马喷王皇人寿榖歕喷同大宛儿大宛马驹即汗血马也曹植七启符采照烛符采犹云光彩左思蜀都赋符采彪炳傅𤣥舆马赋符采横发左传郑文公有贱妾曰燕姞梦天使与已兰既而文公见之与之兰而御之辞曰妾不才幸而有子将不信敢徵兰乎公曰诺生穆公名之曰籣晋郗诜学博多才武帝问曰郷才何如对曰犹桂林一枝崑山片玉沈约诗刷羽同揺漾易鸿渐于陆其羽可用为仪吉"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11971":["归雁二首 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["万里衡阳雁，今年又北归。","双双瞻客上，一一背人飞。","云里相呼疾，沙边自宿稀。","系书元浪语，愁寂故山薇。"],"",[["古注·《杜詩詳註》","鹤注当是大厯五年潭州作"],["古注·《杜詩詳註》","俗本作无"],["古注·《杜詩詳註》","首章见归雁而切故乡之思衡雁又归在潭两春矣雁去既不能留而系书又不可得所以有故山之慨黄希曰公在南而雁北归故曰背人蔡曰衡阳有回雁峯雁至此不过遇春而回应㻛诗言我塞门来将就衡阳栖㑹稽典録虞国少有孝行为日南太守尝有双雁宿止听上每出行县辄飞逐车江淹横吹赋河中之雁一一而学飞李少卿诗双鳬相背飞顾注苏武传匈奴诈言武死常惠教汉使者诡言汉天子射雁上林得武帛书乃归武则雁足系书後人承讹袭谬耳谢灵运诗故山日巳逺风波岂还时"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11972":["归雁二首 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["欲雪违胡地，先花别楚云。","却过清渭影，高起洞庭羣。","塞北春阴暮，江南日色曛。","伤弓流落羽，行断不堪闻。"],"",[["古注·《杜詩詳註》","从杜臆旧作曛"],["古注·《杜詩詳註》","次章伤归雁而兴飘泊之感违胡地去秋雁来别楚云今春雁去别清渭来时所经起洞庭去时所厯塞北江南承上起下言当此春日而犹有伤弓落羽行断声哀者皆穷途旅客所不忍闻也谢灵运诗季秋边朔苦旅雁违霜雪月令八九月鸿雁来正月𠉀雁北更嬴引弓虚发而下雁出国䇿详见十三巻史引虚弓而雁落人问之曰此雁伤弓也"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11973":["小寒食舟中作","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["佳辰强饭食犹寒，隐几萧条带鶡冠。","春水船如天上坐，老年花似雾中看。","娟娟戏蝶过闲幔，片片轻鸥下急湍。","云白山清万余里，愁看直北是长安。"],"刘云意虽索寞语不寒俭",[["古评·《唐诗品汇》","刘云意虽索寞语不寒俭"],["古评·《唐诗品汇》","范元实诗眼云沈佺期诗云白山青千万里几时重谒圣明君杜云云白山青万余里愁看直北是长安沈云人如天上坐鱼似镜中游杜云春水船如天上坐老年花似雾中看皆不免蹈袭然按邵氏闻见録云少陵此诗次聨本沈云卿船如天上坐人似镜中行船如天上去人在镜中悬也要皆触景而发意异句工何可同日而观况少陵独立乎千载之上岂必有所本而後作哉"],["古注·《杜詩詳註》","一作开非"],["古注·《杜詩詳註》","上四寒食舟景下四即景感懐朱瀚曰领聮分承上二时逢寒食故春水盈江老景萧条故看花目暗须於了无蹊径处寻其草蛇灰线之妙腹聨兴起下二戏蝶轻鸥往来自在而云山万里空望长安所以对景而生愁也首尾又暗相照应与几年逢熟食万里逼清明参看篇中看字两见亦无他字可代庄子南郭子綦隠几而坐赵注鶡冠隠者之冠袁叔真隠传有鶡冠子旧注引虎贲武骑之鶡冠误矣孙权与曹操牋春水方生公宜速去陈释惠标诗舟如空里泛人似镜中行沈约诗落花雰似雾何逊"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗品彚（附唐诗拾遗）》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩品彚_(四庫全書本)）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11974":["清明二首 一","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["朝来新火起新烟，湖色春光净客船。","绣羽衔花他自得，红颜骑竹我无缘。","胡童结束还难有，楚女腰肢亦可怜。","不见定王城旧处，长怀贾傅井依然。","虚沾焦举爲寒食，实藉严君卖卜钱。","钟鼎山林各天性，浊醪粗饭任吾年。"],"",[["古注·《杜詩詳註》","鹤注当是大厯四年春初到潭州时作"],["古注·《杜詩詳註》","一作严君"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11975":["清明二首 二","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["此身飘泊苦西东，右臂偏枯半耳聋。","寂寂系舟双下泪，悠悠伏枕左书空。","十年蹴鞠将雏远，万里秋千习俗同。","旅雁上云归紫塞，家人钻火用青枫。","秦城楼阁烟花里，汉主山河锦绣中。","风水春来洞庭阔，白苹愁杀白头翁。"],"",[["古注·《杜詩詳註》","朱瀚曰朝来率尔新火新烟重复绣羽字面尘坌衔花骑竹属对不伦他自得我无缘还难有亦可怜纯是暮气岂少陵顿挫本色正自孤舟老病牵情楚女腰肢甚无谓矣出言有章者不应如是城旧处井依然神理安在钟鼎山林浊醪麤饭堆积陈腐各天性任吾年与他自得亦可怜等同一庸软耳"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11976":["发潭州","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["夜醉长沙酒，晓行湘水春。","岸花飞送客，樯燕语留人。","贾傅才未有，褚公书绝伦。","高名前後事，回首一伤神。"],"",[["古注·《杜詩詳註》","鹤注此四年春自潭之衡时作杜臆时未到衡诗当在望岳之前"],["古注·《杜詩詳註》","俗本作何"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11977":["回櫂","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["宿昔试安命，自私犹畏天。","劳生系一物，爲客费多年。","衡岳江湖大，蒸池疫疠偏。","散才婴薄俗，有迹负前贤。","巾拂那关眼，缾罍易满船。","火云滋垢腻，冻雨裛沈緜。","强饭蓴添滑，端居茗续煎。","清思汉水上，凉忆岘山巅。","顺浪飜堪倚，回帆又省牵。","吾家碑不昧，王氏井依然。","几杖将衰齿，茅茨寄短椽。","灌园曾取适，游寺可终焉。","遂性同渔父，成名异鲁连。","篙师烦尔送，朱夏及寒泉。"],"",[["古注·《杜詩詳註》","此诗旧编在大厯五年黄鹤疑诗中不言臧玠之乱当是四年至衡州畏热将廽棹欲归襄阳不果而竟留於潭也今按杜诗凡纪行之作其次第皆厯然分明不当以欲行禾果之事载之诗集考臧玠之乱在四月公往衡山过耒阳俱在夏日此云火云垢腻殆耒阳回棹而作词不及忧乱者前後诸诗巳详不必每章叠见也还依旧编为当"],["古注·《杜詩詳註》","此厌衡山之热而欲回棹也上四作自咎语平时安命虽専巳自私犹知畏天今以谋生之故而频作客逰深愧不能安命矣且衡岳间地气人情如是且前贤所絶迹不至者乃浪迹於此是负前贤矣无几案故巾拂不用多饮酒故瓶罍满船火云冻雨晴雨皆带郁蒸蓴羮性寒续茗解热也前咏懐诗云衣食相拘阂即所云劳生系一物赵注谓劳生之人不免系着一物是也试尝也汉地理志承阳县属长沙国在承水之阳故名读若蒸元和郡国志衡阳城东傍湘冮北背蒸水寰宇记衡州衡阳县蒸水源出县西名蒸水者其气如蒸也舞鹤赋巾拂两停九剑双止诗瓶之罄矣维罍之耻淮南子旱云烟火尔雅冻雨乃夏日暴雨裛沾也沉绵病也薛梦符田茶録潭邵之间渠江中有茶乡人每年采撷其色如铁芳香异常黄希曰昔尝官郴见其风土唯"],["古注·《杜詩詳註》","尚煎茶客至继以六七则知茗续煎者湖南多如此"],["古注·《杜詩詳註》","此欲托迹襄阳终以安命自处也凊凉之地可以避暑且自衡回潭舟行下水故顺浪而省牵杜碑王井皆襄阳遗蹟几秋茅茨思卜居其地灌园四句甘为遯世篙师二句结出回棹灌园游寺暗使故事渔父鲁连明用古人赵曰沧浪渔父隠不求名仲连却秦军下燕城虽不受封犹为取名者故云异鲁连此章二段各十四句晋书杜预平吴後刻二碑纪绩一立万山之上一沈万山下潭中曰焉知此後不为陵谷乎王粲井注见九巻髙士传陈仲子辞楚相与其妻逃去为人灌园晋书邵绩灌园鬻菜以供衣食石勒叹曰此真髙人矣南史梁刘慧尝㳺匡山遂有终焉之志因不仕居东林寺於山北构园一所号离垢园易寒泉之食"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11978":["赠韦七赞善","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["乡里衣冠不乏贤，杜陵韦曲未央前。","尔家最近魁三象，时论同归尺五天。","北走关山开雨雪，南游花柳塞云烟。","洞庭春色悲公子，鰕菜忘归范蠡船。"],"自注云斗魁下两两相比为三台",[["古评·《唐诗镜》","自注云斗魁下两两相比为三台"],["古评·《唐诗镜》","自注云俚语曰城南韦杜去天尺五"],["古注·《杜詩詳註》","诗云洞庭春色当是大厯五年在潭州作鹤注唐东宫官有左右赞善大夫各五人掌传令讽过失赞礼仪韦赞善必韦见素之後见素位至宰相赠司空故诗云尔家最近魁三象见素与公皆京兆人故又云乡里衣冠不乏贤若韦思谦父子乃郑州人"],["古注·《杜詩詳註》","一作因侵"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗镜》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩鏡_(四庫全書本)）","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11979":["奉酬寇十侍御锡见寄四韵复寄寇","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["往别郇瑕地，於今四十年。","来簪御府笔，故泊洞庭船。","诗忆伤心处，春深把臂前。","南瞻按百越，黄帽待君偏。"],"",[["古注·《杜詩詳註》","上四散而复聚喜洞庭相见下四聚而复散伤百越逺行诗忆指冦君所寄者黄帽指舟人谓相𠉀於水边也顾注郇瑕晋地在平阳府猗氏县诗云郇伯劳之葢其国也魏畧殿中侍御史簪白笔侧陛而坐帝问左右此何官辛毗曰此谓御史旧时簪笔以奏不法今直备位但珥笔耳汉书注簪笔者插笔於首邵注御史所居之署谓之御史府楚辞目极千里伤心处广絶交论自昔把臂之英金兰之友汉百越地即今广东广西赵曰汉书邓通以擢船人为黄头郎注云土胜水故刺船之人皆着黄帽顾氏以黄帽为公自称引前发刘"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11980":["酬郭十五受判官","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["才微岁老尚虚名，卧病江湖春复生。","药裹关心诗总废，花枝照眼句还成。","只同燕石能星陨，自得隋珠觉夜明。","乔口橘洲风浪促，系帆何惜片时程。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11981":["衡州送李大夫七丈勉赴广州","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["斧钺下青冥，楼船过洞庭。","北风随爽气，南斗避文星。","日月笼中鸟，乾坤水上萍。","王孙丈人行，垂老见飘零。"],"此诗气葢宇宙不待赘説老杜送人诗多矣此为冠夏日杨长宁宅送崔侍御常正字入京探韵得深字",[["古注·《杜詩詳註》","上四送李入广烜赫有势下四自叙飘流悲惋动情卢注青㝠自北而来故风随爽气洞庭向南而徃故斗避文星便见叱咤风云指挥天地气象杜臆日月照临之下身如笼鸟乾坤覆载之中迹若浮萍此垂老飘零之状王孙乃我丈人行忍见其若此耶盖望之援手矣记诸侯赐斧龯然後专征伐汉光武书黄龯一下无处所下青㝠犹言自天而下黄生谓入广度岭如下青㝠非也汉杨仆为楼船将军正合粤中事世説王子猷曰西山朝来致有爽气卢注勉好古尚竒故曰文星今按文昌本在北斗宫李自北至南故南斗应避之方回曰日月年年也乾坤处处也张綖注虚度日月起下垂老浪迹乾坤起下飘零左思诗习习笼中鸟举翮触四隅王粲诗朝雾竟㡬何忽如水上萍前汉苏武传汉天子我丈人行也黄生注唐人极重中表亲皆叙行辈同者称兄弟卑者称侄尊者称丈此自勉为丈人行盖中表尊属也"],["古评·《瀛奎律髓》","此诗气葢宇宙不待赘説老杜送人诗多矣此为冠夏日杨长宁宅送崔侍御常正字入京探韵得深字"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）","古籍注评：《瀛奎律髓》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/瀛奎律髓_(四庫全書本)）"]],"open_11982":["哭长孙侍御","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["道爲谋书重，名因赋颂雄。","礼闱曾擢桂，宪府旧乘骢。","流水生涯尽，浮云世事空。","唯余旧台柏，萧瑟九原中。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11983":["虢国夫人","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["虢国夫人承主恩，平明上马入宫门。","却嫌脂粉涴颜色，澹埽蛾眉朝至尊。"],"",[["古注·《杜詩詳註》","作张祜集灵台与紫微殿相近今按祜乃中唐人去天宝巳乆若作追忆虢国之词亦当微带乱後事诗意全不及之还是讥讽现在应属少陵作也唐后妃传杨贵妃三姊长韩国三虢国八秦国并承恩入宫掖通监至德二载贵妃缢死於佛堂虢国夫人及其子裴徽走至陈仓县令薛景仙帅吏士追捕诛之"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11984":["军中醉饮寄沈八刘叟","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["酒渴爱江清，余甘漱晚汀。","輭沙欹坐稳，冷石醉眠醒。","野膳随行帐，华音发从伶。","数杯君不见，醉已遣沈冥。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11985":["杜鹃行","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["古时杜宇称望帝，魂作杜鹃何微细。","跳枝窜叶树木中，抢佯瞥捩雌随雄。","毛衣惨黑貌顦顇，衆鸟安肯相尊崇。","隳形不敢栖华屋，短翮唯愿巢深丛。","穿皮啄朽觜欲秃，苦饥始得食一虫。","谁言养雏不自哺，此语亦足爲愚蒙。","声音咽咽如有谓，号啼略与婴儿同。","口乾垂血转迫促，似欲上诉於苍穹。","蜀人闻之皆起立，至今斅学传遗风。","乃知变化不可穷，岂知昔日居深宫，嫔嫱左右如花红。"],"",[["古注·《杜詩詳註》","英华作翔"],["古注·《杜詩詳註》","末叹世俗之传讹蜀人起立将敬至今传为风俗谓望帝之魂变化不可穷诘也乃今之对花哀鸣者岂犹思深宫妃嫔之乐耶其亦终述不悟矣此章前二段各八句末段五句收书惟斆学半前汉贾谊传遗风余俗尚犹未改长门赋步从容於深宫"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11986":["闻惠二过东溪特一送","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["惠子白驹瘦，归溪唯病身。","皇天无老眼，空谷滞斯人。","崖蜜松花熟，山杯竹叶新。","柴门了无事，黄绮未称臣。"],"",[["古注·《杜詩詳註》","一作鱼坡作驴"],["古注·《杜詩詳註》","一作白一作古"],["古注·《杜詩詳註》","一作村醪"],["古注·《杜詩詳註》","上四送惠归溪惜之也下四溪中自适慰之也八与四言虽在空谷之中不失为黄绮高风黄生注崖蜜山杯即柴门生事黄绮尚多一出恵乃未称臣之黄绮更觉高於古人矣诗皎皎白驹在彼空谷一四正用其语蔡琰曲天有眼兮何不见我黄生注斯人亦从诗中伊人字变换避声病也本草白蜜一名崖蜜葢蜂酿松花所成杜臆山蜂酿蜜於高崖从山上缒人采之庾信诗山杯捧竹根竹叶酒名张华轻薄篇苍梧竹叶清宜城九醖酒张协七命荆南乌程豫北竹叶黄注韩诗且可勤买抛青春坡公歴引唐时以春名酒者为证不知春之为义因酒熟於春而名之也又云柴门亦本诗衡门之下可以栖迟意来"],["古评·《诗人玉屑》","刘路左车为予言：尝收得唐人杂编时人诗册，有送惠二归故居诗云：真子美语也。白驹或作……字"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）","古籍注评：《诗人玉屑》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/詩人玉屑_(四庫全書本)）"]],"open_11987":["舟泛洞庭","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["蛟室围青草，龙堆拥白沙。","护江盘古木，迎櫂舞神鵶。","破浪南风正，收颿畏日斜。","云山千万叠，底处上仙槎。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11988":["李盐铁二首","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["落叶春风起，高城烟雾开。","杂花分户映，娇燕入檐回。","一见能倾产，虚怀只爱才。","盐官虽绊骥，名是汉庭来。"],"",[["古注·《杜詩詳註》","黄作落叶"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11989":["长吟","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["江渚飜鸥戏，官桥带柳阴。","江飞兢渡日，草见蹋春心。","已拨形骸累，真爲烂漫深。","赋诗歌句稳，不免自长吟。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11990":["绝句九首 七","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["闻道巴山里，春船正好行。","都将百年兴，一望九江城。"],"",[["古注·《杜詩詳註》","单氏编在永泰元年成都诗内鲍氏曰谢克庄任伯云此诗得于慎文肃家故书中犹是吴越钱氏时人所传格律髙妙其为少陵无疑诗説隽永谓晁氏得吴越人写本杜诗如日出东篱水六首乃九章其一云漫道春来好云云今按前六首当另为一处不必并合"],["古注·《杜詩詳註》","赵作山首章欲往荆楚而作杜臆九江在洞庭详见九江落日注"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11991":["绝句九首 八","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["水槛温江口，茅堂石笋西。","移船先主庙，洗药淙沙溪。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11992":["绝句九首 九","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["设道春来好，狂风大放颠。","吹花随水去，飜却钓鱼船。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_11993":["瞿唐怀古","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["西南万壑注，勍敌两崖[开]。","地与山根裂，江从月窟来。","削成当白帝，空曲隐阳台。","疏凿功虽美，陶钧力大哉。"],"",[["古注·《杜詩詳註》","上四瞿唐之景下四懐古之意凿山本以通水故山水并起山裂承崖开江来承壑黄注言峡之隘四言源之长五言壁之峭六言崖之深相传皆禹功所䟽凿者其实瞿唐天险葢出於造化神力也山附於地山裂乃地势使然必地与山以裂而後江水得从此来黄氏説与字含下陶钧意独冇解㑹高与白帝相当空处藏隐阳台以阳台配白帝亦暗指神女天然对仗世説万壑争流左传宋及楚战子鱼曰勍敌之人隘而不列以两崖而关鎻万壑真有抜地倚天之力故曰勍敌庾信诗山根一片两长杨赋西厌月螖螖与窟同山海经泰华之山削成而四方杜臆白帝山在䕫州府治东五里阳台在府治北五里高百丈陶𢎞景隐於句容之勾曲山中周廻一百五十里空曲寥旷鹤曰寰宇记阳台台高一百二十歩即宋玉赋游阳云之台郭璞江赋巴东之峡夏后疏凿邹阳传独化於陶钧之上师氏曰陶人转钧葢取周廻调钧耳此借以喻造化黄生曰此诗竒险之句亦若假凿於五丁者又曰疏凿控三巴专归功於神禹也疏凿功虽美兼归功於造物也葢题属懐古不敢忘禹之迹而险山天造亦不可没天之工结以咏叹出之倍有神致"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11994":["送司马入京","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["羣盗至今日，先朝忝从臣。","叹君能恋主，久客羡归秦。","黄阁长司谏，丹墀有故人。","向来论社稷，爲话涕沾巾。"],"",[["古注·《杜詩詳註》","此章从收京説到送班在四句分截乗舆还京君臣如故公犹遐方寄迹而班独匹马归朝故临别伤心黄屋车上之葢朱衣侍从之臣"],["古注·《杜詩詳註》","郑继之善夫曰诗之妙处正在不必写到真説到尽而其欲写欲説者自宛然可想斯得风人之义杜诗每有失之太真太尽者如此诗末二句则有不真不尽之兴矣余可类推"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11995":["惜别行送刘仆射判官","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["闻道南行市骏马，不限匹数军中须。","襄阳幕府天下异，主将俭省忧艰虞。","祗收壮健胜铁甲，岂因格鬬求龙驹。","而今西北自反胡，骐驎荡尽一匹无。","龙媒真种在帝都，子孙永落西南隅。","向非戎事备征伐，君肯辛苦越江湖。","江湖凡马多顦顇，衣冠往往乘蹇驴。","梁公富贵於身疎，号令明白人安居。","俸钱时散士子尽，府库不爲骄豪虚。","以兹报主寸心赤，气却西戎回北狄。","罗网羣马籍马多，气在驱驰出金帛。","刘侯奉使光推择，滔滔才略沧溟窄。","杜陵老翁秋系船，扶病相识长沙驿。","强梳白发提胡卢，手把菊花路旁摘。","九州兵革浩茫茫，三叹聚散临重阳。","当杯对客忍流涕，君不觉老夫神内伤。"],"",[["古注·《杜詩詳註》","诗云扶病相识长沙驿刘判官盖括马至此与公相晤而赠之以诗当是大厯四年秋作朱注唐制仆射下宰相一等时盖刘之主将加此官刘其属下判官也诗见陈浩然又见文苑英华"],["古注·《杜詩詳註》","叙刘君至潭之由南行指判官主将指仆射起处并题"],["古注·《杜詩詳註》","此从英华他本作西南"],["古注·《杜詩詳註》","此言南行车马之难西北指安史吐蕃东南指襄阳长沙凡马皆疲何况龙种乎义鹘行以老鹘为其父此诗以马驹为子孙语近诙谐徐干中论游必帝都"],["古注·《杜詩詳註》","此见襄阳主将之贤梁公即梁崇义上四言俭省而爱人下四言忧虞而敌忾淮南子见之明白处之如玉石黄香传香为魏郡守分俸禄赏赐出赡贫者出金帛购马也"],["古注·《杜詩詳註》","一作涕泪一本有君字"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11996":["呀鹘行","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["病鹘孤飞俗眼丑，每夜江边宿衰柳。","清秋落日已侧身，过雁归鵶错回首。","紧脑雄姿迷所向，疎翮稀毛不可状。","强神迷复皁雕前，俊才早在苍鹰上。","风涛飒飒寒山阴，熊罴欲蛰龙蛇深。","念尔此时有一掷，失声溅血非其心。"],"",[["古注·《杜詩詳註》","蔡梦弼编在大厯三年江陵诗内以诗有江边秋日语也然在䕫州亦可言之今姑依蔡编未定何年耳呀张口貎"],["古注·《杜詩詳註》","英华作月"],["古注·《杜詩詳註》","此见呀鹘而自伤也首叚写其病惫之状俗眼看丑憎其病废雁鸦回首畏其余威紧脑二句仍摹其病态强神二句回想其猛气迷复二字出易复卦言迷於所复也上文有迷所向下句不应又用迷复当作非复为是"],["古注·《杜詩詳註》","下叚深致怜惜之意言当此天寒物藏正鹘鸟凌厉之秋此时应有一撃而悲鸣凄惨如此岂其本心乎此章上八句下四句掷投也鸷鸟传物必自上投下"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11997":["狂歌行赠四兄","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["与兄行年校一岁，贤者是兄愚者弟。","兄将富贵等浮云，弟切功名好权势。","长安秋雨十日泥，我曹鞴马听晨鸡。","公卿朱门未开锁，我曹已到肩相齐。","吾兄睡稳方舒膝，不袜不巾蹋晓日。","男啼女哭莫我知，身上须缯腹中实。","今年思我来嘉州，嘉州酒重花绕楼。","楼头吃酒楼下卧，长歌短咏还相酬。","四时八节还拘礼，女拜弟妻男拜弟。","幅巾鞶带不挂身，头脂足垢何曾洗。","吾兄吾兄巢许伦，一生喜怒长任真。"],"",[["古注·《杜詩詳註》","此当是永泰夏去成都之嘉戎时作观诗言嘉州可见喜兄弟相见故兴至而狂歌胡夏客曰公之诸弟见於诗者不一此所赠四兄又其诸从也"],["古注·《杜詩詳註》","首叙两人性情之异等浮云见其贤好权势见已愚庄子籧伯玉行年六十而化富贵等浮云用论语"],["古注·《杜詩詳註》","此追叙长安往事上四承好权势下四承等浮云説文鞴车⿰也一曰驾於马曰鞴魏志臧洪传年为吾兄分为笃友老子实其腹"],["古注·《杜詩詳註》","一作还一作逺"],["古注·《杜詩詳註》","此又记嘉州近事诗酒唱酬见其豪放男女礼拜喜其殷勤脱巾䝉垢摹其狂态庾信诗三冠葢聚八节管游後汉鲍永传但幅巾诣河内注不着冠但幅巾束首也通典汉末王公名士以幅巾为雅是以袁绍崔豹之徒虽为将帅皆着幅巾易或锡之鞶带説文鞶大带也内则足垢燂汤请洗南史阴子春身脂垢汚脚数年一洗言每洗则失财败事"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11998":["逃难","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["五十头白翁，南北逃世难。","疎布缠枯骨，奔走苦不暖。","已衰病方入，四海一涂炭。","乾坤万里内，莫见容身畔。","妻孥复随我，回首共悲欢。","故国莽丘墟，邻里各分散。","归路从此迷，涕尽湘江岸。"],"",[["古注·《杜詩詳註》","此为无家可归而叹也此章首尾各四句中间六句班彪北征赋旧室灭以邱墟兮"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《杜诗详注》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/杜詩詳註_(四庫全書本)）"]],"open_11999":["寄高适","杜甫","未知","约741前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["楚隔乾坤远，难招病客魂。","诗名惟我共，世事与谁论。","北阙更新主，南星落故园。","定知相见日，烂漫倒芳尊。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]]};